export default [{"id":3217,"title":"اغتيال السلطان أبي سعيد ملك المرينيين وتولية ابنه الناصر .","date":["العام الهجري :801","العام الميلادي :1398"],"text":"هو السلطان أبو سعيد بن عثمان بن أبي العباس أحمد بن أبي سالم إبراهيم بن أبي الحسن المريني ملك المرينيين، لما اغتِيلَ نُصب ولده الناصر عبد الحق خلفًا له وتولى الوصايةَ عليه أبو زكريا يحيى الوطاسي زعيم بني وطاس، والذي به قامت دولة بني وطاس التي خلفت دولة بني مرين فيما بعد."},{"id":3218,"title":"وفاة السلطان الظاهر برقوق وتولي ابنه الناصر فرج  .","date":["العام الهجري :801","الشهر القمري : شوال","العام الميلادي :1399"],"text":"هو الملك الظاهر برقوق أبو سعيد أولُ من ملك مصر من الجراكسة، وَلِيَ سلطانها سنة 784 وبنى المدرسة البرقوقية بمصر بين القصرين. ثم خُلِع، ثم أعيد إلى أن مات سنة 801؛ ففي يوم الثلاثاء خامس شهر شوال ابتدأ مرض السلطان الظاهر برقوق، وذلك أنه ركب للعب الكرة بالميدان في القلعة على العادة، فلما فَرَغ منه قدم إليه عسل نحل ورد من كختا، فأكل منه ومن لحم بلشون، ودخل إلى قصوره، فعكف على شرب الخمر، فاستحال ذلك خلطًا رديًّا لزم منه الفراش من ليلة الأربعاء، وتنوَّع مرضه حتى أُيس منه لشدة الحمى، وضَعْف القوى، فأرجفت بموته في يوم السبت تاسعه، واستمَرَّ أمره يشتد إلى يوم الأربعاء الثالث عشر، فشنع الإرجاف، وغُلِّقت الأسواق، فلما أصبح يوم الخميس استدعى الخليفةُ المتوكل على الله أبا عبد الله محمدًا، وقضاة القضاة وسائر الأمراء الأكابر والأصاغر وجميع أرباب الدولة إلى حضرة السلطان، فحَدَّثهم في العهد لأولاده، فابتدأ الخليفة بالحَلِف للأمير فرج ابن السلطان أنَّه هو السلطان بعد وفاة أبيه، ثم حلف بعده القضاة والأمراء، ثم مات بعد منتصف ليلة الجمعة خامس عشر شوال، وقد تجاوز الستين سنة، منها مدةُ حكمه بديار مصر منذ صار أتابك العساكر عوضًا عن الأمير طشتمر العلاي الدوادار، إلى أن جلس على تخت السلطة أربع سنين وتسعة أشهر وعشرة أيام، ومنذ تسلطن إلى أن مات ست عشرة سنة وأربعة أشهر وسبعة وعشرون يومًا، منها سلطته إلى أن خُلِع ست سنين وثمانية أشهر وعشرون يومًا، وسلطته منذ أعيد إلى أن مات تسع سنين وثمانية أشهر، والفترة بينهما ثمانية أشهر وتسعة أيام، ومدةُ حكمه أتابكًا وسلطانًا إحدى وعشرون سنة وعشرة أشهر وستة عشر يومًا، اجتمع بالقلعة الأمير الكبير أيتمش وسائر الأمراء وأرباب الدولة، واستدعى الخليفة وقضاة القضاة، وشيخ الإسلام البلقيني، ومن عادته الحضور، فلما تكاملوا بالإسطبل السلطاني أُحضِرَ فرج ابن الملك الظاهر برقوق، وخطب الخليفة وبايعه بالسلطة، وقلَّده أمور المسلمين، فقَبِل تقليده، وأُحضِرَت خِلعة سوداء أُفيضت على فرج، ونُعِت بالملك الناصر، ومضى حتى جلس على التخت بالقصر، وقبَّل الأمراءُ كُلُّهم له الأرضَ على العادة، وألبس الخليفة التشريفَ وكان عمره يومها قرابة الثلاث عشرة سنة."},{"id":3219,"title":"استيلاء مراد الأول بن أورخان على الأبلستين .","date":["العام الهجري :801","الشهر القمري : ذي القعدة","العام الميلادي :1399"],"text":"أخذ السلطان مراد الأول بن أورخان بن عثمان الأبلستين، وعزم أن يمشيَ إلى البلاد الشامية، فطلب الأمراء والقضاة وأرباب الدولة إلى القصر السلطاني، وقُرِئَت عليهم كتبٌ تتضمَّنُ أنَّ ابن عثمان ملك الروم بعث أخاه عليًّا بالعساكر، وأنه أخذ ملطية والأبلستين -مدينة مشهورة ببلاد الروم- وفَرَّ منه صدقة بن سولي، فتسلَّمها في الثامن والعشرين من ذي القعدة، وأنَّه محاصر درندة، فوقع الاتفاقُ على المسير إلى قتاله، وتفرَّقوا، فأنكر المماليك السلطانية صِحَّةَ ذلك، وقالوا: \"هذه حيلة علينا حتى نخرجَ من القاهرة فقط\" وعَيَّنوا سودون الطيار أمير أخور لِكَشفِ هذا الخبر."},{"id":3220,"title":"تيمورلنك يستولي على أذربيجان ويحتل شرق الأناضول .","date":["العام الهجري :802","العام الميلادي :1399"],"text":"اتجه تيمورلنك ناحية الغرب في هذا العام فاستولى على أذربيجان، ففَرَّ منها صاحِبُها قره يوسف، ووصل تيمورلنك إلى القوقاز وأدَّب بلاد الكرج الذين ثاروا على عاملِه عليهم، ثم اتَّجه نحو السلطان العثماني بايزيد الأول عن طريق أرضروم ودخل سيواس، وقبض فيها على الأمير أرطغرل سليمان بن السلطان بايزيد، فقَتَله، وفَرَّ حاكِمُها، وكان قد وقف في وجهه أربعة آلاف أرضرومي فجمعهم في خندق واحد وردم التراب فوقهم، وسار إلى ملطية فخربها كما خرب سيواس، فدان له القِسمُ الشرقي من الأناضول."},{"id":3221,"title":"الفتنة بين الأمير أيتمش نائب السلطنة والأمير يشبك الشعباني .","date":["العام الهجري :802","الشهر القمري : صفر","العام الميلادي :1399"],"text":"تزايد الاختلافُ بين أمراء المماليك والخاصكية، وكثُر نفور الخاصكية من الأمير أيتمش الذي كان يتولَّى نيابة السلطنة بوصية السلطان برقوق، وخاصة أن السلطان فرجًا ما زال قاصرًا، وظنوا به وبالأمراء أنَّهم قد مالوا إلى نائب الشام الأمير تنم الحسني الذي بدأ يعصي عن الطاعة، واتفقوا معه على إفناء المماليك بالقتل والنفي، فحَذِرَ الأمراء منهم، واشتدت الوحشةُ بين الطائفتين، وتعيَّن من الخاصكية سودون طاز، وسودون بن زاده، وجركس المصارع، ووافقوا الأمير يشبك الشعباني الذي كان منافسًا لأيتمش، فصاروا في عصبة قوية وشوكة شديدة، وشرع كلٌّ من الأمراء والخاصكية في التدبير، والعمل على الآخر، ثم استدعى الملكُ الناصر فرج الأميرَ الكبير أيتمش إلى القصر، وقال له: يا عمِّ، أنا قد أدركت، وأريد أن أترشَّدُ، وكان هذا قد بيَّته معه الأمير يشبك، والأمير سودون طاز، فيمن معهما من الخاصكية، ليستبِدَّ السلطان ويحصُلَ لهم الغرض في أيتمش والأمراء، ويمتنع أيتمش من تصرُّف السلطان، فينفتح لهم باب إلى القتال، ومحاربة أيتمش والأمراء، فأجاب أيتمش السلطانَ بالسمع والطاعة، واتَّفق مع الأمراء والخاصكية على ترشيد السلطان، وأن يُمتثَلَ سائِرُ ما يرسُمُ به، فكان كما أراد ورُسم بترشيد السلطان، وافترق من يومئذ العسكر فريقان: فرقة مع أيتمش، وفرقة مع يشبك، وانقطع يشبك بداره، وأظهر أنه مريض، فحَذِرَ أيتمش ومن معه من الأمراء وظنوا أنَّها من يشبك حيلة، حتى إذا دخلوا لعيادته قبض عليهم، فلزم كلٌّ منهم داره واستعَدَّ، وأخلد أيتمش إلى العجز، وأعرض عن إعمال الرأي والتدبير، وكان قد تبيَّن منذ مات الظاهر عجزُه وعدم أهليته للقيام بالأمر، فلما كان ليلة الاثنين عاشر من شهر صفر أشيع من العصر ركوب العساكر للقتال، وماج الناس وكثرت حركاتهم، فلم يدخل الليل حتى لبس أيتمش ومن معه آلةَ الحرب، وملك أيتمش الصوة -قرية بشرقية مصر- تجاه باب القلعة، وأصعد عدةً من المقاتِلة إلى عمارة الأشرف تجاه الطبلخاناه؛ ليرموا على من فيها ومن يقف على باب القلعة، ولم يخرُج يشبك من بيته، وأخذ الأمير فارس حاجب الحجاب رأس الشارع الملاصِق لباب مدرسة السلطان حسن؛ ليقاتِلَ من يخرج من باب السلسلة، ودُقَّت بها الكوسات -قطعتان من نحاس يُدَقُّ بإحداهما على الأخرى- الحربية، ولبست المماليك السلطانية، ووقعت الحروبُ بين الفريقين من وقت العشاء الآخرة إلى السَّحَر، وقد نزل السلطان من القصر إلى الإسطبل، فاشتَدَّ قتال المماليك السلطانية، وثبت لهم الأمير فارس، وكاد يهزمُهم لولا ما كادوه من أخذ مدرسة السلطان حسن، ورَمْيه من أعلاها إلى أن هزموه، وأحاطوا بداره، وهزموا تغري بردي وأرغون شاه، بعدما أبلى تغري بردي بلاء كثيرًا، وأحاطوا بدورهما، فصار الجميع إلى أيتمش، وقد امتدَّت الأيدي إلى دُورِهم، فنهبوا ما فيها، فنادي أيتمش بالقاهرة وظواهرها: من قبض مملوكًا جركسيًّا من المماليك السلطانية، وأحضره إلى الأمير الكبير أيتمش يأخذُ عريةً فحنقوا من ذلك، وفارقه من كان معه من الجراكسة، وصاروا إلى جهة السلطان، ومالوا بأجمعِهم على أيتمش، فانهزم ممن بقي معه وقت الظهر من يوم الاثنين يريدون جهة الشام، وانهزم معه من الأمراء الألوف أرغون شاه أمير مجلس، وتغري بردي أمير سلاح، وغيرهم، فمرُّوا بالخيول السلطانية في ناحية سرياقوس، فأخذوا من جيادها نحو المائة، وساروا إلى دمشق، وتجمَّع من المفسدين خلائق، ونهبوا مدرسة أيتمش، وحفَروا قبر ولده الذي بها، وأحرقوا الرَّبعَ المجاور لها من خارج باب الوزير، فلم يُعمَر بعد ذلك، ونهبوا جامع أقسنقر، واستهانوا بحرمة المصاحف، ونهبوا مدرسةَ السلطان حسن، وأتلَفوا عِدَّةً من مساكن المنهزمين، وكسروا حبس الديلم وحبس الرحبة، وأخرجوا المسجونين."},{"id":3222,"title":"حدوث فتنة في الكرك .","date":["العام الهجري :802","الشهر القمري : جمادى الأولى","العام الميلادي :1400"],"text":"لما قَدِمَ المهتار عبدالرحمن الكرك أظهر كتبًا إلى الأمير سودون الظريف نائب الكرك باستعدادِه لحرب الأمير أيتمش، فاختلف أهلُ الكرك وافترقوا فرقتين: قيسية، ويمانية؛ فرأسَ قيسًا قاضي الكرك شرف الدين موسى ابن قاضي القضاة عماد الدين أحمد الكركي. ورأَسَ اليمن الحاجبُ شعبان بن أبي العباس. ووقعت فتنةٌ نُهِب فيها رحل المهتار عبد الرحمن والخِلعة التي أحضرها إلى النائب، وامتدَّت إلى الغور فنُهب، ورحل أهله وفَرَّ عبد الرحمن إلى جهة مصر. وكانت بين الطائفتين مقتلةٌ قُتِل فيها سِتَّةٌ، وجُرِح نحوُ المائة. وانتصر ابنُ أبي العباس ممَّن معه من يمن؛ لِمَيل النائب معهم على قيس، وقُبِض على القاضي شرف الدين موسى وأخيه جمال الدين عبد الله، وذُبِحا ومعهما ثمانيةٌ من أصحابهما، وأُلقوا في بئر من غير غسل ولا كفن، وأُخِذَت أموالُهم كُلُّها."},{"id":3223,"title":"سيل عظيم بمكة يدخل إلى الكعبة .","date":["العام الهجري :802","الشهر القمري : جمادى الأولى","العام الميلادي :1400"],"text":"في ليلة الخميس عاشر جمادى الأولى كان بمكة -شرَّفها الله- سيل عظيم بعد مطر غزير، امتلأ منه المسجد الحرام حتى دخل الكعبة، وعلا على بابها نحوَ ذراع، وهدم عمودين من عُمُد المسجد، وسقطت عدةُ دور، ومات تحت الهدم وفي السيل نحو الستين إنسانًا."},{"id":3224,"title":"خروج الأمير تنم الحسني نائب الشام عن الطاعة ثم قتله .","date":["العام الهجري :802","الشهر القمري : رجب","العام الميلادي :1400"],"text":"كان الأمير تنم الحسني قد تغلَّب على دمشق أيام موت السلطان الظاهر برقوق، ثم إن السلطان الناصر فرج بن برقوق أقرَّه وأعطاه نيابة دمشق، وأجيز بإخراج من أراد من السجون، فأخرج عدة أمراء من السجون، وزاد أمره فأراد تملُّك أكثر من دمشق، كحلب وحمص وطرابلس وغيرها، ثم إن أيتمش لما هرب في الفتنة التي حصلت بينه وبين يشبك -في شهر صفر من هذه السنة- جاء إلى دمشق الأمير تنم هو ومن معه من الأمراء في خامس ربيع الآخر، فخرج الأمير تنم إلى لقائه، وبالغ في إكرامه وإكرام من معه، وعَظُم شأن الأمير تنم بقدوم أيتمش عليه، وأطاعه من خالف عليه، وفي ثامنه قَدِمَ عليه كتابُ الملك الناصر بمَسكِ أيتمش ومن معه وقدومه إلى مصر، فأحضر الكتاب وحامله إلى عند أيتمش، وأعلمه بذلك، ثم جهَّز أيتمش وتغري بردي قصادهما إلى نائب حماة، ونائب حلب، بدعواهما إلى ما هم عليه، فأجابا بالسمع والطاعة في خامس عشر جمادى الأولى، ورُدَّ الخبر بخروج الأمير تنم نائب الشام، وأيتمش، بمن معهما من دمشق إلى جهة غزة، فرسم السلطان فرج بالتجهيز للسفر؛ ففي السابع عشر اجتمع الأمراء والمماليك بمجلس السلطان، فحثَّهم على السفر في أول جمادى الآخرة، وأن يخرج ثمانية أمراء من الألوف بألف وخمسمائة من المماليك المشتراوات وخمسمائة من المستخدمين، فاختلف الرأي؛ فمنهم من أجاب، ومنهم من قال: لا بدَّ من سفر السلطان، وانفضُّوا على غير شيء، ونفوسُهم متغيرةٌ من بعضهم على بعض، ثم في شهر رجب في رابعه يوم الجمعة: نزل السلطان من القلعة إلى الريدانية ليتوجه إلى قتال أيتمش ونائب الشام، فأقام بمخيَّمه، وتلاحق به الأمراء والعساكر والخليفة وقضاة القضاة، وفي ثامنه: رحل السلطان ببقية العسكر، وعِدَّةُ من سار أولًا وثانيًا نحو سبعة آلاف فارس، وأما الأمير تنم نائب الشام فإنه وجَّه نائب حلب بعسكره إلى جهة مصر في ثامنه، وخرج في تاسعه ومعه الأمير أيتمش وبقية العساكر، ومن انضَمَّ إليهم من التركمان، وخيَّم على قبة يلبغا خارج دمشق، حتى لحقه بقية العسكر ومن سار معه من القضاة، وعمل الأمير جركس أبو تنم نائب الغيبة، وفي الحادي عشر رحل الأمير تنم من ظاهر دمشق، وتبعه ابن الطبلاوي في الثاني عشر، وسار نائب طرابلس بعسكره ساقة، ثم إن الأمير تنم  نزل على الرملة بمن معه، وكان لما قدم عليه من انكسر من عَسكرِه على غزة شَقَّ عليه ذلك، وأراد أن يقبِضَ على بتخاص والمنقار، ففارقاه ولحقا بالسلطان، وأن السلطان بعث إليه من غزة بقاضي القضاة صدر الدين المناوي في يوم الثلاثاء التاسع عشر، ومعه ناصر الدين محمد الرماح أمير أخور، وطغاي تمر مُقدَّم البريدية، وكتب له أمانًا، وأنَّه باق على كفالته بالشام إن أراد ذلك، وكتب الأمراء إلى الأمير تنم يقولون له: أنت أبونا وأخونا، وأنت أستاذنا، فإن أردتَ الشام فهي لك، وإن أردت مصر كنَّا مماليكك وغلمانك، فصُنِ الدماء. وكان الأمراء والعسكر في غاية الخوف منه؛ لقوَّتِه وكثرة عدده، وتفرُّقِهم واختلافِهم، فسار إليه القاضي وحَدَّثه في الصلح ووعظه، وحذَّره الشقاق والخروج عن طاعة السلطان، فقال الأمير تنم: ليس لي مع السلطان كلام، ولكن يرسل إلى الأمير يشبك وسودون طاز وجركس المصارع، وجماعة عَيَّنهم، ويعود الأمير أيتمش كما كان هو وجميع الأمراء الذين معه، فإن فعل ذلك وإلا فما بيني وبينهم إلا السيف، وثبت على ذلك، فقام القاضي ليخرجَ، فخرج الأمير تنم معه بنفسِه إلى خارج الخيمة، وأركبه فرسًا في غاية الحُسنِ، وعضده لما ركب، فقدم القاضي يوم الخميس الحادي والعشرين منه ومعه أحد خاصكية السلطان ممن كان عند الأمير تنم، وعوقه نحو أربعة أشهر عن الحضور، وأعاد الجواب فاتفق الجميعُ على محاربته، فلما كان يوم السبت الثالث والعشرين منه: ورد الخبر أن الأمير تنم ركب ممن معه يريد الحرب، فسار السلطان بعساكره من غزة إلى أن أشرف على الجينين قريب الظهر، فعاين الأمير تنم قد صفَّ عساكره، ويقال إنهم خمسة آلاف فارس وستة آلاف راجل، فتقدمت عساكر السلطان إليهم وقاتلوهم، فلم يكن غير يسير حتى انهزمت عساكِرُ الأمير تنم، ووقع في الأسر الأميرُ تنم نائب الشام، وأقبغا نائب حلب، ويونس نائب طرابلس، وأحمد ابن الشيخ علي، وفارس حاجب الحُجَّاب وبيغوت، وشادي خجا، وبيرم رأس نوبة أيتمش، وجلبان نائب حلب، ومن أمراء الطبلخاناه والعشرات ما ينيف على مائة أمير، وفرَّ أيتمش، وتغري بردي، ويعقوب شاه، وأرغون شاه، وطيفور، في ثلاثة آلاف إلى دمشق ليملِكوها، وعندما قُبِضَ على الأمير تنم كتب إلى دمشق بالنصرة ومَسْك تنم، فوصل البريدُ بذلك يوم الثلاثاء السادس والعشرين منه على نائب الغيبة بدمشق، فنودي بذلك, ثم قدم الأمير أيتمش إلى دمشق يوم الأربعاء السابع والعشرين منه، فقبض عليه، وعلى تغري بردي، وطيفور، وأقبغا اللكاش، وحُبسوا بدار السعادة، ثم مُسِك بعد يومين أرغون شاه، ويعقوب شاه، وتقدم القاضي سعد الدين إبراهيم بن غراب إلى دمشق، فقدمها في يوم السبت آخره، دخل السلطان بأمرائه وعساكره إلى قلعة دمشق، فكان يومًا مشهودًا وسُرَّ الناس به سرورًا كبيرًا, وفي ليلة الخميس رابع رمضان قُتِل الأمير تنم نائب الشام، والأمير يونس الرماح نائب طرابلس بقلعة دمشق خنقًا بعد أن استصفيت أموالهما، ولم يبقَ لهما شيء، ثم سُلِّما إلى أهلهما، فدُفِن الأمير تنم بتربته بميدان الحصى خارج دمشق، ودُفِن يونس بالصالحية، فكانت مدة ولاية الأمير تنم نيابة الشام سبع سنين وستة أشهر ونصفًا، وولاية يونس طرابلس نحو ست سنين."},{"id":3225,"title":"حريق هائل في المسجد الحرام يحرق ثلثه .","date":["العام الهجري :802","الشهر القمري : شوال","العام الميلادي :1400"],"text":"في ليلة الثامن والعشرين شوال ظهرت نارٌ بالمسجد الحرام من رباط، ومشت بالجانب الغربي من المسجد، فعَمَّت النار، واحترقت جميع سُقُف هذا الجانب، وبعض الرواقين المقدَّمين من الجانب الشامي، وعمَّ الحريق فيه إلى محاذاة باب دار العجلة لخُلُوِّه بالهدم وقت السيل، وصار موضع الحريق أكوامًا عظيمة، وتكسَّر جميعُ ما كان في موضع الحريق من الأساطين وصارت قِطَعًا، وقُدِّر الذي احترق من المسجِدِ، فكان قَدْرَ الثُّلُثِ تقريبًا."},{"id":3226,"title":"أحمد بن أويس ملك بغداد يهرب منها ويقاتله أهلها ويلجأ للسلطان .","date":["العام الهجري :802","الشهر القمري : ذي القعدة","العام الميلادي :1400"],"text":"في ثاني ذي القعدة ورد البريدُ من حلب ودمشق بأن ألقان أحمد بن أويس صاحب بغداد، لما توجه إلى بغداد واستولى عليها، كان لقرا يوسف في مساعدته أثر كبير؛ فعندما تمكَّن قَبَض على كثير من أمراء دولته وقتَلَهم، وأكثَرَ من مصادرات أهل بغداد وأخذ أموالهم، فثار عليه من بقي من الأمراء، وأخرجوه منها، وكاتبوا صاحب شيراز أن يحضرَ إليهم، فلحق ابن أويس بقرا يوسف بن قرا محمد التركماني صاحب الموصل، واستنجد به، فسار معه إليها، فخرج أهل بغداد وكسروهما بعد حروب، فانهزما إلى شاطئ الفرات، وبعثا يسألان نائب حلب أن يستأذن السلطان في نزولهما بالشام، وأن الأمير دمرداش استدعى الأمير دقماق نائب حماة إلى حلب، وخرجا في عسكر جريدة يبلغ عددهم الألف، وكبسا ابن أويس وقرا يوسف، وهما في نحو سبعة آلاف فارس، فاقتتلا قتالًا شديدًا في يوم الجمعة رابع عشرين شوال، قتل فيه الأمير جاني بلث اليحياوي أتابك حلب، وأُسِر دقماق نائب حماة، وانهزم دمرداش نائب حلب، وصار إلى حلب ولحقه بعد أن افتَكَّ نفسه بمائة ألف درهم وَعَدَ بها، وأن سودون بن واده -القادم من مصر إلى حلب بالبشارة بقدوم السلطان إلى مصر سالِمًا- بعث المائة ألف إليهما مبعثًا إليه: إنَّا لم نأت محاربين وإنما جئنا مستجيرين، ومستنجدين بسلطان مصر، فحاربنا هؤلاء فدفَعْنا عن أنفسنا، فكتب إلى نائب الشام بمسير عساكر الشام جميعًا، وأخذ ابن أويس وقرا يوسف وإرسالهما إلى مصر."},{"id":3227,"title":"تيمورلنك يذبح سكان مدينتي حلب عينتاب وبهنسا .","date":["العام الهجري :803","الشهر القمري : ربيع الأول","العام الميلادي :1400"],"text":"بعد أن انتهى تيمورلنك من سيواس توجه إلى جهة حلب فوصل إلى عينتاب، ووصل إلى بهنسا وأخذها بعد أن حصرها، ثم نزل على بزاعة ظاهر حلب، فبرز نائب طرابلس بسبعمائة فارس إلى جيش تيمورلنك وهم نحو ثلاثة آلاف، وترامى الجمعان بالنشاب، ثم اقتتلوا، وأُخِذ من التتار أربعة، وعاد كل من الفريقين إلى موضعه فوسط الأربعة على أبواب مدينة حلب، وأما دمشق فإن أهلها بدؤوا يتجهزون والقضاة تحرِّضُ الناس على الجهاد ضدَّ تيمورلنك، وأما عساكر مصر فبدأت كذلك بالتجهز، قال تقي الدين المقريزي: \"لما نزل تيمورلنك على عينتاب بعث إلى دمرداش نائب حلب يعده باستمراره في نيابة حلب، ويأمره بمسك الأمير سودن نائب الشام، فلما قدم عليه الرسول بذلك أحضره إلى نواب ممالك الشام، وقد حضروا إلى حلب وهم: سودن نائب دمشق، وشيخ المحمودي نائب طرابلس، ودقماق نائب حماة، وألطنبغا العثماني نائب صفد، وعمر بن الطحان نائب غزة بعساكرها، فاجتمع منهم بحلب نحو ثلاثة آلاف فارس منهم عسكر دمشق ثمانمائة فارس، إلا أن الأهواء مختلفة، والآراء مفلولة، والعزائم محلولة، والأمر مدبَّر، فبلغ رسول تيمورلنك الرسالة دمرداش، فأنكر مَسْكَ سودن نائب دمشق، فقال له الرسول: إن الأمير - يعني تيمورلنك- لم يأت إلا بمكاتبتك إليه، وأنت تستدعيه أن ينزل على حلب، وأعلمته أن البلاد ليس بها أحد يدفع عنها، فحنق منه دمرداش وقام إليه وضربه، ثم أمر به فضُرِبَت رقبته، ويقال: إن كلام هذا الرسول كان من تنميق تيمورلنك ومَكْرِه، ليفَرِّقَ بذلك بين العساكر\" ونزل تيمورلنك على جبلان خارج حلب يوم الخميس تاسع ربيع الأول، وزحف يوم الجمعة، وأحاط بسور حلب، وكانت بين الحلبيين وبينه في هذين اليومين حروب، فلما أشرقت الشمس يوم السبت الحادي عشر خرج نواب الشام بالعساكر وعامة أهل حلب إلى ظاهر المدينة وعبُّوا للقتال، ووقف سودن نائب دمشق في الميمنة، ودمرداش في الميسرة، وبقية النواب في القلب، وقدموا أمامهم عامة أهل حلب، فزحف تيمورلنك بجيوش قد سدَّت الفضاء، فثبت الأمير شيخ المحمودي نائب طرابلس، وقاتل -هو وسودن نائب دمشق- قتالًا عظيمًا، وبرز الأمير عز الدين أزدمر أخو أينال اليوسفي، وولده يشبك ابن أزدمر في عدة من الفرسان، وأبلوا بلاء عظيمًا، وظهر عن أزدمر وولده من الإقدام ما تعجَّب منه كل أحد، وقاتلا قتالًا عظيمًا، فقُتل أزدمر وفُقد خبره، وثخنت جراحات يشبك، وصار في رأسه فقط زيادة على ثلاثين ضربة بالسيف سوى ما في بدنه، فسقط بين القتلى، ثم أُخِذ وحمل إلى تيمورلنك ولم يمضِ غير ساعة حتى ولَّت العساكر تريد المدينة، وركب أصحاب تيمورلنك أقفيتَهم، فهلك تحت حوافر الخيل من الناس عدد لا يدخل تحت حصر؛ فإن أهل حلب خرجوا حتى النساء والصبيان، وازدحم الناسُ مع ذلك في دخولهم من أبواب المدينة، وداس بعضُهم بعضًا، حتى صارت الرمم طول قامة، والناس تمشي من فوقها، وتعلَّق نواب المماليك بقلعة حلب، ودخل معهم كثيرٌ من الناس، وكانوا قبل ذلك قد نَقَلوا إلى القلعة سائر أموال الناس بحلب، واقتحمت عساكر تيمورلنك المدينةَ وأشعلوا بها النيران، وجالوا بها ينهبون ويأسرون ويقتلون، واجتمع بالجامع وبقية المساجد نساءُ البلد، فمال أصحاب تيمورلنك عليهنَّ وربطوهن بالحبال، ووضعوا السيف في الأطفال فقتلوهم بأجمعِهم، وأتت النار على عامة المدينة فأحرقتها، وصارت الأبكار تُفتَضَّ من غير تستُّرٍ ولا احتشام! بل يأخذ الواحد الواحدة ويعلوها في المسجد والجامع، بحضرة الجم الغفير من أصحابه، ومن أهل حلب، فيراها أبوها وأخوها ولا يقدِرُ أن يدفع عنها؛ لِشُغلِه بنفسِه، وفَحُش القتل، وامتلأ الجامع والطرقات برمم القتلى، واستمر هذا الخطب من صحوة نهار السبت إلى يوم الثلاثاء، والقلعة قد نقب عليها من عدة أماكن، ورُدِم خندقها، ولم يبقَ إلا أن تؤخذ، فطلب النواب الأمان، ونزل دمرداش إلى تيمورلنك فخلع عليه ودفع إليه أمانًا، وخِلَعًا للنواب، وبعث معه عدَّةً وافرة إلى النواب، فأخرجوهم ممن معهم، وجعلوا كل اثنين في قيد وأحضروا إليه، فقرعهم ووبَّخهم، ودفع كل واحد منهم إلى من يحتفظ به، وسيقت إليه نساء حلب سبايا، وأُحضرت إليه الأموال ففرَّقها على أمرائه، واستمرَّ بحلب شهرًا، والنهب في القرى لا يبطل، مع قطع الأشجار وهدم البيوت، وجافت حلب وظواهرها من القتلى، بحيث صارت الأرض منهم فراشًا، لا يجِدُ أحد مكانًا يمشي عليه إلا وتحت رجليه رمةُ قتيل، وعُمِل من الرؤوس منابر عدة مرتفعة في السماء نحو عشرة أذرع في دور عشرين ذراعًا، حُرِز ما فيها من رؤوس بني آدم، فكان زيادة على عشرين ألف رأس! وجعلت الوجوه بارزة يراها من يمرُّ بها، ثم رحل تيمورلنك عنها، وهي خاوية على عروشها، خالية من ساكنها وأنيسها، قد تعطلت من الأذان، وإقامة الصلوات، وأصبحت مُظلِمةً بالحريق، مُوحِشةٌ قَفراءُ مُغبرة، لا يأويها إلا الرخم، ثم بعد أن رحل الجيش عنها سائرًا إلى جهة دمشق ورد الخبر أن أحمد بن رمضان التركماني، وابن صاحب الباز، وأولاد شهري، ساروا وأخذوا حلب، وقتلوا من بها من أصحاب تيمورلنك وهم زيادة على ثلاثة آلاف فارس."},{"id":3228,"title":"وفاة الملك الأشرف إسماعيل صاحب اليمن وتولي ابنه الناصر .","date":["العام الهجري :803","الشهر القمري : ربيع الأول","العام الميلادي :1400"],"text":"هو المَلِكُ الأشرَفُ إسماعيلُ بنُ الأفضلِ عباسِ بن المجاهد علي بن المؤيد داود بن المظفر يوسف بن منصور عمر بن علي بن رسول، وَلِيَ سَلطنة اليمن بعد أبيه في سنة 778، حتى مات، وكان حليمًا، كثير السَّخاء، مُقبلًا على العلم، محبًّا للغرباء، وصنَّف تاريخًا لليمن، توفِّيَ في ليلة السبت ثامن عشر ربيع الأول، بمدينة تَعْز من بلاد اليمن، عن سبع وثلاثين سنة، وقام بمملكة اليمن بعده ابنُه الملك الناصر أحمد."},{"id":3229,"title":"جيش تيمورلنك يدخل حماة ويقتل أهلها ويخربها .","date":["العام الهجري :803","الشهر القمري : ربيع الأول","العام الميلادي :1400"],"text":"نزل مرزه شاه بن تيمورلنك على مدينة حماة بكرة يوم الثلاثاء رابع عشر ربيع الأول، وأحاط بسورها، ونهب المدينة، وسبى النساء والأطفال، وأسر الرجال، ووقع أصحابه على النساء يطؤونهن ويفتضُّون الأبكارَ جهارًا من غير استتار وخرَّبوا جميعَ ما خرج عن السور، وقد ركب أهل البلد السور، وامتنعوا بالمدينة، وباتوا على ذلك، فلما أصبحوا يوم الأربعاء فتحوا بابًا واحدًا من أبواب المدينة، ودخل ابنُ تيمورلنك في قليلٍ من أصحابه ونادى بالأمان، فقَدَّمَ الناس إليه أنواع المطاعم فقَبِلَها، وعزم أن يقيم رجلًا من أصحابه على حماة، فقيل له: إن الأعيان قد خرجوا منها، فخرج إلى مخيمه، وبات به، ودخل يوم الخميس ووعد الناس بخير وخرج، ومع ذلك فإن القلعة ممتنعة عليه، فلما كان ليلة الجمعة نزل أهل القلعة إلى المدينة وقتلوا من أصحاب مرزه شاه رجلين كانا أقرَّهما بالمدينة، فغضب من ذلك وأشعل النار في أرجاء البلد، واقتحمها أصحابه يقتلون ويأسرون وينهبون، حتى صارت كمدينة حلب: سوداء، مغبرة، خالية من الأنيس!"},{"id":3230,"title":"تيمورلنك يدمر مدينة دمشق ويذبح أهلها .","date":["العام الهجري :803","الشهر القمري : جمادى الأولى","العام الميلادي :1401"],"text":"لما قدم خبر أخْذ حلب وما ارتكبه المغول في أهلها نودِيَ بدمشق في الناس بالتحوُّل إلى المدينة والاستعداد للعدوِّ، فاختبط الناس وعظُم ضجيجهم وبكاؤهم، وأخذوا ينتقلون في يوم الأربعاء نصفه من حوالي المدينة إلى داخلها، واجتمع الأعيانُ للنظر في حفظ المدينة، فقدم في سابع عشر ربيع الأول المنهزمون من حماة، فعظُمَ الخوف، وهمَّ الناس بالجلاء، فمُنِعوا منه، ونودِيَ: من سافر نُهب، فورد في الثامن العشر منه الخبر بنزول طائفة من العدو على حماة، فحُصِّنت مدينة دمشق، ووقف الناسُ على الأسوار، وقد استعدُّوا، ونُصِبت المجانيق على القلعة، وشُحِنت بالزاد، وهمَّ نائب الغيبة بالفرار، ولكن العامة ردته ردًّا قبيحًا، وهاج الناس وماجوا ونادوا بتسليم البلد من غير قتال، وكل هذا وعسكر مصر لم يخرجُ منها بعدُ، ثم في ربيع الآخر بدأ جيش مصر بالخروج منها متوجِّهين إلى دمشق، هذا وجيش تيمورلنك قد وصل قريبًا من حمص؛ فبدأ الناس بالهرب وخاصة أن أهل بعلبك أيضًا هربوا لنزول تيمورلنك عليهم، ثم في سادس جمادى الأولى قدم السلطان دمشق بعساكره، وقد وصل أصحاب تيمورلنك إلى البقاع، وفي يوم السبت الخامس عشر من هذا الشهر نزل تيمورلنك إلى قطا، فملأت جيوشه الأرض، وركب طائفةٌ منهم إلى العسكر وقاتلوهم، فخرج السلطان من دمشق يوم الثلاثاء الثامن عشر إلى يلبغا، فكانت وقعة انكسرت ميسرةُ العسكر، وانهزم أولاد الغزاوي وغيرهم إلى ناحية حوران، وجُرح جماعة، وحَمل تيمورلنك حملةً منكرة؛ ليأخُذَ بها دمشق، فدفعته عساكِرُ السلطان، ونزل كلٌّ من العسكرين بمعسكره، وبعث تيمورلنك إلى السلطان في طلب الصلح وإرسال أطلمش أحد أصحابه إليه، وأنه هو أيضًا يبعث من عنده من الأمراء المقبوض عليهم في وقعة حلب، فأشار تغري بردي ودمرداش وقطلوبغا الكركي في قبول ذلك؛ لما يعرفون من اختلاف كلمتهم، لا لضعف عسكرهم، فلم يقبلوا وأبوا إلا القتال، ثم أرسل تيمور رسولًا آخر في طلب الصلح وكرَّر القول ثانيًا، وظهر للأمراء ولجميع العساكر صحةُ مقالته، وأن ذلك على حقيقتِه، فأبى الأمراء ذلك، هذا والقتال مستمرٌّ بين الفريقين في كل يوم، فلما كان ثاني عشر جمادى الآخرة اختفى من أمراء مصر والمماليك السلطانية جماعة، منهم الأمير سودون الطيار، وقاني باي العلائي رأس نوبة، وجمق، ومن الخاصكية يشبك العثماني، وقمش الحافظي، وبرسبغا الدوادار، وطرباي، في جماعة أخر، فوقع الاختلافُ عند ذلك بين الأمراء، وعادوا إلى ما كانوا عليه من التشاحُن في الوظائف والإقطاعات والتحكُّم في الدولة، وتركوا أمر تيمورلنك كأنه لم يكن، وأخذوا في الكلام فيما بينهم بسببِ من اختفى من الأمراء وغيرهم، هذا وتيمورلنك في غاية الاجتهاد في أخذ دمشق، وفي عمل الحيلة في ذلك، ثم أُعلِمَ بما الأمراء فيه، فقَوِيَ أمرُه واجتهاده بعد أن كان عزم على الرحيل، واستعدَّ لذلك، فلما كان آخر ليلة الجمعة الحادي والعشرين جمادى الأولى ركب الأمراء وأخذوا السلطان الملك الناصر فرج على حين غفلة، وساروا به من غير أن يعلم العسكر به مِن على عقبة عمر يريدون الديارَ المصرية، وتركوا العساكِرَ والرعية من المسلمين غَنَمًا بلا راعٍ، وأما بقية أمراء مصر وأعيانها من القضاة وغيرهم لما علموا بخروج السلطان من دمشق خرجوا في الحال في إثره طوائف طوائف يريدون اللحاق بالسلطان، فأخذ غالبهم العشير وسلبوهم، وقتلوا منهم خلقًا كثيرًا، وأما العساكر الذين خُلِّفوا بدمشق من أهل دمشق وغيرها، فإنه كان اجتمع بها خلائق كثيرة من الحلبيين والحمويين والحمصيين وأهل القرى ممن خرج جافلًا من تيمور، ولما أصبحوا يوم الجمعة، وقد فقدوا السلطانَ والأمراء والنائب، غلَّقوا أبواب دمشق، وركبوا أسوار البلد، ونادَوا بالجهاد، فتهيَّأ أهل دمشق للقتال وزحف عليهم تيمورلنك بعساكره، فقاتله الدمشقيون من أعلى السور أشدَّ قتال، وردوهم عن السور والخندق، وأسروا منهم جماعة ممن كان اقتحم باب دمشق، وأخذوا من خيولِهم عدَّةً كبيرة، وقتلوا منهم نحو الألف، وأدخلوا رؤوسهم إلى المدينة، وصار أمرُهم في زيادة، فأعيا تيمورلنك أمرهم، وعلم أن الأمر يطول عليه، فأخذ في مخادعتهم، وعمل الحيلة في أخذِ دمشق منهم، وبينما أهل دمشق في أشدِّ ما يكون من القتال والاجتهاد في تحصين بلدهم، قَدِمَ عليهم رجلان من أصحاب تيمورلنك من تحت السور وصاحا مِن بُعدٍ: الأميرُ يريد الصلح، فابعثوا رجلًا عاقلًا حتى يحدِّثَه الأمير في ذلك، ولما سمع أهل دمشق كلام أصحاب تيمورلنك في الصلح وقع اختيارُهم في إرسال قاضي القضاة تقي الدين إبراهيم بن مفلح الحنبلي، فأرخى من سور دمشق إلى الأرض، وتوجَّه إلى تيمورلنك واجتمع به وعاد إلى دمشق وقد خدعه تيمورلنك بتنميق كلامه، وتلطَّف معه في القول، وترفَّق له في الكلام، وقال له: هذه بلدة الأنبياء والصحابة وقد أعتقتُها لرسول الله صلى الله عليه وسلم صدقةً عني وعن أولادي، ولولا حنقي من سودون نائب دمشق عند قتله لرسولي ما أتيتُها، وقد صار سودون المذكور في قبضتي وفي أسري، وقد كان الغرض في مجيئي إلى هنا، ولم يبقَ لي الآن غرض إلا العود، ولكِنْ لا بد من أخذ عادتي من التقدمة من الطقزات، وكانت هذه عادته: إذا أخذ مدينةً صلحًا يُخرِجُ إليه أهلها من كل نوع من أنواع المأكول والمشروب والدواب والملابس والتحف تسعة؛ يسمون ذلك طقزات، والطقز باللغة التركية: تسعةٌ، وهذه عادة ملوك التتار، فعاد ابن مفلح يثني على تيمورلنك ويحثُّ الناس على عدم القتال وإعطائِه ما يريد، وكاد يحصل بسبب ذلك فتنةٌ إلى أن جمع ابن مفلح ما يريده تيمورلنك وحمله إليه وعاد هو ومن معه ومعهم فرمان من تيمورلنك لهم، وهو ورقة فيها تسعة أسطر يتضمن أمانَ أهل دمشق على أنفُسِهم وأهليهم خاصة؛ فقرئ الفرمان المذكور على منبر جامع بني أمية بدمشق، وفُتح من أبواب دمشق باب الصغير فقط، وقدم أمير من أمراء تيمور جلس فيه لِيَحفَظَ البلد ممن يعبر إليها من عساكر تيمور، فمشى ذلك على الشاميين وفرحوا به، لكن تيمورلنك لم يرضَ بالمال الذي أُحضِرَ له، بل طلب أضعافه، فحصل من الغلاء في دمشق ما لا يُصَدَّق بسبب ذلك، ثم إن الجمعة قد دُعِيَ فيها لابن تيمورلنك في الخطبة، ثم قدم شاه ملك أحد أمراء تيمورلنك إلى مدينة دمشق على أنه نائبها من قِبَل تيمور، ثم بعد جمعتين منعوا من إقامة الجمعة بدمشق لكثرة غلبة أصحاب تيمورلنك بدمشق، كل ذلك ونائب القلعة ممتنع بقلعة دمشق، وأعوان تيمورلنك تحاصِرُه أشد حصار، حتى سَلَّمها بعد تسعة وعشرين يومًا، وقد رمي عليها بمدافع ومكاحل لا تدخل تحت حصر، هذا وليس بالقلعة المذكورة من المقاتلة إلا نفر قليل دون الأربعين نفرًا، وطال عليهم الأمر، ويئسوا من النجدة، وطلبوا الأمان، وسلموها بالأمان، وكان تيمورلنك لما اتفق أولًا مع ابن مفلح على ألف ألف دينار يكون ذلك على أهل دمشق خاصة، والذي تركته العساكر المصرية من السلاح والأموال يكون لتيمور، فخرج إليه ابن مفلح بأموال أهل مصر جميعها، فلما صارت كلها إليه وعلم أنه استولى على أموال المصريين ألزمهم بإخراج أموال الذين فرُّوا من دمشق، فسارعوا أيضًا إلى حمل ذلك كله، وتدافعوا عنده حتى خلص المال جميعه، فلما كمل ذلك ألزمهم أن يخرجوا إليه جميع ما في البلد من السلاح: جليلِها وحقيرِها، فتتبعوا ذلك وأخرجوه له حتى لم يبقَ بها من السلاح شيءٌ، فلما فرغ ذلك كله قبض على ابن مفلح ورفقته، وألزمهم أن يكتبوا له جميعَ خِطَط دمشق وحاراتها وسككها، فكتبوا فلكًا ودفعوه إليه، ففرقه على أمرائه، وقسم البلد بينهم، فساروا إليها بمماليكهم وحواشيهم، ونزل كل أمير في قسمه، وطلب من فيه، وطالبهم بالأموال، فحينئذ حلَّ بأهل دمشق من البلاء ما لا يوصف، وأجرى عليهم أنواع العذاب من الضرب والعصر والإحراق بالنار، والتعليق منكوسًا، وغم الأنف بخرقة فيها تراب ناعم، كلما تنفَّس دخل في أنفه حتى تكاد نفسُه تُزهَق؛ فكان الرجل إذا أشرف على الهلاك يخلَّى عنه حتى يستريح، ثم تعاد عليه العقوبة أنواعًا، فكان المعاقَبُ يحسُدُ رفيقَه الذي هلك تحت العقوبة على الموت، ويقول: ليتني أموت وأستريح مما أنا فيه! ومع هذا تؤخذ نساؤه وبناته وأولاده الذكور، وتُقَسَّم جميعهم على أصحاب ذلك الأمير، فيشاهد الرجل المعذَّب امرأته أو بنته وهي توطأ، وولده وهو يلاطُ به، فيصرخ هو من ألم العذاب، والبنت والولد يصرخان من إزالة البكارة واللواط!! وكل ذلك من غير تستُّر في النهار بحضرة الملأ من الناس، ورأى أهل دمشق أنواعًا من العذاب لم يُسمَع بمثلها، واستمرَّ هذا البلاء والعذاب بأهل دمشق تسعة عشر يومًا، آخرها يوم الثلاثاء ثامن عشرين شهر رجب، فهلك في هذه المدة بدمشق بالعقوبة والجوع خلق لا يعلم عددَهم إلا الله تعالى، فلما علم أمراء تيمورلنك أنه لم يبق بالمدينة شيء، خرجوا إلى تيمورلنك فسألهم هل بقي لكم تعلُّق في دمشق؟ فقالوا: لا، فأنعم عند ذلك بمدينة دمشق أتباع الأمراء، فدخلوها يوم الأربعاء آخر رجب، ومعهم سيوف مسلولة مشهورة وهم مشاة، فنهبوا ما قدروا عليه من آلات الحرب وغيرها، وسبَوا نساء دمشق وساقوا الأولاد والرجال، وتركوا من الصغار مَن عُمُره خمس سنين فما دونها، وساقوا الجميعَ مربوطين في الحبال، ثم طرحوا النار في المنازل والدور والمساجد، وكان يومًا عاصف الريح، فعم الحريقُ جميع البلد حتى صار لهيب النار يكاد أن يرتفع إلى السحاب، وعملت النار في البلد ثلاثة أيام بلياليها آخرها يوم الجمعة، وكان تيمورلنك -لعنه الله- سار من دمشق في يوم السبت ثالث شهر شعبان بعدما أقام على دمشق ثمانين يومًا، وقد احترقت كلها وسقطت سقوف جامع بني أمية من الحريق، وزالت أبوابه وتفطَّر رخامه، ولم يبق غيرُ جُدُرِه قائمة، وذهبت مساجد دمشق ودورها وقياسرها وحماماتها وصارت أطلالًا بالية ورسومًا خالية، ولم يبقَ بها دابة تدب إلا أطفال يتجاوز عددهم آلاف، فيهم من مات، وفيهم من سيموت من الجوع!!"},{"id":3231,"title":"تيمورلنك يدخل بغداد ويقتل أهلها ويخربها .","date":["العام الهجري :803","الشهر القمري : ذي الحجة","العام الميلادي :1401"],"text":"كان رحيل تيمورلنك عن دمشق في يوم السبت ثالث شعبان من هذه السنة واجتاز على حلب وفعل بها ما قدر عليه ثانيًا، ثم سار منها حتى نزل على ماردين يوم الاثنين عاشر شهر رمضان من السنة، ووقع له بها أمور، ثم رحل عنها، وأوهم أنه يريد سمرقند، يورِّي بذلك عن بغداد، وكان السلطان أحمد بن أويس قد استناب ببغداد أميرًا يقال له فرج، وتوجَّه هو وقرا يوسف نحو بلاد الروم، فندب تيمور على حين غفلة أمير زاده رستم ومعه عشرون ألفًا لأخذِ بغداد، ثم تبعه بمن بقي معه ونزل على بغداد، وحصرها حتى أخذها عنوةً في يوم عيد النحر من السنة، ووضع السيف في أهل بغداد، لما استولى على بغداد ألزم جميعَ من معه أن يأتيَه كل واحد منهم برأسين من رؤوس أهل بغداد؛ فوقع القتل في أهل بغداد وأعمالها، حتى سالت الدماء أنهارًا، حتى أتوه بما أراد، فبنى من هذه الرؤوس مائة وعشرين مِئذنة، فكانت عدة من قُتِل في هذا اليوم من أهل بغداد تقريبًا مائة ألف إنسان, وقيل: تسعين ألف إنسان، وهذا سوى من قُتِل في أيام الحصار، وسوى من قُتِل في يوم دخول تيمور إلى بغداد، وسوى من ألقى نفسَه في نهر دجلة فغرق، وهو أكثر من ذلك! قال: وكان الرجل المرسوم له بإحضار رأسين إذا عجز عن رأس رجل قطع رأس امرأةٍ من النساء وأزال شعرَها وأحضرها، قال: وكان بعضُهم يقِفُ بالطرقات ويصطاد من مَرَّ به ويقطع رأسَه، ثم رحل تيمور عن بغداد وسار حتى نزل قراباغ بعد أن جعلها دكًّا خرابًا."},{"id":3232,"title":"الصلح بين تيمورلنك والسلطان فرج بن برقوق .","date":["العام الهجري :804","العام الميلادي :1401"],"text":"بعد أن تمَّ للمغول بقيادة تيمورلنك تدميرُ مدن الشام، أرسل تهديداتِه للسلطان فرج بن برقوق سلطان المماليك في مصر، وكان قد أسر أميرًا من المغول يدعى (أطلمس) فطالب تيمورلنك بإطلاق سراحه فورًا، وإلا فسيزحف المغول على مصر ويرفعون راياتهم على ربوعها. وقد أذعن السلطان فرج لهذه التهديدات، وأطلق سراح أطلمس وعقد صلحًا مع تيمورلنك يتعهد فيه السلطان فرج بطاعة تيمورلنك والدعوة باسمه في مساجد مصر، وقد أدى هذا الصلح المُهين إلى ذهاب حرمة دولة المماليك، واختفاء احترام الأمراء والعامة للسلطان فرج، فلم تمضِ سنوات ثلاث حتى عُزل. والواقِعُ أن هزائم دولة المماليك الثانية في عهد فرج بن برقوق تعتبر أقسى الهزائم التي تعرض لها المسلمون في تلك الفترة؛ بسبب تصارع المماليك المتعصبين لأصولهم العِرْقية."},{"id":3233,"title":"نائب الشام تغري بردي يعصي على السلطان وينضم له نائب حلب .","date":["العام الهجري :804","الشهر القمري : محرم","العام الميلادي :1401"],"text":"كان قد رُسِم لتغري بردي بنيابة دمشق، ثم في محرم سنة 804 كتب الأمراء بمصر لأمراء دمشق بالقبض على الأمير تغري بردي، فكَتَب له بذلك بعضُ أعيان أمراء مصر، فسبق كتابُه كتابَ الأمراء، فركب من دار السعادة بدمشق في نفرٍ من مماليكه في ليلة الجمعة ثاني عشرين المحرم وخرج إلى حلب، فتعيَّن لنيابة دمشق عوضًا عنه الأمير آقبغا الجمالي الأطروش أتابك دمشق، وكتب بانتقال دقماق نائب صفد إلى نيابة حلب عوضًا عن دمرداش المحمدي بحُكم عصيانه وانضمامه إلى تغري بردي لَمَّا قدم عليه من دمشق، واستقر الأمير تمربغا المنجكي في نيابة صفد عوضًا عن دقماق، وأما تغري بردي فإنه لما سار إلى حلب وجد الأمير دمرداش نائب حلب قد قبض على الأمير خليل بن قراجا بن دلغادر أمير التركمان، فأمره تغري بردي بإطلاقه، فأطلقه، واتفق الجميعُ على الخروج عن طاعة السلطان بسبب مَن حوله من الأمراء، واجتمع عليهم خلائِقُ من التركمان وغيرهم؛ فإن دقماق جمع جموعَه من العساكر والتركمان لقتال تغري بردي ودمرداش نائب حلب، وسار إلى جهة حلب، فخرج إليه تغري بردي وعلى مقدمته دمرداش، وصدموه صدمة واحدة انكسر فيها بجموعه وولَّوا الأدبار، ونهب ما معهم، وعاد دقماق منهزمًا إلى دمشق، واستنجد بنائبها الأمير آقبغا الجمالي الأطروش، وكتب أيضًا دقماق لجميع نواب البلاد الشامية بالحضور والقيام بنصرة السلطان، وجمع من التركمان والعربان جمعًا كبيرًا، وخرج معه غالب العساكر الشامية، وعاد إلى جهة حلب بعساكر عظيمة، وتغري بردي ودمرداش في مماليكهم لا غير، مع جدب البلاد الحلبية، وخراب قراها؛ فإنه كان عقيب توجه تيمورلنك بسنة واحدة وأشهر، فلما قارب دقماق بعساكره حلب أشار دمرداش على تغري بردي بالتوجه إلى بلاد التركمان من غير قتال، فقال تغري بردي: لا بد من قتالنا معه، فإن انتصرنا وإلا توجهنا إلى بلاد التركمان بحقٍّ، فبرزا لدقماق بمماليكهما، وقد صفَّ دقماق عساكره، واقتتلا قتالًا شديدًا، وثبت كل من الفريقين، وقد أشرف دقماق على الهزيمة، وبينما هو في ذلك خرج من عسكر تغري بردي ودمرداش جماعة إلى دقماق، فانكسرت عند ذلك الميمنة، ثم انهزم الجميع إلى نحو بلاد التركمان، فلم يتبعهم أحد من عساكر دقماق، وملك دقماق حلب، واستمر تغري بردي ودمرداش ببلاد التركمان، وكانت الأخبار وردت بجمع التركمان ونزولهم مع دمرداش إلى حلب، وأن دقماق نائب حلب اجتمع معه نائب حماة والأمير نعير، ثم في السنة التالية في محرم قدم تغري بردي إلى دمشق بأمان كان كُتِبَ له من قِبَل السلطان مع كُتُب جميع الأمراء، وقد فارق دمرداش ورغب في الطاعة، ثم انتقل منها إلى مصر فوصلها في آخر الشهر."},{"id":3234,"title":"مراكب للفرنج تهاجم شاطئ طرابلس .","date":["العام الهجري :804","الشهر القمري : صفر","العام الميلادي :1401"],"text":"قَدِمَ إلى طرابلس يوم الاثنين العاشر من صفر مركب فيه عدةٌ من الفرنج، فخرج الناسُ لحربهم، وكان بالميناء مراكِبُ لتجَّار الفرنج، فاجتمعوا على مراكب المسلمين التي قد شُحِنَت بالبضائع لتسيرَ إلى أرض، وأخذوا منها مركبين فيهما مال كبير، وأسروا خمسة وثمانين مسلمًا بعدما قاتلوا قتالًا شديدًا وغرق جماعةٌ وفرَّ جماعة، وأصبحوا من الغدِ على الحرب، فوقع الاتفاقُ على فكاك من أسروه بمالٍ يُحمَلُ إليهم، فلما حُمِل إليهم بعضُ المال أسروا الرجلَ، ومضوا في ليلة الخميس الخامس عشر، ونزلوا على قرية هناك فقاتلهم أميرُها، وقبضهم وجاء بهم إلى طرابلس، فسُجِنوا، وأخذ المسلمون مركَبَهم."},{"id":3235,"title":"وفاة سراج الدين ابن الملقن .","date":["العام الهجري :804","الشهر القمري : ربيع الأول","العام الميلادي :1401"],"text":"هو سراج الدين أبو حفص عمر بن علي بن أحمد الأنصاري المشهور بابن الملقِّن، ولد بالقاهرة سنة 723 عُرِفَ ابن الملقن؛ لأن الذي كفَلَه بعد وفاة أبيه مُلَقِّن القرآن في الجامع الطولوني بالقاهرة، فعُرِفَ به، فصار يقال: ابنُ المُلَقِّن، وكان هو زوجَ أمِّه، وهو الذي ربَّاه، فأصبح من كبار علماء الحديث والفقه الشافعي، فتولى قضاء الشافعية، ثم التدريس والإفتاء، له مصنفات عديدة؛ منها: إكمال تهذيب الكمال، وله البدر المنير في تخريج أحاديث الرافعي الكبير، وله تحفة المحتاج في أدلة المنهاج، وله التذكرة في علوم الحديث، وله طبقات الأولياء، وله الإعلام بفوائد عمدة الأحكام، وله غاية السول في خصائص الرسول، وغيرها كثير، وكانت له مكتبة عامرة، ولكنها احترقت؛ فأصابه بسبب ذلك ذهولٌ فحَجَبه ابنُه حتى توفِّي عن 81 عامًا."},{"id":3236,"title":"الفتنة بين الأمراء في مصر وقتالهم بين بعضهم .","date":["العام الهجري :804","الشهر القمري : شوال","العام الميلادي :1402"],"text":"كثُرَ تنافرُ الأمراء واختلافهم، وانقطع نوروز، وجكم الجركسي الظاهري، وقنباي، عن الخدمة، ودخل شهر رمضان وانقضى، فلم يحضروا للهناء بالعيد، ولا صلَّوا صلاة العيد مع السلطان، فلما كان يوم الجمعة ثاني شوال ركبوا للحرب، فنزل السلطان من القصر إلى الإسطبل عند سودن طاز، وركب نوروز وجكم وقنباي، وقرقماس الرماح، ووقعت الحربُ من بكرة النهار إلى العصر، ورأس الأمراءَ نوروز وجكم، وخصمهم سودن طاز، فلما كان آخر النهار بعث السلطان بالخليفةِ المتوكل على الله وقضاة القضاة الأربع إلى الأمير الكبير نوروز في طلب الصلح، فلم يجد بدًّا من ذلك، وترك القتال، وخلع عنه آلة الحرب، فكفَّ الأمير جكم الدوادار أيضًا عن الحرب، وعد ذلك مكيدةً من سودن طاز، فإنه خاف أن يغلِبَ ويُسَلِّمَه السلطان إلى الأمراء، فأشار عليه بذلك حتى فعله، فتمَّت مكيدته بعدما كاد أن يؤخذ؛ لقوة نوروز وجكم عليه، وبات الناس في هدوء، فلما كان يوم السبت الغد ركب الخليفة وشيخ الإسلام البلقيني، وحلَّفوا الأمراء بالسمع والطاعة للسلطان، وإخماد الفتنة، فطلع الأمير نوروز إلى الخدمة في يوم الاثنين خامسه، وخُلِعَ عليه، وأُركِبَ فرسًا خاصًّا بسرج، وكنفوش ذهب، وطلع الأمير جكم في ثامنه وهو خائف، ولم يطلع قنباي، ولا قرقماس، وطُلِبا فلم يُوجَدا، وجُهِّز إليهما خلعتان، على أن يكون قنباي نائبًا بحماة، وقرقماس حاجبًا بدمشق، ونزل جكم بغير خِلعة حنقًا وغضبًا، فما هو إلا أن استقر في داره، ونزل إليه سرماش رأس نوبة، وبشباي الحاجب بطلب قنباي، ظنًّا أنه اختفى ليلبس الخلعة بنيابة حماة، فأنكر أن يكون عنده وصرفهما، وركب من ليلته بمن معه من الأمراء والمماليك وأعيانهم قمش الخاصكي الخازندار، ويشبك الساقي، ويشبك العثماني، وألطبغا جاموس، وجانباي الطيبي، وبرسبغا الدوادار، وطرباي الدوادار، وصاروا كلهم على بركة الحبش خارج مصر، ولحق به الأمير قنباي، وقرقماس الرماح، وأرغز، وغنجق، ونحو الخمسمائة من مماليك السلطان، وأقاموا إلى ليلة السبت عاشره، فأتاهم الأمير نوروز، والأمير سودن من زاده رأس نوبة، والأمير تمربغا المشطوب، في نحو الألفين، فسُرَّ بهم، وأقاموا جميعًا إلى ليلة الأربعاء، وأمرُهم يزيد ويقوى بمن يأتيهم من الأمراء والمماليك، فنزل السلطان من القصر في ليلة الأربعاء الرابع عشر إلى الإسطبل عند سودن طاز، وركب بكرةَ يوم الأربعاء فيمن معه، وسار من باب القرافة بعد ما نادى بالعرض، واجتمع إليه العسكر كله، وواقع جكم ونوروز، وكسرهما، وأسَرَ تمربغا المشطوب، وسودن من زاده، وعلى بن أينال، وأرغر، وفرَّ نوروز وجكم في عدة كبيرة يريدون بلاد الصعيد، وعاد السلطان ومعه الأمير سودن طاز إلى القلعة مُظفَّرًا منصورًا، وبعث بالأمراء المأسورين إلى الإسكندرية في ليلة السبت السابع عشر، وانتهى نوروز وجكم إلى منية القائد وعادوا إلى طموه، ونزلوا على ناحية منبابه من بر الجيزة تجاه القاهرة، فمنع السلطان المراكبَ أن تعديَ بأحدٍ منهم في النيل، وطلب الأمير يشبك الشعباني من الإسكندرية، فقدم يوم الاثنين التاسع عشر إلى قلعة الجبل، ومعه عالم كبير ممن خرج إلى لقائه، فباس الأرض ونزل إلى داره، وفي ليلة الثلاثاء عِشرينه: ركب الأمير نوروز نصف الليل، وعدى النيل، وحضر إلى بيت الأمير الكبير بيبرس الأتابك، وكان قد تحدَّث هو والأمير إينال باي بن قجماس له مع السلطان، حتى أمنه ووعده بنيابة دمشق، وكان ذلك من مكر سودن طاز، فمشى ذلك عليه، حتى حضر فاختلَّ عند ذلك أمر جكم وتفرَّق عنه من معه، وفرَّ عنه قنباي وصار فريدًا، فكتب إلى الأمير بيبرس الأتابك يستأذنه في الحضور، فبعث إليه الأمير أزبك الأشقر رأس نوبة، والأمير بشباي الحاجب، وقدما به ليلة الأربعاء في الحادي والعشرين إلى باب السلسلة من الإسطبل السلطاني، فتسلَّمه عدوه الأمير سودن طاز وأصبح وقد حضر يشبك وسائر الأمراء للسلام عليه، فلما كانت ليلة الخميس الثاني والعشرين قُيِّدَ وحمل في الحراقة -سفينة- إلى الإسكندرية، فسُجِن بها حيث كان الأمير يشبك مسجونًا، وفي يوم الخميس هذا خرج المحمَلُ وأمير الحاج نكباي الأزدمري، أحد أمراء الطبلخاناه، وكان قد ألبس الأمير نوروز تشريف نيابة دمشق في بيت الأمير بيبرس يوم الأربعاء، فقُبِض عليه من الغد يوم الخميس، وحُمل إلى باب السلسلة، وقُيِّد وأخرج في ليلة الجمعة الثالث والعشرين إلى الإسكندرية، فسُجِن بها أيضًا، وغضب الأميران بيبرس وإينال باي، وتركا الخدمة السلطانية أيامًا، ثم أُرضيا، واختفى الأميران قانباي وقرقماس، فلم يُعرَف خبرهما."},{"id":3237,"title":"معركة أنقرة  وأسر تيمورلنك السلطان بايزيد الأول  .","date":["العام الهجري :804","الشهر القمري : ذي الحجة","العام الميلادي :1402"],"text":"بعد أن رحل تيمورلنك من بغداد كتب إلى بايزيد الأول صاحب الروم أن يخرجَ السلطان أحمد بن أويس وقرا يوسف من ممالك الروم وإلا قصده وأنزل به ما نزل بغيره، فردَّ بايزيد جوابه بلفظ خَشِنٍ إلى الغاية، فسار تيمور إلى نحوه، فجمع بايزيد الأولُ عساكرَه من المسلمين والنصارى وطوائف التتر، فلما تكامل جيشُه سار لحربه، فأرسل تيمور قبل وصوله إلى التتار الذين مع بايزيد الأول يقول لهم: نحن جنسٌ واحد، وهؤلاء تركمان ندفعُهم من بيننا، ويكون لكم الرومُ عِوَضَهم، فانخدعوا له وواعدوه أنهم عند اللقاء يكونون معه، وسار بايزيد الأول بعساكِرِه على أنه يلقى تيمور خارج سيواس، ويردُّه عن عبور أرض الروم، فسلك تيمور غير طريق بايزيد واختار الطريق الأطول، ومشى في أرض غير مسلوكة، ودخل بلاد بايزيد، ونزل بمعسكر بايزيد الأول بالقرب من أنقرة وضرب الحصار حولها, فلم يشعر بايزيد إلا وقد نُهِبت بلاده، فقامت قيامته وكرَّ راجعًا، وقد بلغ منه ومن عسكره التعبُ مبلغًا أوهَنَ قواهم، وكلَّت خيولهم، ونزل على غير ماء، فكادت عساكره أن تهلك، فلما تدانوا للحرب كان أول بلاء نزل ببايزيد مخامرة التتار بأسْرِها عليه، فضَعُفَ بذلك عسكره؛ لأنهم كانوا معظمَ عسكره، ثم تلاهم ولدُه سليمان ورجع عن أبيه عائدًا إلى مدينة بورصا بباقي عسكرِه، فلم يبقَ مع بايزيد إلا نحو خمسة آلاف فارس، فثبت بهم حتى أحاطت به عساكر تيمورلنك فالتَقَوا في معركة عُرِفت بمعركة أنقرة في ذي الحجة 804 (1402م) واستمر القتال بينهم من ضحى يوم الأربعاء إلى العصر، فصدمهم جيش بايزيد صدمة هائلة بالسيوف والأطبار حتى أفنوا من التمرية أضعافهم، فكفَّت عساكر بايزيد، وتكاثر التمرية عليهم يضربونهم بالسيوف لقلَّتهم وكثرة التمرية، فكان الواحد من العثمانية يقاتله العشرة من التمرية، إلى أن صُرِعَ منهم أكثرُ أبطالهم، وأُخِذَ بايزيد الأول أسيرًا قبضًا باليدِ على نحو ميل من مدينة أنقرة، في يوم الأربعاء سابع عشرين ذي الحجة بعد أن قُتِل غالب عسكره بالعطش، وصار تيمور يوقَف بين يديه في كل يوم السلطان بايزيد ويسخر منه ويُنكيه بالكلام، وجلس تيمور مرةً لمعاقرة الخمر مع أصحابه وطلب بايزيد طلبًا مزعجًا، فحضر وهو يرسُفُ في قيوده وهو يرجف، فأجلسه بين يديه وأخذ يحادثه، ثم وقف تيمور وسقاه من يد جواريه اللاتي أسرهن تيمور، ثم أعاده إلى محبسه، وأما أمر سليمان بن السلطان بايزيد الأول، فإنه جمع المال الذي كان بمدينة بورصا، وجميع ما كان فيها ورحل إلى أدرنة وتلاحق به الناس، وصالح أهل استانبول، فبعث تيمورلنك فرقةً كبيرة من عساكره صحبة الأمير شيخ نور الدين إلى بورصا فأخذوا ما وجدوا بها، ثم تبعهم هو أيضًا بعساكره، ثم أفرج تيمور عن محمد وعلي أولاد ابن قرمان من حبس السلطان بايزيد، وخلع عليهما وولَّاهما بلادهما، وألزم كلَّ واحد منهما بإقامة الخطبة، وضَرْب السكة باسمه واسم السلطان محمود خان المدعو صرغتمش، ثم شتا في معاملة منتشا وعمل الحيلة في قتل التتار الذين أتوه من عسكر بايزيد حتى أفناهم عن آخرِهم، وأما السلطان بايزيد فإنه استمر في أسر تيمورلنك من ذي الحجة سنة أربع إلى أن مات بكربته وقيوده في أيام من ذي القعدة سنة 805."},{"id":3238,"title":"طاهر بن أحمد يثور على أبيه سلطان بغداد .","date":["العام الهجري :805","العام الميلادي :1402"],"text":"ثار على السلطان أحمد بن أويس ولدُه طاهر وحارَبَه، ففرَّ من الحلة إلى بغداد فأَخَذَ وديعة له كانت بها، فهجم عليه طاهر وأخذ منه المال، ففرَّ أحمد من ابنه، وأتاه قرا يوسف بطلبه له وأعانه على ابنه، وحاربه معه، ففرَّ طاهر فاقتحم بفرسه دجلة فغرق بها، ولحِقَ بربِّه."},{"id":3239,"title":"وفاة السلطان العثماني بايزيد الأول .","date":["العام الهجري :805","الشهر القمري : شعبان","العام الميلادي :1403"],"text":"هو السلطان بايزيد الأول بن مراد الأول بن أورخان غازي بن الغازي عثمان بن أرطغرل الملقب بيلدرم -أي الصاعقة- نظرًا لحركته السريعة بجيوشه وتنقُّلِه بين عدة جهات بمنتهى السرعة. كانت ولادته سنة 761 (1360م) وكان هو الابن البكر لمراد الأول، فاتفق أركان الدولة على توليته بعد مقتل والده مراد الأول سنة 791 على يد أحد جرحى الصرب في أعقاب معركة قوصوة. قَتَل أخاه يعقوب الأصغر منه بقليل والمتصف بالشجاعة والإقدام وعلو الهمة، فخاف على المملكة منه من أن يدَّعي الملك ويرتكن على أن الملك انتقل إلى السلطان أورخان بعد وفاة أبيه السلطان عثمان ولم يتولَّ بعده ابنه البكر علاء الدين؛ ولذلك قُتِل باتفاق أمراء الدولة وقواد جيوشها, وقيل: إن قتله كان بناء على فتوى شرعية أفتى بها علماء ذلك الزمان منعًا لحصول الفتنة بناء على قوله تعالى: {وَالْفِتْنَةُ أَشَدُّ مِنَ الْقَتْلِ}.  وابتدأ السلطان بايزيد الأول أعماله بأن ولى الأمير أسطفن بن لازار ملك الصرب حاكمًا عليها وتزوج أخته أوليفيرا وأجازه بأن يحكم بلاده على حسب قوانينهم بشرط دفع جزية معينة وتقديم عدد معين من الجنود ينضمون إلى الجيوش الشاهانية وقت الحرب، وفعل ذلك ولم يضم بلاد الصرب إلى أملاكه ويجعلها ولاية كباقي الولايات ليسكن بال الصربيين حتى لا يكونوا شغلًا شاغلًا له؛ نظرًا لحبهم الاستقلال، ولما ساد الأمن في أوروبا قصد بلاد آسيا وفتح مدينة آلاشهر المعروفة عند الإفرنج باسم فيلادلفيا سنة 1391م، وهي آخر مدينة بقيت للروم في آسيا, وتنازل الأمير علاء الدين حاكم بلاد القرمان للسلطان عن جزء عظيم من أملاكه ليؤمِّنَه على الباقي, وبعد هذه الفتوحات التي تم أغلبها بدون حرب عاد السلطان إلى أوروبا وحارب أمانويل باليولوج ملك الروم وحاصره في القسطنطينية وضيق عليها الحصار ثم ترك حولها جيشًا جرارًا وسافر لغزو بلاد الفلاخ، فقهر أميرها وأكرهه على التوقيع على معاهدة يعترف فيها بسيادة الدولة العلية العثمانية على بلاده ويتعهد لها بدفع جزية سنوية، وتم ذلك في سنة 1393م, وفي أثناء اشتغال السلطان بمحاربة الفلاخ أراد علاء الدين أمير القرمان ان يسترد ما تنازل عنه للدولة العلية، فهاجم مدينة أنقره، فلما بلغ خبره السلطان بايزيد قام بنفسه إلى بلاد الأناضول وجدَّ في طلب علاء الدين حتى تقابل الجيشان فهزمه السلطان وأسره هو وولديه محمد وعلي، وضم ما بقي من أملاكه إليه وبذلك انمحت سلطنة القرمان وصارت ولاية عثمانية، ثم فتحت أمارات سيواس وتوقات, وبذا لم يبق من الإمارات التي قامت على أطلال دولة آل سلجوق إلا إمارة قسطموني خارجة عن أملاك الدولة العثمانية، وكان أميرها يسمى بايزيد أيضًا، فسار إليه السلطان بايزيد بنفسه وأغار على بلاده وفتح مدائن ساسون وجانك وعثمانجق، وبذلك انقرضت جميع الإمارات الصغيرة القائمة ببلاد الأناضول، أما بايزيد صاحب قسطموني فلجأ إلى تيمورلنك سلطان المغول يحثه على غزو بايزيد, ومع استمرار الحصار حول القسطنطينية ضم السلطان بلاد البلغار إلى الأملاك العثمانية فصارت ولاية عثمانية كباقي الولايات بعد أن قتل أميرها سيسمان وأسلم ابنه وعين حاكمًا لسمسون سنة 1394م, وقَعَ بايزيد الأول في أسر تيمورلنك بعد معركة أنقرة فبقي في الأسر مهانًا, وقد حاول الفرار أكثر من مرة، لكن الحراسة المشددة أفشلت كل ذلك، فأصبح في ضيق شديد إلى أن توفي في الخامس عشر من شعبان من هذه السنة، وسمح تيمورلنك بنقل جثته لتُدفَن في بورصا، فكانت مدة ملكه قرابة التسع سنين، ويُذكَر أن أولاده محمد وعيسى وسليمان كانوا ممن استطاعوا الفرار من جيش تيمورلنك، أما ابنه موسى فأُسِرَ مع أبيه بايزيد،  وأما مصطفى بن يزيد فقد اختفى فلم يُعرَف له خبر."},{"id":3240,"title":"وفاة شيخ الإسلام العلامة سراج الدين البلقيني الشافعي .","date":["العام الهجري :805","الشهر القمري : ذي القعدة","العام الميلادي :1403"],"text":"هو الإمام العلامة شيخ الإسلام مجتهد العصر نادرة الوقت فقيه الدنيا وخاتمة المجتهدين: سراج الدين أبو حفص عمر بن رسلان بن نصير بن صالح -وصالح أول من سكن بلقينة- بن شهاب بن عبد الخالق بن عبد الحق بن مسافر بن محمد الكناني البلقيني الشافعي، وُلِد في ليلة الجمعة ثاني عشر شعبان 724 ببلقينة، وهي قرية في المحلة الكبرى بطنطا. حفظ القرآن وهو في السابعة من عمره. حفظ المحرر في الفقه، والكافية لابن مالك في النحو، ومختصر ابن الحاجب في الأصول، والشاطبية في القراءات. أقدمه أبوه إلى القاهرة وله اثنتا عشرة سنة، وأجاز له من دمشق الحافظ أبو الحجاج المزِّي، والحافظ الذهبي، وطلب العلم واشتغل على علماء عصره، وتفقَّه بجماعة كثيرة، وبرع في الفقه وأصوله، والعربية والتفسير، وغير ذلك، وأفتى ودرس سنين، وانفرد في أواخر عمره برئاسة مذهبه، وولي إفتاء دار العدل، ودرس بزاوية الشافعي المعروفة بالخشابية من جامع عمرو بن العاص، وولي قضاء دمشق عوضًا عن تاج الدين عبد الوهاب السُّبكي، فباشر مدة يسيرة، ثم تركه وعاد إلى مصر واستمرَّ بمصر يقرئ ويشتغل ويفتي بقية عمره، له مصنفات؛ منها: تصحيح المنهاج، ومحاسن الاصطلاح، وترجمان شعب الإيمان، وغيرها. توفي في يوم الجمعة عاشر ذي القعدة، وصُلي عليه بجامع الحاكم، ثم دُفِن بمدرسته التي أنشأها تجاه داره بحارة بهاء الدين قراقوش من القاهرة."},{"id":3241,"title":"وفاة الشيخ عبد الجبّار بن عبد الله المعتزلي الحنفي إمام تيمورلنك .","date":["العام الهجري :805","الشهر القمري : ذي القعدة","العام الميلادي :1403"],"text":"هو الشيخ عبد الجبَّار بن عبد الله المعتزلي الحنفي الخوارزمي عالم الدشت، صاحب تيمورلنك وإمامه وعالمه وترجمانه. ولد في حدود سنة 770، وكان إمامًا عالِمًا بارعًا، متقِنًا للفقه، والأصلين، والمعاني، والبيان، والعربية، واللغة، انتهت إليه الرئاسة في أصحاب تيمور، وكان هو عظيم دولته، ولما قدم تيمور البلاد الحلبية والشامية كان عبد الجبَّار هذا معه، وباحَثَ وناظر علماء البلدين، وكان فصيحًا باللغات الثلاث: العربية، والعجمية، والتركية، وكانت له ثروة ووجاهة وعَظَمة وحرمة زائدة إلى الغاية؛ قال أبو الفلاح العكري الحنبلي: \"كان عبدالجبار ينفع المسلمين في غالب الأحيان عند تيمور، وكان يتبرَّمُ من صحبة تيمور ولا يسعُه إلا موافقته، ولم يزل عنده حتى مات في ذي القعدة\"."},{"id":3242,"title":"بداية الاختلاف بين أبناء السلطان العثماني بايزيد الأول .","date":["العام الهجري :806","العام الميلادي :1403"],"text":"بعد أن توفي السلطان بايزيد الأول في الأَسْر, وكان أولاده الذين هربوا من المعركة كل منهم ولى إلى جهة، فلما سار تيمورلنك عن الأناضول عادت مجزَّأة كما كانت قبل أن يوحِّدها العثمانيون وأعلنت الإمارات الأوربية استقلالها لما رأت ما حلَّ بالعثمانيين من قِبَل تيمورلنك، فأعلن البلغار والصرب والأفلاق استقلالهم، واختلف أولاد السلطان بايزيد فزاد الضعف؛ فاستقل سليمان بن بايزيد في أدرنة والمناطق العثمانية في أوروبا تابعة له، وعقد حلفًا مع إمبراطور بيزنطة عمانويل الثاني وتنازل له عن مدينة سلانيك وعن سواحل البحر الأسود ليساعده على إخوته كما تزوج إحدى قريباته، أما عيسى بن بايزيد فقد كان مختبئًا بجهات بورصا، فلما علم بوفاة أبيه أعلن سلطنته على بورصا وساعده كبير قادة بني عثمان ديمور طاش، وأما محمد بن بايزيد فكان مخبؤه في أواسط الأناضول، فلما رأى أن ضغط التتار قد خفَّ جمع جموعه وانطلق محاربًا التتار فتمكن من أخذ مدينة توقات وأماسيا فقوي أمره واستطاع أن يخلص أخاه موسى من الأسر؛ حيث كان أُسِرَ مع أبيه عند تيمورلنك، ثم إن الإخوة بدأ بعضهم يقاتل بعضًا."},{"id":3243,"title":"الفرنج يغزون طرابلس .","date":["العام الهجري :806","الشهر القمري : محرم","العام الميلادي :1403"],"text":"في هذا الشهر كانت واقعة الفرنج بطرابلس، وذلك أنهم نزلوا على طرابلس في ثلاثين شينيًا -سفينة كبيرة- وقراقر، وكان الأمير دمرداش غائبًا عن البلد، فقاتلهم الناس قتالًا شديدًا في يوم الثلاثاء ثاني عشره إلى الغد، فبلغ دمرداش وهو بنواحي بعلبك الخبر، فاستنجد الأمير شيخ المحمودي نائب الشام، وتوجه إلى طرابلس، فقَدِمَها يوم الخميس عشرينه، ونودي في دمشق بالنفير، فخرج الناس على الصعب والذلول، فمضى الفرنج إلى بيروت بعدما قاتلهم دمرداش قتالًا كبيرًا، قُتِل فيه من المسلمين اثنان وجُرح جماعة، فوصل الأمير شيخ إلى طرابلس وقد قضى الأمر، فسار إلى بيروت، فقدمها وقت الظهر من يوم الجمعة الحادي والعشرين، والقتال بين المسلمين وبين الفرنج من أمسه، وقتلى الفرنج مطروحون على الأرض، فحرق تلك الرمم، وتبع الفرنجَ وقد ساروا إلى صيدا بعدما حرقوا مواضع وأخذوا مركبًا قدم من دمياط ببضائع لها قيمة كبيرة، وقاتلوا أهل صيدا، فطرقهم الأمير شيخ وقت العصر وقاتلهم وهم في البر، فهزمهم إلى مراكبهم، وساروا إلى بيروت فلحقهم وقاتلهم، فمضَوا إلى جهة طرابلس، ومرُّوا عنها إلى جهة الماغوصة، فركز الأمير شيخ طائفة ببيروت، وطائفة بصيدا، وعاد إلى دمشق في ثاني صفر."},{"id":3244,"title":"وفاة الإمام العلامة الحافظ زين الدين العراقي الشافعي .","date":["العام الهجري :806","الشهر القمري : شعبان","العام الميلادي :1404"],"text":"هو الشيخ الإمام العلامة الأوحد شيخ العصر حافظ الوقت شيخ المحدِّثين علم الناقدين عمدة المخرجين: أبو الفضل زين الدين عبد الرحيم بن الحسين بن عبد الرحمن بن أبي بكر العراقي المصري الشافعي، شيخ الحديث بالديار المصرية، وُلِدَ بمصر سنة 725, وسمع الكثير ورحل في البلاد، حدَّث وأملى سنين كثيرة وأفاد وتكلم على العلل والإسناد ومعاني المتون وفقهها، فأجاد وصنف التصانيف التي اشتهرت، وخرج تخاريج رُوِيت وانتشرت. كان وَلِيَ قضاء المدينة النبوية، وعدة تداريس، وانتهت إليه رئاسة علم الحديث في زمانه، له مصنفات عديدة منها: ألفية العراقي المسماة بـ: التبصرة والتذكرة في علوم الحديث، والتقييد والإيضاح شرح مقدمة ابن الصلاح، وتقريب الأسانيد وترتيب المسانيد، ومحجة القرب إلى محبة العرب، والمغني عن حمل الأسفار في الأسفار (تخريج الإحياء)، وتخريج أحاديث مختصر المنهاج في أصول الفقه، وغيرها كثير. توفي بمصر في يوم الأربعاء ثامن شعبان."},{"id":3245,"title":"الفتنة بين الأمراء بمصر والقتال بينهم .","date":["العام الهجري :807","الشهر القمري : جمادى الأولى","العام الميلادي :1404"],"text":"أهلَّ شهر جمادى الأولى والفتنة قائمة بين أمراء الدولة؛ وذلك أن الأمير يشبك هو زعيم الدولة، بيده جميع أمورها من الولاية والعزل، والنقض والإبرام، وصار له عصبة كبيرة، فأحبوا عزل الأمير إينال باي ابن الأمير قجماس ابن عم الملك الظاهر برقوق من وظيفة أمير أخور؛ وذلك أنه اختص بالسلطان لأمور؛ منها: قرابته، ثم مصاهرته إياه، فشَقَّ ذلك على عصبة يشبك، وأحبوا أن يكون جركس المصارع أمير أخور، وانقطعوا عن حضور الخدمة السلطانية عدة أيام من جمادى الأولى، فاستوحش السلطان منهم، وتمادى الحال، فتقدم السلطان إلى الأمير إينال باي أن ينزل إلى الأمراء ويصالحهم، فمنع جماعة من المماليك السلطانية إينال باي أن ينزل، وتشاجروا مع طائفة من مماليك الأمراء، واشتد ما بينهم من الشر، وأخذ كل أحد في أُهبة الحرب، وأصبحوا جميعًا يوم الأحد لابسين السلاح، وقد أعدَّ يشبك بأعلى مدرسة حسن مدافع النفط والمكاحل؛ ليرمي على الإسطبل السلطاني، ومن يقف تحت القلعة بالرميلة، ونزل السلطان من قلعة الجبل إلى الإسطبل، واجتمع عليه من أقام على طاعته من الأمراء والمماليك، وأقام مع يشبك من الأمراء المقدَّمين سبعة وأكثر المماليك الظاهرية، فأقاموا على الحصار والمراماة، من بكرة الأحد إلى ليلة الخميس سابعه، وقد أخذ أصحاب السلطان على اليشبكية المنافذ، وحصروهم والقتال بينهم مستمر، وأمرُ يشبك في إدبار، فلما كان ليلة الخميس نصف الليل، خرج يشبك بمن معه على حمية من الرميلة، ومروا إلى جهة الشام، فلم يتبَعْهم أحد من السلطانية، ونودِيَ من آخر الليل في الناس بالقاهرة الأمان والاطمئنان، ومُنِع أهل الفساد من النهب، وأما يشبك ففي مروره إلى دمشق انضم له الكثير وزُوِّد بالكثير من العدد والعتاد، وقد انضم إليهم خلق كثير، فدخلوا دمشق بكرة الثلاثاء رابع شهر رجب، فسألهم الأمير شيخ المحمودي عن خبرهم، فأعلموه بما كان، وذكروا له أنهم مماليك السلطان وفي طاعته، لا يخرجون عنها أبدًا غير أن الأمير إينال باي ثقل عنهم ما لم يقع منهم، فتغير خاطر السلطان، حتى وقع ما وقع، وأنهم ما لم يُنصَفوا منه ويعودوا لِما كانوا عليه، وإلا فأرض الله واسعة، فوعدهم بخير، وقام لهم بما يليق بهم، وكتب إلى السلطان يسأله في أمرهم، وقدمت كتب نواب الشام إلى الأمير يشبك، تَعِدُه بالأمداد، وتقويته بما يريد، وقدم عليهم الأمير نوروز والأمير دقماق، فبعث الأميران شيخ ويشبك بيشبك العثماني إلى الأمير جكم الجركسي الظاهري، يستدعيه من أنطاكية إلى دمشق، وأفرج الأمير شيخ المحمودي أيضًا عن قرا يوسف ابن قرا محمد التركماني."},{"id":3246,"title":"واقعة السعيدية وفتنة الأمير جكم ومحاولة استيلائه على البلاد .","date":["العام الهجري :807","الشهر القمري : جمادى الأولى","العام الميلادي :1404"],"text":"استولى الأمير جكم الجركسي الظاهري على حلب، وقد كان سابقًا خرج عن الطاعة وتمالأ مع التركمان والعربان وأحدث عدة فتن، وأنعم على الأمير علان نائب حماة بموجود دمرداش النائب السابق لحلب، وأحسن جكم السيرة في حلب، وولَّى في القلاع نوابًا من جهته، فاجتمعت له حلب وحماة وطرابلس، وأما الأمير شيخ المحمودي نائب الشام فإنه خرج لأخذ صفد وعمل ثلاثين مدفعًا، وعدة مكاحل للنفط ومنجنيقين، وجمع الحجَّارين والنقَّابين وآلات الحرب، وخرج من دمشق ومعه جميع من عنده من عسكر مصر والشام، وقرا يوسف بجماعته، وجماعة السلطان أحمد بن أويس متملك بغداد، والتركمان الجشارية، وأحمد بن بشارة بعشرانه، وعيسى بن الكابولي بعشيره، بعدما نادى بدمشق من أراد النهب والكسب فعليه بصفد، فاجتمع له خلائق، وسار ومعه مائة جمل تحمل المدافع والمكاحل والمجانيق، والزحَّافات، والبارود، ونحو ذلك من آلات الحصار، وولي الأمير ألطنبغا العثماني نيابة صفد، فكتب يستدعي عشران صفد وعربانها وتركمانها، فقدم الأمير شيخ بمن معه إلى صفد وبعث أمامه تقي الدين يحيى بن الكرماني، وقد ولَّاه العسكر، ومعه قطلوبغا رأس نوبة بكتابه إلى الأمير بكتمر شلق يدعوه إلى موافقته، ويحذِّره من مخالفته، ويُعلِمه أن الأمير جكم قد أخذ حلب من الأمير دمرداش بالقهر، وأنه قادم إليه ومعه الأمير علان نائب حماة، فلم يُذعِن له بكتمر، وأبى إلا قتاله، فأحاط الأمير شيخ بقلعة صفد وحصرها من جميع جهاتها، وقد حصَّنها الأمير بكتمر وشحنها بالرجال والآلات، فاستمرَّت الحرب بينهم أيامًا، جرح فيها من الشيخية نحو ثلاثمائة رجل، وقتل ما ينيف على خمسين فارسًا، ثم إن الأمير جكم خرج من حلب يريد دمشق، وقد حضر إليه شاهين دوادار الأمير شيخ يستدعيه، وكان جكم قد سلم القلعة إلى شرف الدين موسى بن يلدق، وعمل حجابًا وأرباب وظائف، وعزم على أن يتسلطن ويتلقب بالملك العادل، ثم أخر ذلك وقدم دمشق ومعه الأمير قانباي، والأمير تغري بردي القجقاري وجماعة، وقد خرج الأمير شيخ والأمراء إلى لقائه، وأنزله في الميدان، فترفع على الأمراء ترفعًا زائدًا أوجب تنكُّرَهم عليه في الباطن، إلا أن الضرورة قادتهم إلى الإغضاء، فأكرموه، وأنزلوه، وحلفوه على القيام معهم على السلطان وموافقتهم، وأخذ في إظهار شعار السلطنة، فشَقَّ عليهم ذلك، وما زالوا به حتى تركه، وأقام معهم بدمشق ثم توجَّه منها مخفًّا إلى طرابلس، وترك أثقاله بدمشق، ليجمع عساكر طرابلس وغيرها ممن انضم إليه، وأما الأمير شيخ فإنه وقع الصلح بينه وبين الأمير بكتمر نائب صفد، وتحالفوا جميعًا على الاتفاق، ثم سار جكم من طرابلس في عشرينه، وخيَّم ظاهرها، فبعث شيخ السلماني يستدعي علان، فبعث إليه نائب شيزر على عسكر، ففرَّ ابن أمير أسد بمن معه وترك أثقاله، فأخذها السليماني، ورتب أمر قلعة صهيون، وجعل بيازير بها، وتوجه إلى علان - -وقد نزل على بارين - فتلقاه وبالغ في كرامته، وأنزله بمخيمه، فأخذ شيخ عند ذلك في مكاتبة أمراء طرابلس وتركمانها يدعوهم إلى طاعته، فأجابوه بالسمع والطاعة، ووعدوه بالقيام معه، فاضطرب أمر جكم، وانسلَّ عنه من معه، طائفة بعد أخرى، فمضى إلى الناعم وقد كثر جمع السليماني، فمشى ومعه علان يريدان جكم فتركهم، ومضى إلى دمشق، فأدركه في طريقه إليها الأمير سعد الدين إبراهيم بن غراب، ويشبك العثماني، وأقبغا دوادار الأمير يشبك الدوادار، يحثُّونه على القدوم، وقد سار من دمشق فسار معهم، وأركب السليماني تركمان طرابلس في أثر جكم، فأخذوا بعض أطرافه، وقدم السليماني طرابلس وأعاد الخطبة للسلطان، ومهَّد أمورها، وكتب يُعلِم السلطان بذلك، ثم خرج منها بعد يومين يستنفر الناس، فاجتمع عليه خلائق من التركمان، والعربان، والعشران، وعسكر طرابلس وكثير من عسكر حلب، وطائفة من المماليك السلطانية، وكان العجل بن نعير قد استولى على معاملة الحصن والمناصف، واستولى فارس بن صاحب الباز -وأخوه حسين- على سواحل اللاذقية، وجبلة، وصهيون، وبلاطنس، واستولى علم الدين على حصن الأكراد، وعصى بها، واستولى رجب بن أمير أسد على قلعة المرقب، فطرد السليماني العجل من المعاملة، ونزل على حصن الأكراد وحصرها حتى أخذها، وأعاد بها الدعاء للسلطان، وأخذ في استرجاع الساحل، فقدم عليه الخبر بولاية الأمير قانباي طرابلس، ووصول متسلمه سيف الدين بوري -ومعه شهاب الدين أحمد الملطي- على ظهر البحر من ديار مصر، ففتَّ ذلك في عضده، وصار إلى علان نائب حماة، فأشار عليه ألَّا يسلم طرابلس حتى يراجع السلطان بما يترتب على عزله من الفساد بتبدُّد كل العساكر، فكتب بذلك، ودخل بوري والملطي إلى طرابلس، وتسلماها، وحلَّفا الأمراء وغيرهم للسلطان، ثم خرج الأمير شيخ المحمودي نائب الشام ومعه الأمير يشبك وبقية الأمراء إلى لقاء الأمير جكم، فعندما رأوه ترجل له يشبك، ونزل الأرض وسلم عليه، فلم يعبأ به، ولا التفت إليه، وجرى على عادته في الترفع والتكبر، فشقَّ ذلك على الأمير شيخ، ولام يشبك على ترجُّله، وعِيبَ جكم على ما كان منه، ودخلوا معه إلى دمشق والطبول تُضرَب وهو في مركب مهول، فنزل الميدان، وجرى على عادته في التكبر والترفع، فتنكرت القلوب، واختلفت الآراء، فكان جكم أمة وحدة يرى أنه السلطان، ويريد إظهار ذلك، والأمراء تَسوسُه برفق، حتى لا يتظاهر بالسلطنة، ورأيه التوجه إلى بلاد الشمال، ورأي بقية الأمراء المسير إلى مصر، فكانوا ينادون يومًا بالمسير إلى مصر، وينادون يومًا بالمسير إلى حماة وحلب، وينادون يومًا من أراد النهب والكسب فعليه بالتوجه إلى صفد، ثم قوي عزمهم جميعًا على قصد مصر، وبعثوا لرمي الإقامات بالرملة وغزة، وبرزوا بالخيام إلى قبة يلبغا في الرابع عشر، وخرج الأمير شيخ والأمير يشبك وقرا يوسف من دمشق، وندبوا الأمير يشبك وقرا يوسف إلى صفد، فسارا من الخربة في عسكر، ومضى الأمير شيخ إلى قلعة الصبيبة فاستعد الأمير بكتمر شلق نائب صفد، وأخرج كشافته بين يديه، ونزل بجسر يعقوب، فالتقى أصحابه بكشافة يشبك وقرا يوسف، واقتتلوا، فكثرت الجراحات بينهما، وغنم الصفديون منهم عشرة أفراس، فرجع يشبك وقرا يوسف إلى طبرية، ونزلا على البحيرة حتى عاد الأمير شيخ من الصبيبة، وقد حصَّن قلعتها، ثم ساروا جميعًا إلى غزة، وقد تقدَّمهم الأمير جكم، ونزل بالرملة والتقت مقدمة السلطان ومقدمة الأمراء واقتتلوا، فرحل السلطان من بلبيس بكرة نهار الأربعاء، ونزل السعيدية فأتاه كتاب الأمراء الثلاثة: شيخ، وجكم، ويشبك، بأن سبب حركتهم ما جرى بين الأمير يشبك والأمير إينال باي ابن الأمير قجماس من حظ الأنفس، حتى توجه يشبك بمن معه إلى الشام، فكان بها من خراب البلاد، وهلاك الرعية ما كان، وطلبوا منه أن يخرج أينال باي ودمرداش نائب حلب من مصر إلى الشام، وأن يُعطى لكل من يشبك وشيخ وجكم، ومن معهم بمصر والشام ما يليق به؛ لتخمد هذه الفتنة باستمرارهم على الطاعة، وتحقن الدماء، ويعمر ملك السلطان، وإن لم يكن ذلك تَلِفَت أرواح كثيرة، وخربت بيوت عديدة وقد كان عزمهم المكاتبة بهذا من الشام، لكن خشوا أن يُظَنَّ بهم العجز، فإنَّه ما منهم إلا من جعل الموت نصب عينيه، ثم بيت أمراء السلطان، وهم في نحو الثلاثة آلاف فارس وأربعمائة تركماني من أصحاب قرا يوسف، فاقتتل الفريقان قتالًا شديدًا، من بعد عشاء الآخرة إلى بعد نصف الليل، جُرِح فيه جماعة، وقُتِل الأمير صرق صبرًا بين يدي الأمير شيخ؛ لأنه ولي نيابة الشام من السلطان، وركب السلطان ومعه الأمير سودن الطيار، وسودن الأشقر هجنا، وساقوا على البر تحت غلس الصبح يريدون القلعة، وتفرقت العساكر وتركوا أثقالهم وسائر أموالهم، فغنمها الشاميون، ووقع في قبضتهم الخليفة وقضاة مصر، ونحو من ثلاثمائة مملوك، والأمير شاهين الأفرم، والأمير خير بك نائب غزة، وقدم المنهزمون إلى القاهرة، ولم يحضر السلطان ولا الأمراء الكبار، فكثر الإرجاف، وأقيم العزاء في بعض الدور وماج الناس، وكثُر النهب، حتى وصل السلطان قريب العصر ومعه الأمراء، إلى الأمير أقباي، وقد قاسى من العطش والتعب ما لا يوصف، فاستعدَّ وجمع إليه عساكره، وزحفت عساكر الشاميين من الريدانية، وقد نزلوا بها من أمسه وكثر اضطراب الناس بالقاهرة، وغلقت أبوابها ودروبها، وتعطلت الأسواق، وعزَّ وجود الماء، ووصلت العساكر قريبًا من دار الضيافة تحت القلعة، فقاتلهم السلطانية من بكرة النهار إلى بعد الظهر، فأقبل عدة من الأمراء إلى جهة السلطان طائعين له، منهم: أسن بيه أمير ميسرة الشام، والأمير يلبغا الناصري، والأمير سودن اليوسفي، وإينال حطب، وجمق، ففت ذلك في أعضاد من بقي، وعاد طائفة منهم، وحملوا خفهم وأفرجوا عن الخليفة والقضاة وغيرهم، وتسلل الأمير قطلوبغا الكركي، والأمير يشبك الدوادار، والأمير تمراز الناصري، وجركس المصارع في جماعة، واختفوا بالقاهرة وظواهرها، فوَلِيَ حينئذ الأمير شيخ المحمودي نائب الشام، والأمير جكم، وقرا يوسف، وطولو، في طائفة يسيرة، وقصدوا الشام، فلم يتبعهم أحد من عسكر السلطان، ونادى السلطان بالأمان، وأصبح فقَيَّد من استأمن إليه من الأمراء، وبعثهم إلى الإسكندرية، فاعتُقِلوا بها، وانجلت هذه الفتنة عن تلف مال العسكريين، فذهب فيها من الخيل والبغال والجمال والسلاح والثياب والآلات ما لا يدخل تحت حصر، وأما حلب فإن الأمير جكم لما سار عنها ثار بها عدة من أمرائها، ورفعوا سنجق السلطان بباب القلعة، فاجتمع إليهم العسكر، وحلفوا للسلطان، فقدم ابنا شهري الحاجب، ونائب القلعة من عند التركمان البياضية إلى حلب، وقام بتدبير الأمور يونس الحافظي، وامتدت أيدي عرب العجل بن نعير وتراكمين ابن صاحب الباز إلى معاملة حلب، فقسموها، ولم يَدَعوا لأحد من الأمراء والأجناد شيئًا."},{"id":3247,"title":"وفاة الطاغية تيمورلنك وزوال خطر المغول .","date":["العام الهجري :807","الشهر القمري : شعبان","العام الميلادي :1405"],"text":"هو الطاغية تيمورلنك كوركان بن أيتمش قنلغ بن زنكي بن سنيا بن طارم بن طغريل بن قليج بن سنقور بن كنجك بن طغر سبوقا بن التاخان، المغولي الأصل، من طائفة جغتاي، واسمه تمرلنك وقيل تيمور، كلاهما بمعنى واحد، والثاني أفصح، وهو باللغة التركية: الحديد. ومعنى لنك: الأعرج، ومعنى كوركان: صهر الملك، وهو ينتمي إلى قبيلة البرلاس التركية، وقد كان أحد أجداده وهو قراجا رنويان قد دعم جنكيز خان فأحبَّه وجعله وصيًّا على ابنه جغطاي، فبرز بين المغول وعرف. ولد تيمور عام 736 في كش، وقيل: إنه دخل في الإسلام على مذهب الشيعة. وكان تيمور طويل القامة، كبير الجبهة، عظيم الهامة، شديد القوَّة، أبيض اللون مشربًا بحمرة، عريض الأكتاف، غليظ الأصابع، مسترسل اللِّحية، أشلَّ اليد، أعرج اليمنى، تتوقَّد عيناه، جهير الصَّوت، لا يهاب الموت، قد بلغ الثمانين، وهو متمتِّع بحواسه وقوَّته. وكان يكره المزاَّح ويبغض الكذّاب، قليل الميل إلى اللهو، على أنّه كان يعجبه الصوت الحسن، وكان نقش خاتمه: رستى رستى، ومعناه: \"صدقت نجوت\" وكان له فراسات عجيبة، وسعد عظيم، وحظ زائد في رعيته، وكان له عزم ثابت، وفهم دقيق، محجاجًا سريع الإدراك، متيقِّظَا يفهم الرَّمز ويدرك اللمحة، ولا يخفى عليه تلبيس ملبِّس، وكان إذا عزم على شيء لا ينثني عنه، وكان يقال له: صاحب قران الأقاليم السبعة، وقهرمان الماء والطين، وقاهر الملوك والسَّلاطين، وكان مغرمًا بسماع التاريخ وقصص الأنبياء عليهم السَّلام ليلًا ونهارا، حتى صار-لكثرة سماعه للتاريخ- يردُّ على القارئ إذا غلط فيها، وكان يحبُّ العلم والعلماء، ويقرِّب السَّادة الأشراف، ويُدني أرباب الفنون والصَّنائع. وكان انبساطه بهيبة ووقار، وكان يباحث أهل العلم وينصف في بحثه، ويبغض الشُّعراء والمضحكين، ويعتمد على أقوال الأطبَّاء والمنجِّمين، حتى إنَّه كان لا يتحرَّك بحركة إلا باختيار فلكي, وكان يلازم لعب الشطرنج، وكان الشيخ عبد الجبَّار بن عبد الله المعتزلي الحنفي الخوارزمي عالم الدّشت، صاحب تيمورلنك وإمامه وعالمه وترجمانه. ولتيمور واقعة مع العلَّامة القاضي محب الدين أبي الوليد محمد بن محمد بن محمود الحلبي قاضيها الحنفي المعروف بابن الشحنة: لما أخذ تيمور قلعة حلب بالأمان والأيمان فاستحضر علماءها وقضاتها فحضروا إليه وطلب من معه من أهل العلم، فقال لكبيرهم عنده، وهو عبد الجبار ابن العلامة نعمان الدين الحنفي، قُل لهم: إني سائلهم عن مسائل سألت عنها علماء سمرقند وبخارى وهراة وخراسان وسائر البلاد التي افتتحتها فلم يفصحوا الجواب، فلا تكونوا مثلهم، ولا يجاوبني إلا أعلمكم وأفضلكم، وليعرف ما يتكلم به؛ فإني خالطت العلماء، وكان يعنت العلماء في الأسئلة ويجعل ذلك سببًا إلى قتلهم أو تعذيبهم، قال القاضي ابن الشحنة، فقال القاضي شرف الدين موسى الأنصاري الشافعي: هذا شيخنا ومدرس هذه البلاد ومفتيها مشيرًا إليَّ، سلوه. قال: فقال لي قاضيه عبد الجبار: سلطاننا يقول: إنه بالأمس قُتِل منا ومنكم، فمن الشهيد: قتيلُنا أم قتيلكم؟ فوجم الجميع وقلنا في أنفسنا: هذا الذي كان يبلغنا عنه من التعنت، وسكت القوم ففتح الله عليَّ بجواب سريع بديع فألقى إلي تيمور سمعه وبصره، وقال لعبد الجبار يسخر من كلامي: كيف سئل رسول الله عن هذا؟ وكيف أجاب؟ فقلت: جاء أعرابي إلى رسول الله، فقال: يا رسول الله، إن الرجل يُقاتِلُ حميةً ويقاتل ليريَ مكانه من الشجاعة، فأينا الشهيد في سبيل الله؟ فقال: ((من قاتل لتكونَ كلمة الله هي العليا، فهو الشهيد)). فقال تيمورلنك: خوب خوب! فانفتح باب المؤانسة، فكثر منه السؤال وكثر مني الجواب، وكان آخر ما سأل أن قال: ما تقولون في علي ومعاوية ويزيد؟ فأسرَّ إلى القاضي شرف الدين: أن اعرِفْ كيف تجاوبُه؛ فإنه شيعي، فلم أفرغ من سماع كلامه إلا وقد قال القاضي علم الدين القفصي المالكي كلامًا معناه: إن الكل مجتهدون، فغضب لذلك غضبًا شديدًا، وقال: علي على الحق، ومعاوية ظالم، ويزيد فاسق، وأنتم حلبيون تبع لأهل دمشق، وهم يزيدون قتلوا الحسين، قال: فأخذت في ملاطفته والاعتذار عن المالكي بأنه أجاب بشيء وجده في كتاب لا يعرف معناه، فعاد إليَّ دون ما كان عليه من البسط, وحضر صلاة المغرب وأقيمت الصلاة وأمَّنا عبد الجبار، وصلى تيمورلنك إلى جانبي قائمًا يركع ويسجد، ثم تفرقنا، وفي اليوم الثاني: غدر بكل من في القلعة وأخذ جميع ما كان فيها من الأموال والأقمشة والأمتعة ما لا يحصى، أخبرني بعض كُتابه أنه لم يكن أخذ من مدينة قط ما أخذ من هذه القلعة، وعوقب غالب المسلمين بأنواع من العقوبة، وحبسوا بالقلعة. بعد أن عاد تيمورلنك من حربه مع العثمانيين واستقر في سمرقند استعدَّ لغزو الصين، فتوجه بجيوشه إليها، ولكن وفي الطريق هاجت العواصف الثلجية فتأثر ببردها، فكانت وفاته في ليلة الأربعاء سابع عشر شعبان سنة 807 وهو نازل بالقرب من أترار، وأترار بالقرب من آهنكران، ومعنى آهنكران باللغة العربية: الحدادون، وكان سبب موته أنَّه خرج من بلاده لأخذ بلاد الصِّين، وقد انقضى فصل الصيف ودخل الخريف، وكتب إلى عساكره أن يأخذوا الأُهبة لمدة أربع سنين، فاستعدوا لذلك وأتوه من كلِّ جهة، وصُنِع له خمسمائة عجلة لحمل أثقاله. ثمَّ خرج من سمرقند  في شهر رجب وقد اشتد البرد، ونزل على سيحون وهو جامد، فعبره ومرَّ سائرا، فأرسل الله عليه من عذابه جبالًا من الثلج التي لم يُعهَد بمثلها مع قوَّة البرد الشديد، فلم يبقَ أحد من عساكره حتى امتلأت آذانهم وعيونهم وخياشيمهم، وآذان دوابهم وأعينها من الثلج، إلى أن كادت أرواحهم تذهب. ثمَّ اشتدت تلك الرِّياح، وملأ الثلج جميع الأرض -مع سعتها- فهلكت بهائمهم. وجمد كثير من النّاس، وتساقطوا عن خيولهم موتًا. وجاء بعقب هذا الثَّلج والرّيح أمطار كالبحار، وتيمور مع ذلك لا يرقُّ لأحد، ولا يبالي بما نزل بالناس، بل يجدُّ في السَّير، فما أن وصل تيمور إلى مدينة أترار حتى هلك خلق كثير من قواته, ثمَّ أمر تيمور أن يستقطر له الخمر حتى يستعمله بأدوية حارَّة لدفع البرد وتقوية الحرارة، فعُمِل له ما أراد من ذلك, فشرع تيمور يستعمله ولا يسأل عن أخبار عساكره وما هم فيه، إلى أن أثَّرت حرارة ذلك وأخذت في إحراق كبده وأمعائه، فالتهب مزاجه حتى ضَعُف بدنه، وهو يتجلَّد ويسير السَّير السّريع، وأطبَّاؤه يعالجونه بتدبير مزاجه إلى أن صاروا يضعون الثلج على بطنه؛ لعِظَمِ ما به من التلهب، وهو مطروح مدة ثلاثة أيام، فتَلِفَت كَبِده، وصار يضطرب ولونه يحمرُّ، ونساؤه وخواصُّه في صراخ، إلى أن هلك إلى لعنة الله وسَخَطِه، ولما مات لبسوا عليه المسوح، ولم يكن معه أحد من أولاده سوى حفيده سلطان خليل بن ميران شاه بن تيمور، فعاد إلى سمرقند برمَّة جده تيمور. فخرج النَّاس إلى لقائه لابسين المسوح بأسرهم، وهم يبكون ويصرخون، ودخل ورمَّةُ تيمور بين يديه في تابوت أبنوس، والملوك والأمراء وكافة النَّاس مشاة بين يديه، وقد كشفوا رؤوسهم وعليهم المسوح، إلى أن دفنوه على حفيده محمد سلطان بمدرسته، وأقيم عليه العزاء أيَّامًا، وقُرِئَت عنده الختمات، وفُرِّقت الصَّدقات، ومدَّت الحلاوات والأسمطة بتلك الهمم العظيمة، ونُشِرت أقمشته على قبره، وعلَّقوا سلاحه وأمتعته على الحيطان حوالي قبره، وكلُّها ما بين مرصع ومكلل ومزركش، في تلك القبّة العظيمة، وعُلِّقت بالقبَّة قناديل الذَّهب والفضَّة، من جملتها قنديل من ذهب زنته أربعة آلاف مثقال -وهو رطل بالسَّمرقندي، وعشرة أرطال بالدِّمشقي، وأربعون رطلًا بالمصري- وفرشت المدرسة بالبُسُط الحرير والدِّيباج. ثمَّ نُقِلت رمَّتُه إلى تابوت من فولاذ عُمِل بشيراز، وهو على قبره إلى الآن، وتحمل إليه النَّذورة من الأعمال البعيدة، ويُقصَد قبره للزِّيارة والتّبرُّك به، ويأتي قبره من له حاجة ويدعو عنده!! وإذا مرَّ على هذه المدرسة أمير أو جليل خضع ونزل عن فرسه إجلالًا لقبره؛ لِما له في صدورهم من الهيبة. فتسلطن بعده حفيده خليل بن ميران شاه فاستولى خليل على خزائن جده وبذل الأموال، وتم أمرُه إلا أن ولدَي تيمور: شاه رخ، وجلال الدين ميرانشاه، اقتسموا المملكة بينهما بخط ممتد على حدود إيران، فأخذ شاه رخ الغرب، وفيه العراق وأذربيجان وأجزاء من بلاد القفجاق القوقاز، وأخذ ميانشاه الشرق، وفيه خراسان وسجستان وأصفهان وشيراز."},{"id":3248,"title":"فتنة بين أمراء الشراكسة وأمراء الروم واختفاء السلطان ابن برقوق .","date":["العام الهجري :808","الشهر القمري : ربيع الأول","العام الميلادي :1405"],"text":"في يوم الثلاثاء سادس ربيع الأول تخبطت الأحوال بين السلطان وبين المماليك؛ فوقف طائفة من المماليك الجراكسة، وسألوا أن يقبض على الأمير تغري بردي، والأمير دمرداش، والأمير أرغون؛ من أجل أنهم من جنس الروم؛ وذلك أن السلطان اختص بهم، وتزوج ابنة تغري بردي، وأعرض عن الجراكسة، وقبض على إينال باي، فخاف الجراكسة من تقدُّم الروم عليهم، وأرادوا من السلطان إبعادهم، فأبى عليهم، فتحزبوا عليه واجتمعوا على الأمير الكبير بيبرس، وتأخروا عن الخدمة السلطانية، فتغيب في ليلة الأربعاء الأميران تغري بردي ودمرداش، وأصبح الناس يوم الأربعاء سابعه وقد ظهر الأمير يشبك الدوادار، والأمير تمراز، والأمير جركس المصارع، والأمير قانباي العلاي، وكانوا مختفين من حين الكسرة بعد وقعة السعيدية؛ وذلك أن الأمير بيبرس ركب سَحَرًا إلى السلطان وتلاحى معه طويلًا، وعرَّفه بمواضع الأمراء المذكورين، فاستقرَّ الأمر على مصالحة السلطان للجراكسة، وإحضار الأمراء المذكورين، والإفراج عن إينال باي وغيره، فانفضُّوا على ذلك، وصار العسكر حزبين، وأظهر الجراكسة الخلاف، ووقفوا تحت القلعة يمنعون من يقصد السلطان، وجلس الأمير الكبير بيبرس في جماعة من الأمراء بداره، وصار السلطان بالقلعة، وعنده عدة أمراء، وتمادى الحال يوم الخميس والجمعة والسبت، والناس في قلق، وبينهم قالةٌ وتشانيع وإرجافات، ونزل السلطان إلى باب السلسلة، واجتمع معه بعض الأمراء ليصلح الأمر، فلم يُفِدْ شيئًا، وكثرت الشناعة عليه، وباتوا على ما هم عليه، وأصبحوا يوم الأحد الخامس والعشرين وقد كثروا، فطلبوا من السلطان أن يبعث إليهم بالأمير تغري بردي والأمير أرغون، فلما بعثهما قبضوا عليهما، وأخرجوا تغري بردي منفيًّا في الترسيم إلى القدس، فلما كان عند الظهيرة فُقِدَ السلطان من القلعة، فلم يُعرَف له خبر، وسبب اختفائه أن النوروز كان في يوم السبت الرابع والعشرين ربيع الأول، فجلس السلطان مع عدة من خاصكيته لمعاقرة الخمر، ثم ألقى نفسه في بحرة ماء وقد ثَمِل، فتبعه جماعة وألقَوا أنفسهم معه في الماء، وسبح بهم في البحرة، وقد ألقى السلطان عنه جلباب الوقار، وساواهم في الدعابة والمجون، فتناوله من بينهم شخص، وغمه في الماء مرارًا، كأنه يمازِحُه ويلاعبه، وإنما يريدُ أن يأتيَ على نفسه، وما هو إلا أن فُطِن به فبادر إليه بعض الجماعة -وكان روميًّا- وخلصه من الماء، وقد أشرف على الموت، فلم يُبدِ السلطان شيئًا، وكتم في نفسِه، ثم باح بما أسرَّه؛ لأنه كان لا يستطيع كتمان سر، وأخذ يذم الجراكسة -وهم قوم أبيه، وشوكة دولته، وجُلُّ عسكره- ويمدح الروم، ويتعصَّبُ لهم، وينتمي إليهم، فإنَّ أمه شيرين كانت رومية، فشقَّ ذلك على القوم، وأخذوا حِذرَهم، وصاروا إلى الأمير الكبير بيبرس ابن أخت الظاهر واستمالوه، فخاف السلطان وهم أن يفرَّ، فبادره الأمير بيبرس وعنَّفه، وما زال به حتى أحضر الأمراء من الإسكندرية ودمياط، وأظهر الأمراء المختفين، فاجتمع الأضداد، واقترن العدي والأنداد، ثم عادوا إلى ما هم عليه من الخلاف بعد قليل، وأعانهم السلطان على نفسه بإخراج يشبك بن أزدمر، وأزبك، فأبدوا عند ذلك صفحات وجوههم، وأعلنوا بخلافه، وصاروا إلى إينال باي بن قجماس ليلة الجمعة، وسعوا فيما هم فيه، ثم دسُّوا إليه سعد الدين بن غراب كاتب السر، فخيَّله منهم، حتى امتلأ قلبه خوفًا، فلما علم ابن غراب بما هو فيه من الخوف، حسَّن له أن يفِرَّ، فمال إليه، وقام وقت الظهر من بين حرمه وأولاده، وخرج من ظهر القلعة من باب السر الذي يلي القرافة، ومعه الأمير بيغوت، فركبا فرسين قد أعدهما ابن غراب، وسارا مع بكتمر مملوك ابن غراب، ويوسف بن قطلوبك صهره أيضًا، إلى بركة الحبش، ونزلا وهما معهما في مركب، وتركوا الخيل نحو طرا وغيبوا نهارهم في النيل، حتى دخل الليل، فساروا بالمركب إلى بيت ابن غراب، وكان فيما بين الخليج وبركة الفيل، فلم يجدوه في داره، فمروا على أقدامهم حتى أووا في بيت بالقاهرة لبعض معارف بكتمر مملوك ابن غراب، ثم بعثوا إلى ابن غراب فحول السلطان إليه وأنزله عنده بداره، من غير أن يعلم بذلك أحد."},{"id":3249,"title":"وقعة بين المسلمين والفرنج بالأندلس .","date":["العام الهجري :808","الشهر القمري : ربيع الأول","العام الميلادي :1405"],"text":"لما انقضت مدة الصلح بين المسلمين بغرناطة وبين الطاغية صاحب قشتالة، أبى الطاغية الصلح، فبعث السلطان أبو سعيد عثمان صاحب ماس عشرين غرابًا أوسقها بالعدد والزاد، وجهز ثلاثة آلاف فارس، قدم عليهم القائد مارح، وجعل الشيخ عمر بن زيان الوساطي على ألف فارس أخرى، فنزلوا سبتة، وجهز أبو عبد الله محمد بن أبي الحجاج يوسف -صاحب غرناطة- أسطوله إلى جبل الفتح، فلقيهم أسطول الطاغية بالزقاق في يوم الجمعة السادس عشر، وقاتلهم، وقد اجتمع أهل فاس وأهل غرناطة، فكانت النصرة للفرنج، ولم ينجُ من المسلمين إلا القليل، وغنم الفرنج المراكبَ كلها بمن فيها وما فيها، فكانت مصيبة عظيمة، تكالب فيها الفرنج على المسلمين، وقوي طمعُهم فيهم."},{"id":3250,"title":"خلع السلطان الناصر فرج بن برقوق وتولية أخيه المنصور .","date":["العام الهجري :808","الشهر القمري : ربيع الأول","العام الميلادي :1405"],"text":"لما فُقِدَ الملك الناصر وقتَ الظهر من يوم الأحد خامس عشرين ربيع الأول بادر الأمراء بالركوب إلى القلعة، وهم طائفتان: الطائفة التي خالفت الناصر وحاربته، ويرجع أمرُهم إلى الأمير يشبك الدوادار، والطائفة الأخرى هي التي وَفَت للناصر، وكبيرهم الأمير الكبير بيبرس ابن أخت الظاهر، وحاربت يشبك الدوادار ومن معه، فلما صار الفريقان إلى القلعة، منعهم الأمير سودون تلى المحمدي أمير أخور من صعود القلعة، وهم يضرعون إليه من بعد نصف النهار إلى بعد غروب الشمس، ثم مكَّنهم من العبور من باب السلسلة، وقد أحضروا الخليفة والقضاة الأربعة، واستدعوا الأمير عبد العزيز بن الظاهر برقوق، وقد ألبسه سعد الدين إبراهيم بن غراب الخِلعة الخليفتية، وعمَّمه، فعهد إليه الخليفة أبو عبد الله محمد المتوكل على الله بالسلطنة، ولقَّبوه الملك المنصور عز الدين، وكنَّوه بأبي العز، وذلك عند أذان عشاء الآخرة، من ليلة الاثنين سادس عشرين ربيع الأول، وقد ناهز الاحتلام، وقام سعد الدين إبراهيم بن غراب كاتب سر مصر بأعباء المملكة، يدبر الأمراء كيف شاء، والمنصور تحت كفالة أمِّه، ليس له من السلطنة سوى مجرد الاسم في الخطبة، وعلى أطراف المراسيم."},{"id":3251,"title":"خلع السلطان المنصور عبدالعزيز بن برقوق وعودة أخيه الناصر فرج .","date":["العام الهجري :808","الشهر القمري : جمادى الآخرة","العام الميلادي :1405"],"text":"في شهر جمادى الآخرة، أوله الثلاثاء، وفيه مرض السلطان الملك المنصور، وفي يوم الجمعة رابعه: عادت الخيول من الربيع، وظهر بين أهل الدولة حركة، فكَثُرت القالة، وبات المماليك تسعى بعضها إلى بعض، فظهر الملك الناصر في بيت الأمير سودن الحمزاوي، وتلاحق به كثير من الأمراء والمماليك، ولم يطلع الفجر حتى ركب السلطان بآلة الحرب، وإلى جانبه ابن غراب، وعليه آلة الحرب، وسار بمن اجتمع إليه يريد القلعة، فقاتله سودن المحمدي أمير أخور، وإينال باي بن قجماس، وبيبرس الكبيري، ويشبك بن أزدمر، وسودن المارديني، قتالًا ليس بذاك، ثم انهزموا، وصعد السلطان إلى القلعة، فكانت مدة عبد العزيز سبعين يومًا، فعاد السلطان الملك الناصر زين الدين فرج ابن الملك الظاهر برقوق إلى الملك ثانيًا؛ وذلك أنه لما فُقِد من القلعة وصار إلى بيت سعد الدين بن غراب، ومعه بيغوت، قام له بما يليق به، وأعلم الأمير يشبك به، فخفي على أهل الدولة مكانه، ولم يعبؤوا به، وأخذ ابن غراب يدبر في القبض على الأمير إينال باي، فلم يتمَّ له ذلك، فلما تمادت الأيام قرر مع الطائفة التي كانت في الشام من الأمراء، وهم يشبك، وقطلو بغا الكركي، وسودن الحمزاوي في آخرين، أنه يخرج إليهم السلطان، ويعيدونه إلى المُلك؛ لينفردوا بتدبير الأمور؛ وذلك أن الأمير بيبرس الأتابك قويت شوكته على يشبك، وصار يتردد إليه، ويأكل على سماطه، فعزَّ عليه وعلى أصحابه ذلك، فما هو إلا أن أعلمهم ابن غراب بالخبر، فوافقوه على ذلك، وواعد بعضهم بعضًا، فلما استحكم أمرهم، برز الناصر نصف ليلة السبت خامس جمادى الآخرة من بيت ابن غراب، ونزل بدار الأمير سودن الحمزاوي، واستدعى الناس، فأتوه من كل جهة، وركب وعليه سلاحه، وابن غراب إلى جانبه، وقصد القلعة، فناوشه من تأخر عنه من الأمراء قليلًا، ثم فرُّوا، فملك السلطان القلعة بأيسر شيء؛ وذلك أن صوماي رأس نوبة كان قد وكل بباب القلعة، فعندما رأى السلطان فتح له، فطلع منه، وملك القصر، فلم يثبت بيبرس ومن معه، ومرُّوا منهزمين، فبعث السلطان بالأمير سودن الطيار في طلب الأمير بيبرس فأدركه خارج القاهرة، فقاتله وأخذه وأحضره إلى السلطان، فقيَّده وبعثه إلى الإسكندرية فسُجِن بها، واختفى الأمير إينال باي بن قجماس، والأمير سودن المارديني."},{"id":3252,"title":"وفاة الخليفة العباسي المتوكل محمد وتولية ابنه المستعين بالله العباس .","date":["العام الهجري :808","الشهر القمري : رجب","العام الميلادي :1406"],"text":"الخليفةُ أمير المؤمنين المتوكل على الله أبو عبد الله محمد بن المعتضد أبي بكر ابن المستكفي بالله أبي الربيع سليمان بن الحاكم بأمر الله أبي العباس أحمد، وكان عرض عليه الاستقلال بالأمر مرتين فأبى، وكان بويع بالخلافة بعهد من أبيه في سابع جمادى الآخرة سنة 763، وجعله الأمير أينبك البدري بن زكريا بن إبراهيم في ثالث عشرين صفر سنة تسع وسبعين، ثم أعيد في عشرين ربيع الأول، منها، وقبض عليه الظاهر برقوق في أول رجب سنة خمس وثمانين، وقيَّده وسجنه إلى أول جمادى الأولى سنة إحدى وتسعين، ثم أفرج عنه. توفي المتوكل على الله في سابع عشرين شهر رجب. وفي يوم الاثنين أول شعبان استدعى السلطان الملك الناصر أبا الفضل العباس ولد الخليفة المتوكل على الله أبي عبد الله محمد، وبايعه بالخلافة بعد موت أبيه، ولبس العباس التشريف، ولُقِّب بالمستعين بالله، ونزل إلى داره."},{"id":3253,"title":"وفاة ابن خلدون .","date":["العام الهجري :808","الشهر القمري : رمضان","العام الميلادي :1406"],"text":"هو القاضي ولي الدين أبو زيد عبد الرحمن بن محمد بن محمد بن خلدون التونسي الإشبيلي الحضرمي القاهري المالكي. وُلِدَ في تونس سنة 732. اشتغل في بلاده وسمع من الوادي آشي وابن عبد السلام وغيرهما، وأخذ القراءات عن محمد بن سعد بن براد، واعتنى بالأدب وأمور الكتابة والخط، حتى مهر في جميع ذلك. وولي كتابة العلامة عن صاحب تونس. ثم غادرها فارًّا من الطاعون متوجهًا إلى فاس في سنة ثلاث وخمسين، فعلا شأنه فيها حتى كِيدَ له فسُجِن فيها حتى أطلقه الوزير الحسن الفودوي، كان دخل في الأحوال السياسية ثم عافها بعد موت صديقه لسان الدين الخطيب، فاعتزل في قلعة بالجزائر في وهران، وألَّف فيها مقدمته المشهورة، ثم تنقل ابن خلدون بين تونس وغرناطة عند بني الأحمر وتلمسان وفاس، إلى أن استقر في مصر سنة أربع وثمانين. قال ابن حجر العسقلاني: \"قدم الديار المصرية سنة 784 في ذي القعدة، وحجَّ ثمَّ رجع فلازم ألطنبغا الجوباني، فاعتنى به إلى أن قرَّره الملك الظاهر برقوق في قضاء المالكية بالديار المصرية، فباشرها مباشرةً صعبة، وقَلَب للناسِ ظَهرَ المجن، وصار يعزِّر بالصفع ويسِّميه الزج. فإذا غضب على إنسان، قال: زجوه، فيُصفَع حتى تحمَرَّ رقبته. قرأتُ بخط البشبيشي: كان فصيحًا مفوهًا جميل الصورة، وخصوصًا إذا كان معزولًا عن القضاء. أما إذا ولي فلا يُعاشَر، بل ينبغي ألَّا يُرى. وقد ذكره لسان الدين ابن الخطيب في تاريخ غرناطة ولم يصِفْه بعلم، وإنما ذكر له تصانيف في الأدب، وشيئًا من نظمه، ولم يكن بالماهر فيه. وكان يبالغ في كتمانه، مع أنه كان جيدًا لنقد الشعر من غير تقدم فيه، ولكن محاضرته إليها المنتهى، ولما دخل الديار المصرية تلقاه أهلها وأكرموه، وأكثروا ملازمته والتردد إليه، فلما ولي المنصب تنكَّر لهم، وفتك في كثير من أعيان الموقعين والشهود. وقيل: إن أهل المغرب لما بلغهم أنه ولي القضاء عجبوا من ذلك، ونسبوا المصريين إلى قلة المعرفة، ولما دخل القضاة للسلام عليه، لم يقم لأحدٍ منهم، واعتذر لمن عاتبه على ذلك. وباشر ابن خلدون بطريقة لم يألفها أهل مصر، حتى حصل بينه وبين الركراكي تنافس، فعُقِد له مجلس، فأظهر ابن خلدون فتوى زعم أنها خط الركراكي، وهي تتضمن الحط على السلطان الظاهر برقوق. فتنصَّل الركراكي من ذلك، وتوسَّل بمن اطَّلع على الورقة فوُجِدت مُدلَّسة. فلما تحقق برقوق ذلك عزل ابن خلدون، وأعاد القاضي جمال الدين. وذلك في جمادى الأولى سنة سبع وثمانين. فكانت ولايته الأولى دون سنتين. واستمر معزولًا ثلاث عشرة سنة وثلاثة أشهر، وحجَّ في سنة تسع وثمانين. ولازمه كثير من الناس في هذه العطلة وحَسُن خلقه فيها، ومازح الناس وباسطهم، وتردد إلى الأكابر وتواضع معهم. ومع ذلك لم يغيِّرْ زيه المغربي ولم يلبَس زي قضاة هذه البلاد. وكان يحب المخالفةَ في كل شيء. ولما مات ناصر الدين ابن التنسي، طلبه الملك الظاهر برقوق، ففوض إليه القضاء في خامس عشر شهر رمضان سنة إحدى وثمانمائة. فباشر على عادته من العسف والجنف. لكنه استكثر من النواب والشهود والعقاد، على عكس ما كان في الأول، فكثرت الشناعةُ عليه، إلى أن صرف ببعض نوابه، وهو نور الدين ابن الجلال صرفًا قبيحًا، وذلك في ثاني عشر المحرم سنة ثلاث وثمانمائة. وطلب ابن خلدون إلى الحاجب الكبير فأقامه للخصوم وأساء عليه بالقول. وادَّعوا عليه بأمور كثيرة أكثرها لا حقيقة له, وحصل له من الإهانة ما لا مزيد عليه وعُزل، فتحيَّل لما حاصر تيمورلنك دمشق إلى أن حضر مجلسه، وعرَّفه بنفسه فأكرمه وقرَّبه، وكان غرضه استفساره عن أخبار بلاد المغرب، فتمكَّن منه إلى أن أذن له في السفر وزوَّده وأكرمه. فلما وصل القاهرة أعيد إلى منصب القضاء، فباشره عشرة أشهر. ثم صرف بجمال الدين البساطي إلى آخر السنة. وأعيد ابن خلدون وسار على عادته، إلا أنه تبسَّط بالسكن على البحر، وأكثر من سماع المطربات، ومعاشرة الأحداث، فكثرت الشناعة عليه. قرأت بخط جمال الدين البشبيشي في كتابه (القضاة) قال: وكان -ابن خلدون- مع ذلك أكثر من الازدراء بالناس، حتى شهد عنده الأستادار الكبير بشهادة فلم تُقبَل شهادته، مع أنه كان من المتعصبين له. ولم يشتهر عنه في منصبه إلا الصيانة، إلى أن صُرِف في سابع شهر ربيع الأول سنة ست وثمانمائة. ثم أعيد في شعبان سنة سبع، فباشر في هذه المرة الأخيرة بلين مفرِطٍ وعجزٍ وخَورٍ. ولم يلبث أن عُزِل في أواخر ذي القعدة. وقرأت بخط الشيخ تقي الدين المقريزي في وصف تاريخ ابن خلدون: (مقدمته لم يُعمَل مثالها، وإنه لعزيز أن ينال مجتهد منالها؛ إذ هي زبدة المعارف والعلوم، وبهجة العقول السليمة والفهوم، تُوقِف على كُنهِ الأشياء، وتعرف حقيقة الحوادث والأنباء، وتعبِّرُ عن حال الوجود، وتنبئُ عن أصل كل موجود، بلفظ أبهى من الدر النظيم، وألطف من الماء مر به النسيم). انتهى كلامه. وما وصفها به فيما يتعلق بالبلاغة والتلاعب بالكلام على الطريقة الجاحظية مُسلَمٌ له فيه، وأما ما أطراه به زيادة على ذلك فليس الأمر كما قال، إلَّا في بعض دون بعض، إلا أن البلاغة تُزين بزخرفها، حتى تري حسنًا ما ليس بالحسن. وقد كان شيخنا الحافظ أبو الحسن بن أبي بكر يبالغ في الغض منه. فلما سألته عن سبب ذلك، ذكر لي أنه بلغه أنه ذكر الحسين بن علي رضي الله عنهما في تاريخه، فقال: قُتل بسيف جدِّه. ولما نطق شيخنا بهذه اللفظة، أردفها بلعن ابن خلدون وسَبِّه، وهو يبكي. قلت (ابن حجر): ولم توجد هذه الكلمة في التاريخ الموجود الآن. وكأنه كان ذكرها في النسخة التي رجع عنها. والعجَبُ أن صاحبنا المقريزي كان يُفرِطُ في تعظيم ابن خلدون؛ لكونه كان يجزم بصحة نسب بني عبيد الذين كانوا خلفاء بمصر، وشهروا بالفاطميين إلى علي، ويخالف غيره في ذلك، ويدفع ما نُقِل عن الأئمة في الطعن في نسبهم ويقول: إنما كتبوا ذلك المحضر مراعاة للخليفة العباسي\". ثم استعفى وانقطع للتدريس والتأليف وله مصنفات غير مقدمته المشهورة، ومنها: كتاب العِبَر وديوان المبتدأ والخبر في أيام العرب والعجم والبربر ومن عاصرهم من ذوي السلطان الأكبر، وشرح البردة والحساب، ورسالة في المنطق، توفي في القاهرة يوم الأربعاء الخامس والعشرين من شهر رمضان فجأة عن 76 عامًا ودُفِن بمقابر الصوفية."},{"id":3254,"title":"مقاتلة الأمير جكم المتغلب على حلب مع التركمان والأعراب .","date":["العام الهجري :808","الشهر القمري : ذي القعدة","العام الميلادي :1406"],"text":"في شهر ذي القعدة في ثالثه قَدِمَ الخبر بأن الأمير جكم الجركسي الظاهري لما أخذ حلب سار إلى الأمير فارس بن صاحب الباز التركماني المتغلب على إنطاكية، وقاتله وكسره أقبح كسرة وقتله وأخذ له أموالًا جزيلة، فقوي جكم بذلك، وكان قبل ذلك جاءه الخبر بمسير الأمير نعير بن حيار أمير الملا إليه، فلقيه عند قنسرين في النصف من شوال وقاتله، فوقع نعير في قبضته، وسَجَنه بقلعة حلب، وولي ابنه العجل بن نعير إمرة آل فضل عوضًا عنه، فسار العجل إلى سلمية وعاد جكم إلى حلب، ثم بدا له في العجل رأي، فاستدعاه فأخذ يعتذر بأعذار فقبلها، وسار إلى إنطاكية، فأرسل إليه التركمان بالطاعة، وأن يمكِّنَهم من الخروج إلى الجبال لينزلوا من أماكنهم القديمة، وهم آمنون، ويسلموا إليه ما بيدهم من القلاع، فأجابهم إلى ذلك، وعاد إلى حلب، ثم سار منها يريد دمشق، منزل شيزر، وواقع أولاد صاحب الباز وكسرهم كسرةً فاحشة وأسَرَ منهم جماعة، قتلهم صبرًا، وقتل الأمير نعير أيضًا، وبعث برأسه إلى السلطان، وذلك كله في شوال، ثم واقع جكم التركمان في ذي القعدة وبدَّد شملَهم."},{"id":3255,"title":"قتال الأمير جكم الجركسي مع نائب دمشق ومعه التركمان والأعراب .","date":["العام الهجري :808","الشهر القمري : ذي الحجة","العام الميلادي :1406"],"text":"في خامس ذي الحجة اقتتل الأمير جكم الجركسي الظاهري، والأمير شيخ المحمودي نائب الشام، بأرض الرستن -فيما بين حماة وحمص-  قُتِل فيها الأمير طولو نائب صفد، والأمير علاق نائب حماة، وجماعة كثيرة من الفريقين، وانهزم الأمير شيخ ومعه الأمير دمرداش المحمدي إلى دمشق، ومضى منها إلى الرملة يريد القاهرة، فإن الأمير شيخ توجَّه من دمشق بعد عيد الأضحى، ومعه الأمير دمرداش، فنزل مرج عذراء في عسكره يريد حمص، وقد نزل بها عسكر جكم عليهم الأمير، ونزل جكم على سلمية، فلبس الأمير دمرداش خلعة نيابة حلب الواصلة إليه مع تقليده وهو بالمرج، وقدِمَ إليهم الأمير عجل ابن نعير بعربه طالبًا أخذ ثأره من جكم، ووصل أيضًا ابن صاحب الباز يريد أيضًا أخذ ثأر أخيه من جكم، ومعه جمع من التركمان، فسار بهم الأمير شيخ من المرج في ليلة الاثنين الثالث عشر إلى أن نزل قارا ليلة الثلاثاء، فوصل تقليد العجل بن نعير بإمرة العرب، وقدِمَ الأمير علان نائب حماة وحلب - كان- من مصر، وقد استقر أتابك دمشق، ونزل الأمير شيخ حمص يوم الخميس السادس عشر، فكاتب الفريقان في الصلح فلم يتِمَّ، واقتتلا في يوم الخميس الثالث والعشرين بالرستن، فوقف الأمير شيخ والأمراء في الميمنة، ووقف العرب في الميسرة، فحمل جكم بمن معه على جهة الأمير شيخ فكسره، وتحول إلى جهة العرب، وقد صار شيخ إليها وقاتلوا قتالًا كبيرًا ثبتوا فيه، فلم يطيقوا جموع جكم وانهزموا، وسار شيخ بمن معه -من دمرداش وغيره- إلى دمشق، فدخلوها يوم السبت الخامس والعشرين، وجمعوا الخيول والبغال، وأصحابهم متلاحقيين بها، ثم مضوا من دمشق بكرة الأحد، فقدم في أثناء النهار من أصحاب الأمير جكم الأمير نكبيه، وأزبك، دوادار الأمير نوروز، ونزل أزبك بدار السعادة، وقدم الأمير جرباش، فخرج الناس إلى لقاء نوروز، فدخل دمشق يوم الاثنين السابع والعشرين، ونزل الإسطبل، ودخل الأمير جكم يوم الخميس آخره، ونادى ألا يشوش أحد على أحد، وكان قد شنق رجلًا في حلب رعى فرسه في زرع، وشنق آخر بسلمية، ثم شنق جنديًّا بدمشق على ذلك، فخافه الناس، وانكفُّوا عن التظاهر بالخمر، وقُتِل في وقعة الرستن الأمير علان نائب حماة وحلب، والأمير طولو نائب صفد، قُدِّما بين يدي الأمير جكم فضرب أعناقهما وعُنُقَ طواشي كان في خدمة الأمير شيخ، كان يؤذي جماعة نوروز المسجونين، ومضى الأمير شيخ إلى جهة الرملة."},{"id":3256,"title":"طاعون عظيم يعود إلى أرض مصر .","date":["العام الهجري :809","الشهر القمري : شوال","العام الميلادي :1407"],"text":"ابتدأ الطاعون بالقاهرة ومصر، وتزايد حتى فشا في الناس وكثر الموت وبلغ عدد من يرد اسمه الديوان إلى مائتين وخمسين في كل يوم، وترجف العامة بأن عددهم أضعاف ذلك وشبهتهم أن الحوانيت المعدة لإطلاق الأموات أحد عشر حانوتًا، في كل حانوت نحو الخمسين تابوتًا، ما منها تابوت إلا ويتردد إلى الترب كل يوم ثلاث مرات وأكثر، مع كثرة ازدحام الناس عليها، وعز وجودها، فيكون على هذا عدة من يموت لا يقصر عن ألف وخمسمائة في اليوم، سوى من لا يرد اسمه الديوان من مرضى المارستان، ومن يُطرَح على الطرقات، وغالب من يموت الشباب والنساء، ومات بمدينة منوف العليا أربعة آلاف وأربعمائة إنسان، كان يموت بها في كل يوم مائة وأربعون نفرًا!"},{"id":3257,"title":"مقتل الأمير جكم الذي تسلطن وتلقب بالملك العادل .","date":["العام الهجري :809","الشهر القمري : ذي القعدة","العام الميلادي :1407"],"text":"تسلطن الأمير جكم الجركسي الظاهري بحلب يوم حادي عشر رمضان، وتلقب بالسلطان الملك العادل أبي الفتوح عبد الله جكم، وخطب باسمه من حلب إلى الفرات إلى غزة، ما عدا صفد؛ وذلك أنه عَظُم أمره جدًّا، وخاصة أن السلطان فرج بن برقوق حاول أن يزيله عن عصيانه على حلب وغيرها، فكان أولًا قد هرب جكم منه، ثم لما رحل السلطان عن حلب رجع إليها واستطاع أن يتغلب على أكثر المناطق حتى وصل أمره إلى أن ولَّى هو مِن عنده على دمشق نائبًا له، ثم كان سببُ قتله أنه لما تسلطن بمدينة حلب، ووافقه وأطاعه غالب نواب البلاد الشامية، وعَظُم أمره، وكثُرَت عساكره، وخافه كل أحد حتى أهل مصر، وتهيأ الملك الناصر فرج إلى الخروج من مصر لقتاله، ابتدأ جكم بالبلاد الشامية واستعد لأخذها، على أن الديار المصرية صارت في قبضته، وأعرض عنها حتى ينتهي من بلاد الشرق، وجعل تلك الناحية هي الأهم، وخرج من مدينة حلب بعساكره إلى نحو الأمير عثمان بن طر علي المعروف بقرا يلك، صاحب آمد، وغيرها من ديار بكر، وكان قرا يلك يومئذ نازلًا بآمد، فسار جكم حتى نزل على البيرة، وحصرها وأخذها، وقتل نائبها الأمير كزل، فأتته بها رسلُ قرا يلك يرغب إليه في الطاعة، ويسأله الرجوع عنه إلى حلب، وأنه يحمل إليه من الجمال والأغنام عدةً كبيرة، ويخطب له بديار بكر، فلم يقبل جكم ذلك، وسار حتى نزل قرب ماردين، فأقام هناك أيامًا حتى قدم الملك الظاهر مجد الدين عيسى الأرتقي صاحب ماردين، ومعه حاجبه فياض بعساكره، فاستصحبه جكم معه إلى نحو مدينة آمد، وقد تهيأ قرا يلك لقتال جكم، فعبَّأ جكم عساكره، ومشى على آمد، فالتقاه قرا يلك بظاهرها، وتقاتلا قتالًا شديدًا قاتل فيه جكم بنفسه، وقَتَل بيده إبراهيم بن قرا يلك، ثم حمل على قرا يلك بنفسه، فانهزم قرا يلك بمن معه إلى مدينة آمد وامتنعوا بها، وغلَّقوا أبوابها، فاقتحم جكم في طائفةٍ من عسكره القرا يلكية، وساق خلفهم حتى صار في وسط بساتين آمد، وكان قرا يلك قد أرسل المياه على أراضي آمد حتى صارت ربوًا، يدخل فيها الفارس بفرسِه فلا يقدر على خلاص، فلما وصل جكم إلى ذلك الموضع أخذه الرجم هو ومن معه من كل جهة، وقد انحصروا من الماء الذي فاض على الأرض، وجعلها ربوًا، فصاروا لا يمكنهم فيه الكرُّ والفر، فصوب عند ذلك بعض التركمان من القرا يلكية على جكم، وهو لا يعرفه، ورماه بحجر في مقلاع أصاب جبهته وشجَّه، وسال الدم على ذقنه ووجهه، وجكم يتجلد ويمسح الدم عن وجهه، فلم يتمالك نفسه وسقط عن فرسه مغشيًّا عليه، وتكاثر التركمان على رفقته فهزموهم بعد أن قتلوا منهم عدة كبيرة، فنزل بعض التركمان وقطع رأس جكم، وجال العسكر واضطرب أمر جيش جكم ساعة، ثم انكسروا لفَقدِ جكم، ثم أخذ التركمان في الأسر والقتل والنهب في عساكر جكم وعساكر ماردين، حتى إنه لم ينجُ منهم إلا القليل، فلما ذهب القوم نزل قرا يلك وتطلب جكم بين القتلى حتى ظفر به، فقطع رأسه، وبعث به إلى السلطان الملك الناصر إلى الديار المصرية، وقُتِل في هذه الواقعة مع الأمير جكم من الأعيان: الملك الظاهر عيسى صاحب ماردين، وكان من أجَلِّ الملوك، والأمير ناصر الدين محمد بن شهري حاجب حجاب حلب، والأمير قمول نائب عينتاب، وصارو سيدي، وفر الأمير تمربغا المشطوب، وكمشبغا العيساوي، حتى لحقا بحلب في عدة يسيرة من المماليك."},{"id":3258,"title":"وفاة محمد السابع سلطان بني نصر وقيام أخيه أبي الحجاج مكانه .","date":["العام الهجري :810","العام الميلادي :1407"],"text":"هو محمد السابع المستعين بن أبي الحجاج يوسف الثاني ملك بني نصر -بني الأحمر- في غرناطة بالأندلس، وقام بالأمر بعده أخوه أبو الحجاج يوسف الثالث الناصر، وكان معتقَلًا في سجن قلعة شلوبانية الحصينة القريبة من ثغر المنكب، والذي كان قد حبسه هو أخوه الملك محمد السابع هذا، وقام الملك الجديد أبو الحجاج بتجديد الهدنة مع ملك قشتالة لمدة تنتهي سنة 813."},{"id":3259,"title":"تغلب الأمير شيخ المحمودي على دمشق وعصيانه ثم قتله .","date":["العام الهجري :810","الشهر القمري : ربيع الآخر","العام الميلادي :1407"],"text":"في صفر حضر السلطان إلى دمشق وأمر باعتقال الأمير شيخ المحمودي نائبها ومعه الأمير يشبك الشعباني وحُبِسا بالقلعة، وأما الأمير جركس المصارع فهرب، ووكل بهما الأمير منطوق ولكنهما استطاعا أن يستميلاه، فهربوا جميعًا من القلعة، فأرسل وراءهم ولكن لم يُقتَل إلا منطوق، واستطاع يشبك وجركس وشيخ التغلُّبَ على حمص، ثم لما رحل السلطان عن دمشق وترك عليها الأمير بكتمر شلق، ثم لما كانت ليلة الأحد ثامن ربيع الآخر طرق الأمير شيخ - ومعه يشبك وجركس المصارع- دمشق، ففرَّ من كان بها من الأمراء وملك شيخ دمشق، وقبض على جماعة، وولى وعزل، ونادى بالأمان، وأخذ خيول الناس، وصادر جماعة، فورد الخبر في يوم الأربعاء الحادي عشر، بأن بكتمر شلق نزل بعلبك في نفر قليل، فسار يشبك وجركس في عسكر، فمضى بكتمر إلى جهة حمص، فوافاهم الأمير نوروز بجمع كبير على كروم بعلبك، فكانت بينهما وقعة قُتِل فيها يشبك وجركس المصارع في طائفة، وقبض نوروز على عدة ممن معهما، فلما بلغ ذلك الأمير شيخ سار من دمشق على طريق جرود في ليلة الجمعة الثالث عشر، وهي الليلة التي تلي يوم الوقعة، ودخل نوروز دمشق يوم السبت الرابع عشر بغير ممانع."},{"id":3260,"title":"تولية أمير مكة إمرة الحجاز كلها وعصيان جماز بن نعير بالمدينة .","date":["العام الهجري :811","العام الميلادي :1408"],"text":"أضاف السلطانُ إمرةَ المدينة النبوية، وإمرة ينبع، وخليص، والصفراء، وأعمالهم، إلى الشريف حسن بن عجلان أمير مكة، وكتب له بذلك توقيعًا، وهذا شيء لم ينَلْه أمير مكة قبله في هذا الزمان، أما المدينة فإن أميرها كان ثابت بن نعير، فمات فولى حسن بن عجلان مكانَه نيابة عنه أخاه، فثار بالمدينة جماز بن نعير، فكتب إليه ابن عجلان يقول: اخرُجْ بسلام، وإلَّا فأنا قاصدك، فأظهر جماز الطاعة، ثم إن جماز أرسل إلى الخُدَّام بالمسجد النبوي يستدعيهم، فامتنعوا، فأتى إلى المسجد وأخذ ستارتي باب الحجرة النبوية، وطلب من الطواشية -خدام المسجد- المصالحة عن حاصل القبَّة بتسعة آلاف درهم، فأبَوا ذلك، فطلب مفاتيح الحاصل من زين الدين أبي بكر بن حسين قاضي المدينة، فمانعه، فأهانه وأخذها منه، وأتى إلى القبة، وضرب شيخ الخدَّام بيده، ألقاه على الأرض، وكسر الأقفال ودخلها ومعه جماعة، فأخذ ما هناك؛ فمن ذلك أحد عشر حوائج خاناه، وصندوقين كبيرين، وصندوقًا صغيرًا فيه ذهب من ودائع ملوك العراق وغيرهم، وأخرج خمسة آلاف شقة بطاين معدة لأكفان الموتى، فنقل ذلك كله، وهمَّ أحد بني عمه بأخذ قناديل الحجرة الشريفة، فمنعه، وأخذ آخَرُ بُسُط الروضة، فأمره جماز برَدِّها، وصادر بعضَ الخدام، ثم خرج من الغد الحادي عشر راحلًا، فقصد العرب المجتمعة الرجوع، فرماهم الناس بالحجارة، ثم في السنة التالية ولى السلطان بدمشق الشريف جماز بن نعير إمرة المدينة النبوية، وشرط عليه إعادة ما أخذ من الحاصل، وولى أيضًا جمال الدين محمد بن عبد الله الكازروني قضاء المدينة، وبعث لهما توقيعهما وتشريفهما."},{"id":3261,"title":"حدوث زلزلة عظيمة في نواحي بلاد حلب وطرابلس .","date":["العام الهجري :811","الشهر القمري : شعبان","العام الميلادي :1409"],"text":"وقعت زلزلةٌ عظيمة في نواحي بلاد حلب وطرابلس، فخرب من اللاذقية وجبلة وبلاطنس أماكن عديدة، وسقطت قلعة بلاطنس. فمات تحت الردم بها خمسة عشر نفسًا، ومات بجبلة خمسة عشر نفسًا، وخربت شغر بكاس كلها والقلعتين بها، ومات جميع أهلها، إلا نحو خمسين نفسًا، وانشقَّت الأرض, وكما وقعت الزلزلة أيضًا بقبرص فخربت منها أماكن كثيرة."},{"id":3262,"title":"عصيان الأمير شيخ المحمودي نائب دمشق وقتاله مع السلطان .","date":["العام الهجري :812","الشهر القمري : محرم","العام الميلادي :1409"],"text":"أفرج الأمير شيخ المحمودي نائب الشام عن الأمير سودن تلي الحمدي، والأمير طوخ، والأمير سودن اليوسفي، وهم الذين طلبهم السلطان، فامتنع من إرسالهم إليه حتى غضب، وسار من مصر إلى دمشق ليأخُذَ الأمير شيخ، ثم أظهر شيخ ما في نفسه، وصرح بالخروج عن طاعة السلطان، وأخذ في الاستعداد، وطلب الأمراء الذين أفرج عنهم إليه بالمرج، في ليلة الثامن والعشرين من المحرم واستدعى قضاة دمشق وفقهاءها، وتحدث معهم بحضرة الأمراء بجواز محاربة السلطان، فأفتاه شهاب الدين أحمد بن الحسباني بما وافق غرَضَه، ثم في شهر صفر أوله السبت في ليلة السبت نزل السلطان باللجون، فشاع بين العسكر تنكُّر قلوب المماليك الظاهرية على السلطان، وتحدثوا بإثارة فتنة لتقديمه مماليكه الجلب -هكذا يُعرَفون- عليهم، واختصاصه بهم، وكثرة عطائه لهم، فلما أصبح السلطان رحل ونزل بيسان من آخره، فما هو إلا أن غربت الشمس، واشتد اضطراب الناس، وكثر قلق السلطان وخوفُه طول الليل إلى أن طلع الفجر، فرحل إلى جهة دمشق، وفي ليلة الخميس سادسه نزل السلطان الكسوة، ففر الأمير علان وجماعة من المماليك إلى جهة الأمير شيخ، فركب السلطان بكرة يوم الخميس ودخل دمشق، وفي ثاني ربيع الأول سارت أطلاب السلطان والأمراء من دمشق إلى الكسوة، وتبعهم السلطان بعساكره، وعليهم آلة الحرب، فبات بالكسوة، وأصبح راحلًا إلى جهة الأمير شيخ، وسار بكرة يوم الثلاثاء، فمر بالصنمين، ونزل من آخره برأس الماء على بريد من الصنمين، وبات فقَدِمَ الخبر بالتقاء كشافة السلطان بكشافة الأمير شيخ، وأسْرِهم رجلًا من الشيخية، وسار السلطان بكرةَ يوم الأربعاء إلى قرية الحراك، فنزل نصف النهار ثم رحل رحيلًا مزعجًا، ظنَّ الناس أن العدو قد طرقهم، فجدَّ في مسيره ونزل عند الغروب بكرك البثنية من حوران، وفي يوم الخميس سار السلطان إلى أن نزل ظاهر مدينة بصرى، فتحقق هناك خبر الأمير شيخ، وأنه في عصر يوم الأربعاء الماضي بلغه أن السلطان قد سار في إثره، فرحل فَزِعًا يريد صرخد، فأقام السلطان على بصرى إلى بكرة السبت، وقَدِمَ عليه ببصرى من الشيخية الأمير برسباي والأمير سودن اليوسفي، فكتب بذلك إلى دمشق، ثم سار ونزل بقرية عيون -تجاه صرخد- فكانت حرب بين أصحابه وبين الشيخية، قُتِل فيها فارسان من الشيخية، وجرح من السلطانية جماعة، ففرَّ منهم جماعة إلى الأمير شيخ، فلَحِقوا به، وكثر تخوُّف السلطان من أمرائه ومماليكه، وبلغه أنهم عوَّلوا على أنه إذا وقع مصاف الحرب، تركوه ومضوا إلى الأمير شيخ، فبات ليلته مستعدًّا لأن يُؤخَذ، ودبَّر أمرًا كان فيه نجاتُه، وسار بهم فلم يفجأ القوم إلا وقد طلع عليهم من ثنية هناك، وقد عبأ الأمير شيخ أصحابه، فأوقف المصريين ناحية، وقدم عليهم الأمير تمراز الناصري نائب السلطة، ووقف في ثقاته -وهم نحو الخمسمائة فارس- وحطم عليهم السلطان بنفسه ومن معه، فانهزم تمراز بمن معه من أول وهلة، وثبت الأميرُ شيخ فيمن معه، فكانت بينهم معارك صدرًا من النهار، وأصحاب الأمير شيخ تنسَلُّ منه، وهو يتأخر إلى جهة القلعة، وكانت الحرب بين جدران مدينة صرخد، فولى السلطان وطاق الشيخية، وانتهب أصحابه جميع ما كان فيه من خيل وجِمال، وثياب وأثاث، وخيام وآلات، وغيرها، فحازوا شيئًا كثيرًا، واستولى السلطان على جامع صرخد، وأصعده أصحابَه، فرَمَوا من أعلى المنارة بمكاحل النفط والأسهم الخطالية على الأمير شيخ، وحمل السلطان عليه حملة واحدة منكرة، فانهزم أصحاب شيخ، والتجأ في نحو العشرين إلى قلعة صرخد، وكانت خلف ظهره، وقد أعدها لذلك، فتسارع إليه عدة من أصحابه، وتمزَّق باقيهم، فأحاط السلطان بالمدينة، ونزل على القلعة، فأتاه الأمراء فهَنَّؤوه بالظفر، وامتدت الأيدي إلى صرخد، فما تركوا بها لأهلها جليلًا ولا حقيرًا، حتى أخذوه نهبًا وغصبًا، فامتلأت الأيدي مما لا يدخل تحت حصر، ولم يزل السلطان على قلعة صرخد يرميها بالمدافع والسهام، ويقاتل من بها ثلاثة أيام بلياليها، حتى أحرق جسر القلعة، فامتنع الأمير شيخ ومن معه بداخلها، وركبوا أسوارها، فأنزل السلطان الأمراء حول القلعة، وألزم كل أمير بقتال جهة من جهاتها، واستدعى المدافع ومكاحل النفط من الصبيبة وصفد ودمشق، ونَصَبها حول القلعة، وتمادى الحصر ليلًا ونهارًا، حتى قدم المنجنيق من دمشق على مائتي جمل، فلما تكامل نَصبُه ولم يبقَ إلا أن يرمي بحجره ترامى الأمير شيخ ومن معه من الأمراء على الأمير الكبير تغري بردي الأتابك، وألقوا إليه ورقة في سهم من القلعة، يسألونه فيها الوساطة بينهم وبين السلطان، فما زال حتى بعثه السلطان إليهم، فصعد إلى القلعة ومعه الخليفة وكاتب السر فتح الله، وجماعة من ثقات السلطان، في يوم السبت الثامن والعشرين، فجلسوا على شفير الخندق، وخرج الأمير شيخ، وجلس بداخل باب القلعة، ووقف أصحابه على رأسه، وفوق سور القلعة، وتولى كاتب السر محادثة الأمير شيخ، فطال الخطب بينهما، واتسع مجال الكلام؛ فتارة يعظه، وأخرى يؤنِّبه ويوبِّخُه، وآونة يعدِّدُ بالله على السلطان من جميل الأيادي وعوائد النصر على أعدائه، ويخوِّفه عاقبة البغي، وفي كل ذلك يعتذر الأمير شيخ، ثم انصرفوا على أن الأمير شيخ لا يقابل السلطان أبدًا خوفًا من سوء ما اجترمه، وقبيح ما فعله، فأبى السلطان إلا أن ينزل إليه، وأعاد الأمير تغري بردي وفتح الله فقط، بعدما ألح تغري بردي على السلطان في سؤاله العفو، فأحلف الأمير شيخ، وأخذ منه الأمير كمشبغا الجمالي وأسنبغا، بعدما خلع عليهما، وأدلاهما بحبال من سور القلعة، ثم أرخى أيضًا ابنه ليبعث به إلى السلطان، فصاح الصغير وبكى من شدة خوفِه، فرحمه من حضر، وما زالوا به حتى نشله، وتصايح الفريقان من أعلى القلعة، وفي جميع خيم العسكر، فرحًا وسرورًا بوقوع الصلح، وذلك أن أهل القلعة كانوا قد أشفَوا على الأخذ لقلة زادهم ومائهم، وخوفًا من حجارة المنجنيق، فإنها كانت تدمرهم تدميرًا، لو رمى بها عليهم، وأما العسكر فإنهم كانوا طول إقامتهم يسرحون كل يوم، فينهبون القرى نهبًا قبيحًا، ويأخذون ما يجدونه من الغلال والأغنام وآلات النساء، ويعاقبون من ظفروا به حتى يُطلِعَهم على ما عنده من علف الدواب وغيره، وفيهم من يتعرَّض للحريم فيأتون من القبائح بما يشنع ذكره، وهذا وهم في خصاصة من العيشِ، وقلة من المأكل، وكادت بركة صرخد أن يُنزح ماؤها، ومع ذلك فإن أصحاب السلطان معظمهم غير مناصِح له، لا يريدون أن يظفر بالأمير شيخ خشية أن يتفرغ منه لهم؛ فلهذا حسن موقع الصلح من الطائفتين، وبات العسكر على رحيل، وأصبحوا يوم الأحد، فركب الأمير تغري بردي، وكاتب السر فتح الله، والأمير جمال الدين، ومعظم الأمراء، فصعدوا إلى قلعة صرخد، وجلسوا على شفير خندقها فخرج الأمير شيخ وجلس بداخل باب القلعة، ووقف من معه على رأسه، ومن فوق السور، وأحلف فتح الله من بقي مع الأمير شيخ المحمودي من الأمراء للسلطان، وهم: جانم نائب حماة، وقرقماس ابن أخي دمرداش نائب صفد، وتمراز الأعور، وأفرج الأمير شيخ عن يحيي بن لاقي وتجار دمشق، وغيرهم ممن كان مسجونًا معه، وبعث للسلطان تقدمة فيها عدة مماليك، وتقرر الحال على مسير الأمير شيخ نائبًا بطرابلس، وأن يلبس التشريف السلطاني إذا رحل السلطان، فلما عادوا إلى السلطان رحل من صرخد، وقد رحل أكثر المماليك من الليل، فسار في قليل من ثقاته، وترك عدة من الأمراء على صرخد، وأنفق فيهم خمسة وعشرين ألف دينار وستين ألف درهم فضة، خارجًا عن الغنم والشعير، ونزل زرع فبات بها، ثم في شهر جمادى الأولى في ثالثه: قرئ بدمشق كتاب السلطان بأنه قد ولى الأمير شيخ نيابة طرابلس، فإن قصد دمشق فدافعوه عنها وقاتلوه، وكان الأمير شيخ قد قصد دمشق، وكتب إلى الأمير بكتمر جلق بأنه يريد دخول دمشق، ليقضيَ بها أشغاله ويرحل إلى طرابلس، فكثر تخيُّل السلطان من دخوله إليها، وفي ليلة الجمعة عاشره نزل الأمير شيخ على شقحب، وكان الأمير بكتمر قد خرج إلى لقائه بعسكر دمشق، ونزل قبة يلبغا، ثم ركب ليلًا يريد كبس الأمير شيخ، فلقي كشافته عند خان ابن ذي النون، فواقعه فبلغ ذلك الخبر شيخًا، فركب وأتاه، فلم يثبت بكتمر، وانهزم وأتى الأمير شيخ فنزل بمن معه قبة يلبغا، ودخل بكرة يوم الجمعة إلى دمشق، ونزل بدار السعادة من غير ممانع، ثم تغلب على دمشق بدل نائبها نوروز الحافظي الذي لم يستطع دخول دمشق؛ لمكان شيخ فيها، بل ظل محصورًا في حماة مع نائبها."},{"id":3263,"title":"القتال بين أولاد السلطان العثماني بايزيد الأول .","date":["العام الهجري :813","العام الميلادي :1410"],"text":"اتجه محمد جلبي لقتال أخيه عيسى، وجرت بينهما عدة معارك خرج فيها محمد منتصرًا وقُتِل عيسى، فرجعت الأناضول تحت إمرته، ثم إن محمدًا الأول أرسل أخاه موسى على رأس جيش لقتال أخيهما سليمان الذي استطاع أن يهزم جيش موسى، فعاد خائبًا، ثم إنه كرر المحاولة مرة أخرى فتمكن في هذه السنة من القضاء على سليمان، وقَتَله على أبواب أدرنة، ثم بعد ذلك اتجه إلى الصرب الذين كانوا أعلنوا استقلالهم عن الدولة العثمانية في أثناء الأزمة التي جرت على الدولة العثمانية أثناء غزو تيمورلنك والخلاف بين أبناء بايزيد، ثم إن ملك المجر أسرع لمساندة الصرب ولكنهم باؤوا بالهزيمة أمام الجيش العثماني."},{"id":3264,"title":"فرنج قشتالة يهزمون المسلمين ويستولون على مدينة أشقيرة بالأندلس .","date":["العام الهجري :813","الشهر القمري : محرم","العام الميلادي :1410"],"text":"لما أوقع الطاغية صاحب قشتالة بالمسلمين في الزقاق، كثرت غاراته في بلاد المسلمين بالأندلس، وكثرت غاراتهم أيضًا على بلاد قشتالة، وكان ألفونسو قد قام بأمر أخيه دون، وكان عارفًا بالحروب والمكايد، شجاعًا، دَربًا، شديد البأس، فجمع لحرب المسلمين، ونزل على أشقيرة -تجاه مالقة - أول ذي الحجة، فلم يستنجد أبو الحجاج يوسف بن يوسف بن محمد بن إسماعيل بن نصر ابن الأحمر -صاحب غرناطة- عساكر فاس كما هي العادة، بل رأى أن في عسكره كفاية، وجهَّز أخويه محمدًا وعليًّا على عسكر الأندلس، وقد جمع أهل القرى بأسرها، وخرجوا من غرناطة في ثامن عشر ذي الحجة سنة اثنتي عشرة وثمانمائة، ونزلوا على حصن أرشذونة -وهو على ستة أميال من أشقيرة- حتى تكاملت الجموع في الثامن والعشرين، ثم ساروا في ليلة التاسع والعشرين وعسكروا تجاه العدو، بسفح جبل المدرج، فما استقَرَّت، وقد أعجبتهم أنفسهم بهذه الدار حتى زحف العدو لحربهم، فثاروا لقتاله، وقد أعجبتهم أنفسهم، واغتروا بكثرتهم، وتباهوا بزينتهم، ولم يراقبوا الله في أمرهم، فما أحد إلا ومعه نوع من المعاصي كالخمر والأحداث، فلما اشتد القتالُ في الليل، انهزم العدو بعد ما قتل من المسلمين عشرة فرسان، ولما كان أول يوم من محرم سنة ثلاث عشر، نادى أخو السلطان في العسكر بالنفقة، وكانت نفقة السفر قد أُخِّرت عن وقتها؛ لئلا يأخذها العسكر ولا يشهدوا الحرب، وجُعِلت عند حضور الجهاد، فهَمَّ في أخذ النفقة، وإذا بالعدو وقد أقبل عند طلوع الشمس، فخرجت المطوعة وقاتلتهم، وأقام العسكر بأجمعهم لأخذ النفقة، وعلم العدو بذلك فرجعوا كأنهم منهزمين، والمطوعة تتبعُهم، وتنادي في العسكر: يا أكالين الحرامِ، العامةُ هزمت النصارى، وأنتم في خيامكم جلوس، فلما وصل العدو إلى معسكرهم وقفوا للحرب، وقد اجتمع جميع رجالة المسلمين طمعًا في الغنيمة، فإذا العدو وقد خندق على معسكره ورتَّب عليه الرماة، فسُقِط في أيديهم، ووقفوا إلى الظهر في حيرة، فخرج أمراء الطاغية عند ذلك من جوانب الخندق، وحملوا على المسلمين، فقتَلوا من قاتلهم، وأسروا من ألقى منهم سلاحه، حتى وصلوا مخيَّم المسلمين، فركب طائفة من بني مرين وبني عبد الواد، وقاتلوا على أطراف خيمهم قليلًا، وانهزموا هم وجميع أهل الأندلس، بحيث خرج أخوا السلطان بمن معهما مشاة إلى الجبل على أقدامهم، فأحاط العدو بجميع ما كان معهم، وأكثروا من القتل فيهم، وكانت عدة من قُتل من المعروفين من أهل غرناطة خاصة مائة ألف إنسان، سوى من لم يُعرَف، وسوى أهل أقطار الأندلس؛ بحرِها وبَرِّها، سهلها وجبلها؛ فإنهم عالم لا يحصيه إلا الله تعالى، وأقام النصارى ثلاثة أيام يتتبعون المسلمين، فيقتلون ويأسرون، وبعث الطاغية إلى أعماله يخبرهم بنصرته، فلما بلغ ذلك أهل أبدة وسبتة، وأهل حيان، خرجوا إلى وادي أش -وهو بيد المسلمين- ونزلوا قريبًا من حصن أرتنة، فاستغاث أهل الحصن بأهل غرناطة، فأمدوهم بعسكر، فصار النصارى إلى حصن مشافر، وقاتلوا أهله حتى أخذوا الربض، وشرعوا في تعليق الحصن، وإذا بعسكر غرناطة قد جاءهم في سابع المحرم، فأوقعوا بهم وقيعة شنعاء، أفنَوهم فيها، وأسروا منهم زيادة على ألف وخمسمائة، وعادوا إلى غرناطة بهم، فدخلوا في تاسعه، وبلغ ذلك الطاغية -وهو على حصار أشقيرة- فكف أصحابه عن الدخول بعدها إلى بلاد المسلمين، وأقام على الحصار ستة أشهر حتى ضَعُفت أحوال المسلمين بأشقيرة، ورفعوا كرائم أموالهم إلى حصنها، وتعلقوا به، فملك الطاغية المدينة بما فيها من الأزواد والأمتعة، ووقع مع هذا في المسلمين الوخم، فمات منهم جماعة كثيرة، فاضطرهم الحال إلى طلب الأمان؛ ليلحقوا ببلاد المسلمين بأموالهم فأمَّنهم ألفونسو على أن يخرجوا بما يطيقون حمله، فخرجوا بأجمعهم إلى معسكره، فوفى لهم، وجهز جميع المسلمين، وبعث من أوصلهم إلى غرناطة، فلم يفقد أحد منهم، ولا شراك نعل وأقام بأشقيرة من يثق به، وعاد عنها قافلًا إلى بلاده في أوائل جمادى الآخرة، فكانت هذه الحادثة من أشنع ما أصاب المسلمين بالأندلس!"},{"id":3265,"title":"الأمير المحمودي والأمير نوروز يحاولان خلع السلطان فرج بن برقوق .","date":["العام الهجري :813","الشهر القمري : محرم","العام الميلادي :1410"],"text":"في شهر ذي الحجة من سنة اثنتي عشرة وثمانمائة قاتل (الأمير شيخ المحمودي)  نوروزًا ودمرداش، سبعة أشهر وحاصرهما بحماة، ووقع بينهم في هذه المدة المذكورة حروب وخطوب يطول شرحها، وقُتِل بينهم خلائق لا تُحصى، واشتد الأمر على نوروز وأصحابه بحماة، وقلَّت عندهم الأزواد وقاسوا شدائد حتى وقع الصلح بينه وبين الأمير شيخ، وذلك عندما سمعوا بخروج الملك الناصر فرج إلى البلاد الشامية، وخاف نوروز إن ظفر به الملك الناصر لا يبقيه، فاحتاج إلى الصلح، وحلف كل من نوروز والأمير شيخ لصاحبه، وأما السلطان الملك الناصر فإنه أخذ في التجهيز إلى السفر نحو البلاد الشامية، وعَظُم الاهتمام في أول محرم هذه السنة، وأما الأمير شيخ فإنه لما بلغه خروج السلطان من الديار المصرية لم يَثبُت، وداخَلَه الخوف، وخرج من دمشق في يوم الثلاثاء السادس والعشرين من شهر ربيع الأول بعساكره ومماليكه، وتبعه الأمير جانم نائب حماة، فدخل بكتمر جلق إلى الشام من الغد في يوم السابع والعشرين -على حين غفلة- حتى يطرق الأمير شيخًا، ففاته الأمير شيخ بيوم واحد، لكنه أدرك أعقابه وأخذ منهم جماعةً، ونهب بعض أثقال الأمير شيخ، ثم دخل السلطان الملك الناصر إلى دمشق بعد عشاء الآخرة من ليلة الخميس الثامن والعشرين، وقد ركب من بحيرة طبرية في عصر يوم الأربعاء على جرائد الخيل ليكبسَ الأمير شيخًا، ففاته بيسير، وكان الأمير شيخ قد أتاه الخبر وهو جالس بدار السعادة من دمشق، فركب من وقته وترك أصحابه، ونجا بنفسه بقماش جلوسه، فما وصل إلى سطح المزة إلا وبكتمر جلق داخل دمشق؟ ومر الأمير شيخ على وجهه منفردًا عن أصحابه، ومماليكه وحواشيه في أثره، والجميع في أسوأ ما يكون من الأحوال، وسار السلطان بعساكره إلى جهة حلب حتى وصلها في قصد الأمير شيخ ونوروز بمن معهما من الأمراء، ثم كتب السلطان لنوروز والأمير شيخ يخيِّرُهما، إما الخروج من مملكته، أو الوقوف لمحاربته، أو الرجوع إلى طاعته، فأجابه الأمير شيخ بأنه ليس بخارج عن طاعته، ويعتذر عن حضوره بما خامر قلبه من شدة الخوف والهيبة عندما قبض عليه السلطان مع الأتابك يشبك الشعباني في سنة 810، وأنه قد حلف لا يحارب السلطان ما عاش، من يوم حلفه الأمير الكبير تغري بردي في نوبة صرخد، وكرَّر الاعتذار عن محاربته لبكتمر جلق، حتى قال: وإن كان السلطان ما يسمح له بنيابة الشام على عادته، فينعم عليه بنيابة أبلستين، وعلى الأمير نوروز بنيابة ملطية، وعلى يشبك بن أزدمر بنيابة عينتاب، وعلى غيرهم من الأمراء ببقية القلاع؛ فإنهم أحق من التركمان المفسدين في الأرض، فلم يرضَ السلطان بذلك، وصمَّم على الإقامة ببلاد الشام، وبينما السلطان بحلب ورد عليه الخبر بأن الأمير شيخًا ونوروزًا وصلا عينتاب، وسارا على البرية إلى جهة الشام، فركب السلطان مسرعًا من حلب على حين غفلة في الثالث والعشرين شهر رجب ببعض عساكره، وسار حتى دخل دمشق في أربعة أيام، وأما الأمير شيخ ونوروز، فإنهما لما سار السلطان عن أبلستين خرجا من قيسارية بمن معهم، وجاؤوا إلى أبلستين فمنعهم أبناء دلغادر وقاتلوهم، فانكسروا منهم وفروا إلى عينتاب، فلما قربوا من تل باشر تمزقوا، وأخذت كل طائفة جهة من الجهات، فلحق بحلب ودمشق منهم عدة وافرة، واختفى منهم جماعة، ومرَّ الأمير شيخ ونوروز بحواشيهما على البرية إلى تدمر فامتاروا منها، ومضَوا مسرعين إلى صرخد وتوجَّهوا إلى البلقاء ودخلوا بيت المقدس، ثم توجهوا إلى غزة وأقاموا بها حتى أخرج السلطان إليهم بكتمر جلق على عسكر كبير، فسار إلى زرع، ثم كتب للسلطان يطلب نجدة، فأخرج إليه السلطان من دمشق بعسكر هائل من الأمراء والمماليك السلطانية، فلما وصل بكتمر جلق بمن معه من الأمراء إلى غزة، وبلغه توجه الأمير شيخ ونوروز إلى جهة مصر، إلى أن وصلوا إلى مصر في يوم الأحد ثامن شهر رمضان ودخل معهم إلى القاهرة خلائق من الزعر، وبني وائل -من عرب الشرقية - والأمير سعيد الكاشف هو معزول، وأصبح الأمير شيخ أقام رجلًا في ولاية القاهرة فنادى بالأمان، ووعد الناس بترخيص الأسعار، وبإزالة المظالم، فمال إليه جمع من العامة، وأقاموا ذلك اليوم، وملكوا مدرسة الملك الأشرف شعبان التي كانت بالصوة تجاه الطبلخاناة السلطانية، هذا والقتال مستمر بينهم وبين أهل القلعة، ثم طلبوا من الأمراء الذين بالقلعة فتح باب القلعة لهم، قالوا: ما لنا غرض في النهب، وإنما نريد أن نأخذ ابن أستاذنا -يعنون بابن أستاذنا: الأمير فرج ابن السلطان الملك الناصر فرج- فقال كافور الزمام: وأيش أصاب السلطان حتى تأخذوا ولده؟ فقالوا: لو كان السلطان حيًّا ما كنا هاهنا -يعنون أنهم قتلوا السلطان، وساروا إلى الديار المصرية ليسلطنوا ولده- فلم يمش ذلك على كافور ولا على غيره، وطال الكلامُ بينهم في ذلك، فلم يلتفت كافور إلى كلامهم، فهددوه بإحراق الباب، فخاف وبدأ يماطلهم؛ لعلمه بمجيء العسكر المصري من الشام، وبينما كافور الزمام في مدافعتهم لاحت طلائع العسكر السلطاني لمن كان الأمير شيخ أوقفه من أصحابه يرقبهم بالمآذن بقلعة الجبل، وقد ارتفع العجاج، وأقبلوا سائقين سوقًا عظيمًا جهدهم، فلما بلغ الأمير شيخ وأصحابه ذلك لم يثبتوا ساعةً واحدةً، وركبوا من فورهم ووقفوا قريبًا من باب السلسلة، فدهمهم العسكر السلطاني فولَّوا هاربين نحو باب القرافة، والعسكر في أثرهم، فكبا بالأمير شيخ فرسُه عند سوق الخيم بالقرب من باب القرافة، فتقنطر من عليه، فلم يستطع النهوض ثانيًا؛ لعظم روعه وسرعة حركته، فأركبه بعضُ أمراء آخوريته وركب الأمير شيخ ولحق بأصحابه، فمروا على وجوههم على جرائد الخيل، وتركوا ما أخذوه من القاهرة، وأيضًا ما كان معهم، وساروا على أقبح وجه بعد أن قبض عسكر السلطان على جماعة من أصحاب الأمير شيخ، ودخل الأمير بكتمر جلق بعساكره، وأرسل الأمير سودون الحمصي فاعتقل جميع من أمسك من الشاميين، وأخذ يتتبَّعُ من بقي من الشامية بالقاهرة، ثم نادى في الوقت بالأمان، وقدم عليه الخبر في ليلة الأربعاء حادي عشر من شهر رمضان بأن الأمير شيخًا نزل إطفيح وأنهم افترقوا فرقتين؛ فرقة: رأسها الأمير نوروز الحافظي، ويشبك بن أزدمر، وسودون بقجة، وفرقة: رأسها الأمير شيخ المحمودي، وسودون تلي المحمدي، وسودون قراصقل، وكل فرقة منهما معها طائفة كبيرة من الأمراء والمماليك، وأنهم لما وصلوا إلى الشوبك دفعهم أهلها عنها، فساروا إلى جهة الكرك وبها سودون الجلب، فتضرعوا له حتى نزل إليهم من قلعة الكرك، وتلقاهم وأدخلهم مدينة الكرك، وأنهم استقروا بالكرك، واستمر السلطان بدمشق إلى يوم سابع عشر ذي القعدة، وخرج منها إلى قبة يلبغا، ورحل من الغد بأمرائه وعساكره يريد الكرك بعدما تحقق نزول الأمراء بالكرك، وأما الأمير شيخ ونوروز وجماعتهما، فإنهم أقاموا بالكرك أيامًا، واطمأنوا بها، ثم أخذوا في تحصينها، وأما السلطان الملك الناصر فإنه سار من مدينة دمشق حتى نزل على مدينة الكرك في يوم الجمعة الرابع والعشرين ذي القعدة، وأحاط بها ونصَب عليها الآلات، وجَدَّ في قتالها، وحصرها وبها الأمير شيخ ونوروز وأصحابهما، واشتدَّ الحصار عليهم بالكرك، وأخذ الملك الناصر يلازم قتالهم حتى أشرفوا على الهلاك والتسليم، ثم أخذ الأمير شيخ ونوروز والأمراء يكاتبون الأمير تغري بردي ويتضرعون إليه، وهو يتبرَّم من أمرهم والكلام في حقهم، ويوبخهم بما فعله الأمير شيخ مع بكتمر جلق بعد حَلِفِه في واقعة صرخد، فأخذ الأمير شيخ يعتذر ويحلف بالأيمان المغلظة أن بكتمر جلق كان الباغي عليه والبادئ بالشر، وأنه هو دفع عن نفسه لا غير، وأنه ما قَصْدُه في الدنيا سوى طاعة السلطان، ولا زالوا حتى تكلم تغري بردي مع السلطان في أمرهم، ثم تردَّدت الرسل بينهم وبين السلطان أيامًا حتى انعقد الصلح، على أن يكون تغري بردي نائب الشام، وأن يكون الأمير شيخ نائب حلب، وأن يكون الأمير نوروز نائب طرابلس، وكان ذلك بإرادة الأمير شيخ ونوروز، فإنهما قالا: لا نرضى أن يكون بكتمر جلق أعلى منا رتبة بأن يكون نائب الشام، ونحن أقدم منه عند السلطان، فإن كان ولا بد، فيكون الأمير الكبير تغري بردي في نيابة الشام، ونكون نحن تحت أوامره، ونسير في المهمات السلطانية تحت سنجقه، وأما بكتمر ودمرداش فلا، وإن فعل السلطان ذلك لا يقع منا بعدها مخالفة أبدًا، ولما بلغ الأمراء والعساكر هذا القول أعجبهم غاية الإعجاب، وقد ضجر القوم من الحصار، وملوا من القتال، فلا زالوا بالسلطان حتى أذعن ومال إلى تولية تغري بردي نيابة الشام، وكان السلطان قد شرط على الأمراء شروطًا كثيرة فقبلوها، على أن يكون تغري بردي نائب دمشق."},{"id":3266,"title":"وفاة الملك أحمد بن أويس الجلائري وانقضاء دولة بني جلائر المغولية .","date":["العام الهجري :813","الشهر القمري : ربيع الآخر","العام الميلادي :1410"],"text":"هو أحمد بن أويس بن الشيخ حسن النوين بن حسين بن أقبغا بن أيلكان بن القال غياث الدين سلطان العراق. أوَّل ما ولي إمرة البصرة من أخيه حسين، فلما اختلف الأمراء على حسين خرج من بغداد إلى تبريز، فقدم أحمد بالجنود واغتال أخاه وقام بالسلطنة، وذلك في صفر سنة أربع وثمانين، وقبض على أعيان الأمراء فقتلهم وأقام أولادهم، فثار عليه من بقي ببغداد مع أخيه شيخ على شاه زاده؛ فآل الأمر إلى أن قتل واستبد أحمد فسار السيرة الجائرة وقتل في يوم واحد ثمانمائة نفس من الأعيان وانهمك في اللذات، واتفق أن تيمورلنك نازل شاه منصور صاحب شيراز وقتله وبعث برأسه إلى بغداد، والتمس منهم ضرب السكة باسمه، فلم يُطِعْه أحمد، فنزل تيمورلنك بغداد في شوال سنة خمس وتسعين، ففرَّ منها ابن أويس بأهله وما يعزُّ عليه من ماله، فلحقه عسكر تيمورلنك بالحلة فهزموه ونهبوا ما معه وخربوا الحلة، وقَصَد الشام فوصل إلى الرحبة واستأذن الظاهر في القدوم عليه، فأجابه بما يطيب خاطره وأمر النواب بإكرامه، ثم جهز السلطان أحمد بن أويس في أول شعبان سنة 796 ورسم له بجميع ما يحتاج إليه، فدخل بغداد في رمضان فوجد بها مسعود الخراساني من جهة تيمورلنك، ففر وأقام أحمد ببغداد، واستخدم جنودًا من العرب والتركمان، ووقع الوباء ببغداد، ففر أحمد إلى الحلة، وجرى على سيرته السيئة من سفك الدماء والجِدِّ في أخذ أموال الرعية، ولم يزل على ذلك إلى أن عاد تيمورلنك طالبًا الشام، ففرَّ أحمد إلى قرا يوسف بن قرا محمَّد بن بيرم خجا صاحب الموصل واستنجد به فسار معه، وكان أهل بغداد قد كرهوه فحاربوه وهزموهما معًا، فدخلا بلاد الشام واستأذنا أمير حلب وكان يومئذٍ دقماق من جهة الناصر فرج، وذلك في شوال سنة 802، فلم يأذن لهم فخرج لمحاربتهم فاقتتلوا قتالًا شديدًا، فانهزم أهل حلب وأُسِرَ دقماق، فبلغ الناصر ذلك فغضب وأمر بتجهيز عساكر الشام، فتوجهوا ففر قرا يوسف فأوقعوا بأحمد فكسروه ونهبوا ما معه وبعثوا بسيفه إلى الناصر. رجع أحمد إلى بغداد فأقام بها قليلًا فثار عليه ولده طاهر بن أحمد ففر منه وأتى إلى قرا يوسف فسار معه وقاتلا طاهرًا بالحلة، فانهزم وغرق، ودخل أحمد بغداد ثم غدر أحمد بجماعة كانوا عنده من جهة قرا يوسف عدتهم خمسون نفسًا من أعيان دولته، فغضب قرا يوسف وسار لمحاربة أحمد، فهرب ثم اختفى في بئر ببغداد، فأمر قرا يوسف بطم البئر، فطُمَّت فما شكُّوا في هلاكه، واتفق أنه كان بالبئر فرجة فخرج منها ابن أويس ومضى إلى تكريت ثم إلى حلب، وملك قرا يوسف بغداد فأخذها منه تيمورلنك, فكتب قرا يوسف إلى أحمد ليجتمعا على قتال عسكر تيمورلنك فنازلا مرزا أبي بكر بن تيمورلنك بالسلطانية سنة 808، فهزموه وقتلوا ابنه, وملك قرا يوسف تبريز ورجع أحمد إلى بغداد، فاستأذنه قرا يوسف فيمن يقيمه في السلطنة، فأذن له بإقامة ولده بزق ففعل، وذلك في سنة إحدى عشرة، فقدم مرزا شاه في طلب ثأر ولده، فواقعه قرا يوسف فقتل، وغنم قرا يوسف جميع ما كان معه, واتفق في غضون ذلك أن أحمد لما تغلب على طباعه من الغدر مضى إلى تبريز فملكها، ونهب جميع ما وجده لقرا يوسف وولده، فرجع إليه وقاتله فانهزم منه، وذلك في ربيع الآخر سنة ثلاث عشرة، فلم يزل قرا يوسف يتطلب ابن أويس إلى أن ظفر به فأكرمه، ثم سجنه ثم دسَّ عليه من خنقه، فمات في آخر يوم من ربيع الآخر، واستقرت قدم قرا يوسف في بغداد وتبريز، وكان أحمد بن أويس سفاكًا للدماء، متجاهرًا بالقبائح، وله مشاركة في عدة علوم، كالنجوم والموسيقى، وله شعر كثير بالعربية وغيرها؛ وكتب الخط المنسوب، وكانت له شجاعة ودهاء وحِيَل، ومحبة في أهل العلم."},{"id":3267,"title":"الفرنج يحاولون إعادة عمارة بيت لحم .","date":["العام الهجري :813","الشهر القمري : جمادى الآخرة","العام الميلادي :1410"],"text":"وصل إلى ميناء يافا أربع قطع، فيها نحو سبعمائة من الفرنج، فأسَروا جماعة من المسلمين، وأخذوا مركبًا فيه خام للسلطان قَدِمَ من مصر، وقدم أيضًا إلى يافا مركب فيه فرنج، معهم أخشاب وعَجَل وصُنَّاع، برسم عمارة بيت لحم بالقدس؛ حيث مولِدُ عيسى عليه السلام، وبيدهم مرسوم السلطان بتمكينهم من العمل، فدعوا الناس للعمل بالأجرة، فأتاهم عدة من القلعة والصنَّاع، وشرعوا في إزاحة ما بطريقهم من الأوعار، وكان سبب هذا أن موسى -وهو صبي بطرك النصارى الملكانية- سأل السلطان لما قدم إلى القدس، بعد نوبة صرخد، في سنة 812 أن يمكن النصارى من إعادة عمارة مولد عيسى ببيت لحم على ما كان عليه، فكتب له بذلك مرسومًا، فطار به كلَّ مطار، وبعثه إلى بلاد الفرنج فاغتنموا الفرصة، وبعثوا هؤلاء، فبدؤوا بتوسعة الدرب الآخذ من ميناء روبيل إلى القدس، وقصدوا أن يصير سعته بحيث يمر فيه عشرة فرسان متواكبين، فإنه لم يكن يسع غير فارس واحد بمشقة، وأحضروا معهم دهنًا إذا وضعوه على تلك الصخرة سَهُل قطعها. فلما رجع الناصر إلى دمشق عرف نصحاؤه بسوء القالة في ذلك، فكتب إلى أرغون كاشف الرملة يمنعهم من ذلك والقبض عليهم وعلى من معهم من الصنَّاع وآلات السلاح والجِمال والدهن، فخُتِم على مخازنهم وحملهم وما معهم."},{"id":3268,"title":"تأسيس الدولة الكثيرية الأولى .","date":["العام الهجري :814","العام الميلادي :1411"],"text":"في أواخرِ القرنِ السادسِ الهِجريِّ كانت حَضرَموتُ مَيدانًا لِلمُناوراتِ السياسيةِ والفَوضى، حيث الصِّراعاتُ بينَ أطرافٍ مُتعدِّدةٍ، كبَني راشِدٍ وبَني يَمانٍ، وعَساكِرِ الغُزِّ الهاجمين مِنَ العَساكرِ المِصريةِ، وجُيوشِ ابنِ مَهديٍّ اليَمنيِّ، وغَيرِها مِنَ القَبائلِ والعَشائرِ الحَضرَميةِ، كبَني نَهدٍ وبَني حارِثةَ، فكانت حَضرَموتُ مُتفرقةً بينَ وُلاةٍ مُتعدِّدينَ، مُنتشرًا فيها النَّهبُ وسَفكُ الدِّماءِ، ولم يَنفَعْها احتِلالُ الأيُّوبيِّينَ لها. وفي ظِلِّ هذا الوَضعِ رأى آلُ كَثيرٍ -وهم أعظَمُ قبائِلِ هَمَدانَ، وهم قَبائلُ مُتعدِّدةٌ- أنْ يُؤسِّسوا لِأنفُسْهم دولةً، وأنْ يَكونَ لهم دَورٌ في إنهاءِ حالةِ الفَوْضى والفِتنةِ المُكتَسِحةِ في حَضرَموتَ. فاقتَرَب بَنو كَثيرٍ مِن مَشايخِ العِلْمِ والصَّلاحِ مِن آلِ البَيتِ العَلويِّينَ ومِن أهلِ السُّنةِ، على أمَلِ تأسيسِ دولةٍ سُنِّيةٍ شافعيةٍ، على أنقاضِ المَذهبِ الأباضيِّ الذي انتَهت دولتُه عامَ 561هـ. بدأ آلُ كَثيرٍ بتَقويةِ نُفوذِهمُ السياسيِّ، وفي عامِ 683هـ تحالَفَ آلُ كَثيرٍ مع سالمِ بنِ إدريسَ الحَبُوظيِّ، أميرِ ظَفارِ، الذي أخَذَ يَتوسَّعُ في الاستيلاءِ على البُلدانِ بحَضرَموتَ، وتولَّى آلُ كَثيرٍ إدارةَ العَسكريةِ الحَبُوظيَّةِ، ثم لم يَلبَثْ أنِ انهَزَم سالمُ بنُ إدريسَ وقُتلَ على يَدِ السُّلطانِ المُظفَّرِ الغَسَّانيِّ مَلكِ الدولةِ الرَّسوليةِ. وأخَذَ آلُ كَثيرٍ بعدَ مَقتلِ سالمِ بنِ إدريسَ في تَثبيتِ ما بأيديهم مِنَ القُرى، والاستيلاءِ على مَناطِقَ أُخرى، وكانَ مُلكُهم يَنبسِطُ مَرَّةً ويَتقلَّصُ أُخرى، لِتَخاصُمِهم وتَنازُعِهم فيما بَينَهم، وفيما بينَ غَيرِهم مِنَ المُنافِسينَ، وفي أواخِرِ القرنِ الثامِنِ الهِجريِّ تَفرَّغَ أبناءُ جَعفرِ بنِ بَدرٍ الكَثيريِّ وهم (يَمانيٌّ ومُدرِكٌ وعُمَرُ) لِمُناوشةِ قَبيلةِ الظلفانِ، والتفَتَ أفرادُ الوحدةِ الكَثيريةِ الآخَرون إلى تَدبيرِ السَّلطنةِ، وفي هذه الأثناءِ وُلد السُّلطانُ علِيُّ بنُ عُمَرَ بنِ جَعفرٍ الكَثيريُّ، الذي به أصبحتِ الدولةُ الكَثيريةُ رَسميةً، يَعرِفُها جُمهورُ أهلِ القُطرِ الحَضرميِّ. وكانت بدايةُ الدولةِ الكَثيريةِ الأولى حين غادَرَ السُّلطانُ علِيُّ بنُ عُمَرَ \"بُورَ\" سنةَ 814هـ، واتَّصلَ بالشيخِ عليِّ بنِ عُمَرَ باعَبَّادٍ وغيرِه مِن رِجالِ الصَّلاحِ، وكانوا يَعِدُونه بالاستيلاءِ على ظَفارِ وجَميعِ بُلدانِ حَضرَموتَ، فاشتَدَّ عَزمُه بذلك، وشرَعَ في تَذليلِ العَقباتِ، يُحارِبُ ويَغزو حتى استتَبَّ له الأمرُ، وخضَعَت له الرِّقابُ واستَحقَّ لَقَبَ سُلطانٍ."},{"id":3269,"title":"السلطان فرج بن برقوق يقتل المماليك الشراكسة مماليك أبيه وغيرهم .","date":["العام الهجري :814","العام الميلادي :1411"],"text":"قبض السلطانُ الناصِرُ فرج على جماعةٍ من كبار المماليك الظاهرية -مماليك برقوق- وحبسهم بالبرج من القلعة، ثم قتَلَهم بعد شهر، وكانوا جمعًا كبيرًا، ثم في شهر رجب نزل السلطان من القلعة إلى الصيد، فبات ليلةً وعزم على مبيت ليلة أخرى بسرياقوس، فبلغه أن طائفة من الأمراء والمماليك اتفقوا على قتله، فعاد إلى القاهرة مسرعًا، وأخذ يتتبَّعُ ما قيل حتى ظفر بمملوكين عندهما الخبر، فعاقبهما في ثامن عشر شهر رجب، فأظهرا ورقةً فيها خطوط جماعة كبيرة، كبيرُهم الأمير جانم، وكان جانم قد سافر قبل تاريخه إلى منية ابن سلسيل، وهي من جملة إقطاعه، فندب السلطان الأمير بكتمر جلق، والأمير طوغان الحسني الدوادار؛ لإحضار جانم ومَسَك السلطان بعد خروجهما جماعةً كبيرةً من الأمراء والمماليك الظاهرية ووسَطَ منهم خمسةً، فنفرت القلوب منه، ووجد شيخ ونوروز للوثوب عليه سبيلًا. ذبح السلطان في ليلة الأربعاء مُستهلَّ شعبان عشرين مملوكًا ممن قُبِض عليهم، ثم وَسَط من الأمراء في يوم الأربعاء الثامن عشر آخر تحت القلعة، وفي ليلة الأربعاء قتل السلطان أيضًا بالقلعة من المماليك الظاهرية زيادة على مائة مملوك من الشراكسة من مماليك أبيه، ثم إن السلطان نادى في أول شهر رمضان بالقلعة بالأمان، وأنهم عتقاء شهر رمضان، فظهر منهم جماعة، فأَمِنوا، وتتابع بقيتهم حتى ظهر قريب من ثلاثين مملوكًا في عدة أيام، فوُعدوا بخير، وأن يُعطَوا الخيل، ورُسِم لهم بيوم يجتمعون فيه لأخذ خيولهم فاغترُّوا وحضروا، فقُبِض عليهم كلهم وحبسوا، وتتبع المماليك السلطانية، وجلس السلطان لتفريق القرقلات برسم الرسم عليهم، فقبض على جماعة كثيرة منهم وسَجَنهم، فما انقضى شهر رمضان حتى زادت عدة المسجونين من المماليك السلطانية على أربعمائة رجل، ثم ذبح السلطان في ليلة ثالث شوال أزيدَ من مائة نفس من المماليك السلطانية الظاهرية المحبوسين بالبرج، ثم أُلقوا من سور القلعة إلى الأرض، ورُموا في جبٍّ مما يلي القرافة، واستمر الذبحُ فيهم."},{"id":3270,"title":"عودة الأميرين شيخ ونوروز للخروج عن طاعة السلطان فرج بن برقوق .","date":["العام الهجري :814","الشهر القمري : جمادى الآخرة","العام الميلادي :1411"],"text":"تواترت الأخبارُ بأنَّ الأميرين شيخًا ونوروزًا قد اتفقا على الخروج عن طاعة السلطان، وعزما على أخذ حماة، فوقع الشروع في عمارة قلعة دمشق، وكُتِبَ تقدير المصروف على ذلك مبلغ ثلاثين ألف دينار، وفيه وقع الاهتمام في بلاد الشام بتجهيز الإقامات للسلطان، وفي شهر رجب قدم الخبر بأن الأمير نوروزًا نائب طرابلس توجَّه منها إلى حصن الأكراد وحاصرها، وأن الأمير شيخًا كتب إليه أنه اتفق مع جماعة من قلعة حلب على أن يسلِّموها له، وأشار عليه أن يرجع إلى طرابلس يحصل قلعة حلب بيده، وأن الاتفاق وقع بينهما على أن يجهزا سودن الجلب على ثلاثمائة فارس ليأخُذَ حماة، وأن الأمير شيخًا أرسل إلى ناصر الدين محمد بن دلغادر يعرض عليه نيابة عينتاب فلم يقبل ذلك، وأنه خرج من حلب يريد العمق، فنزله آخر جمادى الآخرة، وجمع عليه طائفة التركمان البياضية وابن سقل سيز، ابن صاحب الباز، وغيرهم من التركمان والعرب، وأنه أوقع بعمر بن كندر في ثالث رجب، ثم قاتل التركمان في سابعه، فكسرهم، وأسر منهم جماعة، وأنه بعث أحمد الجنكي أحد ندمائه بهدية إلى قرا يوسف، وأن نوروزًا بعث إليه بهدية أخرى صحبة بهلوان من أصحابه، وفي شهر رمضان تأكد عند السلطان خروج الأميرين شيخ ونوروز عن طاعته، وأنهما عزما على أخذ دمشق، وأن سودن الجلب ويشبك بن أزدمر سعيا في ذلك، وأن الأمير نوروزًا قتل أقسنقر الحاجب، ثم في شهر ذي الحجة خرج السلطان بجيشه من مصر يريد الشام وأن يأخذ الأمير شيخًا ونوروزًا، ثم جاء الخبر بأن الأمراء الذين تقدموه قد خرجوا عن الطاعة، فلم يَثبُت، وسار السلطان من غزة مجدًّا في طلبهم، وقد نفرت منه القلوب، وتمالأت على بُغضِه؛ لقبح سيرتِه، وسوء سريرتِه، وفي السادس والعشرين ذي الحجة نزل الأمراء الذين تقدموا بقبة يلبغا خارج دمشق، وركبوا إلى الأمير تغري بردي نائب الشام، فعادُوه وقد اشتد به مرضُه، وأعلنوا بما هم عليه من الخلاف للسلطان، والخروج عن طاعته، ثم رحلوا عن قبة يلبغا في التاسع والعشرين، ونزلوا على برزة يريدون اللحاق بالأميرين شيخ ونوروز على حمص، فلم يوافقهم على ذلك الأمير شاهين الزردكاش، فقبضوا عليه ومضوا، ونزل السلطان الكسوة في بكرة يوم الثلاثاء آخره، وقد فتَّ في عَضُدِه مخالفة الأمراء عليه، ولاحت أمارات الخذلان عليه، وظهرت كآبة الزوال والإدبار، فألبس من معه من العسكر السلاح، ورتَّبهم بنفسه، ثم ساق بهم، وقصد دمشق."},{"id":3271,"title":"نزول الفرنج دمياط وهزيمتهم .","date":["العام الهجري :814","الشهر القمري : شوال","العام الميلادي :1412"],"text":"نزل عددٌ من الفرنج على دمياط في أربعة أغربة وبيونيين -نوعين من المراكب-  فقاتلهم المسلمون على بر الطينة قتالًا كبيرًا، جُرح فيه جماعة من المسلمين، وقُتِلت خيولهم. فمضى الفرنج في آخر النهار إلى بر الطينة القديمة، ونهبوا ما كان هناك، وأتوا من الغد إلى حيث كانوا، فقاتلوا المسلمين مرة ثانية قتالًا كثيرًا، وعادوا إلى مراكبهم، فقدم في الحال غراب من أغربة المسلمين، فأحاط به الفرنج، فلم يثبت من كان في الغراب وألقَوا أنفسهم في الماء، وخلصوا إلى البر -وكانوا قريبًا منه- ثم مضوا إلى دمياط؛ فتكاثر المسلمون على الفرنج، وأخذوا منهم غراب المسلمين بعد قتال شديد، وقتلوا منهم إفرنجيينِ وأخذوا سلاحًا، فانهزم بقيتهم، وحُمِل الرأسان والسلاح إلى السلطان."},{"id":3272,"title":"خروج السلطان الناصر فرج بن برقوق لقتال الأمراء المتمردين .","date":["العام الهجري :815","الشهر القمري : محرم","العام الميلادي :1412"],"text":"خرج السلطان الملك الناصر فرج من دمشق بعساكره في يوم الاثنين سادس المحرم، ونزل برزة، ثم رحل منها يريد محاربة الأمراء الخارجين عليه: نوروز الحافظي، وشيخ المحمودي، ونزل حسيا بالقرب من حمص، فبلغه رحيل القوم من قارا إلى جهة بعلبك، فترك أثقاله بحسيا وساق على أثرهم إلى بعلبك، فوجدهم قد توجهوا إلى البقاع، فقصدهم، فمضوا نحو الصبيبة، فتبعهم حتى نزلوا باللجون، فساق السلطان خلفهم وهو سكران لا يعقِل، فما وصل إلى اللجون حتى تقطعت عساكره عنه من شدة السَّوق، ولم يبقَ معه غير من ثَبَت على سوقه، وهم أقل ممن تأخَّر، وكان قد وصل وقت العصر من يوم الاثنين ثالث عشر المحرم، فوجد الأمراء قد نزلوا باللجون وأراحوا، وفي ظنهم أنه يتمهَّلُ ليلته ويلقاهم من الغد، فإذا جنَّهم الليل ساروا بأجمعهم من وادي عارة إلى جهة الرملة، وسلكوا البرية عائدين إلى حلب، وليس في عزمهم أن يقاتلوه أبدًا، لا سيما الأمير شيخ المحمودي فإنه لا يريد ملاقاته بوجه من الوجوه، فحال وصول الملك الناصر إلى اللجون أشار عليه الأتابك دمرداش المحمدي أن يريح خيلَه وعساكره تلك الليلة، ويقاتلهم من الغد، فأجابه السلطان بأنهم يفرُّون الليلة، فقال له دمرداش: إلى أين بقُوا يتوجهون يا مولانا السلطان بعد وقوع العين في العين؟ يا مولانا السلطان مماليكك في جهد وتعب من السَّوق، والخيول كَلَّت، والعساكر منقطعة، فلم يلتفت إلى كلامِه، وحرَّك فرسه ودقَّ بزخمته على طبله، وسار نحو القوم، وحمل عليهم بنفسِه من فوره حال وصولِه، فارتضمت طائفة من مماليكه في وحلٍ كان هناك، ثم قبل اللقاء خرج الأمير قجق أحد أمراء الألوف بطلبه من مماليكه وعسكره، وذهب إلى الأمراء، وتداول ذلك مع المماليك الظاهرية واحدًا بعد واحد، والملك الناصر لا يلتفت إليهم، ويشجِّع من بقي معه حتى التقاهم وصدمهم صدمةً هائلة، وتقهقر عسكره مع قلتهم، فانهزم السلطان عند ذلك، بعد أن قاتل بنفسه، وساق يريد دمشق -وكان الرأي توجهه إلى مصر- وتبعه سودون الجلب، وقرقماس ابن أخي دمرداش، ففاتهما الملك الناصر ومضى إلى دمشق، وأحاط القوم بالخليفة المستعين بالله، وفتح الدين فتح الله كاتب السر، وناظر الجيش بدر الدين حسن بن نصر الله، وناظر الخاص ابن أبي شاكر، واستولوا على جميع أثقال الملك الناصر وأمرائه، وامتدت أيدي أصحاب الأمراء إلى النهب والأسر في أصحاب الملك الناصر، وما غربت الشمس حتى انتصر الأمراء وقَوِيَ أمرهم، وباتوا تلك الليلة بمخيماتهم، وهي ليلة الثلاثاء، وأصبح الأمراء وليس فيهم من يرجع إليه، بل كل واحد منهم يقول: أنا رئيس القوم وكبيرهم، وأما الملك الناصر فإنه لما انكسر سار نحو دمشق حتى دخلها ليلة الأربعاء في ثلاثة نفر، ونزل بالقلعة واستدعى القضاة والأعيان ووعدهم بكل خير، وحثَّهم على نصرته والقيام معه، فانقادوا له، فأخذ في تدبير أموره، وتلاحقت به عساكره شيئًا بعد شيء في العاشر من محرم، ثم أحضر السلطان الأموال وصبها وأتاه الناس من كل فج من التركمان والعربان والعشير وغيرهم، فكتب أسماءهم وأنفق عليهم وقوَّاهم بالسلاح، وأنزل كل طائفة منهم بموضع يحفظه، فكان عدة من استخدمه من المشاة زيادةً على ألف رجل، وحَصَّن القلعة بالمجانيق والمدافع الكبار، وأتقن تحصين القلعة؛ بحيث إنه لم يبق سبيلٌ للتوصل إليها بوجه من الوجوه واستمر ذلك إلى بكرة يوم السبت ثامن عشر المحرم، فنزل الأمراء على قبة يلبغا خارج دمشق، فندب السلطان عسكرًا فتوجهوا إلى القبيبات، فبرز لهم سودون المحمدي، وسودون الجلب، واقتتلوا حتى تقهقر السلطانية منهم مرتين، ثم انصرف الفريقان، وفي يوم الأحد تاسع عشر المحرم ارتحل الأمراء عن قبة يلبغا، ونزلوا غربي دمشق من جهة الميدان، ووقفوا من جهة القلعة إلى خارج البلد، فتراموا بالنشاب نهارهم وبالنفط، فاحترق ما عند باب الفراديس من الأسواق، فلما كان الغد من يوم الاثنين عشرين محرم اجتمع الأمراء للحصار، فوقفوا شرقي البلد وقبليه، ثم كروا راجعين ونزلوا ناحية القنوات إلى يوم الأربعاء الثاني والعشرين، ووقع القتال من شرقي البلد، ونزل الأمير نوروز بدار الطعم، وامتدت أصحابه إلى العقيبة، ونزل طائفة بالصالحية والمزة، ونزل الأمير شيخ بدار غرس الدين خليل تجاه جامع كريم الدين الذي بطرف القبيبات ومعه الخليفة وكاتب السر فتح الله، ونزل بكتمر جلق وقرقماس المدعو بسيدي الكبير في جماعة من جهة بساتين معين الدين ومنعوا الميرة عن الملك الناصر، وقطعوا نهر دمشق، ففُقد الماء من البلد، وتعطلت الحمَّامات، وغُلِّقت الأسواق، واشتدَّ الأمر على أهل دمشق، واقتتلوا قتالًا شديدًا، وتراموا بالسهام والنفوط، فاحترق عدة حوانيت بدمشق، وكثرت الجراحات في أصحاب الأمراء من الشاميين، وأنكاهم السلطانية بالرمي من أعلى السور، وعَظُم الأمر، وكلُّوا من القتال، ثم بلغ الأمير شيخ المحمودي أن الملك الناصر عزم على إحراق ناحية قصر حجاج حتى يصير فضاءً ثم يركب بنفسه ويواقع القوم هناك بمن يأتيه من التركمان وبمن عنده، فبادر الأمير شيخ وركب بعد صلاة الجمعة بأمير المؤمنين ومعه العساكر، وسار من طريق القبيبات ونزل بأرض الثابتية، وقاتل الملك الناصر في ذلك اليوم أشد قتال إلى أن مضى من الليل جانب، وكثر من الشاميين الرمي بالنفط عليهم، فاحترق سوق خان السلطان وما حوله، وحملت السلطانية على الشيخية حملةً عظيمة هزموهم فيها، وتفرقوا فِرَقًا، وثبت الأمير شيخ في جماعة قليلة بعدما كان انهزم هو أيضًا إلى قريب الشويكة، ثم تكاثر الشيخية وانضم عليهم جماعة من الأمراء، فحمل الأمير شيخ بنفسه بهم حملة واحدة أخذ فيها القنوات، ففرَّ من كان هناك من التركمان والرماة وغيرهم، وكان الأتابك دمرداش المحمدي نازلًا عند باب الميدان تجاه القلعة، فلما بلغه ذلك ركب وتوجه إلى الملك الناصر وهو جالس تحت القبة فوق باب النصر، وسأله أن يندب معه طائفة كبيرة من المماليك السلطانية؛ ليتوجه بهم إلى قتال الأمير شيخ؛ فإنه قد وصل إلى طرف القنوات، وسهل أخذه على السلطان، فنادى الملك الناصر لمن هناك من المماليك وغيرهم بالتوجه مع دمرداش، فلم يجِبْه منهم أحد، ثم كرر السلطان عليهم الأمر غيرَ مرة حتى أجابه بعضهم جوابًا فيه جفاء وخشونة ألفاظ، معناه أنهم ملوا من طولِ القتال، وضَجِروا من شدة الحصار، وبينما هم في ذلك إذ اختبط العسكر السلطاني وكثر الصراخ فيهم بأن الأمير نوروزًا قد كبسهم، فسارعوا بأجمعهم وعبروا من باب النصر إلى داخل مدينة دمشق، وتفرَّقوا في خرائبها بحيث إنه لم يبقَ بين يدي السلطان أحد، فولى دمرداش عائدًا إلى موضعه، وقد ملك الأمير شيخ وأصحابه الميدان والإسطبل، فبعث دمرداش إلى السلطان مع بعض ثقاته بأن الأمر قد فات، وأن أمر العدو قوي، وأمر السلطان أخذ في إدبار، والرأي أن يلحق السلطان بحلب ما دام في الأمر سعة، فلما سمع الملك الناصر ذلك قام من مجلسه وترك الشمعة تتقد حتى لا يقع الطمع فيه بأنه ولى، ويوهم الناس أنه ثابت مقيم على القتال، ثم دخل إلى حَرَمِه وجهَّز ماله، وأطال في تعبئة ماله وقماشه، فلم يخرج حتى مضى أكثر الليل، والأتابك دمرداش واقف ينتظره، فلما رأى دمرداش أن الملك الناصر لا يوافقه على الخروج إلى حلب، خرج هو بخواصه ونجا بنفسه، وسار إلى حلب وترك السلطان، ثم خامر الأمير سنقر الرومي على الملك الناصر، وأتى أمير المؤمنين وبطل طبول السلطان والرماة، ثم خرج الملك الناصر من حرمه بماله، وأمر غلمانه فحُمِلت الأموال على البغال ليسير بهم إلى حلب، فعارضه الأمير أرغون من بشبغا الأمير آخور الكبير وغيره، ورغبوه في الإقامة بدمشق، وقالوا له: الجماعة مماليك أبيك لا يوصلون إليك سوءًا أبدًا، ولا زالوا به حتى طلع الفجر، فعند ذلك ركب الملك الناصر بهم، ودار على سور المدينة فلم يجد أحدًا ممن كان أعدَّه للرمي، فعاد ووقف على فرسه ساعة، ثم طلع إلى القلعة والتجأ بها بمن معه -وقد أشحنها- وترك مدينة دمشق، وبلغ أمير المؤمنين والأمراء ذلك، فركب الأمير شيخ بمن معه إلى باب النصر، وركب نوروز بمن معه إلى نحو باب توما، ونصب الأمير شيخ السلالم حتى طلع بعض أصحابه، ونزل إلى مدينة دمشق وفتح باب النصر، وأحرق باب الجابية، ودخل شيخ من باب النصر، وأخذ مدينة دمشق، ونزل بدار السعادة، وذلك في يوم السبت تاسع صفر، بعدما قاتل الملك الناصر نحو العشرين يومًا، قُتِل فيها من الطائفتين خلائق لا تُحصى، ووقع النهب في أموال السلطان وعساكره، وامتدت أيدي الشيخية وغيرهم إلى النهب، فما عفوا ولا كفُّوا، وركب أمير المؤمنين ونزل بدار في طرف ظواهر دمشق، وتحول الأمير شيخ إلى الإسطبل، وأنزل الأمير بكتمر جلق بدار السعادة، كونه قد ولي نيابة دمشق قبل تاريخه، هذا والسلطانية ترمي عليهم من أعلى القلعة بالسهام والنفوط يومهم كله، وباتوا ليلة الأحد على ذلك، فلما كان يوم الأحد عاشر صفر بعث الملك الناصر بالأمير أسندمر أمير آخور في الصلح، وتردد بينهم غير مرة حتى انعقد الصلح بينهم، وحلف الأمراء جميعهم وكُتِبت نسخة اليمين، ووضعوا خطوطهم في النسخة المذكورة، وكتب أمير المؤمنين أيضًا خطه فيها، وصعد بها أسندمر إلى القلعة ومعه الأمير ناصر الدين محمد بن مبارك شاه الطازي أخو الخليفة المستعين بالله لأمه، ودخلا على الملك الناصر وكلماه في ذلك، وطال الكلام بينهم، فلم يعجب الملك الناصر ذلك، وترددت الرسل بينهم غير مرة بغير طائل، وأمر الملك الناصر أصحابه بالرمي عليهم، فعاد الرمي من أعلى القلعة بالمدافع والسهام، وركب الأمراء واحتاطوا بالقلعة، فأرسل الملك الناصر يسأل بالكف عنه، فضايقوا القلعة خشية أن يفر السلطان منها إلى جهة حلب، ومشت الرسل أيضًا بينهم ثانيًا، وأضر الملك الناصر التضييق والغلبة إلى أن أذعن إلى الصلح، وحلفوا له ألا يوصلوا إليه مكروهًا، ويؤمِّنوه على نفسه، وأن يستمِرَّ الخليفة سلطانًا، وقيل غير ذلك: وهو أنه ينزل إليهم، ويتشاور الأمراء فيمن يكون سلطانًا، فإن طلبه المماليك فهو سلطان على حاله، وإن لم يطلبوه فيكون الخليفة، ويكون هو مخلوعًا يسكن بعض الثغور محتفظًا به، ومحصول الحكاية أنه نزل إليهم في ليلة الاثنين حادي عشر صفر، ومعه أولاده يحملهم ويحملون معه، وهو ماشٍ من باب القلعة إلى الإسطبل والناس تنظُره، وكان الأمير شيخ نازلًا بالإسطبل، فعندما عاينه الأمير شيخ قام إليه وتلقَّاه وقبَّل الأرض بين يديه، وأجلسه بصدر المجلس، وجلس بالبعدِ عنه وسكَّن روعه، ثم تركه بعد ساعة وانصرف عنه، فأقام الملك الناصر بمكانه إلى يوم الثلاثاء ثاني صفر، فجمع الأمراء والفقهاء والعلماء المصريون والشاميون بدار السعادة بين يدي أمير المؤمنين وقد تحول إليها وسكنها، وتكلموا في أمر الملك الناصر والمحضر المكتب في حقه، فأفتوا بإراقة دمه شرعًا، فأخذ في ليلة الأربعاء من الإسطبل، وطلع به إلى قلعة دمشق، وحبسوه بها في موضع وحدَه، وقد ضُيِّق عليه وأُفرِدَ من خَدَمِه، فأقام على ذلك إلى أن قُتِلَ ليلة السبت سادس عشر صفر."},{"id":3273,"title":"خلع السلطان الناصر فرج بن برقوق وتولية الخليفة العباسي المستعين .","date":["العام الهجري :815","الشهر القمري : محرم","العام الميلادي :1412"],"text":"دار الأمرُ بين السلطان والأمراء العصاة عليه، وفي هذه الأثناء وفي يوم السبت خامس عشرين المحرم خلع الخليفة المستعين بالله الملكَ الناصر فرج من السلطنة، واتفق الأمراء على إقامة الخليفة المستعين بالله أبي الفضل العباس ابن الخليفة المتوكل على الله أبي عبد الله محمد ابن الخليفة المعتصم بالله أبي بكر ابن الخليفة المستكفي بالله أبي الربيع سليمان ابن الخليفة الحاكم بأمر الله أبي العباس أحمد بن الحسن بن أبي بكر بن علي بن الحسين في السلطنة؛ لتستقيم بسلطنته الأحوال، وتنفذ الكلمة، وتجتمع الناس على سلطان، وثبت خَلعُ الملك الناصر على القضاة، وأجمعوا على إقامة الخليفة سلطانًا، فامتنع الخليفة من ذلك غايةَ الامتناع، وخاف ألا يتمَّ له ذلك فيَهلِك، وصمم على الامتناع، وخاف من الملك الناصر خوفًا شديدًا، فلما عجز عنه الأمراء دبَّروا عليه حيلةً، وطلبوا الأمير ناصر الدين محمد بن مبارك شاه الطازي أخا الخليفة المستعين بالله لأمِّه، فندبوه بأن يركب ومعه ورقة تتضمن مثالب الملك الناصر ومعايبه، وأن الخليفة قد خلعه من المُلكِ وعزله من السلطنة، ولا يحل لأحد معاونته ولا مساعدته، فلما بلغ الخليفة ذلك لام أخاه ناصر الدين بن مبارك شاه على ذلك، وأيس الخليفة عند ذلك من انصلاح الملك الناصر له، فأذعن لهم حينئذ بأن يتسلطن؟ فبايعوه بأجمعهم، وحلفوا له بالأيمان المغلظة والعهود على الوفاء له وعلى القيام بنصرته ولزوم طاعته، وأما الملك الناصر فإنه لما تسلطن الخليفة، وخُلِعَ هو من المُلك، نفر الناس عنه وصاروا حزبين: حزبًا يرى أن مخالفة الخليفة كُفر، والناصر قد عُزِل من الملك، فمن قاتل معه فقد عصى اللهَ ورسوله، وحزبًا يرى أن القتال مع المَلِك الناصر واجب، وأنه باقٍ على سلطنته، ومن قاتله إنما هو باغٍ عليه وخارج عن طاعته، ومن حينئذٍ أخذ أمر الملك الناصر في إدبار."},{"id":3274,"title":"اغتيال السلطان المخلوع فرج بن برقوق في حبسه في قلعة دمشق .","date":["العام الهجري :815","الشهر القمري : صفر","العام الميلادي :1412"],"text":"هو الملِكُ الناصر فرج ابن السلطان برقوق، سلطان مملوكي، تولى عرش مصر بعد وفاة والده برقوق وعمره 13 سنة. حدث في عهده قحطٌ عام في البلاد وانتشرت أوباء مات فيها ثلث سكان البلاد, كما سادت الفتن والاضطرابات في عهده؛ فقد ثار عليه أمراء المماليك الظاهرية مماليك أبيه؛ لأنه قرَّب المماليك الجركسية وأبعدهم، وقتل عددًا كبيرًا من أمراء المماليك الظاهرية فقاتلوه حتى خلعوه من السلطنة، ثم تم القبض عليه وحَبسُه في القلعة إلى أن قُتِل بعد اختلاف كبير وقع في أمره بين الأمراء؛ فكان رأي الأمير شيخ إبقاءه محبوسًا بثغر الإسكندرية، وإرساله إليها مع الأمير طوغان الحسني الدوادار، وكان رأي نوروز قتله، وقام نوروز وبكتمر جلق في قتله قيامًا بذلَا فيه جهدهما، وكان الأمير يشبك بن أزدمر أيضًا ممن امتنع من قتله، وشنَّع ذلك على نوروز، وأشار عليه ببقائه، واحتج بالأيمان التي حُلِفت له، واختلف القومُ في ذلك، فقوي أمر نوروز وبكتمر بالخليفة المستعين بالله، فإنه كان أيضًا اجتهد هو وفتح الله كاتب السر في قتله، وحملا القضاة والفقهاء على الكتابة بإراقة دمِه بعد أن توقَّفوا عن ذلك، حتى تجرد قاضي القضاة ناصر الدين محمد بن العديم الحنفي لذلك، وكافح من خالفَه من الفقهاء بعدم قَتلِه بقوة الخليفة ونوروز وبكتمر وفتح الله، ثم أشهد على نفسِه أنه حكم بقَتلِه شرعًا، فاستُخرِجت فتوى بحلِّ دمه لأمورٍ قام بها, ثم في ليلة السبت سادس عشر صفر دخل عليه ثلاثة نفر، هم: الأمير ناصر الدين محمد بن مبارك شاه الطازي أخو الخليفة المستعين بالله لأمه، وآخر من ثقات الأمير شيخ، وآخر من أصحاب نوروز، ومعهم رجلان من المشاعلية، فعندما رآهم الملك الناصر فرج قام إليهم فزعًا، وعرف فيما جاؤوا، ودافع عن نفسه، وضرب أحد الرجلين بالمدورة صرعه، ثم قام الرجل هو ورفيقه ومشوا عليه وبأيديهم السكاكين، ولا زالوا يضربونه بالسكاكين وهو يعاركهم بيديه، وليس عنده ما يدفع عن نفسه به، حتى صرعاه، بعد ما أثخنا جراحه في خمسة مواضع من بدنه، وتقدم إليه بعض صبيان المشاعلية فخنقه وقام عنه، فتحرك الملك الناصر، فعاد إليه وخنقه ثانيًا حتى قَوِيَ عنده أنه مات، فتحرَّك فعاد إليه ثالثًا وخنقه، وفرى أوداجه بخنجر كان معه، وسلبه ما عليه من الثياب، ثم سَحَب برجليه حتى ألقيَ على مزبلة مرتفعة من الأرض تحت السماء، وهو عاري البدن، يستر عورته وبعض فخذيه سراويله، وعيناه مفتوحتان، والناس تمر به ما بين أمير وفقير ومملوك وحر، قد صرف الله قلوبَهم عن دفنه ومواراتِه، وبقيت الغلمان والعبيد والأوباش تعبث بلحيته وبدنِه، واستمَرَّ على المزبلة طول نهار السبت، فلما كان الليل من ليلة الأحد حمله بعض أهل دمشق وغسَّله وكفَّنه، ودفنه بمقبرة باب الفراديس احتسابًا لله تعالى، بموضع يعرف بمرج الدحداح، ولم تكن جنازته مشهودة، ولا عُرِف من تولى غَسلَه ومواراتَه، فكانت مدة ولاية السلطان الناصر فرج الثانية حوالي السبع سنين والأولى مثلها تقريبًا."},{"id":3275,"title":"وفاة العلامة محب الدين أبو الوليد ابن الشحنة  .","date":["العام الهجري :815","الشهر القمري : ربيع الآخر","العام الميلادي :1412"],"text":"هو العلامة الفقيه المحدث القاضي الشاعر الأديب قاضي القضاة محبُّ الدّين أبو الوليد محمد بن محمد بن محمود بن غازي ابن أيوب بن الشِّحنة محمود، والشِّحنة جدُّه الأعلى محمود، الشهير بابن الشِّحنة التُّركي الأصل الحلبي الحنفي، وأسرة آل الشحنة المشهورين بحلب من قبيلة ثقيف، وظهر منهم علماء أجلاء. ولد أبو الوليد سنة 749، وحفظ القرآن العظيم وعدة متون، وتفقَّه وبرع في الفقه، والأصول، والنحو، والأدب، وأفتى ودرّس، وتولى قضاء قضاة الحنفية بحلب، ثم دمشق، إلى أن قبض عليه الظَّاهر برقوق، وقدم به إلى القاهرة، ثم أُفرِجَ عنه ورجع إلى حلب، فأقام بها إلى أن قبض عليه الملك الناصر فرج سنة 813 لقيامه مع جماعةٍ على الناصر، ثم أفرج عنه فقدمَ القاهرة، ثم عاد إلى دمشق بصحبة الملك الناصر سنة أربع عشرة، فلما انكسر الناصر وحوصر بدمشق ولَّاه قضاء الحنفية بالقاهرة، فلم يتمَّ؛ لأنه لما أزيلت دولة الناصر أعيد ابن العديم لقضاء الدِّيار المصرية، واستقرَّ ابن الشِّحنة في قضاء حلب ودرس بدمشق. قال ابن حجر: \"كان كثير الدعوى والاستحضار، عالي الهمَّة، وعمل تاريخًا لطيفًا فيه أوهام عديدة، وله نظم فائق وخط رائق\" له ألفية رجز تشتمل على عشرة علوم، وألفية اختصر فيها منظومة النَّسَفي وضم إليها مذهب أحمد. وله تآليف أخرى في الفقه، والأصول، والتفسير. توفي بحلب يوم الجمعة ثاني عشر ربيع الآخر. ومحب الدين هو والد أبي الفضل"},{"id":3276,"title":"خلع الخليفة العباسي المستعين بالله وتولية الأمير شيخ المحمودي .","date":["العام الهجري :815","الشهر القمري : شعبان","العام الميلادي :1412"],"text":"بقي الخليفة العباسي المستعين بالله سلطانًا بعد خلع السلطان الناصر فرج أول السنة، ولكن الأمير شيخ المحمودي بيده كل شيء من أمر ونهي وعزل حتى تسمى بالأمير الكبير، ثم لما عَظُم أمره بعد موت بكتمر، وهو مقدم الألوف في الجيش، رأى شيخ المحمودي أن الجوَّ قد خلا له فلا مانع من سلطنته، فطلب الأمراء وكلَّمهم في ذلك، فأجاب الجميع بالسمع والطاعة طوعًا وكرهًا واتفقوا على سلطنته، فلما كان يوم الاثنين مستهل شعبان، وعمل الموكب عنده على عادته بالإسطبل السلطاني، واجتمع القضاة الأربعة، قام فتح الله كاتب السر على قدميه في الملأ وقال لمن حضر: إن الأحوال ضائقة، ولم يعهد أهل نواحي مصر اسم خليفة، ولا تستقيم الأمور إلا بأن يقوم سلطان على العادة، ودعاهم إلى الأتابك شيخ المحمودي، فقال الأمير شيخ: هذا لا يتم إلا برضا الجماعة، فقال من حضر بلسان واحد: نحن راضون بالأمير الكبير، فمدَّ قاضي القضاة جلال الدين عبد الرحمن البلقيني يدَه وبايعه، فلم يختلف عليه اثنان، وخُلِعَ الخليفة المستعين بالله العباس من السلطنة بغير رضاه، وبعد مبايعته بالسلطنة لُقِّب بالملك المؤيد شيخ، ثم جلس على كرسي الملك، وبعث إلى الخليفة القضاة ليسلِّموا عليه، ويشهدوا عليه أنه فوَّض إلى الأمير شيخ السلطنة على العادة، فدخلوا إليه وكلموه في ذلك، فتوقف في الإشهاد عليه بتفويض السلطنة توقفًا كبيرًا، ثم اشترط في أن يؤذَنَ له في النزول من القلعة إلى داره، وأن يحلف له السلطان بأنه يناصِحَه سرًّا وجهرًا، ويكون سِلمًا لمن سالمه وحَربًا لمن حاربه، فعاد القضاة إلى السلطان وردوا الخبر عليه، وحَسَّنوا له العبارة في القول، فأجاب: يُمهَل علينا أيامًا في النزول إلى داره، ثم يُرسَم له بالنزول، فأعادوا عليه الجواب بذلك وشهدوا عليه، وتوجَّهوا إلى حال سبيلهم، وأقام الخليفة بقلعة الجبل محتفظًا به على عادته أولًا خليفة، فكانت مدة سلطنته من يوم جلس سلطانًا خارج دمشق إلى يوم خلعه يوم الاثنين أول شعبان، سبعة أشهر وخمسة أيام، فلما حان يوم الاثنين مستهل شعبان حضر القضاة وأعيان الأمراء وجميع العساكر وطلعوا إلى باب السلسلة، وتقدم قاضي القضاة جلال الدين البلقيني وبايعه بالسلطنة، ثم قام الأمير شيخ من مجلسه ودخل مبيت الحراقة بباب السلسلة، وخرج وعليه خِلعة السلطنة السوداء الخليفتي على العادة، وركب فرس النوبة بشعار السلطنة، والأمراء وأرباب الدولة مشاة بين يديه، والقبة والطير على رأسه حتى طلع إلى القلعة، ونزل ودخل إلى القصر السلطاني، وجلس على تخت الملك، وقَبَّلت الأمراءُ الأرض بين يديه، ودُقَّت البشائر، ثم نودي بالقاهرة ومصر باسمه وسلطنته، وخُلِع على القضاة والأمراء ومن له عادة في ذلك اليوم."},{"id":3277,"title":"السلطان محمد جلبي بن بايزيد الأول يتولى حكم الدولة العثمانية .","date":["العام الهجري :816","العام الميلادي :1413"],"text":"لما مات السلطان بايزيد الأول بن مراد الأول استولى أولاده على البلاد وجرت بينهم حروب، وكان أقواهم محمد الأول بن بايزيد الذي استطاع أن يأخُذَ البلاد التي تحت يد أخيه عيسى وسليمان، وأن ينفرد بالسلطة ويصبح هو السلطان العثماني الخامس المتفرد بحكم الدولة العثمانية، ولكن رغم ذلك لم تهدأ الفتن الداخلية والخارجية، وبقي على قتال مع جيرانه ممن كانوا يثورون عليه أحيانًا ويثور عليهم أحيانًا."},{"id":3278,"title":"عصيان الأمير نوروز نائب دمشق على السلطان ثم قتل نوروز .","date":["العام الهجري :816","الشهر القمري : محرم","العام الميلادي :1413"],"text":"كانا الأميران نوروز وشيخ مشتركينِ في العصيان على السلطان الناصر فرج بن برقوق حتى تم لهما التغلب عليه، وقاما بسلطنة الخليفة المستعين بالله الذي  فوض إلى الأمير نوروز كفالة الشام جميعه: دمشق، وحلب، وطرابلس، وحماة، وصفد، وغزة، وجعل له أن يعيِّنَ الأمراء والإقطاعات لمن يريده ويختاره، وأن يولي نواب القلاع الشامية والسواحل وغيرها لمن أراد من غير مراجعة في ذلك، غير أنه يطالع الخليفة، ثم إن الأمير شيخًا استطاع أن يتسلطن ويخلع الخليفة من السلطنة فهذا ما أثار حفيظة نوروز الذي استدعى جميع النواب بالبلاد الشامية، فخرج الأمير نوروز إلى ملاقاتهم، والتقاهم وأكرمهم، وعاد بهم إلى دمشق، وجمع القضاة والأعيان، واستفتاهم في سلطنة الملك المؤيد شيخ وحبسه للخليفة وما أشبه ذلك، فلم يتكلم أحد بشيء، وانفضَّ المجلس بغير طائل، وأخذ الأمير نوروز في تقوية أموره واستعداده لقتال الملك المؤيد شيخ، وطلب التركمان، وأكثر من استخدام المماليك، وبلغ الملك المؤيد شيخًا ذلك فخلع في ثالث ذي الحجة من السنة على الأمير قرقماس ابن أخي دمرداش المدعو سيدي الكبير باستقراره في نيابة دمشق عوضًا عن الأمير نوروز الحافظي، فلما وصل قرقماس سيدي الكبير إلى غزة، سار منها في تاسع صفر وتوجَّه إلى صفد واجتمع بأخيه تغري بردي سيدي الصغير، ثم خرج في أثرهما الأمير ألطنبغا العثماني نائب غزة، والجميع متوجِّهون لقتال الأمير نوروز فقرَّروا البدء بأخذ حلب لَمَّا بلغهم خروج نوروز منها إلى جهة دمشق، فعاد نوزوز من حلب إلى دمشق، فأقاموا بالرملة، ولما بلغ نوروز قدوم قرقماس بمن معه إلى الرملة سار لحربهم، وخرج من دمشق بعساكره، فلما بلغ قرقماس وأخاه ذلك عادا بمن معهما إلى جهة الديار المصرية عجزًا عن مقاومته حتى نزلا بالصالحية، ثم إن السلطان جهز جيشًا وسيَّره إلى الشام للقاء نوروز، ثم في شهر صفر في ثامنه من السنة 817 نزل السلطان شيخ على قبة يلبغا خارج دمشق، وقد استعد نوروز وحَصَّن القلعة والمدينة، فأقام السلطان أيامًا، ثم رحل ونزل بطرف القبيبات، وكان السلطان -من الخربة- قد بعث قاضي القضاة مجد الدين سالم الحنبلي إلى الأمير نوروز ومعه قرا أول المؤيدي في طلب الصلح، فامتنع من ذلك، ووقعت الحرب، فانهزم نوروز، وامتنع بالقلعة في السادس والعشرين ونزل السلطان بالميدان، وحاصر القلعة، ورمى عليها بالمكاحل والمدافع والمنجنيق، حتى بعث نوروز بالأمير قمش الأمان، فأُجيبَ ونزل من القلعة، ومعه الأمراء: طوخ، ويشبك بن أزدمر، وسدن كستا، وقمش، وبرسبغا، وأينال، فقُبِض عليهم جميعًا في الحادي والعشرين شهر ربيع الآخر، وقُتِل من ليلته، وحُمِل رأسه على يد الأمير جرباش إلى القاهرة، وعلى يده كتب البشارة، وذلك أن الأمير كزل نائب طرابلس قَدِمَ في العشر الأخير من صفر، وقاتل عسكر نوروز، فركب السلطان بمن معه، فانهزم النوروزية إلى القلعة، وملك السلطان المدينة، ونزل بالإسطبل ودار السعادة، وحصر القلعة، وفي يوم الخميس مستهل جمادى الأولى قدم رأس نوروز، فعُلِّقَ على باب القلعة!"},{"id":3279,"title":"ظهور رجل في الشام يزعم أنه السفياني .","date":["العام الهجري :816","الشهر القمري : ربيع الأول","العام الميلادي :1413"],"text":"قَدِمَ إلى أرض عجلون شخص يُسمَّى عثمان بن أحمد بن عثمان بن محمود بن محمد بن علي بن فضل بن ربيعة، يعرف بابن ثقالة، من فقهاء دمشق، وادعى أنه السفياني، وظهر بقرية الجيدور وحلَّف أهل البلاد وأقطع الإقطاعات، وأمَّر عدة من الناس، وقال: أنا السلطان الملك الأعظم السفياني، فاجتمع عليه خلق كثير؛ من عرب وترك وعشير، بألوية خضر إلى وادي إلياس من جبل عوف بمعاملة عجلون، وبثَّ كتُبَه، ووقَّع عليها تحت البسملة السفياني، ونصها: إلى حضرة فلان أن يجمع فرسان هذه الدولة السلطانية، الملكية، الإمامية، الأعظمية، الربانية، المحمدية، السفيانية، أعلاها الله تعالى وشرَّفها، وأنفذها في الآفاق، وصرَّفها، ويحضروا بخيلهم ورجالهم وعددهم، مهاجرين إلى الله ورسوله، ومجاهدين في سبيل الله تعالى، ومقاتلين؛ لتكون كلمة الله هي العليا، والاعتماد على العلامة الشريفة أعلاه أعلاها الله تعالى. ثم دخل أرض عجلون في تاسع ربيع أول، بعسكر كبير، فيه سلاح دارية، وطبر دارية، فأقطع الإقطاعات، وكتب على القصص، يكتب كما يكتب السلطان، فقَبَّل الناس الأرض بين يديه في ساعة واحدة، وهم زيادة على خمسمائة رجل، في وقتٍ واحد معًا، وخُطِب له على منبر عجلون، فقيل: السلطان الملك الأعظم السفياني، ونادى ببلاد عجلون أن مغلَّ هذه السنة يسامح به الناس فلا يؤخذُ منهم منه، وفيما بعدها يؤخَذُ منهم العشر فقط، ويترك أخذ الخراج وأخذ المكس، فإن حكم التركِ قد بَطَل، ولم يبقَ إلا حكم أولاد الناس، فثار عند ذلك غانم الغزاوي به، وجهز إليه طائفة طرقوه وهو بالجامع وقاتلوه، وقبضوا عليه، وعلى ثلاثة من أصحابه، بعدما ركب وقاتلهم، فاعتُقل الأربعة بقلعة عجلون، وكتب بالخبر إلى السلطان، فنقله إلى قلعه صفد، واعتقله بها."},{"id":3280,"title":"خلع الخليفة العباسي المستعين بالله وتولية أخيه داود المعتضد بالله .","date":["العام الهجري :816","الشهر القمري : ذي الحجة","العام الميلادي :1414"],"text":"قام السلطانُ المؤيد شيخ المحمودي في شهر ذي الحجة باستدعاء داود بن المتوكل على الله من داره، وهو أخو الخليفة العباسي العباس المستعين بالله، فحضر بين يديه بقلعة الجبل، وقد حضر قضاة القضاة الأربعة، فعندما رآه قام له، وقد ألبسه خِلعةً سوداء، وأجلسه بجانبه، بينه وبين قاضي القضاة شيخ الإسلام جلال الدين البلقيني، فدعا القضاة، وانصرفوا على أن داود بن المتوكل على الله استقَرَّ في الخلافة، ولم يقع خلع الخليفة المستعين بالله، ولا أقيمت بينه بما يوجب شغور الخلافة عنه، ولا بويع داود هذا، بل خُلِعَ عليه فقط، ولُقِّبَ بأبي الفتح المعتضد بالله أمير المؤمنين، أما الخليفة المستعين بالله فأُخِذ إلى قلعة الجبل في دار بالقلعة مدة، ثم نُقِل إلى برج بالقلعة إلى يوم عيد النحر من سنة 819، فأُنزل من القلعة نهارًا إلى ساحل النيل على فرس، وصحبته أولاد الملك الناصر فرج ابن الظاهر برقوق، وهم: فرج، ومحمد، وخليل، وتوجه معهم الأمير كزل الأرغون شاوي إلى الإسكندرية، فدام الخليفة المستعين هذا مسجونًا بالإسكندرية إلى أن نقله الملك الأشرف برسباي إلى قاعة بثغر الإسكندرية، فدام بها إلى أن توفي بالطاعون في يوم الأربعاء لعشرين بقين من جمادى الأولى سنة 833، ولم يبلغ الأربعين سنة من العمر، ومات وهو في زعمه أنه مستمِرٌّ على الخلافة، وأنه لم يُخلَع بطريق شرعي؛ ولذلك عهد بالخلافة لولده يحيى، فلما مات المعتضد داود في يوم الأحد رابع شهر الأول من سنة 845، تكلم يحيى المذكور في الخلافة، وسعى سعيًا عظيمًا، فلم يتِمَّ له ذلك."},{"id":3281,"title":"هبوب ريح شديدة ورعد مرعب ومطر غزير وبَرَد كثير على مصر .","date":["العام الهجري :817","العام الميلادي :1414"],"text":"هبَّت بمصر ريحٌ شديدة تلاها رعد مرعب، ومطر غزير، وسقط مع ذلك بمدينة مصر خاصة برد بقدر البندقة كثير جدًّا، بحيث ألقي على أسطحة الدور منه قناطير، وأخرب عدة دور، فخزن الناس منه شيئًا كثيرًا وبِيعَ في الأسواق بعد ذلك كل رطل بستة دراهم، ولم يسقط منه بالقاهرة شيء البتة."},{"id":3282,"title":"القتال بين السلطان العثماني محمد جلبي وأمير قرمان .","date":["العام الهجري :817","الشهر القمري : محرم","العام الميلادي :1414"],"text":"وقعت معركةٌ بين محمد الأول سلطان العثمانيين وبين أمير قرمان محمد بن قرمان؛ وذلك أنه لما رأى اضطراب الأمور بين الإخوة العثمانيين، قَوِيَ عزمه على المسير إلى السلطان محمد جلبي ومحاربته فسار إلى بورصا وحاصرها، ثم حصل بين الطرفين قتال انتهى بانتصار السلطان محمد الأول على أمير قرمان وأخذه أسيرًا، ولكنه عفا عنه بعد أن حلف له بالطاعة وأنه لا يخرج عليه مرة أخرى، لكنه حنث وعاود الخروج لقتاله مرة أخرى، فانتصر عليه السلطان محمد مجددًا وأخذه كذلك أسيرًا، ولكنه عفا عنه مرة ثانية بعد أن حلف كذلك على الطاعة!"},{"id":3283,"title":"نزول ملك البرتقال على مدينة سبتة .","date":["العام الهجري :817","الشهر القمري : شعبان","العام الميلادي :1414"],"text":"نزل ملك البرتقال من الفرنج على مدينة سبتة في ثلاثمائة مركب، وأقام مدة بجزيرة فيما بينها وبين جبل الفتح يقال لها طرف القنديل، حتى ملَّ المسلمون الذين حُشِروا بسبتة من الجبال، ونفدت أزوادهم، وعادوا إلى ديارهم، فطرقها عند ذلك الفرنج، وقاتلوا المسلمين، وهزموهم، وركبوا أقفيَتَهم، وعبروا باب الميناء فتحَمَّل المسلمون بما قدروا عليه، ومرُّوا على وجوههم، فتملك البرتقال سبتة في سابع شعبان. وكان لذلك سبب هو: أن موسى بن أبي عنان لما ملك سبتة أعطاها لأبي عبد الله محمد ابن الأحمر، فنقل منها العدد الحربية بأجمعها إلى غرناطة، فلما استرد بنو مرين سبتة ساءت سيرة عمَّالهم بها، وكثر ظلمهم؛ فوقع الوباء العظيم بها حتى باد أعيانها، وكان من فساد ملك بني مرين وخراب فاس وأعمالها ما كان، فاغتنم الفرنج ذلك ونزلوا على سبتة، فلم يجدوا فيها من يدفعُهم."},{"id":3284,"title":"وفاة الفيروزآبادي صاحب كتاب القاموس المحيط .","date":["العام الهجري :817","الشهر القمري : شوال","العام الميلادي :1415"],"text":"هو الشيخ العلَّامة أبو الطاهر مجد الدين محمد بن يعقوب بن محمد بن إبراهيم بن عمر الفيروزآبادي الشيرازي الشافعي اللغوي، وُلِدَ سنة 729 بمدينة كازرون وتفقه بها. قال جلال الدين السيوطي: \"كان يرفع نسبَه إلى الشيخ أبي إسحاق الشيرازي صاحب التنبيه، ويقول: إن جده فضل الله ولد الشيخ أبي إسحاق، ولا يبالي بما يشاع بين الناس أن الشيخ أبا إسحاق لم يتزوَّج فضلًا عن أن يُعقِبَ\" وقال المقري التلمساني: \"ثم ارتقى الشيخ مجد الدين درجة فادعى بعد أنْ ولي قضاء اليمن بمدة طويلة أنَّه من ذرية أبي بكر الصديق رضي الله عنه، وزاد إلى أنْ رأيت بخطه لبعض نوابه في بعض كتبه: محمد الصديق, ولم يكن مدفوعًا عن معرفة إلَّا أنَّ النفس تأبى قبولَ ذلك\". دخل بلاد الروم واتصل بخدمة السلطان بايزيد بن السلطان مراد، ونال عنده رتبة وجاهًا، وأعطاه السلطان مالًا جزيلًا، وأعطاه تيمورلنك خمسة آلاف دينار، ثم جال البلاد شرقًا وغربًا، وأخذ عن علمائها، حتى برع في العلوم كلها، لا سيما الحديث والتفسير والفقه. توفي بزَبيد من بلاد اليمن في ليلة العشرين من شوال، عن ثماني وثمانين سنة وأشهر، وَلِيَ قضاء الأقضية ببلاد اليمن نحو عشرين سنة حتى مات بعدما طاف البلاد، وأقام بالقاهرة زمانًا، وله مصنفات كثيرة تنيفُ على أربعين مصنفًا، أشهرها كتاب القاموس في اللغة المعروف بالقاموس المحيط، وكتاب تسهيل الأصول إلى الأحاديث الزائدة على جامع الأصول، وله بصائر ذوي التمييز في لطائف الكتاب العزيز، وله فتح الباري في شرح صحيح البخاري، وله المرقاة الوفية في طبقات الحنفية، وله تاريخ أصبهان، وغيرها."},{"id":3285,"title":"حدوث فتنة بالمسجد الحرام .","date":["العام الهجري :817","الشهر القمري : ذي الحجة","العام الميلادي :1415"],"text":"كان الأميرُ جقمق الأرغون شاوي الدوادار الثاني أمير الحاج فوقع بينه وبين أشراف مكة وقعة في خامس ذي الحجة، وخبر ذلك أن جقمق ضرب أحدَ عبيد مكةَ وحبسه؛ لكونه يحمل السلاح في الحرم الشريف، وكان قد مَنَع من ذلك، فثارت بسبب ذلك فتنة انتُهِكت فيها حرمة المسجد الحرام، ودخلت الخيلُ إليه عليها المقاتِلةُ من قوَّاد مكة لحرب الأمير جقمق، وأدخل جقمق أيضًا خيله إلى المسجِدِ الحرام، فباتت به تروث!! وأوقد مشاعِلَه بالحرم، وأمر بتسمير أبواب الحرم فسُمِرَت كلها إلا ثلاثة أبواب ليمتَنِعَ من يأتيه، فمشت الناس بينهم في الصلح، وأطلق جقمق المضروبَ فسكتت الفتنة من الغد بعدما قُتِل جماعة، ولم يحجَّ أكثر أهل مكة في هذه السنة من الخوفِ!!"},{"id":3286,"title":"فكاك الأسرى المسلمين من قبرص .","date":["العام الهجري :818","الشهر القمري : محرم","العام الميلادي :1415"],"text":"قَدِمَ كتاب أقبغا النظامي -أحد خواص السلطان الناصر فرج بن برقوق- من جزيرة قبرص، وقد توجَّه إليها لفك الأسرى، وأنه وجد بالجزيرة من أسارى المسلمين خمسمائة وخمسة وثلاثين أسيرًا، فِكاكُهم بثلاثة عشر ألف دينار وثلاثمائة دينار، وأنه قد أوصل إلى متملك قبرص العشرة آلاف دينار المجهَّزة معه، فانفك بها أربعمائة أسير، كل أسير بخمسة وعشرون دينارًا، وقد افتَكَّ متملك قبرص من مائة وخمسة وثلاثين أسيرًا، بثلاثة آلاف وثلاثمائة وخمسة وسبعين دينارًا، وقد حمل منهم إلى جهة مصر في البحر مائتي أسير، وفرق في جهات السواحل الشامية باقيهم."},{"id":3287,"title":"وفاة الأمير سودون بن عبد الله المحمدي الظاهري الشهير بتلي .","date":["العام الهجري :818","الشهر القمري : محرم","العام الميلادي :1415"],"text":"هو الأمير سيف الدين سودون بن عبد الله المحمدي الظاهري، الشهير بتلي، يعني مجنونًا، كان من مماليك الملك الظاهر برقوق، ومن أعيان خاصكيته، وترقى في الدولة الناصرية فرج بن برقوق إلى أن صار أمير مائة ومقدم ألف. ثم قُبِضَ عليه وحُبِسَ بثغر الإسكندرية، هو وبيبرس الصغير الدوادار، وجانم بن حسن شاه، في يوم الخميس سابع عشر ذي الحجة سنة 806، فاستمروا في السجن إلى أن أُفرج عنهم في شوال سنة 807. وقَدِموا القاهرة، فأقام سودون المحمدي بالقاهرة، من جملة الأمراء، إلى يوم الخميس ثامن شوال سنة 808، استقر أمير آخورا كبيرًا، عوضًا عن جرباش الشيخي الظاهري بحكم عزله. فاستمر في وظيفته إلى أن اختفى الملك الناصر فرج، وخُلع وتسلطن أخوه الملك المنصور عبد العزيز ابن الملك الظاهر برقوق، فاستمر سودون المحمدي على وظيفته، إلى أن ظهر الملك الناصر وأراد الطلوع إلى القلعة، فمنعه سودون المحمدي مع من منعه من الأمراء، وقاتلوه قتالًا ليس بالقويِّ، ثم انهزم سودون ومن معه فملك الناصِرُ القلعة وتسلطن ثانيًا، وخلع المنصور عبد العزيز، فأمسك بسودون وأخرجه إلى دمشق على إقطاع الأمير سودون اليوسفي، واستقَرَّ الأمير أخورية من بعده الأمير جاركس القاسمي المصارع, ولما توجه سودون المحمدي إلى دمشق قبض عليه نائبها الأمير شيخ المحمودي، وحبسه بقلعتها إلى أوائل سنة 809، إلى أن فرَّ من السجن، ولحق بالأمير نوروز الحافظي، وهو إذ ذاك خارج عن طاعة الملك الناصر فرج. واستمر بتلك البلاد سنين، ووقع له أمور ومحن، وملك مدينة غزة، وشنَّ بها الغارات إلى أن ظفر به الأمير شيخ ثانيًا، وحبسه أيضًا بقلعة دمشق مدة، وحبس معه سودون اليوسفي وغيره من الأمراء. وبلغ الملك الناصر مسْكه، فبعث بطلبه مع الأمير كمشبغا الجمالي، فامتنع شيخ من إرسال سودون ورفقته، ثم أطلقهم وخرج شيخ أيضًا عن الطاعة، وذلك في سنة 812. فعاد الجمالي إلى الناصر بغير طائل، وصار سودون المحمودي من أعزِّ أصحاب شيخ، ودام معه إلى أن ملك صفد من جهة شيخ، ثم خرج عن طاعة شيخ وفرَّ إلى نوروز ثانيًا، ثم اصطلح الجميع على العصيان. واستمرَّ مع شيخ ونوروز إلى أن قُتِلَ الملك الناصر فرج، وقدِمَ سودون بصحبة الأمير شيخ إلى الديار المصرية، وأنعم عليه بإمرة مائة وتقدمة ألف, واستمرَّ على ذلك إلى أن قبض عليه الملك المؤيد شيخ في شوال سنة 815 وحبسه بثغر الإسكندرية، فاستمر بها إلى أن قُتِلَ سودون في المحرم سنة ثماني عشرة وثمانمائة، وقتل معه الأمير دمرداش المحمدي والأمير طوغان الحسني, وسودون هذا غير الأمير سودون بن عبد الله النوروزي المعروف بالعجمي المتوفى سنة 847"},{"id":3288,"title":"إعادة طرسوس إلى سلطة المماليك بعدما كانت تابعة لتيمورلنك .","date":["العام الهجري :818","الشهر القمري : صفر","العام الميلادي :1415"],"text":"قَدِمَ كتاب نائب حلب بأن الشهابي أحمد بن رمضان -وهو من الأمراء التركمان الأوحقية- أخذ مدينة طرسوس عَنوةً في ثالث عشر المحرم، بعد أن حاصرها سبعة أشهر، وأنه سلمها إلى ابنه إبراهيم، بعدما نهبها وسبى أهلها، وقد كانت طرسوس من نحو اثنتي عشرة سنة يخطب بها تارة لتيمورلنك، وتارة لمحمد باك بن قرمان، فيقال: السلطان الأعظم سلطان السلاطين، فأعاد ابن رمضان الخطبة فيها باسم السلطان الملك المؤيد شيخ المحمودي."},{"id":3289,"title":"عصيان نواب الشام بزعامة نائب دمشق الأمير قاني باي وقتله .","date":["العام الهجري :818","الشهر القمري : جمادى الآخرة","العام الميلادي :1415"],"text":"قَدِمَ الخبر على السلطان المؤيد شيخ المحمودي بخروج قاني باي نائب الشام عن الطاعة، ثم ورد الخبر بخروج الأمير طرباي نائب غزة عن الطاعة وتوجُّهِه إلى الأمير قاني باي المحمدي نائب دمشق، فعند ذلك ندب السلطان الأمير يشبك المؤيدي المشد ومعه مائة مملوك من المماليك السلطانية، وبعثه نجدةً للأمير ألطنبغا العثماني، ثم ورد الخبر ثالثًا بعصيان الأمير تنبك البجاسي نائب حماة وموافقته لقاني باي، وكذلك الأمير إينال الصصلاني نائب حلب ومعه جماعة من أعيان أمراء حلب، ثم ورد الخبر أيضًا بعصيان الأمير سودون بن عبد الرحمن نائب طرابلس والأمير جانبك الحمزاوي نائب قلعة الروم، ولما بلغ الملك المؤيد هذا الخبر استعَدَّ للخروج إلى قتالهم بنفسه، ولما كان في سادس جمادى الآخرة ركب الأمير بيبغا المظفري أتابك دمشق، وناصر الدين محمد بن إبراهيم بن منجك، وجلبان الأمير آخور, وأرغون شاه، ويشبك الأيتمشي في جماعة أخر من أمراء دمشق يسيرون بسوق خيل دمشق، فبلغهم أن يلبغا كماج كاشف القبلية حضر في عسكر إلى قريب داريا، وأنَّ خَلْفَه من جماعته طائفة كبيرة، وأن قاني باي خرج إليه وتحالفا على العصيان، ثم عاد قاني باي إلى بيت غرس الدين، فاستعد المذكورون ولبسوا آلة الحرب، ونادوا أجناد دمشق وأمراءها بالحضور، وزحفوا إلى نحو قاني باي، فخرج إليهم قاني باي بمماليكه وبمن انضمَّ معه من أصاغر الأمراء وقاتلهم من بكرة النهار إلى العصر حتى هزمهم، ومرُّوا على وجوههم إلى جهة صفد، ودخل قاني باي وملك مدينة دمشق، ونزل بدار العدل من باب جابية، ورمى على القلعة بالمدافع، وأحرق جملون دار السعادة، فرماه أيضًا من القلعة بالمجانيق والمدافع، فانتقل إلى خان السلطان وبات بمخيمه وهو يحاصر القلعةَ، ثم أتاه النواب، فنزل تنبك البجاسي نائب حماة على باب الفرج، ونزل طرباي نائب غزة على باب آخر، ونزل على باب جديد تنبك دوادار قاني باي، وداموا على ذلك مدةً، وهم يستعدون، وقد ترك قاني باي أمر القلعة إلى أن بلغه وصول العسكر، وسار هو والأمراء من دمشق، وكان الأمير ألطنبغا العثماني بمن معه من أمراء دمشق والعشير والعربان نائب صفد قد توجه من بلاد المرج إلى جرود، فجَدَّ العسكر في السير حتى وافَوا الأمير قاني باي قد رحل من برزة، فنزلوا هم على برزة، وتقدم منهم طائفة فأخذوا من ساقته أغنامًا وغيرها، وتقاتلوا مع أطراف قاني باي، فجرح الأمير أحمد بن تنم صهر الملك المؤيد في يدِه بنشابة أصابته، وجُرِح معه جماعة أخرى، ثم عادوا إلى ألطنبغا العثماني، وسار قاني باي حتى نزل بسلمية في آخرها، ثم رحل إلى حماة، ثم رحل منها واجتمع بالأمير إينال الصصلاني نائب حلب، واتفقوا جميعًا على التوجه إلى جهة العمق لما بلغهم قدوم السلطان الملك المؤيد لقتالهم، وسيروا أثقالهم، فنادى نائب قلعة حلب بالنفير العام، فأتاه جُلُّ أهل حلب، ونزل هو بمن عنده من العسكر الحلبي، وقاتل إينال وعساكره فلم يثبتوا، وخرج قاني باي وإينال إلى خان طومان، وتخطف العامة بعضَ أثقالهم، وأقاموا هناك ثم في يوم الجمعة الثاني والعشرين شهر رجب ركب السلطان بعد صلاة الجمعة من قلعة الجبل بأمرائه وعساكره المعينين صحبته للسفر يريد البلاد الشامية، ومعه الخليفة وقاضي القضاة ناصر الدين محمد بن العديم الحنفي لا غير، وسار السلطان حتى وصل إلى غزة في تاسع عشرين شهر رجب، وسار منها في نهاره، وكان قد خرج الأمير قاني باي من دمشق في السابع والعشرين ودخل الأمير ألطنبغا العثماني إلى دمشق في ثاني شعبان، وقُرِئَ تقليده، وسار السلطان مجدًّا من غزة حتى دخل دمشق في يوم الجمعة سادس شعبان، ثم خرج من دمشق بعد يومين في أثر القوم، وقدم بين يديه الأمير أقباي الدوادار في عسكر من الأمراء وغيرهم كالجاليش، فسار أقباي أمام السلطان والسلطان خلفه إلى أن وصل أقباي قريبًا من تل السلطان، ونزل السلطان على سرمين، وقد أجهدهم التعب من قوة السير وشدة البرد، فلما بلغ قاني باي وإينال الصصلاني وغيرهما من الأمراء مجيء أقباي، خرجوا إليه بمن معهم من العساكر، ولقوا أقباي بمن معه من الأمراء والعساكر وقاتلوه، فثبت لهم ساعة ثم انهزم أقبح هزيمة، وقَبَضوا عليه وعلى الأمير برسباي الدقماقي وعلى الأمير طوغان دوادار الوالد، وهو أحد مقدَّمي الألوف بدمشق، وعلى جماعة كبيرة، وتمزَّقت عساكرهم وانتُهِبت، وأتى خبر كسرة الأمير أقباي للسلطان فتخوَّف وهمَّ بالرجوع إلى دمشق وجَبُن عن ملاقاتهم؛ لقلة عساكره، حتى شجَّعه بعض الأمراء أرباب الدولة، وهونوا عليه أمر القوم، فركب بعساكره من سرمين، وأدركهم وقد استفحل أمرُهم، فعندما سمعوا بمجيء السلطان انهزموا ولم يثبتوا، وولَّوا الأدبار من غير قتال، فعند ذلك اقتحم السلطانية عساكرَ قاني باي، وقبض على الأمير إينال الصصلاني نائب حلب، وعلى الأمير تمان تمر اليوسفي المعروف بأرق أتابك حلب، وعلى الأمير جرباش كباشة حاجب حجاب حلب، وفر قاني باي واختفى، أما سودون بن عبد الرحمن نائب طرابلس، وتنبك البجاسي نائب حماة، وطرباي نائب غزة، وجانبك الحمزاوي نائب قلعة الروم، والأمير موسى الكركري أتابك طرابلس وغيرهم؛ فقد ساروا على حمية إلى جهة الشرق قاصدين قرا يوسف صاحب بغداد وتبريز، ثم ركب الملك المؤيد ودخل إلى حلب في يوم الخميس الرابع عشر شهر رجب وظفر بقاني باي في اليوم الثالث من الوقعة، فقيده ثم طلبهم الجميع، فلما مثلوا بين يدي السلطان فعند ذلك أمر بهم الملك المؤيد، فرُدُّوا إلى أماكنهم وقُتِلوا من يومهم الأربعة: قاني باي، وإينال، وتمان تمر أرق، وجرباش كباشه، وحُمِلت رؤوسهم إلى الديار المصرية على يد الأمير يشبك شاد الشرابخاناه، فرُفِعوا على الرماح، ونودي عليهم بالقاهرة: هذا جزاء من خامر على السلطان، وأطاع الشيطان، وعصى الرحمن، ثم عُلِّقوا على باب زويلة أيامًا، ثم حُملوا إلى الإسكندرية فطيف بهم أيضًا هناك، ثم أعيدت الرؤوس إلى القاهرة وسُلِّمت إلى أهاليها."},{"id":3290,"title":"انتشار الطاعون بمصر والشام وبلاد المشرق والمغرب .","date":["العام الهجري :819","الشهر القمري : محرم","العام الميلادي :1416"],"text":"دخل فصل الربيع، وقد فشا في الناس الموت بالطاعون، وأُحصيَ من ورد اسمُه الديوان ممن مات بالقاهرة في مدة شهر أوله عاشر المحرم، فكان ثلاثة آلاف إنسان، ثم تجاوز عدد من يرد اسمه الديوان من الأموات مائة نفس في اليوم، وهذا سوى من يموت بالمارستان، وفي عدة مواضع خارج المدينة، ويكون ذلك نحو الخمسين نفسًا، وكانت عدة من صُلِّي عليه من الأموات بمصلى باب النصر خاصة من أول النهار إلى آذان الظهر اثنين وتسعين ميتًا، وشنع ما يحكى من تواتر نزول الموت في الأماكن، بحيث مات في أسبوع واحد من درب واحد ثلاثون إنسانًا، وكثير من الدور يموت منها العشرة فصاعدًا، وقدم الخبر بكثرة الوباء أيضًا ببلاد الصعيد، وفي طرابلس الشام، وأُحصي من مات بها في مدة أيام، فكانت عدتهم عشرة آلاف إنسان، وكثر الوباء أيضًا بالوجه البحري من أراضي مصر، وقدم الخبر بأن معظم أهل مدينة من صعيد مصر قد ماتوا بالطاعون، وفي شهر ربيع الأول كثر الموتان بالقاهرة ومصر، وتجاوزت عدة من ورد اسمه الديوان من الموالي الثلاثمائة، وتوهم كل أحد أن الموت آتيه عن قريب؛ لسرعة موت من يُطعن، وكثرة من يموت في الدار الواحد، وتواتر انتشار الوباء في جميع أراضي مصر، وبلاد الشام، والمشرق، بحيث ذكر أنه بأصبهان مات غالب أهلها، حتى صار من يمشي بشوارعها لا يرى أحدًا يمر إلا في النادر، وأن مدينة فاس بالمغرب أحصى من مات بها في مدة ثلاثين يومًا ممن ورد الديوان فكانوا ستة وثلاثين ألفًا سوى الغرباء من المساكين، وأن المساكن عندهم صارت خالية ينزل بها من قدم إليها من الغرباء، وأن هذا عندهم في سنتي سبع عشرة وثماني عشرة، وبلغت عدة من يرد اسمه الديوان من الأموات في الثالث والعشرين ما ينيف على خمسمائة، بما فيهم من موتى المارستان والطرحاء، ومع ذلك والأخبار متواترة بأنه صلِّيَ في هذا اليوم بمصليات الجنائز على ما ينيف على ألف ميت، وأن الكُتَّاب يخفون كثيرًا ممن يرد اسمه إليهم، وانقضى هذا الشهر، وقل دار بالقاهرة ومصر وظواهرهما لم يكن بها حزن على ميت، وأقل ما قيل: إنه مات من عاشر المحرم إلى آخر هذا الشهر عشرون ألفًا، وفي شهر ربيع الآخر، أوله الجمعة: بلغت عدة من ورد اسمه الديوان من الأموات إلى مائة وعشرين سوى المارستان والطرحاء، وقدم الخبر من دمشق بتزايد الموتان عندهم، وأنه يموت في اليوم ستون إنسانًا، وأنه ابتدأ الوباء عندهم من أثناء ربيع الأول، عندما تناقص من ديار مصر."},{"id":3291,"title":"الفرنج ينزلون على يافا ويأسرون بعض المسلمين .","date":["العام الهجري :819","الشهر القمري : ربيع الآخر","العام الميلادي :1416"],"text":"قدم الفرنج في أربعة أغربة -نوع من المراكب- إلى مدينة يافا، وأسروا نحو الخمسين امرأة وطفلًا، وحاربهم المسلمون، وقتلوا منهم واحدًا، ثم افتكُّوا الأسرى خمسة عشر دينارًا لكل أسير."},{"id":3292,"title":"السلطان شيخ المحمودي يأمر الخطباء بالنزول درجة عند الدعاء له .","date":["العام الهجري :819","الشهر القمري : جمادى الآخرة","العام الميلادي :1416"],"text":"في سابع جمادى الآخرة من هذه السنة أمر السلطان المؤيد شيخ المحمودي الخطباء إذا أرادوا الدعاء للسلطان على المنبر في يوم الجمعة أن ينزلوا درجةً ثم يدعوا للسلطان حتى لا يكون ذكر السلطان في الموضع الذي يذكر فيه اسمُ الله عزَّ وجلَّ واسم نبيه صلى الله عليه وسلم؛ تواضعًا لله تعالى، ففعل الخطباء ذلك، وحَسُن هذا ببال الناس إلى الغاية، واعتمد خطباء مصر والقاهرة ما أشار به السلطان، فنزلوا عندما أرادوا الدعاء له درجة، ثم دعَوا، وامتنع من ذلك قاضي القضاة البلقيني في جامع القلعة؛ لكونه لم يُؤمَرْ بذلك ابتداء، فسُئِلَ عن ذلك، فقال: ليس هو السُّنَّة، فغيَّرَ عزم السلطان عن ذلك، فترك الناسُ ذلك بعده."},{"id":3293,"title":"الفرنج ينزلون على الإسكندرية ويأسرون بعض المسلمين .","date":["العام الهجري :819","الشهر القمري : جمادى الآخرة","العام الميلادي :1416"],"text":"في سادس عشر جمادى الآخرة قدم الأمير صلاح الدين محمد الحاجب بن الصاحب بدر الدين حسن بن نصر الله ناظر الخاص إلى الإسكندرية في تحصيل المال، فجلس بالخمس، وبين يديه أعيان أهلها، فجاءه الخبر بأن الفرنج الذين وصلوا ببضائع المتجر، وهم في ثمان عشاريات من مراكب بحر الملح، قد عزموا على أن يهجموا عليه، وأن يأخذوه هو ومن معه، فقام عَجِلًا من غير تأنٍّ يريد الفرار، وتسارع الناس أيضًا يفرون، فهجم الفرنج من باب البحر، فدافعهم من هناك من العتالين، حتى أغلقوا باب البحر، وقتلوا رجلًا من الفرنج، فقتل الفرنج نحو عشرين من المسلمين، وانتشروا على الساحل، وأسروا نحو سبعين مسلمًا، وأخذوا ما ظفروا به، ولحقوا بمراكبهم، وأتوا في الليل يريدون السورَ، فتراموا ليلتَهم كلها مع المسلمين إلى الفجر، فأخذ كثير من المسلمين في الرحيل من الإسكندرية، وأخرجوا عيالهم، وقام الصياح على فقد من قُتِل وأُسِر، وباتوا ليلة الجمعة مع الفرنج في الترامي من أعلى السور، فقَدِمت طائفة من المغاربة في مركب ومعهم زيت وغيره من تجاراتهم، فمال الفرنج عليهم وقاتلوهم قتالًا شديدًا حتى أخذوهم عَنوة، وأخرجوهم إلى البر، وقطَّعوهم قطعًا، وأهل الإسكندرية يرونهم فلا يغيثونَهم، فقدم الخبر بذلك في ليلة السبت عشرينه، فاضطرب الناس بالقاهرة، وخرج ناظر الخاص نجدة لولده، ومضى معه عدة من الأمراء، وخرج الشيخ أبو هريرة بن النقاش في عدة من المطوعة، يوم الأحد الحادي والعشرين، وقدموا الإسكندرية، فوجدوا الفرنج قد أقلعوا، وساروا بالأسرى، وما أخذوه من البر ومن مركب المغاربة، في يوم الثلاثاء الثاني والعشرين، فعادوا في آخر الشهر إلى القاهرة."},{"id":3294,"title":"السلطان محمد الأول يغزو  قسطمونية .","date":["العام الهجري :819","الشهر القمري : شوال","العام الميلادي :1416"],"text":"توجَّه السلطان محمد جلبي بن بايزيد بن مراد صاحب بورصا؛ لقتال اسفنديار ابن أبي يزيد متملك قسطمونية وحصره في جزيرة سينوب، فقامت معركة على بحر إيجه قرب مدينة غاليبولي كان نهايتها أن وقع بينهما الاتفاق على أن يخطب له ويضرب السكة باسمه، فأفرج عنه وعاد اسفنديار إلى قسطمونية، وخُطِب باسم السلطان محمد الأول فلم يوافِقْه وزيره خواند سلار على إقامة الخطبة بالجامع الذي أنشأه للسلطان محمد جلبي، وصار يخطب فيه باسم ملك اسفنديار، وخطب اسفنديار في بقية جوامع قسطمونية باسم محمد."},{"id":3295,"title":"فتنة بمكة بين الأشراف والأمراء .","date":["العام الهجري :819","الشهر القمري : شوال","العام الميلادي :1416"],"text":"لما عُزِل الشريف حسن بن عجلان بالشريف رميثة في صفر من السنة الحالية، ودخل رميثة إلى مكة لم يتعرض إليه الشريف حسن، حتى بعث ابنه بركات، وقائده شكر إلى السلطان، فقدما فكتب السلطان بإعادة الشريف حسن إلى الإمرة في ثامن عشر شهر رمضان، وجهز إليه تشريفه وتقليده، فقدما عليه وهو بجدة في ثاني شوال، فبعث إلى القواد العمرية -وكانوا باينوه من شعبان ولحقوا برميثة في مكة- يرغبهم في طاعته، فأبوا عليه وجمعوا لحربه، فسار إلى مكة وعسكر بالزاهر ظاهِرَ مكة في يوم السبت الثاني والعشرين شوال، ومعه الأشراف: آل أبي نمي، وآل عبد الكريم، والأدارسة، ومعه الأمير الشريف مقبل بن مختار الحسني أمير ينبع بعسكره، ومعه مائة وعشرون من الأتراك، فبعث إلى العمرية يدعوهم إلى طاعته، فندبوا إليه ثلاثة منهم، فلما أتوه خوَّفهم عاقبة الحرب وحذرهم، ومضوا إلى مكة فلم يعودوا إليه؛ لتماديهم وقومهم على مخالفته، فركب يوم الاثنين الرابع والعشرين من الزاهر، وخيَّم بقرب العسيلة أعلى الأبطح، وأصبح يوم الثلاثاء زاحفًا في ثلاثمائة فارس وألف راجل، فخرج إليه رميثة في قدر الثلث من هؤلاء فلما بلغ الشريف حسن إلى المعابدة، بعث يدعوهم، فلم يجيبوه فسار إلى المعلَّى ووقف على الباب ورمى من فوقه فانكشفوا عنه، وأُلقِيَت فيه النار فاحترق، وانبث أصحابُ حسن ينقبون السور ويرمون من الجبل بالنشاب والأحجار أصحاب رميثة، ثم اقتحموا السور عليهم وقاتلوهم حتى كثرت الجراحات في الفريقين، فتقدَّم بعض بني حسن وأجار من القتال، فانكف عند ذلك حسن، ومنع أصحابه من الحرب، فخرج القضاة والفقهاء والفقراء بالمصاحف والربعات إلى حسن، وسألوه أن يكفَّ عن القتال، فأجابهم بشرط أن يخرج رميثة ومن معه من مكة، فمضوا إلى رميثة وما زالوا به حتى تأخر عن موضعه إلى جوف مكة، ودخل الشريف حسن بجميع عسكره، وخيم حول بركتي المعلى، وبات بها، وسار يوم الأربعاء السادس والعشرين وعليه التشريف السلطاني ومعه عسكره، إلى المسجد، فنزل وطاف بالبيت سبعًا، والمؤذِّنُ قائم على بئر زمزم يدعو له حتى فرغ من ركعتي الطواف، ثم مضى إلى باب الصفا فجلس عنده، وقرئ تقليده إمرة مكة هناك، ثم قرئ كتاب السلطان إليه بتسلُّم مكة من رميثة، وقد حضره عامة الناس، ثم ركب وطاف البلد، ونودي بالأمان، وأجَّل رميثة ومن معه خمسة أيام، فلما مضت سار بهم إلى جهة اليمن، واستقرَّ أمر الشريف حسن بمكة على عادته، وثبت من غير منازِع."},{"id":3296,"title":"السلطان المؤيد المحمودي يغير على التركمان في أبلستين .","date":["العام الهجري :820","الشهر القمري : ربيع الآخر","العام الميلادي :1417"],"text":"أمر السلطان المؤيد شيخ المحمودي ولده المقام الصارمي إبراهيم ليتوجه إلى أبلستين ومعه الأمير جقمق الأرغون شاوي الدوادار، وجماعة من الأمراء؛ لكبس الأمير ناصر الدين محمد بن دلغادرة فساروا مجِدِّين، فصبَّحوا أبلستين وقد فرَّ منها ابن دلغادر، وأجلى البلاد من سكانها، فجدوا في السير خلفه ليلًا ونهارًا حتى نزلوا بمكان يقال له كل دلي في يوم الخامس عشر من ربيع الآخر وأوقعوا بمن فيه من التركمان، وأخذوا بيوتهم وأحرقوها، ثم مضَوا إلى خان السلطان، فأوقعوا أيضًا بمن كان هناك وأحرقوا بيوتهم وأخذوا من مواشيهم شيئًا كثيرًا، ثم ساروا إلى مكان يقال له صاروس ففعلوا بهم كذلك، وباتوا هناك، ثم توجهوا يوم السادس عشر فأدركوا ناصر الدين بك بن دلغادر وهو سائر بأثقاله وحريمه، فتتبعوه وأخذوا أثقاله وجميع ما كان معه، ونجا ابن دلغادر بنفسه على جرائد الخيل، ووقع في قبضتهم عدة من أصحابه، ثم عادوا إلى السلطان المؤيد بالغنائم، ومن جملتها مائة جمل بختي وخمسمائة جمل نفر، ومائة فرس، هذا سوى ما نهب وأخذه العسكر من الأقمشة الحرير، والأواني الفضية ما بين بلور وفضيات وبسط وفرش، وأشياء كثيرة لا تدخل تحت حصر."},{"id":3297,"title":"السلطان المؤيد شيخ المحمودي يتسلم طرسوس .","date":["العام الهجري :820","الشهر القمري : ربيع الآخر","العام الميلادي :1417"],"text":"أخذ الأميرُ صارم الدين إبراهيم بن رمضان طرسوس, وصيَّرها في طاعة السلطان المؤيد، ولكنه لم يسلِّمْها، بل جعل الخطبة للسلطان، وفي هذه السنة قدم الأمير إبراهيم بن رمضان، وابن عمه حمزة بن أحمد بن رمضان، وسائر أمراء التركمان الأوحقية، في جمع كبير، ومعهم أم إبراهيم بن رمضان، وأولاده الصغار في خمسمائة من أمرائه وأقاربه وأزلامه، فقام السلطان لهم، وخلع على إبراهيم وعلى أخيه، وحلف التركمان على الطاعة، وخلع عليهم نحوًا من مائتي خِلعة، وألبس إبراهيم بن رمضان الكلوتة، وأنعم عليه، وعلى جماعته، ثم تقرر الحال على أن الأمير قجقار نائب حلب يتوجَّه بمن معه إلى مدينة طرسوس، ويسير السلطان على جهة مرعش إلى الأبلستين، ويتوجه مصلح الدين إلى ابن قرمان بجوابه، ويعود في مستهل جمادى الأولى بتسليم طرسوس، فسار مصلح الدين صحبة نائب حلب إلى طرسوس، وكان الأمير قجقار نائب حلب لما توجه إلى طرسوس، قدم بين يديه إليها الأمير شاهين الأيدكاري متولي نيابة السلطة بها، وقد بعث ابن قرمان نجدة إلى نائبه بطرسوس الأمير مقبل القرماني، فلما بلغ مقبل مسير عساكر السلطان إليه، رحل من طرسوس وبعث إلى شاهين الأيدكاري يخبره برحيله، فدخل شاهين طرسوس وقد امتنع مقبل بقلعتها، فنزل الأمير قجقار والأمير شاهين عليها، وكتب إلى السلطان بذلك، ثم في شهر رجب في السادس والعشرين كملت عمارة القصر بقلعة حلب، وجلس فيه السلطان واستدعى مقبل القرماني ورفاقه، وضربه ضربًا مبَرِّحًا، ثم صُلِبَ هو ومن معه."},{"id":3298,"title":"وفاة أبي الحجاج يوسف الثالث ملك بني نصر بغرناطة وتولي ابنه .","date":["العام الهجري :820","الشهر القمري : شوال","العام الميلادي :1417"],"text":"توفِّيَ الملك أبي الحجاج يوسف الثالث بن إسماعيل بن فرج ملك بني نصر في الأندلس، طُعِنَ بخنجر في جبينه يوم عيد الفطر، فمات منه وتسلطن بعده ابنه أبو عبد الله محمد الثامن الملقَّب بالأيسر."},{"id":3299,"title":"فتنة في دمياط بسبب والي مصر .","date":["العام الهجري :820","الشهر القمري : ذي الحجة","العام الميلادي :1418"],"text":"وقعت فتنة بدمياط قُتِلَ فيها الوالي، وهي أنَّ أعمال مصر منذ ابتداء أيام الظاهر برقوق، لا يولَّى بها وال إلا بمالٍ يقوم به، أو يلتَزِمُ به، وكان من أتباع المماليك رجل سوَّلت له نفسه ولاية في دمياط، يعرف بناصر الدين محمد السلاخوري، التزم بمالٍ ووَلِيَها، واستدان مالًا حتى عمل له ما يتجمَّلُ به وباشرها غير مرة في هذه الأيام المؤيدية، فلما وليها في هذه السنة جرى على عادته في ظلم الناس، وأخْذِ أموالهم ونسائهم وشباب أولادهم، ومن جملة أهل دمياط طائفة يقال لهم السمناوية، يتعيشون بصيد السمك من بحيرة تنيس، ويسكن كثير منهم بجزائر يسمونها العزب -واحدتها عِزبة- فأَنِفوا من قبائح أفعال السلاخوري؛ ففي يوم الأحد الثاني والعشرين ذي الحجة أوقعوا بنائب الوالي وضربوه وأهانوه، بحيث كاد يهلك، وجرُّوه إلى ظاهر البلد، وتجمَّعوا على باب الوالي، وقد امتنع بها، ورماهم بالنشاب من أعلاها، فأصاب واحدًا منهم فقتله، وجرح ثلاثة، فألحوا في أخذه، وهو يرميهم، حتى نَفِدَت سهامه، فألقى نفسه في البحر، وركب في سفينته إلى الجزيرة، فتَبِعوه في السفن، وأخذوه وتناوبوا ضربه، وأتوا به إلى البلد، وسجنوه موثقًا في رجليه بالخشب، وباتوا يحرُسونه إلى بُكرة غدِهم، ثم أخرجوه وحلقوا نصف لحية نائبه، وشهروه على جمل والمغاني تزُفُّه، حتى طافوا به البلد ثم قتلوه شَرَّ قِتلة، وأخرجوا الوالي من الحبس، وأتَوا ببعض قضاتهم وشهودهم؛ ليثبتوا عليه محضرًا، وأوقفوه على رجليه مكشوف الرأس عاري البدن، فبدره أحد السمناوية وصرعه، وتواثب عليه باقيهم حتى هلك، وسحبوه وأحرقوه بالنار ونهبوا داره وسلبوا حريمه وأولاده ما عليهم، وقتلوا ابنًا له في المهد، مات من الرجفة، وأسروا له ابنًا، فكانت فتنة لم يُدرَك مثلُها في معناها."},{"id":3300,"title":"وفاة القلقشندي صاحب صبح الأعشى .","date":["العام الهجري :821","الشهر القمري : جمادى الآخرة","العام الميلادي :1418"],"text":"هو شهاب الدين أبو العباس أحمد بن علي بن أحمد الفزاري القلقشندي, ولد سنة 765 بقلقشند إحدى قرى القليوبية قرب القاهرة، وبرع القلقشندي بالعربية والإنشاء، وكان عالِمًا بالأنساب، عَمِلَ بديوان الإنشاء في عهد السلطان المملوكي الظاهر برقوق الشركسي ويعتبر كتابه صبح الأعشى في صناعة الإنشاء من أهم كتبه، بل يعتبر من أهم الكتب التي جمعت عدة معارف يحتاج إليها الكاتب: من الخط، والقلم، والمِداد، والجغرافية، والتاريخ، والأنساب، والبلاغة، والأدب، وفيه يصِفُ ويُعَرِّف بكثير من الأشياء بمصر سواء بالأماكن أو المصطلحات المستخدمة وقتها، وله كتاب: نهاية الأرب في معرفة قبائل العرب، وله قلائد الجمان في التعريف بقبائل عرب الزمان، وغيرها، توفي ليلة السبت عاشر جمادى الآخرة عن خمس وستين سنة."},{"id":3301,"title":"عدوان قرا يوسف التركماني صاحب بغداد وتبريز على بلاد الشام  .","date":["العام الهجري :821","الشهر القمري : شعبان","العام الميلادي :1418"],"text":"قَدِمَ الأمير بردبك الحمزاوي -أحد أمراء الألوف بحلب- ومعه نائب كختا -الأمير منكلي بغا- بكتاب يشبك نائب حلب، والأمير عثمان بن طر علي، المعروف بقرا يلك التركماني العثماني، بأن قرا يلك عدى الفرات من مكان يقال له زغموا، ونزل على نهر المرزبان؛ وذلك أنه بلغه أن قرا يوسف قصد كبْسَه، فما أحس قرا يلك إلا وقد هجمت فرقة من عسكر قرا يوسف التركماني عليه من شميصات دخل بهم خليل نائب كركر، فأدركوا قرا يلك عند رحيله من نهر المرزبان إلى مرج دابق، فقاتلهم في يوم الثلاثاء الثاني عشر شعبان، وأخذوا بعض أثقاله، فنزل مرج دابق، ثم قدم حلب في نحو ألف فارس، باستدعاء الأمير يشبك له، فجفل من كان خارج سور مدينة حلب، ورحلوا ليلًا عن آخرهم، واضطرب من بداخل السور، وألقوا بأنفسهم من السور ورحل أجناد الحلقة ومماليك النائب المستخدمين، بحرمهم وأولادهم، فانثنى عزم السلطان عن السفر إلى الحجاز، وكتب إلى العساكر الشامية في المسير إلى حلب، والأخذ في تهيئة الإقامات، وأصبح يوم الثلاثاء السادس والعشرين وقد جمع الأمراء والخليفة وقضاة القضاة، وطلب شيخ الإسلام جلال الدين البلقيني، وقص عليهم خبر قرا يوسف، وما حصل لأهل حلب من الخوف والفزع، وجفلتهم هم وأهل حماة, وأن قرا يوسف في عصمته أربعون امرأة، وأنه لا يدين بدين الإسلام، وكتب صورة فتوى في المجلس فيها كثير من قبائحه، وأنه قد هجم على ثغور المسلمين، ونحو هذا من الكلام، فكتب شيخ الإسلام جلال الدين البلقيني وقضاة القضاة بجواز قتاله، وكتب الخليفة خطه بها أيضًا، وانصرفوا ومعهم الأمير مقبل الداودار فنادوا في الناس بالقاهرة بين يدي الخليفة وشيخ الإسلام وقضاة القضاة الأربعة، بأن قرا يوسف يستحل الدماء، ويسبي الحريم، ويخرب الديار، فعليكم بجهاده كلكم، بأموالكم وأنفسكم، فدهى الناس عند سماعهم هذا، واشتد قلقُهم، وكتب إلى ممالك الشام أن ينادَى بمثل ذلك في كل مدينة، وأن السلطان واصِلٌ إليهم بنفسه وعساكره، وكتب إلى الوجه القبلي بإحضار الأمراء، ثم في شهر رمضان في أوله الأحد قدم الخبر بأن قرا يلك رحل من حلب، وأقام بها الأمير يشبك نازلًا بالميدان، وعنده نحو مائة وأربعين فارسًا، وقد خلت حلب من أهلها، إلا من التجأ إلى قلعتها، فأتاه النذير ليلًا أن عسكر قرا يوسف قد أدركه، فركب قُبَيل الصبح فإذا مقدَّمته وطأت بابلًا فواقعهم وهزمهم، وقتل وأسر جماعة، فأخبروه أنهم جاؤوا لكشف خبر قرا يلك، وأن قرا يوسف بعينتاب، فعاد وتوجه إلى سرمين، فلما بلغ قرا يوسف هزيمة عسكره، كتب إلى نائب حلب يعتذر عن نزوله بعينتاب، وأنه ما قصد إلا قرا يلك؛ فإنه أفسد في ماردين، فبعث إليه صاروخان -مهمندار حلب- فلقيه على جانب الفرات، وقد جازت مجموعة الفرات وهو على نية الجواز، فأكرمه واعتذر عن وصوله إلى عينتاب، وحلف أنه لم يقصد دخول الشام، وأعاده بهدية للنائب، فسُرَّ السلطان بذلك، وكان سبب حركة قرا يوسف أن الأمير قرا يلك صاحب آمد نزل في أوائل شعبان على مدينة ماردين من بلاد قرا يوسف، فأوقع بأهلها، وأسرف في قتلهم، وسبى نساءهم، وباع الأولاد والنساء، حتى بِيعَ الصغير بدرهمين، وحَرَق المدينة، ورجع إلى آمد، فلما بلغ قرا يوسف ذلك اشتد حنقه وسار، ومعه الطائفة المخالفة للسلطان، يريد أخذ قرا يلك، ونزل على آمد، ثم رحل عنها في ثامن شعبان جريدة خلف قرا يلك، وقطع الفرات من شميصات في عاشره، ولحق قرا يلك، وضربه على نهر المرزبان ففَرَّ منه إلى حلب، وهو في أثره، فتوجه قرا يلك من حلب، وكان من مواقعة نائب حلب لعسكر قرا يوسف ما ذُكر، وفي تاسع رمضان قدم الخبر بأن قرا يوسف أحرق أسواق عينتاب ونهبها، فصالحه أهلها على مائة ألف درهم، وأربعين فرسًا، فرحل عنها بعد أربعة أيام إلى جهة البيرة، وعدى معظم جيشه إلى البر الشرقي في يوم الاثنين سابع عشر شعبان، وعدى من الغد، ونزل ببساتين البيرة وحصرها، فقاتله أهلها يومين وقتلوا منه جماعة، فدخل البلد ونهب وأحرق الأسواق، حتى بقيت رمادًا، وامتنع الناس منه ومعهم حريمهم بالقلعة، ثم رحل في التاسع عشر إلى جهة بلاده، بعدما حرق ونهب جميع معاملة البيرة، فسُرَّ السلطان برجوع قرا يوسف، وفتر عزمُه عن السفر إلى الشام."},{"id":3302,"title":"الطاعون يفشو في مصر ويحصد الآلاف من الناس .","date":["العام الهجري :822","الشهر القمري : صفر","العام الميلادي :1419"],"text":"فشا الموت بالطاعون في إقليمي الشرقية والغربية وجميع الوجه البحري، وكان ابتداؤه بالقاهرة ومصر منذ حلت الشمس في برج الحمل، في يوم الأحد الخامس عشر صفر، فبلغت عدة من يرد الديوان من الأموات ما بين العشرين والثلاثين في كل يوم، وبلغت عدة من ورد من الأموات بالقاهرة إلى الديوان نحو الخمسين، أكثرهم أطفال، وذلك سوى المارستان، وموتهم بأمراض حادة، وحبة الموت قَلَّ من يمرض منهم ثلاثة أيام، بل كثير منهم يموت ساعة يمرض، أو من يومه، وبلغت عدة من ورد الديوان من الأموات في ربيع الأول بمدينة بلبيس ألف إنسان، وبناحية بردين من الشرقية خمسمائة نفس، وبناحية ديروط من الغربية ثلاثة آلاف إنسان، سوى بقية القرى، وهي كثيرة جدًّا، وفي شهر ربيع الآخر أوله الخميس في ثالثه بلغت عدة من يرد الديوان من الأموات بالقاهرة إلى مائة وستة وتسعين، سوى المارستان، ومصر، وبقية المواضع التي لا ترد الديوان، وما تقصر عن مائة أخرى، هذا مع شناعة الموتان بالأرياف، وخلو عدة قرى من أهلها، وكان عدة من مات بالقاهرة وورد اسمه إلى الديوان من العشرين من صفر إلى آخر شهر ربيع الآخر 7652؛ من الرجال: ألف وخمسة وستون رجلًا، والنساء 669 امرأة، والصغار 3969 صغيرًا، والعبيد 544، والإماء 1369، والنصارى 69، واليهود 32، وذلك سوى المارستان، وسوى ديوان مصر، وسوى من لا يَرِدُ اسمه إلى الديوانين، ولا يقصر ذلك عن تتمة العشرة آلاف، ومات بقرى الشرقية والغربية مثل ذلك وأزيدُ!"},{"id":3303,"title":"دخول قيسارية إلى السلطنة المملوكية .","date":["العام الهجري :822","الشهر القمري : ربيع الآخر","العام الميلادي :1419"],"text":"قَدِمَ الخبر برحيل ابن السلطان المؤيد شيخ من حلب، ودخل إلى مدينة قيسارية الروم في يوم الخميس تاسعه، فحضر إليه أكابرها من القضاة والمشايخ والصوفية، وتلقوه، فألبسهم الخِلَع، وطلع قلعتها في يوم الجمعة، وخُطِبَ في جوامعها للسلطان، وضُرِبت السكة باسمه، وأن شيخ جلبي نائب قيسارية انسحب قبل وصوله إليها، وأنه خلع على الأمير محمد بك قرمان، وأقره في نيابة السلطنة بقيسارية الروم، فدُقَّت البشائر بقلعة الجبل، وفرح السلطانُ بأخذ قيسارية، فإنَّ هذا شيء لم يتَّفِق لملك من ملوك الترك بمصر، سوى للظاهر بيبرس، ثم انتقض الصلح بينه وبين أهلها."},{"id":3304,"title":"منع النصارى من العمل في ديوان السلطان وإلزامهم بملابس خاصة .","date":["العام الهجري :822","الشهر القمري : جمادى الأولى","العام الميلادي :1419"],"text":"في سابع جمادى الأولى استُدعِيَ بطرك النصارى، وقد اجتمع القضاة ومشايخ العلم عند السلطان، فأُوقِفَ على قدميه، ووُبِّخ وقُرِّع، وأنكر عليه ما بالمسلمين من الذلِّ في بلاد الحبشة، تحت حكم الحطي متملِّكِها، وهُدِّد بالقتل، فانتدب له محتسب القاهرة صدر الدين أحمد بن العجمي وأسمعه المكروه له من أجل تهاون النصارى فيما أُمروا به من التزام الذلة والصغار في ملبسهم وهيأتهم، وطال الخطابُ في معنى ذلك إلى أن استقر الحال على ألَّا يباشر أحد من النصارى في ديوان السلطان، ولا عند أحد من الأمراء، ولا يخرج أحد منهم عمَّا يُلزمون به من الصَّغار، ثم طلب السلطان الأكرم فضائل النصراني كاتب الوزير، وكان قد سُجِنَ منذ أيام، فضربه بالمقارع وشَهَره بالقاهرة، عُريانًا بين يدي المحتَسِب، وهو ينادي عليه: هذا جزاء من يباشر من النصارى في ديوان السلطان، ثم سُجِن بعد إشهاره، فانكفَّ النصارى عن مباشرة الديوان ولزموا بيوتهم، وصغَّروا عمائِمَهم، وضيَّقوا أكمامهم، والتزم اليهود مثل ذلك، وامتنعوا جميعهم من ركوب الحمير في القاهرة، فإذا خرجوا من القاهرة ركبوا الحمير عَرضًا، وأنف جماعة من النصارى أن يفعلوا ذلك، وبذلوا جهدهم في السعي لإبطاله، فلما لم يجابوا إلى عودهم إلى ما كانوا عليه، تتابع عدةٌ منهم في إظهار الإسلام، وصاروا من ركوب الحمير إلى ركوبِ الخيول المسوَّمة، والتعاظم على أعيان أهل الإسلام، والانتقام منهم بإذلالِهم، وتعويق معاليمِهم ورواتِبِهم، حتى يخضعوا لهم، ويتردَّدوا إلى دورهم، ويلحُّوا في السؤال لهم، ولا حول ولا قوة إلا بالله، ونادى المحتسب في شوارع القاهرة ومصر بأن النصارى واليهود لا يمرون في القاهرة إلا مشاةً غيرَ ركَّاب، وإذا ركبوا خارج القاهرة فليركبوا الحمير عرضًا، ولا يلبَسوا إلا عمائم صغيرة الحجم، وثيابًا ضيقةَ الأكمام، ومن دخل منهم الحمَّام فليكُنْ في عنُقِه جَرَس، وأن تلبس نساءُ النصارى الأُزُرَ الزُّرْقَ، ونساءُ اليهود الأزُرَ الصُّفْرَ، فضاقوا بذلك، واشتدَّ الأمر عليهم، فسَعَوا في إبطاله سعيًا كبيرًا، فلم ينالوا غرضًا، وكبست عليهم الحمامات، وضُرِب جماعة منهم لمخالفته، فامتنع كثير منهم عن دخول الحمَّام، وعن إظهار النساءِ في الأسواق."},{"id":3305,"title":"وفاة السلطان عثمان المريني سلطان بني مرين ومبايعة ابنه الصبي .","date":["العام الهجري :823","الشهر القمري : شوال","العام الميلادي :1420"],"text":"هو السلطان أبو سعيد عثمان بن السلطان أبي العباس أحمد ابن السلطان أبي سالم إبراهيم ابن السلطان أبي الحسن علي بن عثمان بن يعقوب بن عبد الحق المريني الفاسي ملك الغرب وصاحب فاس. توفي قتيلًا في ليلة الثالث عشر شوال، قتله وزيره عبد العزيز اللباني، وكانت مدته ثلاثًا وعشرين سنة وثلاثة أشهر، وأقيم ولده عبد الحق خلفًا له مع أنه ما يزال صبيًّا، وكان الوصيُّ عليه الوزير أبا زكريا يحيى الوطاسي، فكان هو الحاكم، ويعتبر أبو سعيد آخر ملوك بني مرين؛ ففي ذي الحجة سار أبو زيان محمد بن أبي طريق محمد ابن السلطان أبي عنان من تازي، وكان ابن الأحمر قد بعث به من الأندلس لأخذ فاس، فنزل عليها وبايعه الشيخ يعقوب الحلفاوي الثائر بمدينة فاس، بمن اجتمع معه من أهل البلد، وقاتلوا اللباني أربعة أشهر."},{"id":3306,"title":"السلطان المؤيد شيخ المحمودي يعهد بالسلطنة لولده أحمد من بعده .","date":["العام الهجري :823","الشهر القمري : شوال","العام الميلادي :1420"],"text":"طلب السلطان القضاة والأمراءَ فعهد إلى ولده الأمير أحمد بالسلطة من بعده، ومولده في ثاني جمادى الأولى من السنة الماضية، وله من العمر سبعة عشر شهرًا وخمسة أيام، وجعل الأمير الكبير ألطنبغا القرمشي القائِمَ بأمره، وأن يقومَ بتدبير الدولة, ثم أحضر القرمشي من حلب الأمراء الثلاثة، وهم: قجقار القردمي، وتنبك ميق، وططر، وحلفوا على ذلك، ثم حلف المماليك من الغد، ثم في ذي الحجة أثبت عهد الأمير أحمد ابن السلطان المؤيد، على قاضي القضاة زين الدين عبد الرحمن التفهني الحنفي، بالسلطنة، ثم نفذ على بقية القضاة."},{"id":3307,"title":"وفاة الأمير قرا يوسف متملك العراق وتبريز وتملك ابنه شاه محمد .","date":["العام الهجري :823","الشهر القمري : ذي القعدة","العام الميلادي :1420"],"text":"هو الأمير قرا يوسف ابن الأمير قرا محمد بن بيرم خجا التركماني متملك العراق وتبريز، وكان قرا يوسف شديد الظلم قاسي القلب لا يتمسَّك بدين، واشتهر عنه أنَّ في عصمته أربعين امرأة، وقد خربت في أيامه وأيام أولاده مملكة العراقين, فصدر بحقه فتوى تستبيحُ دمه, فقد ذكر موفق الدين ابن العجمي \"أن قرا يوسف عنده أربع زوجات، فإذا طلَّق واحدةً دفعها إلى قصر له وتزوَّج غيرها حتى بلغ عدد من في القصر أربعين امرأة يسمِّيهن السراري ويطؤُهنَّ كالسَّراري بمِلكِ اليمين! فاتفق الحال على كتابة فتوى متضمنة سوء سيرته، فصُوِّرت وكُتِبَت وكَتَب عليها البلقيني ومن حضر المجلس يتضمَّنُ جواز قتاله. وأعجب السلطان ما كتب الحنبلي وأمر أن ينسخ ويقرأ على الناس, فنودي في الناس: بأن قرا يوسف طرق البلاد وأنه يستحل الدماء والفروج والأموال وخرَّب البلاد\" وقد عصى عليه ولده شاه محمد ببغداد فحاصره ثلاثة أيام، حتى خرج إليه، فأمسكه واستصفى أمواله، وولى عِوَضَه ابنه أصبهان أمير زاة، ثم عاد إلى تبريز لحركة شاه رخ بن تيمورلنك عليه، ثم في ثامن عشر ذي الحجة قَدِمَ كتاب سليمان صاحب حصن كيفا، يتضمن موت قرا يوسف في رابع عشر ذي القعدة مسمومًا، فيما بين السلطانية وتوريز، وهو متوجه إلى قتال شاه رخ بن تيمورلنك، وملك بعده ابنه شاه محمد بن قرا يوسف، ثم تنصَّر ودعا الناس إلى دين النصرانية، وأباد العلماء والمسلمين، ثم ملك بعده إسكندر، وكان على ما كان عليه شاه محمد وزيادة، ثم أخوهما أصبهان، فكان زنديقًا لا يتديَّنُ بدين، فقرا يوسف وذريته هم كانوا سببًا لخراب بغداد التي كانت كرسيَّ الإسلام، ومنبعَ العلوم، ومدفنَ الأئمة الأعلام!!"},{"id":3308,"title":"وفاة السلطان محمد جلبي سلطان العثمانيين وتولي ابنه مراد الثاني .","date":["العام الهجري :824","العام الميلادي :1421"],"text":"هو السلطان محمد الأول بن بايزيد الأول بن مراد الأول بن أورخان غازي بن عثمان بن أرطغرل، هو السلطان الخامس للدولة العثمانية والملقب بالجلاد -ويعرف بمحمد جلبي- تولى السلطنة بعد وفاة أبيه، ونازعه إخوته الثلاثة على الحكم فقاتلهم حتى تمكن من قتلهم، ثم عمل على استرجاع الأراضي التي انتُزِعَت من الدولة بعد هزيمة والده وأسْرِه من قِبَل تيمورلنك في معركة أنقرة سنة 804, كما أنه عمل على بناء وتقوية الأسطول البحري العثماني، ونقل عاصمته من بورصا إلى أدرنة, وكان قد أوصى لابنه مراد من بعده، وكان يوم وفاة أبيه محمد الأول في أماسيا وكُتم وفاة السلطان حتى وصل مراد إلى أدرنة بعد واحد وأربعين يومًا، ودفن السلطان محمد جلبي في بورصا، وكانت مدة سلطنته قريبًا من ثماني عشرة سنة."},{"id":3309,"title":"وفاة السلطان الملك المؤيد شيخ المحمودي سلطان المماليك .","date":["العام الهجري :824","الشهر القمري : محرم","العام الميلادي :1421"],"text":"هو السلطان الملك المؤيد أبو النصر سيف الدين شيخ بن عبد الله المحمودي الظاهري، وهو السلطان الثامن والعشرين من ملوك الترك المماليك بالديار المصرية، والرابع من الشراكسة وأولادهم، أصله من مماليك الملك الظاهر برقوق، اشتراه من أستاذه الخواجا محمود شاه البرزي في سنة 782، وبرقوق يوم ذاك أتابك العساكر بالديار المصرية قبل سلطنته، وكان عمر شيخ يوم اشتراه الملك الظاهر نحو اثنتي عشرة سنة تخمينًا، وجعله برقوق من جملة مماليكه، ثم أعتقه بعد سلطنته. تولى المؤيد شيخ السلطنة سنة 815 بعد خروجه هو والأمير ونوروز على السلطان الناصر فرج ابن السلطان برقوق فتغلَّبا عليه فخلعوه ثم قتلوه، وتولى الخليفة المستعين بالله السلطنة ثم خلعه الأمير شيخ وأخذ البيعة لنفسه, وتلقَّب بالسلطان الملك المؤيد شيخ, ثم ثار عليه صاحبه نوروز ونائبه على دمشق سنة 816 فتغلب عليه المؤيد وقَتَله, وفي شوال من السنة الماضية أخذ المؤيد البيعةَ لابنه أحمد وهو لا يزال رضيعًا, وفي مستهل المحرم من هذه السنة لازم السلطان المؤيد الفراش، وقد أفرط به الإسهالُ الدموي مع تنوُّع الأسقام وتزايُد الآلام، بحيث إنه لم يبق مرض من الأمراض حتى اعتراه، غير أنه صحيح العقل والفهم طَلِقَ اللسان، وقد اشتد الأمر بالسلطان من الآلام والإرجاف تتواتر بموته، والناس في هرج إلى أن توفي قبيل الظهر من يوم الاثنين تاسع المحرم فارتجَّ الناس لموته ساعة ثم سكنوا، وطلع الأمراء القلعة وطلبوا الخليفة المعتضد بالله داود والقضاة والأعيان لإقامة الأمير أحمد بن السلطان المؤيد في السلطنة، وكان أبوه قد عهد له بذلك، فخلع عليه فتسلطَنَ ثم أخذوا في تجهيز السلطان الملك المؤيد وتغسيله وتكفينه، وصلِّيَ عليه خارج باب القلعة، وحُمِل إلى الجامع المؤيدي فدُفِن بالقبة قبيل العصر، ولم يشهد دفنه كثير من الأمراء والمماليك لتأخُّرهم بالقلعة، ومات وقد أناف على الخمسين، وكانت مدة ملكه ثماني سنين وخمسة أشهر وثمانية أيام، أما السلطان الجديد أحمد بن المؤيد شيخ وعمره سنة واحدة وثمانية أشهر وسبعة أيام، فأُركب على فرس من باب الستارة، فبكى وساروا به وهو يبكي إلى القصر، حيث الأمراء والقضاة والخليفة، فقبَّلوا له الأرضَ، ولقَّبوه بالملك المظفر أبي السعادات، وقام الأمير ططر بأعباء الدولة، وخلع عليه لالا -مربي- السلطان وكافله!!"},{"id":3310,"title":"عصيان الأمير جقمق نائب دمشق وتسلطنه فيها ثم إنهاء فتنته وقتله .","date":["العام الهجري :824","الشهر القمري : صفر","العام الميلادي :1421"],"text":"في سابع شهر صفر قدم الخبر بأن الأمير جقمق نائب الشام أخذ قلعة دمشق واستولى على ما فيها من الأموال وغيرها، وكان بها نحو المائة ألف دينار، فاضطرب أهلُ الدولة؛ وذلك لما بلغه من أن الأمير ططر قام بأمور السلطنة كلها وتفرد بها، وفي ثامن عشر ربيع الآخر قدم الخبر بأن عساكر دمشق برزت منها، وأنها نزلت باللجون، فركب الأمير ططر في يوم الثلاثاء التاسع عشر من قلعة الجبل ومعه السلطان الملك المظفر أحمد والأمراء، يريد السفر إلى الشام، ونزل بهم في المخيم ظاهر القاهرة، وخرج الناس أفواجًا في إثره، وأصبح يوم الأربعاء الأمير تنبك ميق راحلًا، ومعه عدة من الأمراء وغيرهم، ثم استقل الأمير ططر بالمسير ومعه السلطان والخليفة وبقية العسكر في يوم الجمعة الثاني والعشرين، وفي يوم الأحد ثاني شهر جمادى الأولى دخل الأمير ططر بالسلطان إلى غزة، فقدم إليه طائعًا كثيرٌ ممن خرج من عسكر دمشق، منهم الأمير جلبان أمير أخور أحد المجردين إلى حلب في أيام المؤيد، والأمير أينال نائب حماة، فسُرَّ بهم، وأنعم عليهم، وفرَّ ممن كان معهم الأمير مقبل الدوادار في طائفة يريد دمشق، فلما كان في يوم الاثنين ثالثه: بلغ القرمشي عن جقمق بأنه يريد أن يقبض عليه، فبادر القرمشي إلى محاربته، وركب في جماعته بآلة الحرب، ووقف بهم تجاه القلعة، وقد رفع الصنجق السلطاني، فأتاه جماعة عديدة راغبين في الطاعة، وكانت بينه وبين جقمق وقعة طول النهار، فانكسر جقمق ومضى هو والأمير طوغان أمير أخور والأمير مقبل الدوادار في نحو الخمسين فارسًا إلى جهة صرخد، وأن القرمشي استولى على مدينة دمشق وتقدم إلى القضاة والأعيان أن يتوجهوا إلى ملاقاة السلطان، فقدموا إلى العسكر، وسار الأمير ططر بمن معه إلى دمشق، فدخلها بكرة يوم الأحد الخامس عشر، وأول ما بدأ به أن قبض على القرمشي والمرقبي وجرباش، وعلى الأمير أردبغا من أمراء الألوف بدمشق، وعلى الأمير بدر الدين حسن بن محب الدين أستادار المؤيد، وقدم الخبر بأن الأمير برسباي الدقماقي نائب طرابلس كان بعثه الأمير ططر من حلب، ومعه القاضي بدر الدين محمد بن مزهر ناظر الإسطبل إلى صرخد، وأنه ما زال بالأمير جقمق حتى أذعن، وسار معه إلى دمشق، وصحبه الأمير طوغار أمير أخور، فلما قدموا دمشق قبض الأمير تنبك ميق النائب على جقمق وطوغان وسجنهما، وأن الأمير ططر برز من حلب بمن معه في حادي عشر شعبان، وأنه قدم بهم إلى دمشق في الثالث والعشرين، فقتل جقمق نائب الشام."},{"id":3311,"title":"الأمير الكبير ططر يتفرد بأمور السلطنة بحجة صغر السلطان المظفر .","date":["العام الهجري :824","الشهر القمري : صفر","العام الميلادي :1421"],"text":"في عاشر شهر صفر جمع الأميرُ الكبير ططر عنده بالأشرفية من القلعة قضاةَ القضاة وأمراء الدولة ومباشريها، وكثيرًا من المماليك السلطانية، وأعلَمَهم بأن نواب الشام والأمير ألطنبغا القرمشي ومن معه من الأمراء المجردين لم يرضوا بما عمل بعد موت المؤيد، ولا بد للناس من حاكم يتولى تدبيرَ أمورهم، ولا بد أن يعيِّنوا رجلًا ترضَونه؛ ليقوم بأعباء المملكة ويستبد بالسلطنة، فقال الجميع: قد رضينا بك، وكان الخليفة حاضرًا فيهم، فأشهد عليه أنَّه فوض جميع أمور الرعية إلى الأمير الكبير ططر، وجعل إليه ولاية من يرى ولايته، وعزل من يريد عزله من سائر الناس، وأن يُعطي من شاء ما شاء، ويمنع من يختار من العطاء، ما عدا اللقب السلطاني، والدعاء له على المنابر، وضرب اسمه على الدنانير والدراهم، فإن هذه الثلاثة أشياء باقية على ما هي عليه للملك المظفَّر، وأثبت قاضي القضاة زين الدين عبد الرحمن التفهني هذا الإشهاد، وحكم بصحته، ونفذَ حكمه قضاة القضاة الثلاثة، ثم حلف الأمراء للأمير الكبير يمينهم المعهودة."},{"id":3312,"title":"الحرب بين بني زيان والمرينيين .","date":["العام الهجري :824","الشهر القمري : ربيع الآخر","العام الميلادي :1421"],"text":"كانت حربٌ بمدينة فاس من بلاد المغرب بين أبي زيان محمد بن أبي طريق بن أبي عنان, وقد قام بأمر الحرب الشيخ يعقوب الحلفاوي الثائر على الوزير الحاجب عبد العزيز اللباني لقتله السلطان أبا سعيد عثمان بن أبي العباس أحمد وثلاثة عشر أميرًا من إخوته وأولاده وبني إخوته, وكان اللباني قد استنصر بالشاوية، وبعث إليهم بمال كبير، فأتوه، فلم يطق الحلفاوي مقاومتهم، فأُدخل اللباني مدينة فاس بجموعه، وألويته منشورة على رأسه، وأنزله دار الحرة آمنة بنت السلطان أبي العباس أحمد، فرحل الشاوية عن المدينة، ثم قُبِضَ على اللباني، وأُسلِمَ إلى الحلفاوي، فدخل السلطان أبو زيان فاس الجديد في ربيع الآخر، وبعث بالسلطان أبي عبد الله محمد بن أبي سعيد إلى الأندلس، فما كان سوى شهر حتى ثار بنو مرين على أبي زيان، وحصروه، وطلبوا الوزير أبا البقاء صالح بن صالح أن يحمل أبا عبد الله محمد المتوكل ابن السلطان أبي سعيد، فقدم الوزير به، واستمرت الحرب أربعة أشهر إلى أن فر أبو زيان ووزيره فارح، وأخذ بنو مرين البلد الجديد، وطلبوا من ابن الأحمر أن يبعث بالسلطان الكبير أبي عبد الله محمد المستنصر بن أبي سالم إبراهيم بن أبي الحسن، فبعثه إليهم، فملكوه وأطاعوه."},{"id":3313,"title":"خلع السلطان المظفر أحمد وتسلطن الأمير الكبير ططر .","date":["العام الهجري :824","الشهر القمري : شعبان","العام الميلادي :1421"],"text":"لما انتهى الأمير ططر من أمر جقمق في دمشق وكان هو المتولي لكل أمور السلطنة، عزم على خلع المظفر من السلطنة، وخاصة أنه يراه صغيرًا جدًّا على هذا الأمر، فخلعه في التاسع والعشرين شعبان وهو في دمشق، فكانت مدة سلطنة السلطان المظفر أحمد بن المؤيد شيخ سبعة أشهر وعشرين يومًا، وتلقب السلطان الجديد بالظاهر سيف الدين أبو الفتح ططر بن عبد الله الظاهري، وخُطِب له من يومه على منابر دمشق، وكُتِب إلى مصر وحلب وحماة وحمص وطرابلس وصفد وغزة بذلك."},{"id":3314,"title":"عصيان مصطفى بن بايزيد على ابن أخيه السلطان مراد الثاني  .","date":["العام الهجري :824","الشهر القمري : ذي القعدة","العام الميلادي :1421"],"text":"بعد أن تولى السلطان مراد الثاني سلطنة الدولة العثمانية، طلب منه إمبراطور القسطنطينية إيمانويل أن يتعهد له بعدم محاربته مطلقًا وأن يسلمه اثنين من إخوته تأمينًا على نفاذ هذا التعهد وتهدده بإطلاق سراح عمه مصطفى بن بايزيد ولَمَّا لم يجبه مراد الثاني لطلبه أخرج مصطفى من منفاه وأعطاه عشرة مراكب حربية تحت إمرة دمتريوس لاسكاريس, فحاصر بها مدينة غاليبولي فسُلِّمَت إلا القلعة فتركها مصطفى بعد أن أقام حولها من الجند ما يكفي لمنع وصول المدد إليها وسار ببقية جيشه قاصدًا أدرنه، فخرج الوزير بايزيد باشا لمحاربته فتقدم مصطفى وخطب في العساكر بإطاعته؛ لأنه أحق بالملك من ابن أخيه فأطاعته الجيوش وقتلت بايزيد باشا قائدهم فسار مصطفى بعد ذلك لمقابلة ابن أخيه مراد الثاني الذي كان متحصنًا مع من معه من الجنود خلف نهر صغير، وهناك خان مصطفى بعضُ قواده فتركه أغلبُ جنوده حتى التزم الهروبَ إلى مدينة جاليبولي فسلَّمه بعض أتباعه إلى ابن أخيه مراد الثاني فأمر بشنقِه."},{"id":3315,"title":"وفاة السلطان الملك الظاهر ططر وتولي ابنه الصالح محمد .","date":["العام الهجري :824","الشهر القمري : ذي الحجة","العام الميلادي :1421"],"text":"هو الملِكُ الظاهر سيف الدين أبو الفتح ططر بن عبد الله الظاهري الشركسي, ربَّاه بعض التجار، وعلَّمه شيئًا من القرآن وفِقهَ الحنفية، وقَدِمَ به القاهرة في سنة 801، وهو صبيٌّ، فدل عليه الأمير قانبيه العلاي لقرابته به، فسأل السلطان الملك الظاهر برقوق فيه حتى أخذه من تاجره، ونزله في جملة مماليك الطباق، فنشأ بينهم، وكان الملك الظاهر برقوق أعتقه بسفارة الأمير جرباش الشيخي. بعد وفاة الملك المؤيد شيخ بويعَ ابنُه الملك المظفر أحمد، وقام الأمير الكبير ططر بأعباء الدولة، وخلع عليه لالا -مربي- للسلطان وكافله. ثم عزل ططر المظفر أحمد؛ لصِغَر سنِّه، وأخذ البيعة بالسلطنة لنفسه, وفي أول ذي الحجة يوم الخميس زاد مرض السلطان الظاهر ططر، والإرجاف بمرضه كبير، ثم في يوم الجمعة استدعى الخليفة والقضاة إلى القلعة، وقد اجتمع الأمراء والمباشرون والمماليك، وعهد السلطان لابنه الأمير محمد، وأن يكون القائم بدولته الأمير جانبك الصوفي، والأمير برسباي الدقماقي لالا -مربي السلطان- فحلف الأمراء على ذلك، كما حلفوا لابن الملك المؤيد، فلما كانت ضحوة نهار الأحد رابعَه توفي السلطان، فاضطرب الناس ساعة، ثم غُسِّل وأخرج من باب السلسلة، وليس معه إلا نحو العشرين رجلًا، حتى دُفن بجوار الليث بن سعد من القرافة، فكانت مدة تحكمه منذ مات المؤيد أحد عشر شهرًا تنقص خمسة أيام، منها مدة سلطنته أربعة وتسعين يومًا، أما السلطان الجديد فهو محمد بن الظاهر ططر أقيم في السلطنة بعهد أبيه إليه، وعمره نحو العشر سنين، عقيب موت أبيه، وفي يوم الأحد رابع ذي الحجة من هذه السنة اجتمع الأمراء بالقلعة إلا الأمير جانبك الصوفي فإنه لم يحضر، فما زالوا به حتى حضر، وأجلسوا السلطان، ولقَّبوه بالملك الصالح ناصر الدين، وفوَّض الخليفة إلى الأمير الكبير نظام الملك برسباي أمورَ المملكة بأسرها؛ ليقوم بها إلى أن يبلغ السلطان رُشدَه، وحكم بصحة ذلك قاضي القضاة الحنفي."},{"id":3316,"title":"خروج الأمير تغري بردي المؤيدي نائب حلب عن الطاعة .","date":["العام الهجري :824","الشهر القمري : ذي الحجة","العام الميلادي :1421"],"text":"لما كان يوم ثامن عشر ذي الحجة ورد الخبر بأن الأمير تغري بردي المؤيدي نائب حلب المعروف بأخي قصروه- خرج عن طاعة السلطان، وقبض على الأمراء الحلبيين، واستدعى التركمان والعربان، وأكثر من استخدام المماليك، وسببُ خروجه عن الطاعة أنه بلغه أن الملك الظاهر ططر عزَلَه، وأقرَّ عِوَضَه في نيابة حلب الأمير تنبك البجاسي نائب طرابلس، فلما تحقق ذلك خرج عن الطاعة وفعل ما فعل، فشاور الأمير برسباي الأمراءَ في أمره، فوقع الاتفاقُ على أن يكتب الأمير تنبك البجاسي بالتوجُّه إليه وبصحبته العساكر، وقتاله، وأخذ مدينة حلب عنوة، وباستقراره في نيابتها كما كان الملك الظاهر ططر أقره، وكتب له بذلك، ثم في يوم الأحد ثالث محرم سنة 825 ورد الخبر إلى الديار المصرية بفرار الأمير تغري بردي المؤيدي من حلب بعد وقعة كانت بينه وبين تنبك البجاسي المنتَقِل عِوَضَه إلى نيابة حلب."},{"id":3317,"title":"خلع السلطان الصالح محمد بن ططر وتسلطن الأشرف برسباي .","date":["العام الهجري :825","الشهر القمري : ربيع الآخر","العام الميلادي :1422"],"text":"ما زال برسباي قائمًا بتدبير أمر الدولة، ثم أحَبَّ أن يُطلَق عليه اسمُ السلطان لما خلا له الجو؛ فإنه كان ينافسه جنبك  الصوفي، وقد استطاع طرباي التخلص منه، ثم استطاع برسباي بمكيدة كذلك التخلص من طرباي وسجنه، ولما تم أمر الأمير برسباي فيما أراد من القبض على الأمير طرباي والاستبداد بالأمر، أخرج الأمير سودون الحموي منفيًّا إلى ثغر دمياط، ثم أخذ في إبرام أمره ليترقى إلى أعلى المراتب، فلم يلقَ في طريقه من يمنعه من ذلك، وساعده في ذلك موت الأمير حسن بن سودون الفقيه خال الملك الصالح محمد بن ططر في يوم الجمعة الثالث عشر صفر، فإنه كان أحد مقدمي الألوف وخال السلطان الملك الصالح، وكان جميع حواشي الملك الظاهر ططر يميلون إليه، فكُفِيَ الأمير برسباي همَّه أيضًا بموته، فلما رأى برسباي أنَّه ما ثَمَّ عنده مانع يمنعه من بلوغ غرضه بالديار المصرية، خَشِيَ عاقبة الأمير تنبك ميق نائب الشام، وقال: لا بدَّ من حضوره ومشورته فيما نريد فِعلَه، فندب لإحضاره الأمير ناصر الدين محمد ابن الأمير إبراهيم ابن الأمير منجك اليوسفي، فحضر ثم خلا به الأمير برسباي وتكلم معه واستشاره فيمن يكون سلطانًا؛ لأن الديار المصرية لا بد لها من سلطان تجتمع الناس على طاعته، ثم قال له: وإن كان ولا بد فيكون أنت، فإنك أغاتنا وكبيرنا وأقدَمنا هجرةً، فاستعاذ الأمير تنبك من ذلك وقام في الحال، وقَبَّل الأرض بين يديه، وقال: ليس لها غيرك، فشكر له الأمير برسباي على ذلك، ثم اتفق جميع الأمراء على سلطنته، وخلع الملك الصالح محمد بن ططر من السلطنة، فوقع ذلك يوم الأربعاء ثامن شهر ربيع الآخر، فكانت مدة حكم الملك الصالح أربعة أشهر وثلاثة أيام, وتم الخلع بموافقة نائب الشام على ذلك، واستُدعِيَ الخليفة والقضاة، وقد جُمع الأمراء وأرباب الدولة، فبايعه الخليفة في هذا اليوم الأربعاء، ولُقِّبَ بالملك الأشرف أبي العز، ونودي بذلك في القاهرة ومصر، وهو السلطان الملك الأشرف سيف الدين أبو النصر برسباي الدقماقي الظاهري، وأصل الملك الأشرف هذا شركسي الجنس، وجُلِب من البلاد فاشتراه الأمير دقماق المحمدي الظاهري نائب ملطية، وأقام عنده مدة، ثم قدمه إلى الملك الظاهر برقوق في عدة مماليك أخر، ثم أعتقه السلطان الظاهر برقوق."},{"id":3318,"title":"السلطان الأشرف برسباي يمنع من عادة تقبيل الأرض للملوك  .","date":["العام الهجري :825","الشهر القمري : ربيع الآخر","العام الميلادي :1422"],"text":"أول ما بدأ به الأشرف في سلطنته أنَّه منع الناس كافةً من تقبيل الأرض بين يديه، فامتنعوا من ذلك، وكانت عادةُ تقبيل الأرض جرت بالديار المصرية من أيام المعزِّ معد أول خلفاء بني عُبَيد بمصر، وبقيت إلى يوم تاريخه، وكان لا يُعفى أحد عن تقبيل الأرض، والكل يُقَبِّل الأرض: الوزير والأمير والمملوك وصاحب القلم ورسل ملوك الأقطار، إلا قضاة الشرع وأهل العلم وأشراف الحجاز! حتى لو ورد مرسوم السلطان على ملك من نواب السلطان قام على قدميه وخرَّ إلى الأرض وقبَّلها قبل أن يقرأ المرسوم، فأبطل الملك الأشرف برسباي ذلك وجعل بدلَه تقبيل اليد، فمشى ذلك أيامًا، ثم عاد تقبيل الأرض لكن بطريق أحسن من الأولى؛ فإن الأولى كان الشخص يخرُّ إلى الأرض حتى يقبِّلَها كالساجد، والآن صار الرجل ينحني كالراكع ويضع أطرافَ أصابع يده على الأرض كالمقَبِّل، ثم يقوم ولا يقبِّل الأرضَ بفَمِه أبدًا، بل ولا يَصِلُ بوجهه إلى قريب الأرض، فهذا على كل حال أحسنُ مما كان أولًا!"},{"id":3319,"title":"السلطان الأشرف يمنع اليهود والنصارى من استخدام ديوان السلطنة .","date":["العام الهجري :825","الشهر القمري : جمادى الأولى","العام الميلادي :1422"],"text":"في يومِ الخميس ثامن جمادى الأولى صدر مرسوم السلطان الملك الأشرف بألَّا يُستخدَم أحد من اليهود ولا من النصارى في ديوان من دواوين السلطان والأمراء، ونودِيَ بذلك في القاهرة، وصَمَّم الأشرف على ذلك، فلم يسلَمْ من اعتراض بعض عظماء الأقباط من مباشري الدولة، فلم يتِمَّ له ذلك."},{"id":3320,"title":"السلطان العثماني مراد الثاني يعقد صلح مع ملوك أوروبا .","date":["العام الهجري :825","الشهر القمري : جمادى الأولى","العام الميلادي :1422"],"text":"بعد أن تولى مراد الثاني السلطنة خلفًا لأبيه محمد جلبي رأى أنَّ عليه أن يعيد الإمارات في الأناضول إلى حظيرة الدولة العثمانية، فعَقَد هدنة مع ملك المجر مدتها خمس سنوات، وصالح أمير قرمان، وأمَّا إمبراطور القسطنطينية فطلب من  مراد الثاني التعهُّدَ بعدم قتاله، وطلب منه أن يسلِّمَه اثنين من إخوته كرهائن، وأنه إذا فكر بالحرب فسيطلق سراح عم السلطان مصطفى بن بايزيد المحجوز في سلانيك، وهو المنافس لمراد الثاني في السلطنة، فرفض مراد هذا الشرط فأطلق الإمبراطور مصطفى بن بايزيد ودعمه بعشرات المراكب لحصار مدينة غاليبولي، فلم يتمكن مصطفى من مراده, فاتجه نحو أدرنة بعد أن ترك قوة محاصرة لقلعة غاليبولي، وفي أدرنة واجهه القائد بايزيد باشا فقاتله فقتله مصطفى وتابع سيره إلى مراد، ولكن كثيرًا من الأمراء الذين كانوا معه لم يطيعوه فتركوه، فعاد إلى غاليبولي؛ حيث قُبِضَ عليه فيها وقُتِلَ؛ انتقامًا لِما فعله الإمبراطور القسطنطيني."},{"id":3321,"title":"السلطان مراد الثاني يحاصر القسطنطينية .","date":["العام الهجري :825","الشهر القمري : رجب","العام الميلادي :1422"],"text":"لما تخلص مراد الثاني من عمه مصطفى بن بايزيد الذي دعمه إمبراطور القسطنطينية سار في شهر رجب من بورصا إلى اسطنبول ( قسطنطينية) ونزل عليها أول شعبان، وقطع عامة أشجارها، ومنع عنها الميرة، حتى فرغ شهر رمضان من غير حرب، سوى مرة واحدة في يوم الجمعة ثالث رمضان، فإنه زحف على المدينة فكان بينه وبين أهلها حرب شديدة، فتخلى عنه عسكره، وبينما هو في ذلك إذ جاءه أخوه مصطفى، وكان في مملكة محمد باك بن قرمان، فتفرق عن مراد عسكره، وكانوا نحو مائة وخمسين ألفًا، حتى بقي في زهاء عشرين ألفًا، والتجأ مصطفى إلى اسطنبول، وواقفَ مرادًا نحو شهر، وقد عجز عنه مراد لمخالفة عسكرِه عليه."},{"id":3322,"title":"خروج الأمير إينال نائب صفد عن الطاعة وقتله .","date":["العام الهجري :825","الشهر القمري : رجب","العام الميلادي :1422"],"text":"في شهر رجب ورد الخبر على السلطان بخروج الأمير إينال نائب صفد عن الطاعة، وكان سبب خروجه عن الطاعة أنه كان من جملة مماليك الملك الظاهر ططر، ربَّاه صغيرًا، ثم ولاه نيابة قلعة صفد بعد سلطنته، فلما قام الملك الأشرف برسباي بعد الملك الظاهر ططر بالأمر ولى إينال نيابة صفد، وبلغه خلع ابن أستاذه الملك الصالح محمد من السلطنة، فشَقَّ عليه ذلك، وأخذ في تدبيرِ أمره، واتَّفق مع جماعة على العصيان، وخرج عن الطاعة، وأفرج عمن كان محبوسًا بقلعة صفد، وهم: الأمير يشبك أنالي المؤيدي الأستادار، ثم رأس نوبة النوب، والأمير إينال الجكمي أمير سلاح ثم نائب حلب، والأمير جلبان أمير آخور أحد مقدَّمي الألوف، وقبض على من خالفه من أمراء صفد وأعيانها، ففي الحال كتب السلطان الملك الأشرف للأمير مقبل الحسامي الدوادار حاجب حجاب دمشق باستقراره في نيابة صفد، وأن يستمِرَّ إقطاع الحجوبية بيده حتى يتسلم صفد، ثم كتب إلى الأمير تنبك ميق نائب الشام أن يخرج بعسكر دمشق لقتال إينال، ثم ورد على السلطان الأشرف كتاب الأمير تنبك ميق نائب الشام بمجيء الأمير إينال الجكمي، ويشبك أنالي، وجلبان أمير آخور إليه من صفد طائعين للسلطان، وكان من خبر هؤلاء وإينال نائب صفد أنه لما قدم عليه الأمير مقبل الدوادار بعساكر دمشق انهزم إلى قلعة صفد إلى يوم الاثنين رابع شوال، فنزل إليه إينال بمن معه، بعد أن ترددت الرسل بينهم أيامًا كثيرة، فتسلم أعوان السلطان قلعةَ صفد في الحال، وعندما نزل إينال أمر الأمير مقبل أن تفاض عليه خلعة السلطان ليتوجه أميرًا بطرابلس، وكان قد وعد ذلك، لما ترددت الرسل بينهم وبينه مرارًا حتى استقرَّ الأمر على أن يكون إينال من جملة أمراء طرابلس، وكتب له السلطان أمانًا ونسخةَ يمين فانخدع الخمول ونزل من القلعة، فما هو إلا أن قام بلبس الخلعة وإذا هم أحاطوا به وقيَّدوه وعاقبوه أشد عقوبة على إظهار المال، ثم قتلوه وقتلوا معه مائة رجل ممن كان معه بالقلعة، وعلَّقوهم بأعلاها."},{"id":3323,"title":"عبث الفرنج بسواحل الإسكندرية .","date":["العام الهجري :825","الشهر القمري : شعبان","العام الميلادي :1422"],"text":"كثُرَ عَبثُ الفرنج بالسواحل، وهجم في الليل غرابان -مركبان- فيهما طائفة من الفرنج، على ميناء الإسكندرية، فوجدوا فيها مركبًا للتجار فيه بضائع بنحو مائة ألف دينار، فاقتتلوا معهم عامة الليل، فخرج الناس من المدينة، فلم يقدروا على الوصول إليهم؛ لعدم المراكب الحربية عندهم، ولا وصلت سهامهم إلى الفرنج، بل كانت تسقط في البحر، فلما طال الحرب بين الفرنج والتجار المسلمين، واحترقت مركب التجار، نجَوا في القوارب إلى البر، فأتت نار الفرنج على سائر ما في المركب من البضائع، حتى تَلِفَ بأجمعها، ومضى الفرنج نحو برقة، فأخذوا ما قدروا عليه، ثم عادوا إلى الإسكندرية، ومضَوا إلى نحو الشام."},{"id":3324,"title":"القتال بين عسكر السلطان الأشرف برسباي والأمير مقبل أمير ينبع .","date":["العام الهجري :825","الشهر القمري : ذي الحجة","العام الميلادي :1422"],"text":"في السابع والعشرين ذي الحجة نزل الحاج بينبع، وقد استعدَّ من فيهم من المماليك السلطانية مع الأمير جانبك الخازندار أحد أمراء العشرات لحرب الشريف مقبل: متولي ينبع، وقد قدم الشريف عقيل بن وبير الحسني من القاهرة بصحبتهم بعدما خُلِع عليه بها في شوال من هذه السنة، واستقرَّ أمير ينبع شريكًا لعمه مقبل، بمالٍ التزم للدولة، فلما عَلِمَ مقبل بذلك نزح عن ينبع إلى واد بالقرب منها، وكان الحاج قد دخلوا ينبع في ذي القعدة، فبعث أمراء الحاج الثلاثة، وهم افتخار الدين ياقوت أمير المحمل، وأسندمر الأسعردي من أمراء العشرات أمير الركب الأول، وجانبك أمير الركب الثاني، إلى الشريف مقبل حتى يحضر إليهم، فجرت أمور آخرها أن يستقر عقيل شريكًا له كما كان أبوه وبير، وأن يكاتب السلطان الأشرف برسباي بذلك، ومهما ورد المرسوم به اعتمده، ورحل الحاج من ينبع إلى مكة، وقد وجَّهوا نجابًا إلى السلطان الأشرف بكتبهم، وتركوا عقيلًا بينبع، فاقتتل هو وعمه، فظَفِرَ به عمُّه، وقَيَّده، وأقام بينبع حتى عاد الحاج إليها، فاستعدَّ الأمير جانبك وركب في جمع من المماليك وغيرهم ليلة الأحد الثامن والعشرين ذي الحجة، وطرقَ مقبلًا على حين غفلة، فكانت بينه وبين مقبل وقعة قتل فيها جماعة من أشراف بني حسن، وجُرِح كثير من العربان والعبيد، وانهزم مُقبِل، فمَدَّت المماليك أيديها، وانتهبت ما قدرت عليه، وسلبت النساء الشريفات ما عليهن، وساقوا خمسمائة وخمسين رجلًا، وثلاثين فرسًا، وأمتعة كثيرة، ومالًا جزيلًا، وعادوا من يومهم إلى ينبع، ومعهم عقيل قد خلصوه من الأسر ورحلوا، وقد أقام عقيل بينبع أميرًا، فلم يكن إلا ليالٍ حتى عاد مقبل، واحترب مع عقيل، فانهزم مُقبِل، وقُتِل بينهما جماعة."},{"id":3325,"title":"اعتداء ملك الحبشة على المسلمين بسبب إغلاق كنيسة القيامة .","date":["العام الهجري :826","العام الميلادي :1422"],"text":"غَضِبَ متملِّك الحبشة، وهو أبرم -ويقال إسحاق- بن داود بن سيف أركد؛ بسبب إغلاق المسلمين كنيسةَ القيامة بالقدس، وقَتَل عامة من كان في بلاده من رجال المسلمين، واسترقَّ نساءهم وأولادهم، وعذَّبهم عذابًا شديدًا، وهدم ما في مملكته من المساجد، وركِبَ إلى بلاد جبرت، فقاتلهم حتى هزمهم، وقتل عامة من كان بها، وسبى نساءهم، وهدم مساجدهم، فكانت في المسلمين ملحمة عظيمة في هذه السنة لا يُحصى فيها من قُتِلَ من المسلمين، فاشتاط غضبًا السلطانُ الأشرف برسباي الظاهري، وأراد قَتْلَ بطرك النصارى وجميعِ ما في مملكته من النصارى ثم رجع عن ذلك، ورسم في السنة التالية بفتح كنيسة القيامة."},{"id":3326,"title":"مقتل الأمير ناصر الدين محمد باك متملك بلاد قرمان .","date":["العام الهجري :826","الشهر القمري : صفر","العام الميلادي :1423"],"text":"قُتلَ الأمير ناصر الدين محمد باك بن علي بن قرمان باك متملك بلاد قرمان في صفر بحجر مدفع أصابه في حرب مع عساكر مراد بن كرشجي متملِّك بورصا."},{"id":3327,"title":"الوباء في الشام ينتشر ويحصد الآلاف من الناس .","date":["العام الهجري :826","الشهر القمري : ربيع الأول","العام الميلادي :1423"],"text":"بدأت هذه السنة والوباءُ يتزايد في الشام والموتى بالمئات، وبدأ يتزايد شيئًا فشيئًا، ثم في شهر رجب تناقص الوباء ببلاد الشام، بعدما عم كورة دمشق وفلسطين والساحل، وبلغت عدة من مات بصالحية دمشق زيادة على خمسة عشر ألف إنسان، وأُحصي من ورد ديوان دمشق من الموتى فكانوا نحو الثمانين ألفًا، وكان يموت من غزة في كل يوم مائة إنسان وأزيد، وكان معظم من مات الصغار والخدم والنساء، فخلت الدور منهم إلا قليلًا، وفي رجب وقع الوباء ببلاد الخليل عليه السلام، ثم وقع بدمياط."},{"id":3328,"title":"قدوم جراد عظيم إلى المدينة النبوية أتلف عامة زروعها وأشجارها .","date":["العام الهجري :826","الشهر القمري : ربيع الأول","العام الميلادي :1423"],"text":"قدم إلى المدينة النبوية جرادٌ عظيم أتلف عامَّةَ زروعها وأشجارها، حتى أكل الأسابيطَ -العذوق- من فوق النخل، فأمحلت ونزح كثيرٌ من أهلها، فمات معظم الفقراء النازحين جوعًا وعَطشًا."},{"id":3329,"title":"خراب في مدينة الكرك وقراها .","date":["العام الهجري :826","الشهر القمري : ربيع الآخر","العام الميلادي :1423"],"text":"في شَهرِ ربيع الآخر من هذا العام تلاشى أمر مدينة الكرك وخربت قراها, وتشتَّت أهلها، وآلت إلى الدُّثور."},{"id":3330,"title":"وفاة الحافظ الإمام قاضي القضاة أبي زرعة العراقي .","date":["العام الهجري :826","الشهر القمري : شعبان","العام الميلادي :1423"],"text":"هو الحافِظُ الإمام قاضي قضاة الديار المصرية، الإمام الحافظ، وأستاذ المحدِّثين، ولي الدين أبو زُرعة أحمد ابن الحافظ الكبير الشيخ زين الدين عبد الرحيم بن الحسين بن عبد الرحمن بن إبراهيم بن أبي بكر بن إبراهيم المعروف بابن العراقي الشافعي، كردي الأصل قاهري الولادة والنشأة والوفاة، وُلِدَ في ذي القعدة سنة 762، اعتنى به والده مبكرًا في صِغَرِه، فرحل به إلى الشام سنة خمس وستين، فأدرك جماعة من مُسنِدِي دمشق, ثم رجع به فحفظ القرآن وعدة مختصرات في الفنون, ونشأ يقِظًا وأسمعه أبوه الكثير ثم طلب هو بنفسِه، فسمع الكثير بقراءته وقراءة غيره, ثم رحل بنفسه إلى الشام ثانية، فسمع الكثير بقراءته وقراءة غيره, ومهر في عدة فنون واشتغل فيها وهو شاب، ونشأ على طريقة حسنة من الصيانة، والديانة والأمانة والعفَّة، مع طلاقة الوجه وحسن الصورة، وطيب النغمة، وضيق الحال، وكثرةِ العيال، إلى أن اشتهَرَ أمره، وطار ذِكرُه. ولما مات والِدُه تقرر في مناصبه الجليلة، فزادت رياسته. برع في علم الحديث، ثم غلب عليه الفقه فبرع فيه أيضًا، وأفتى ودرس سنين في عدة أماكن منذ حياة والده ومشايخه، وتولى نيابة الحكم بالقاهرة، ثم تنزه عن ذلك ولَزِمَ داره مدة طويلة، إلى أن استقدَمَه الملك الظاهر ططر بعد وفاة جلال الدين البلقيني، وخلع عليه وأقره قاضيَ قضاة الديار المصرية في قضاء الشافعية. فباشره بعفة ونزاهة، وشهامة ومعرفة، وصار يصمِّمُ في أمور لا يحتملها أهلُ الدولة, فتمالؤوا عليه ثم صُرِفَ بقاضي القضاة علم الدين صالح البلقيني، فلزم داره, فحصل له بذلك قهر أداه إلى التلف، ومات مبطونًا شهيدًا في يوم الخميس السابع عشر شعبان عن خمس وستين سنة، ودفن إلى جانب والده، وكثر الأسفُ عليه خصوصًا من طلبة العلم. ولم يخلفْ بعده مثلُه في جمعِه بين الفقه والحديث والدين والصلاح، وله مصنفاتٌ كثيرة، منها: تحفة التحصيل بذكر رواة المراسيل، والبيان والتوضيح لمن أُخرج له في الصحيح وقد مُسَّ بضربٍ من التجريح، وشارك والده في طرح التثريب شرح تقريب الأسانيد، وله الأطراف في أوهام الأطراف، وله المستفاد من مبهمات المتن والإسناد، وشرح الصدر بذكر ليلة القدر، وغيرها من المؤلفات. قال ابن حجر: \"صَنَّف أبو زُرعة في الفنون الحديثة عدة تصانيف، وأكمل شرح تقريب الأسانيد لأبيه فأجاد فيه. وشرع في شرح مُطَوَّل لسنن أبي داود، لو كمل كان قدر ثلاثين مجلَّدة بل يزيد. وجمع النكت على المختصرات الثلاثة: التنبيه، والحاوي، والمنهاج. فزاد فيها على من تقدَّمه ممن عمل تصحيح التنبيه، وكذا المنهاج، وكذا الحاوي؛ فإنه جمع بين تصانيفهم وبين ما استفاده من حاشية الروضة لشيخنا البلقيني الكبير. وكان قد جرَّدها فجاءت في مجلدين. وجردها قبله الشيخ بدر الدين الزركشي، وقد ملكتُها بخطِّه، لكن كان قبل أن يجرِّدَها أبو زرعة بعشرين سنة. فزادت في تلك المدة فوائد جمة. واختصر المهمات للإسنوي، وضم إليه فوائد وزوائد من الحاشية المذكورة. وعُقِد مجلس الإملاء بعد أن كان انقطع بموت شيخِنا والده من سنة 806 إلى أن شرع هو فيه في سنة عشر. ولم يزل يملي في كل يوم ثلاثاء، إلى أن مرض المرض الذي توفي فيه، مع ما كان فيه من شغل البال بالدرس والحكم وغير ذلك\"."},{"id":3331,"title":"وباء بمكة  .","date":["العام الهجري :826","الشهر القمري : ذي الحجة","العام الميلادي :1423"],"text":"ابتدأ وباء بمكة من نصف ذي الحجة واستمر إلى آخر شهر ربيع الآخر من هذه السنة، فمات بها نحو ثلاثة آلاف نفس، وأنه كان يموت في اليوم خمسون إنسانًا عدة أيام، وأن الوباء تناقص من أوائل جمادى الأولى."},{"id":3332,"title":"خروج الأمير تنبك البجاسي نائب دمشق عن الطاعة وقتله .","date":["العام الهجري :827","الشهر القمري : صفر","العام الميلادي :1424"],"text":"في رابع عشر شهر صفر قدم الخبر بخروج تنبك البجاسي عن الطاعة ومحاربته أمراء دمشق، وسبب ذلك أنه لما ولي سودن بن عبد الرحمن نيابة الشام عوضا عن تنبك، تقدمت الملطفات السلطانية إلى أمراء دمشق، بالقبض على تنبك البجاسي، فأتوا دار السعادة في ليلة الجمعة رابِعَه، واستدعوه ليقرأ عليه كتاب السلطان، فارتاب من ذلك، وخرج من باب السِّرِّ، وقد لبس السلاحَ في جمع من مماليكه، فثار إليه الأمراءُ واقتتلوا معه حتى مضى صدر نهار الجمعة، فانهزموا منه، وتحصن طائفة منهم بالقلعة، ومضى آخرون إلى سودن بن عبد الرحمن، وقد نزل على صفد، ثم خرج تنبك البجاسي من دمشق بعد محاربته الأمراء حتى نزل على الجسر في يوم الجمعة الحادي عشر، وقد قطع سودن بن عبد الرحمن الجسرَ، فباتوا يتحارسون، وأصبحوا يوم السبت الثاني عشر يترامَون نهارهم كلَّه حتى حجز الليلُ بينهم، فباتوا ليلةَ الأحد على تعبيتهم، وأصبح تنبك يوم الأحد الثالث عشر راحلًا إلى جهة الصبيبة، في انتظار ابن بشارة أن يأتيه تقويةً له، فكتب سودن بذلك إلى السلطان، وركب بمن معه على جرائد الخيل، وترك الأثقال في مواضعها مع نائب القدس، وساق حتى دخل دمشق في يوم الأربعاء السادس عشر، فتمكن من القلعة، فللحال أدركهم تنبك وقد بلغه مسيرهم، فلقوه عند باب الجابية وقاتلوه، فثبت لهم مع كثرتهم، وقاتلهم أشد قتال، والرمي ينزل عليه من القلعة، فتقنطر عن فرسه لضربةٍ أصابت كَتِفَه حتى خلعته، فتكاثروا عليه وجروه إلى القلعة ومعه نحو عشرين من أصحابه، وكُتِبَ بذلك للسلطان، فقَدِمَ الكتاب الأول من جسر يعقوب في يوم الأحد عشرين، فاضطرب الناس، ووقع الشروع في السفر، وأُحضِرَت خيول كثيرة من مرابطها بالربيع، فقدم الخبر الثاني بأخذ تنبك البجاسي بدمشق، فدُقَّت البشائر، وكُتِبَ بقتله وحَمْل رأسه إلي مصر، وتتبُّع من كان معه، وبطلت حركةُ السَّفَرِ."},{"id":3333,"title":"سيل بمكة يصل إلى الكعبة .","date":["العام الهجري :827","الشهر القمري : جمادى الأولى","العام الميلادي :1424"],"text":"في ثالث جمادى الأولى جاء سيل عظيم حتى صار المسجد الحرام بحرًا، ووصل الماء إلى قريب من الحجر الأسود، وصار في المسجد أوساخ وخِرَق كثيرة جاء بها السيل، وأنَّ الخطبة أعيدت بمكة لصاحب اليمن في سابع جمادى الأولى بعدما تُرِك اسمه والدعاء له من أيام الموسِم."},{"id":3334,"title":"استيلاء الحفصيين على تلمسان ونهاية دولة بني عبد الواد بها .","date":["العام الهجري :827","الشهر القمري : جمادى الآخرة","العام الميلادي :1424"],"text":"جهَّز أبو فارس عبد العزيز بن أبي العباس أحمد صاحب تونس وبلاد إفريقية وملك الحفصيين ابنَه المعتمد أبا عبد الله محمدًا، من بجاية في عسكر إلى مدينة تلمسان، فحارب مَلِكَها أبا عبد الله عبد الواحد بن أبي محمد عبد الله بن أبي حمو موسى ملك بني زيان حروبًا كثيرة، حتى ملكها في جمادى الآخرة، وخطب لنفسه ولأبيه، فزالت دولة بني عبد الواد من تلمسان بعدما ملكت مائة وثمانين سنة، وولَّى على تلمسان الأمير الزياني محمد بن أبي تاشفين عبد الرحمن الثاني."},{"id":3335,"title":"وفاة العلامة البزازي .","date":["العام الهجري :827","الشهر القمري : رمضان","العام الميلادي :1424"],"text":"هو العلامة البحر الزاخر المولى حافظ الدين محمد بن محمد بن شهاب بن يوسف الكردي البريقيني الخوارزمي الحنفي الشهير بالبزازي، برع في الأصول حتى ذاع صيته في البلاد، اشتهر بفتاويه وخاصة فتواه بتكفير تيمورلنك، وتُعرَف بالفتاوى البزازية، وله مصنفات؛ منها: مناقب الإمام الأعظم  أبي حنيفة، ومناسك الحج، وآداب القضاة، وتعريفات الأحكام، وغيرها من الكتب. قال عصام الدين طاشْكُبْري زادَهْ: \"له كتاب في مناقب الإمام الأعظم أبي حنيفة رضي الله عنه، وهو كتاب نافع في الغاية، مشتمل على المطالب العالية، طالعته من أوله إلى آخره واستفدت منه، ولما دخل بلاد الروم باحَثَ مع المولى الفناري وغلب هو عليه في الفروع، وغلب ذلك عليه في الأصول وسائر العلوم\"."},{"id":3336,"title":"أحوال الشام ومصر الاقتصادية  .","date":["العام الهجري :828","العام الميلادي :1424"],"text":"كانت أسواق القاهرة ومصر ودمشق في كساد، وظلمُ ولاة الأمر من الكشاف والولاة فاشٍ. ونواب القضاة قد شنعت قالة العامة فيهم من تهافتهم، وأرض مصر أكثرها بغير زراعة؛ لقصور مد النيل في أوانه، وقلة العناية بعمل الجسور؛ فإن كشَّافها إنما دأبهم إذا خرجوا لعملها أن يجمعوا مال النواحي لأنفسهم وأعوانهم، والطرقات بمصر والشام مخوفة من كثرة عبث العربان والعشير، والناس على اختلاف طبقاتهم قد غلب عليهم الفقر، واستولى عليهم الشح والطمع فلا تكاد تجد إلا شاكيًا مهتمًّا لدنياه، وأصبح الدِّين غريبًا لا ناصر له، وسعر القمح بمائتي درهم الأردب، والشعير بمائة وعشرة، والفول بنحو ذلك، ولحم الضأن السليخ كل رطل بسبعة دراهم ونصف، ولحم البقر كل رطل بخمسة دراهم، والفلوس كل رطل بتسعة دراهم، وهي النقد الذي يُنسَب إليه ثمن ما يباع وقيمة ما يُعمل. والفضة كل درهم وزنًا بعشرين درهمًا من الفلوس، والذهب الإفرنجي المشخَّص بمائتي وخمسة وعشرين درهمًا!"},{"id":3337,"title":"الشروع في عمل مراكب حربية لغزو بلاد الفرنج .","date":["العام الهجري :828","الشهر القمري : محرم","العام الميلادي :1424"],"text":"في شهر محرم من هذا العام وقع الشروعُ في عمل مراكب حربية؛ لغزو بلاد الفرنج."},{"id":3338,"title":"أحوال دولة الترك المماليك مع مطلع هذا العام .","date":["العام الهجري :828","الشهر القمري : محرم","العام الميلادي :1424"],"text":"أهلَّت هذه السنة وخليفةُ الوقت المعتضد بالله أبو الفتح داود بن المتوكل على الله أبي عبد الله محمد، وليس له من الخلافة إلا مجرد الاسم بلا زيادة. وسلطانُ مصر والشام والحجاز الملِكُ الأشرف برسباي الدقماقي، والأمير الكبير الأتابك قجق، والدوادار الكبير صاحب الأمر والنهي في الدوادارية بل في سائر أمور الدولة, وأمير سلاح أينال النوروزي، وأمير مجلس أينال الجكمي، وأمير أخور جقمق، ورأس نوبة تغري بردي المحمودي، وحاجب الحجاب جرباش قاشق، وأستادار صلاح الدين محمد بن الصاحب بدر الدين حسن بن نصر الله، وناظر الخاص الصاحب بدر الدين حسن بن نصر الله، والوزير الصاحب كريم الدين عبد الكريم ابن الوزير تاج الدين عبد الرزاق ابن كاتب المناخ، وكاتب السر نجم الدين عمر بن حجي الدمشقي، وناظر الجيش زين الدين عبد الباسط بن خليل، وليس لأحد في الدولة تصرُّف غير السلطان برسباي والأمير جانبك الدوادار، والقضاة: الشافعي: شمس الدين محمد الهروي. والقاضي الحنفي: زين الدين عبد الرحمن التفهني، وقاضي القضاة المالكي: شمس الدين محمد البساطي، والقاضي الحنبلي: علاء الدين علي بن مغلي، ونائب الشام سودن بن عبد الرحمن، ونائب حلب شار قطلوا، ونائب حماة جلبان أمير أخور، ونائب طرابلس قصروه، ونائب صفد مقبل الدوادار، ونائب الإسكندرية أقبغا التمرازي، وبمكة الشريف علي بن عنان والأمير قرقماس."},{"id":3339,"title":"تغيير أمير مكة ومشاركة الأمير قرقماس في إمارة مكة .","date":["العام الهجري :828","الشهر القمري : ربيع الأول","العام الميلادي :1425"],"text":"في سنة 827 تأخر الأمير قرقماس الدوادار في ينبع، وطلب عسكرًا ليقاتِلَ به الشريف حسن بن عجلان، ويستقر عِوَضَه في إمارة مكة، فأُجيب إلى ذلك، ثم خَلَع على الشريف علي بن عنان بن مغامس، واستقر في إمارة مكة شريكًا للأمير قرقماس، ثم قَدِمَ الخبر بوصول الشريف علي بن عنان إلى ينبع بمن معه من المماليك المجردين، وتوجه الأمير قرقماس معه إلى مكة، فدخلوها يوم الخميس سادس جمادى الأولى بغير حرب، وأن الشريف حسن بن عجلان سار إلى حلي بني يعقوب من بلاد اليمن، ثم في الرابع والعشرين من محرم من هذه السنة قدم الرَّكبُ الأول من الحجاج إلى مصر، ثم قدم من الغد المحمَل ببقية الحاجِّ، ومعهم الشريف رميثة بن محمد بن عجلان في الحديد، وقد قبض عليه الأمير قرقماس بمكة، ثم في شهر جمادى الآخرة خرج الأمير قرقماس من مكة بمن معه في طلب الشريف حسن بن عجلان حتى بلغ حلي من أطراف اليمن، فلم يقابله ابن عجلان مع قوته وكثرة من معه، بل تركه وتوجَّه نحو نجد تنزُّهًا عن الشر، وكراهة الفتنة، فعاد قرقماس وقدم مكة في العشرين منه، ثم في شهر ذي الحجة قدم كتاب الأمير تغري بردي المحمودي من مكة وقد توجه حاجبًا يتضمن أنه بعث لَمَّا نزل من عقبة أيلة، قاصدًا إلى الشريف حسن بن عجلان يرغِّبه في الطاعة ويحذِّره عاقبة المخالفة، فقَدِمَ ابنه الشريف بركات بن حسن، وقد نزل بطن مر في الثامن والعشرين ذي القعدة، فسُرَّ بقدومه ودخل به معه مكة أول ذي الحجة، وحلف له بين الحجر الأسود والملتزم أن أباه لا يناله مكروه من قِبَلِه ولا من قِبَل السلطان، فعاد إلى أبيه، وقدم به مكة يوم الاثنين ثالث ذي الحجة، وأنه حلف له ثانيًا، وألبسه التشريف السلطاني، وقرَّره في إمارة مكة على عادته، وأنه عزم على حضوره إلى السلطان صحبة الركب، واستخلاف ولده بركات على مكة، ثم في شهر محرم من سنة 829 قدم الأمير قرقماس المقيم هذه المدة بمكة، وقدم الشريف حسن بن عجلان، فأُكرِمَ ثم خُلِعَ عليه في السابع والعشرين، واستقر في إمارة مكة على عادته، وأُلزم بثلاثين ألف دينار، فبعث قاصده إلى مكة حتى يحصرها، وأقام هو بالقاهرة رهينة، ولم يقع في الدولة الإسلامية مثلُ هذا، ثم في يوم الثلاثاء الرابع والعشرين رمضان من سنة 829 قدم الشريف بركات بن حسن بن عجلان من مكة، وقد استُدعي بعد موت أبيه فخُلِع عليه، واستقر في إمرة مكة، على أن يقوم بما تأخَّر على أبيه وهو مبلغ خمسة وعشرين ألف دينار، فإنه كان قد حمل قبل موته من الثلاثين الألف التي التزم بها مبلغ خمسة آلاف دينار، وأُلزم بركات أيضًا بحمل عشرة آلاف دينار في كل سنة، وألَّا يتعرض لما يؤخذ بجدة من عشور بضائع التجار الواصلة من الهند وغيره."},{"id":3340,"title":"قدوم طائفة من الفرنج إلى صور وهزيمتهم .","date":["العام الهجري :828","الشهر القمري : جمادى الأولى","العام الميلادي :1425"],"text":"قَدِمَت طائفة من الفرنج إلى صور من معاملة صفد، فحاربهم المسلمون، وقتلوا كثيرًا منهم، وقُتِل من المسلمين نحو الخمسين رجلًا."},{"id":3341,"title":"السلطان الأشرف برسباي يجهز جيشًا لغزو قبرص ويأسر ملكها .","date":["العام الهجري :828","الشهر القمري : جمادى الآخرة","العام الميلادي :1425"],"text":"أخذ السلطان في تجهيز الغزاة وعيَّن جماعة كبيرة من المماليك السلطانية والأمراء، وقام السلطان في الجهاد أتمَّ قيام، ثم في العشرين من هذا الشهر سارت خيول الأمراء والأعيان من المجاهدين في البر إلى طرابلس، وعِدَّتُها نحو ثلاثمائة فرس؛ لتحمل من طرابلس صحبة غزاتها في البحر، ثم في يوم الخميس تاسع شوال ورد الخبر من طرابلس بنصرة المسلمين على الفرنج، وبينما الناس مستبشرون في غاية ما يكون من السرور والفرح بنصر الله قَدِمَ الخبر في يوم الاثنين الثالث عشر شوال بوصول الغُزاة المذكورين إلى الطينة من مصر، وكان من خبرهم أنهم لما توجهوا من ساحل بولاق إلى دمياط ساروا منه في البحر المالح إلى مدينة طرابلس فطلعوا إليها، فانضم عليهم بها خلائق من المماليك والعساكر الشامية وجماعة كبيرة من المطوعة إلى أن رحلوا عن طرابلس في بضعة وأربعين مركبًا، وفي يوم الجمعة ثاني رجب سار أربعة أمراء إلى الجهاد، وهم تغري بردي المحمودي رأس نوبة، وقد جُعِل مقدَّمَ عسكر البر، والأمير أينال الجكمي أمير مجلس، وجُعِل مقدَّمَ عسكر البحر، والأمير تغري برمش، والأمير مراد خجا، وتبعهم المجاهدون، وتوجهوا في النيل أرسالًا حتى كان آخرهم سفرًا في يوم السبت الحادي عشر، ثم في شهر شعبان في خامسه قدم الخبر بأن طائفة من الغزاة لما ساروا من رشيد إلى الإسكندرية وجدوا في البحر أربع قطع بها الفرنج، وهي قاصدة نحو الثغر، فكتبوا لمن في رشيد من بقيتهم بسرعة لحاقهم، وتراموا هم والفرنج يومهم، وباتوا يتحارسون، واقتتلوا من الغد، فما هو إلا أن قَدِمَت بقية الغزاة من رشيد، فولى الفرنج الأدبار بعدما استُشهد من المسلمين عشرة. وصلت في رجب عساكر المسلمين  الماغوصة لغزو قبرص، فنزلوا عليها بأجمعهم، وخيَّموا في برها الغربي، وقد أظهر متملك الماغوصة طاعة السلطان الأشرف برسباي وعرَّفهم تهيؤَ صاحب قبرص واستعداده لقتالهم وحربهم، فاستعدوا وأخذوا حِذْرَهم وباتوا بمخيمهم على الماغوصة، وهي ليلة إحدى وعشرين من شهر رمضان، ولما أصبحوا يوم الاثنين شنُّوا الغارات على ما بغربيِّ قبرص من الضِّياع، ونهبوا وأسروا وقتلوا وأحرقوا وعادوا بغنائم كثيرة، ثم ساروا ليلة الأربعاء يريدون الملاحة، وتركوا في البر أربعمائة من الرجَّالة يسيرون بالقرب منهم إلى أن وصلوا إليها ونهبوها وأسَروا وأحرقوا أيضًا، ثم ركبوا البحر جميعًا وأصبحوا باكر النهار فوافاهم الفرنج في عشرة أغربة -نوع من المراكب- وقرقورة كبيرة، فلم يثبتوا للمسلمين وانهزموا من غير حرب، واستمر المسلمون بساحل الملاحة وقد أرست مراكبهم عليها، وبينما هم فيما هم فيه كرَّت أغربة الفرنج راجعة إليهم، وكان قصد الفرنج بعودهم أن يخرج المسلمون إليهم فيقاتلوهم في وسط البحر، فلما أرست المسلمون على ساحل الملاحة كرَّت الفرنج عليهم، فبرز إليهم المسلمون وقاتلوهم قتالًا شديدًا إلى أن هزمهم الله تعالى، وعادوا بالخِزي، وبات المسلمون ليلة الجمعة الخامس والعشرين من رمضان، فلما كان بُكرة نهار الجمعة أقبل عسكر قبرص وعليهم أخو الملك، ومشى على المسلمين، فقاتله مقدار نصف عسكر المسلمين أشد قتال حتى كسروهم، وانجَلَت المعركة عن وقوع جينوس بن جاك متمَلِّك قبرص في الأسر بأمر من عند الله يُتعَجَّبُ منه؛ لكثرة مَن معه وقوتهم، وقلَّة من لَقِيَه، ووقع في الأسر عدة من فرسانه، فأكثر المسلمون من القتل والأسر، وانهزم بقية الفرنج، ووُجد معهم طائفة من التركمان قد أمدهم بهم علي بك بن قرمان، فقُتِل كثير منهم، واجتمع عساكر البر والبحر من المسلمين في الملاحة في يوم الاثنين ثانيه، وقد تسلم ملك قبرص الأمير تغري بردي المحمودي، وكثرت الغنائم بأيدي الغُزاة، ثم ساروا من الملاحة يوم الخميس خامسه يريدون الأفقسية، مدينة الجزيرة، ودار مملكتها، فأتاهم الخبر في مسيرهم أن أربعة عشر مركبًا للفرنج قد أتت لقتالهم، منها سبعة أغربة -نوع من المراكب- وسبعة مربعة القلاع، فأقبلوا نحوها وغنموا منها مركبًا مربعًا، وقتلوا عدة كثيرة من الفرنج، وتوجه الغزاة إلى الأفقسية وهم يقتلون ويأسِرون ويغنمون، حتى دخلوها، فأخذوا قصر الملك، ونهبوا جانبًا من المدينة، وعادوا إلى الملاحة بعد إقامتهم بالأفقسية يومين وليلة، فأراحوا بالملاحة سبعة أيام، وهم يقيمون شعائر الإسلام, وكان من خبر ذلك أن الغُزاة نازلوا قلعة اللمسون حتى أخذوها عَنوةً في يوم الأربعاء السابع والعشرين شعبان، وهدموها وقتلوا كثيرًا من الفرنج وغنموا، ثم ساروا بعد إقامتهم عليها ستة أيام، في يوم الأحد أول شهر رمضان وقد صاروا فرقتين؛ فرقة في البر، وفرقة في البحر، حتى كانوا فيما بين اللمسون والملاحة، إذا هم بجينوس بن جاك متملك قبرص قد أقبل في جموعِه، فكانت بينه وبين المسلمين حرب شديدة، ثم ركبوا البحر عائدين بالأسرى والغنيمة في يوم الخميس الثاني عشر، وقد بعث أهل الماغوصة يطلبون الأمان، ثم في يوم الاثنين الثالث والعشرين رمضان قدم الخبر في النيل بأخذ جزيرة قبرص وأسْر ملكها، وفي يوم الأحد سابع شهر شوال قَدِمَ الأمير تغري بردي المحمودي والأمير أينال الجكمي -مُقَدَّمَا الغُزاة المجاهدين- بمن معهما من العسكر، وصُحبتهم جينوس بن جاك متملك قبرص، وعاد ومن أسروه وسَبَوه من الفرنج، وما غنموه، وجميعهم في مراكبهم التي غزوا قبرص فيها، فمروا على ساحل بولاق حتى نزلوا بالميدان الكبير، فكان يومًا مشهودًا، ثم طال الكلام فيما يَفدي به نفسه، وطُلِبَ منه خمسمائة ألف دينار، فتقرر الصلح على مائتي ألف دينار، يقوم منها مائة ألف دينار، فإذا عاد إلى مُلكِه بعث بمائة ألف دينار، ويقوم في كل سنة بعشرين ألف دينار، واشترط على السلطان أن يكُفَّ عنه الطائفة البندقية وطائفة الكيتلان."},{"id":3342,"title":"قتال بين الفرنج القطرانيون وبين البنادقة في ميناء الإسكندرية .","date":["العام الهجري :829","الشهر القمري : ربيع الآخر","العام الميلادي :1426"],"text":"اقتتل الفرنج القطرانيون والبنادقة في ميناء الإسكندرية، فغلب القطرانيون وأخذوا مركب البنادقة بما فيه، بعدما قُتِل بينهم جماعة، ثم أسروا طائفة من المسلمين كانوا بالميناء، ومَضَوا في البحر."},{"id":3343,"title":"نزوح بعض أهل المدينة النبوية منها بسبب إهمالها .","date":["العام الهجري :830","الشهر القمري : ربيع الآخر","العام الميلادي :1427"],"text":"في شهر ربيع الآخر قَدِمَ الخبر بتشتت أهل المدينة النبوية، وانتزاحهم عنها؛ لشدة الخوف وضياع أحوال المسجد النبوي، وقلة الاهتمام بإقامة شعائر الله فيه، منذ كانت كائنة المدينة، فرُسِم الأمير بكتمر السعدي أحد أمراء العشرات إلى المدينة فأخذ في تجهيز حالِه."},{"id":3344,"title":"خلع الملك محمد التاسع الأيسر ملك بني نصر بالأندلس .","date":["العام الهجري :830","الشهر القمري : ربيع الآخر","العام الميلادي :1427"],"text":"كان صاحب غرناطة ومالقة والمرية ورندة ووادي آش وجبل الفتح من الأندلس، وهو أبو عبد الله محمد التاسع الملقَّب بالأيسر ابن السلطان أبي الحجاج يوسف الأنصاري الخزرجي الأرجوني الشهير بابن الأحمر- قد خرج من غرناطة دار ملكه يريد النزهةَ في فحص غرناطة في نحو مائتي فارس في مستهَلِّ ربيع الآخر، وكان ابن عمه أبو عبدالله محمد الثامن بن نصر بن محمد بن يوسف محبوسًا في الحمراء، وهي قلعة غرناطة، فخرج الجواري السُّودُ إلى الحرَّاس الموكلين به، وقالوا لهم: تخلَّوا عن الدار حتى تأتيَ أم مولاي تزوره وتتفقَّد أحواله، فظنوا أن الأمر كذلك، فخلَّوا عن الدار، فخرج في الحال شابان من أولاد صنايع أبي المحبوس، وأطلقوه من قيده وأظهروه من الحبس، وأغلقوا أبواب الحمراء، وذلك كلُّه ليلًا، وضربوا الطبول والأبواق على عادتهم، فبادر الناس إليهم ليلًا، وسألوا عن الخبر، فقيل لهم من الحمراء: قد ملَّكْنا السلطان أبا عبد الله محمد بن نصر، فأقبل أهل المدينة وأهل الأرباض فبايعوه محبةً فيه وفي أبيه، وكرهًا في الأيسر، فما طلع النهار حتى استوسق له الأمر، وبلغ الخبر إلى الأيسر فلم يثبُتْ، وتوجه نحو رندة وقد فرَّ عنه مَن كان معه من جنده، حتى لم يبقَ معه منهم إلا نحو الأربعين، وخرجت الخيل من غرناطة في طلبه، فمنعه أهل رندة، وأبوا أن يسلموه، وكتبوا إلى المنتصب بغرناطة في ذلك فآل الأمر إلى أن ركب سفينة وسار في البحر، وليس معه سوى أربعة نفر، وقدم تونس متراميًا على متملِّكها أبي فارس عبد العزيز الحفصي، وبلغ ألفونسو متملك قشتالة ما تقدَّم ذكره، فجمع جنوده من الفرنج، وسار يريد غرناطة في جمع موفور، فبرز إليه القائم بغرناطة وحاربه، فنصره الله على الفرنج، وقتل منهم خلقًا كثيرًا، وغَنِمَ ما يجلُّ وصفُه!"},{"id":3345,"title":"وفاة الملك المنصور عبد الله ابن رسول ملك اليمن وتولي أخيه .","date":["العام الهجري :830","الشهر القمري : جمادى الأولى","العام الميلادي :1427"],"text":"هو الملك المنصور عبد الله بن الناصر أحمد بن الأشرف إسماعيل بن الأفضل عباس بن المجاهد علي بن المؤيد داود بن المظفر يحيى بن المنصور عمر بن علي بن رسول متملك اليمن, وهو تاسع حكَّام دولة بني رسول باليمن، وحكم سنة واحدة فقط من 829 إلى 830. توفِّي في جمادى الأولى، وأُقيم مِن بَعدِه أخوه الأشرف إسماعيل."},{"id":3346,"title":"سلطان العثمانيين مراد الثاني يحارب الروم النصارى .","date":["العام الهجري :830","الشهر القمري : شوال","العام الميلادي :1427"],"text":"في شهر شوال قدم الخبر بأن السلطان العثماني مراد الثاني بن محمد بن بايزيد الأول، صاحب بورصا من بلاد الروم، جمع قواتِه بقيادة علي بك أحد أمرائه لمحاربة الأنكرس -من طوائف الروم المتنصرة- فهُزم فيها علي بك، واستُشهِدَ جمع وافر من عسكرِه."},{"id":3347,"title":"خلع أمير المدينة الشريف خشرم بن دوغان وتولية الشريف مانع .","date":["العام الهجري :830","الشهر القمري : ذي الحجة","العام الميلادي :1427"],"text":"في الرابع والعشرين ذي الحجة قُبض بالمدينة النبوية على أميرها الشريف خشرم بن دوغان بن جعفر بن هبة الله بن جماز بن منصور بن جماز بن شيحة؛ لأنه لم يقم بالمبلغ الذي وعد به، وقُرِّر عِوَضًا عنه الشريف مانع بن علي بن عطية بن منصور بن جماز بن شيحة بن هاشم بن قاسم بن مهنا بن حسين بن مهنا بن داود بن قاسم بن عبد الله بن طاهر بن يحيى بن الحسين بن جعفر بن الحسين بن علي بن الحسين بن علي بن أبي طالب."},{"id":3348,"title":"السلطان الأشرف برسباي يصدر مرسومًا خاصًّا بالحرم المكي .","date":["العام الهجري :830","الشهر القمري : ذي الحجة","العام الميلادي :1427"],"text":"قُرئ مرسوم السلطان الأشرف برسباي بمكة المشرفة في الملأ بمنْعِ الباعة من بَسطِ البضائع أيام الموسم في المسجد الحرام، ومِن ضَرْبِ الناسِ الخيامَ بالمسجد الحرام على مصاطبه وأمامها، ومن تحويل المنبر في يوم الجمعة والعيدين من مكانه إلى جانب الكعبة حتى يُسنَدَ إليها، فأُمِرَ أن يُتركَ مكانَه مُسامتًا لمقام إبراهيم الخليل عليه السلام، ويَخطُبَ الخطيب عليه هناك، وأمر أن تُسَدَّ أبواب المسجد بعد انقضاء الموسم إلا أربعة أبواب، من كل جهة باب واحد، وأن تُسَدَّ الأبواب الشارعة من البيوت إلى سطح المسجد، فامتُثِلَ جميع ذلك؛ أما منع الباعة بالحرم فكان من أكبر المصالح والمعروف؛ فإنه كان يقوم الشخص في طوافه وعبادته وأُذنُه ملأى من صياح الباعة والغوغاء من كثرة ازدحام الشراة، وأما نَصبُ الخيام فكان من أكبر القبائحِ، فإنه قيل: إن بعض الناس كان إذا نصب خيامَه بالمسجد الحرام نصب به أيضًا بيت الراحة وحفر له حُفرةً بالحرم، وفي هذا كفاية! وأما تحويل المنبر فإنه قيل للسلطان إن المنبر في غاية ما يكون من الثِّقلِ، وأنه كلما أُلصق بالبيت الشريف انزعج منه وتصدع، فمُنِعَ بسبب ذلك."},{"id":3349,"title":"ارتفاع أسعار الغلال لقلة المطر وهبوب الرياح وأمراض بالشام .","date":["العام الهجري :831","الشهر القمري : ربيع الأول","العام الميلادي :1428"],"text":"في آخر هذا الشهر ارتفعت أسعار الغلال، وسببه خِسَّة الزرع بالجيزية والوجه البحري؛ لعدم المطر، وتوالي هبوب الرياح المريسية زيادة على ثلاثين يومًا، فلم تَسِرْ فيها المراكب. وأهلَّ شهر ربيع الآخر والناس على تخوُّف من سوء حال الزرع، وانكشاف ساحل النيل من الغلال وقلة وجود القمح, وبعد أيام قَدِمَت الأخبار بكثرة أمراض أهل الشام، وكثرة موت الخيول بدمشق وحماة!"},{"id":3350,"title":"خلع الملك الأشرف إسماعيل ملك اليمن وتولي عمه الظاهر يحيى .","date":["العام الهجري :831","الشهر القمري : جمادى الأولى","العام الميلادي :1428"],"text":"في شهر جمادى الأولى كانت الفتنة الكبيرة بمدينة تعز من بلاد اليمن؛ وذلك أن الملك المنصور عبد الله بن أحمد لما توفي في جمادى الأولى السنة الفائتة، أقيم بعده أخوه الملك الأشرف إسماعيل بن أحمد الناصر بن الملك الأشرف إسماعيل بن عباس، فتغيَّرت عليه نيات الجند كافةً؛ من أجل وزيره شرف الدين إسماعيل بن عبد الله بن عبد الرحمن بن عمر العلوي، نسبةً إلى علي بن بولان العكي؛ فإنه أخَّر صرف جوامكهم -مخصَّصاتهم- ومرتَّباتهم، واشتد عليهم، وعنف بهم، فنفرت منه القلوب، وكثُرت حُسَّاده؛ لاستبداده على السلطان، وانفراده بالتصرف دونه، وكان يليه في الرتبة الأمير شمس الدين علي بن الحسام، ثم القاضي نور الدين علي المحالبي مشد -ضابط- الاستيفاء، فلما اشتد الأمر على العسكر وكثرت إهانة الوزير لهم، واطِّراحه جانبهم، ضاقت عليهم الأحوال حتى كادوا أن يموتوا جوعًا، فاتفق تجهيز خزانة من عدن، وبرز الأمر بتوجه طائفة من العبيد والأتراك لنقلِها، فسألوا أن يُنفَق فيهم أربعة دراهم لكلٍّ منهم يرتفق بها، فامتنع الوزير ابن العلوي من ذلك، وقال: ليمضوا غصبًا إن كان لهم غرضٌ في الخدمة، وحين وصول الخزانة يكون خير، وإلا ففَسَح الله لهم، فما للدهر بهم حاجة، والسلطان غني عنهم، فهيج هذا القول حفائِظَهم، وتحالف العبيد والترك على الفتك بالوزير، وإثارة فتنة، فبلغ الخبر السلطان، فأعلم الوزير، فقال: ما يسووا شيئًا، بل نشنق كل عشرة في موضع، وهم أعجَزُ من ذلك، فلما كان يوم الخميس تاسع جمادى الآخرة هذا قبيل المغرب، هجم جماعةٌ من العبيد والترك دار العدل بتعز، وافترقوا أربع فرق؛ فرقة دخلت من باب الدار، وفرقة دخلت من باب السر، وفرقة وقفت تحت الدار، وفرقة أخذت بجانب آخر، فخرج إليهم الأمير سنقر أمير جندار، فهبروه بالسيوف حتى هلك، وقتلوا معه علي المحالبي مشد المشدين، وعدة رجال، ثم طلعوا إلى الأشرف -وقد اختفى بين نسائه وتزيَّا بزيهن- فأخذوه ومضوا إلى الوزير ابن العلوي، فقال لهم: ما لكم في قتلي فائدة؟ أنا أنفق على العسكر نفقة شهرين، فمضوا إلى الأمير شمس الدين علي بن الحسام بن لاجين، فقبضوا عليه، وقد اختفى، وسجنوا الأشرف وأمَّه وحظيَّته في طبقة المماليك، ووكلوا به، وسجنوا ابن العلوي الوزير وابن الحسام قريبًا من الأشرف، ووكلوا بهما، وقد قيدوا الجميع، وصار كبير هذه الفتنة برقوق من جماعة الترك، فصعد هو في جماعة ليُخرِجَ الظاهر يحيى بن الأشرف إسماعيل بن عباس من مدينة ثعبات بتعز، فامتنع أمير البلد من الفتح ليلًا، وبعث الظاهر إلى برقوق بأن يتمهَّل إلى الصبح، فنزل برقوق ونادى في البلد بالأمان والاطمئنان والبيع والشراء، والأخذ والعطاء، وأن السلطان هو الملك الظاهر يحيى بن الأشرف، هذا وقد نهب العسكر عند دخولهم دار العدل جميعَ ما في دار السلطان، وأفحَشوا في نهبهم، فسلبوا الحريم ما عليهن، وانتهكوا ما حرَّم الله، ولم يَدَعوا في الدار ما قيمتُه الدرهم الواحد، وأخذوا حتى الحُصُر، وامتلأت الدار وقت الهجمة بالعبيد والترك والعامة، فلما أصبح يوم الجمعة عاشره اجتمع بدار العدل الترك والعبيد، وطلبوا بني زياد وبني السنبلي والخدم، وسائر أمراء الدولة والأعيان، فلما تكامل جمعهم ووقع بينهم الكلام فيمن يقيموه، قال بنو زياد: ما تمَّ غير يحيى، فاطلَعوا له هذه الساعة، فقام الأمير زين الدين جياش الكاملي والأمير برقوق، وطلعا إلى مدينة ثعبات في جماعة من الخدام والأجناد، فإذا الأبوابُ مغلقة، وصاحوا بصاحب البلد حتى فتح لهم، ودخلوا إلى القصر، فسلموا على الظاهر يحيى بالسلطنة وسألوه أن ينزل معهم إلى دار العدل، فقال: حتى يصل العسكر أجمع، ففكُّوا القيد مِن رِجلَيه، وطلبوا العسكرَ بأسرِهم، فطلعوا بأجمعهم، وأطلعوا معهم بعشرة جنائب من الإسطبل السلطاني في عدة بغال، فتقدَّم الترك والعبيد وقالوا للظاهر: لا نبايعك حتى تحلفَ لنا أنَّه لا يحدث علينا منك سوءٌ بسبب هذه الفعلة، ولا ما سبقَ قبلها،، فحلف لهم ولجميع العسكر، وهم يعيدون عليه الأيمانَ، ويتوثَّقون منه، وذلك بحضرة قاضي القضاة موفق الدين علي بن الناشري، ثم حلفوا له على ما يحبُّ ويختار، فلما انقضى الحلف، وتكامل العسكر، ركب ونزل إلى دار العدل في أهبة السلطنة، فدخلها بعد صلاة الجمعة، فكان يومًا مشهودًا، وعندما استقر بالدار أمر بإرسال ابن أخيه الأشرف إسماعيل إلى ثعبات، فطلعوا به، وقيدوه بالقيد الذي كان الظاهر يحيى مُقيَّدًا به، وسجنوه بالدار التي كان مَسجونًا بها، ثم حُمل بعد أيام إلى الدملوه، ومعه أمه وجاريته، وأنعم السلطان الملك الظاهر يحيى على أخيه الملك الأفضل عباس بما كان له، وخلع عليه وجعله نائب السلطة كما كان في أول دولة الناصر، وخمدت الفتنة، وكان الذي حرَّك هذا الأمر بني زياد، فقام أحمد بن محمد بن زياد الكاملي بأعباء هذه الفتنة، لحنقه على الوزير ابن العلوي؛ فإنه كان قد مالأ على قتل أخيه جياش، وخذل عن الأخذ بثأره وصار يمتَهِنُ بني زياد، ثم ألزم الوزير ابن العلوي وابن الحسام بحمل المال، وعُصِرا على كِعابهما وأصداغهما، ورُبطا من تحت إبطهما، وعُلِّقا منكسَينِ، وضُرِبا بالشيب والعصا، وهما يوردان المال، فأُخِذَ من ابن العلوي -ما بين نقد وعروضٍ- ثمانون ألف دينار، ومن ابن الحسام ثلاثون ألف دينار، وظهر من السلطان نبل وكرم وشهامة ومهابة، بحيث خافه العسكر بأجمعهم؛ فإن له قوة وشجاعة، حتى إن قوسه يعجز من عندهم من الترك عن جَرِّه، وبهذه الحادثة اختَلَّ مُلكُ بني رسول."},{"id":3351,"title":"مقتل الخواجا مبعوث ملك الحبشة إلى الفرنج للهجوم على الإسلام .","date":["العام الهجري :832","الشهر القمري : جمادى الأولى","العام الميلادي :1429"],"text":"عُثِر على أحد تجار العجم، وهو الخواجا نور الدين علي التبريزي العجمي المنتمي إلى الإسلام، وقد توجه من عند الحطي ملك الحبشة إلى الفرنج يحثهم على القيام معه لإزالة دين الإسلام وأهله، وإقامة الملة العيسوية؛ فإنه قد عزم على أن يسير من بلاد الحبشة في البر بعساكره، فتلاقوه بجموعهم في البحر إلى سواحل بلاد المسلمين، فسلك هذا التاجر الفاجر في مسيره من الحبشة البرية حتى صار من وراء الواحات إلى وراء المغرب، وركب منها البحر إلى بلاد الفرنج، ودعاهم للثورة مع الحطي على إزالة ملة الإسلام وأهلها، واستعمل بتلك البلاد عدة ثياب مُذَهَّبة باسم الحطي، ورَقَمَها بالصُّلبان؛ فإنه شعارهم، وقدم من بلاد الفرنج في البحر إلى الإسكندرية ومعه الثياب المذكورة وراهبان من رهبان الحبشة، فنمَّ عليه بعضُ عبيده، فأحيط بمركبه، وحُمِل هو والراهبان وجميع ما معه إلى السلطان الأشرف برسباي، ثم في الرابع والعشرين من جمادى الأولى استدعى قضاة القضاة للنظر في أمر نور الدين علي بن الخواجا، التاجر التبريزي المتوجه برسالة الحطي ملك الحبشة إلى الفرنج، فاجتمعوا بين يدي السلطان، ونُدب قاضي القضاة شمس الدين محمد البساطي المالكي للكشف عن أمره، وإمضاء حكم الله فيه فنقله من سجن السلطان إلى سجنه، فقامت عليه بيِّنةٌ بما أوجب عنده إراقة دمه، فشُهِرَ في يوم الأربعاء الخامس والعشرين على جملٍ بمصر وبولاق، ونودي عليه: هذا جزاء من يجلب السلاح إلى بلاد العدو ويلعب بالدينَينِ، ثم أُقعِدَ تحت شباك المدرسة الصالحية بين القصرين، وضُرِبَت عنُقُه، وكان يومًا مشهودًا."},{"id":3352,"title":"العسكر المصري والشامي يستولي على الرها ويخربها .","date":["العام الهجري :832","الشهر القمري : شوال","العام الميلادي :1429"],"text":"سار عسكر المماليك من القاهرة لأخذ قلعة خرت برت، وقد مات متوليها، ونازلها عسكرُ قرا يلك صاحب آمد، فلما وصلوا إلى مدينة حلب ورد إليهم الخبر بأخذ قرا يلك قلعة خرت برت وتحصينها، وتسليمها لولده، فتوجه العسكر وقد انضم إليه الأمير سودن بن عبد الرحمن نائب الشام، وجميع نواب المماليك الشامية، ومضوا بأجمعهم إلى الرها، فأتاهم بالبيرة كتابُ أهل الرها بطلب الأمان، وقد رَغِبوا في الطاعة، فأمَّنوهم وكتبوا لهم به كتابًا، وساروا من البيرة، وبين أيديهم مائتا فارس من عرب الطاعة كشَّافة، فوصلت الكشافة إلى الرها في التاسع عشر من شوال، فإذا الأمير هابيل بن قرا يلك قد وصل إليها من قِبَل أبيه الأمير عثمان بن طور علي، المعروف بقرا يلك صاحب آمد، وحَصَّنها وجمع فيها عامة أهل الضِّياع بمواشيهم وعيالهم وأموالهم، فناولوها وهم يرمونهم بالنشاب من فوق الأسوار، ثم برز إليهم الأمير هابيل في عسكر نحو ثلاثمائة فارس، وقاتلهم، وقتل منهم جماعة، وعلق رؤوسهم على قلعة الرها، فأدركهم العسكر، ونزلوا على ظاهر الرها في يوم الجمعة العشرين من شوال، وقد ركب الرجال السور ورموا بالحجارة، فتراجع العسكر المصري والشامي عنهم، ثم ركبوا بأجمعهم بعد نصف النهار وأرسلوا إلى أهل قلعة الرها بتأمينهم، وإن لم تكفُّوا عن القتال وإلا أخربنا المدينة، فجعلوا الجوابَ رميهم بالنشاب، فزحف العسكر وأخذوا المدينة في لحظة، وامتنع الأكابر وأهل القوة بالقلعة، فانتشر العسكر وأتباعهم في المدينة ينهبون ما وجدوا، ويأسِرون من ظفروا به، فما تركوا قبيحًا حتى أتوه ولا أمرًا مستشنعًا إلا فعلوه! وكان فعلهم هذا كفعل أصحاب تيمورلنك لَمَّا أخذوا بلاد الشام! وأصبحوا يوم السبت محاصرين القلعة، وبعثوا إلى من فيها بالأمان فلم يقبلوا، ورموا بالنشاب والحجارة، حتى لم يقدر أحد على أن يدنوَ منها، وباتوا ليلة الأحد في أعمال النقوب على القلعة، وقاتلوا من الغد يوم الأحد حتى اشتد الضحى، فلم يثبت من بالقلعة، وصاحوا: الأمانَ، فكفوا عن قتالهم حتى أتت رسلهم الأمير نائب الشام، وقدم مُقَدَّم العساكر، فحلف لهم -هو والأمير قصروه نائب حلب- على أنهم لا يؤذونهم ولا يقتلون أحدًا منهم، فركنوا إلى أيمانهم، ونزل الأمير هابيل بن قرا يلك ومعه تسعة من أعيان دولته عند دخول وقت الظهر من يوم الأحد، فتسلمه الأمير أركماس الدوادار، وتقدَّم نواب المماليك إلى القلعة ليتسلموها، فوجدوا المماليك السلطانية قد وقفوا على باب القلعة ليدخلوا إليها، فمنعوهم فأفحشوا في الرد على النواب، وهمُّوا بمقاتلتهم، وهجموا على القلعة، فلم تُطِقِ النواب منعهم، ورجعوا إلى مخيماتهم، فمد المماليك أيديهم ومن تبعهم من التركمان والعربان والغلمان، ونهبوا جميع ما كان بها، وأسروا النساء والصبيان، وألقوا فيها النار، فأحرقوها بعد ما أخلَوها من كل صامت وناطق، وبعد ما أسرفوا في قتل من كان بها وبالمدينة حتى تجاوزوا الحد، وخربوا المدينة، وفَجَروا بالنساء علنًا من غير خوف لا من الله ولا من الناس!! وألقوا النار فيها فاحترقت، ثم رحلوا من الغد يوم الاثنين الثالث والعشرين، وأيديهم قد امتلأت بالنهوب والسبي، فتقطعت منهم عدة نساء من التعب، فمِتنَ عطشًا، وبِيعَت منهن بحلب وغيرها عدة، وكانت هذه الكائنة من مصائب الدهر!!"},{"id":3353,"title":"الأمير محمد الزياني أمير تلمسان يخرج عن طاعة الحفصيين .","date":["العام الهجري :832","الشهر القمري : شوال","العام الميلادي :1429"],"text":"كان أمير فاس أبو فارس عبد العزيز قد عيَّن الأمير محمد بن أبي تاشفين الزياني أميرًا على تلمسان بعد أن تملَّكها من المرينيين، ثم إنَّ محمدًا الزياني رأى أن يعلِنَ استقلاله فيها، فأعلن خروجه عن طاعة السلطان الحفصي أبي فارس، الذي سار من وقته فحاصر تلمسان، فهرب منها الأمير محمد الزياني، ولكن لم يلبث أن قُبِضَ عليه واعتُقِلَ، فحمله أبو فارس معه إلى فاس وسجنه هناك حتى توفي في سجنه من السنة التالية."},{"id":3354,"title":"شاه رخ بن تيمورلنك يخرب مدينة توريز وهروب ملكها إسكندر .","date":["العام الهجري :832","الشهر القمري : ذي الحجة","العام الميلادي :1429"],"text":"عندما زحف إسكندر بن قرا يوسف قرا محمد بين بيرم خجا متملك توريز على مدينة السلطانية، وقتل متولِّيَها من جهة ملك المشرق شاه رخ بن تيمور كركان في عدة من أعيانها، ونهَب وأفسد، فسار إليه شاه رخ بن تيمور في جموع كبيرة، فخرج إسكندر بن قرا يوسف من توريز، وجمع لحربه، ولقيه وقد نزل خارج توريز، فانتدب لمحاربته الأمير قرا يلك صاحب آمد، وقد لحق بشاه رخ، وأمدَّه بعسكر كبير، وقاتله خارج توريز في يوم الجمعة سابع عشر ذي الحجة، قتالًا شديدًا، قُتِلَ فيه كثير من الفئتين، وانهزم إسكندر، وهم في إثرِه يطلبونه ثلاثة أيام، ففاتهم إدراكُه، وقد نُهِبت جقطاي عامة تلك البلاد، وقتلوا وسبوا وأسَروا وفعلوا ما يشنع ذكره، ثم إن شاه رخ ألزم أهل توريز بمال كبير اجتاح فيه أموالهم، حتى لم يَدَعْ بها ما تمتدُّ إليه العين، ثم جلاهم بأجمعهم إلى سمرقند، فما ترك إلا ضعيفًا عاجزًا لا خير فيه، ورحل بعد مدة يريد بلاده، وقد اشتدَّ الغلاء معه، فأعقب رحيلَه عن توريز جرادٌ عظيم، لم يترك بها ولا بجميع أعماله خضرًا وانتشرت الأكراد بتلك النواحي تعبث وتفسد، ففُقِدَت الأقوات، حتى بِيعَ رطل اللحم بعدة دنانير، وصار فيما بين توريز وبغداد مسافة عشرين يومًا وأزيد خرابًا يبابًا، وأما إسكندر فإنه جال في بلاد الأكراد، وقد وقعت بها الثلوج مدة، ثم صار إلى قلعة سلماس فحصره بها الأكراد، فنجا وتشتَّت في البلاد."},{"id":3355,"title":"وفاة الإمام الحافظ شمس الدين ابن الجزري .","date":["العام الهجري :833","العام الميلادي :1429"],"text":"هو الإمامُ الحافظ شمس الدين محمد بن محمد بن محمد بن علي بن يوسف الشافعي شيخ القراء، ومُقرِئ الممالك الإسلامية، الشهير بابن الجزري نسبة إلى جزيرة عُمر. ولد بدمشق ليلة السبت الخامس والعشرين من شهر رمضان سنة 751، وتفقَّه بها، ولهج بطلب الحديث والقراءات، وبرَّز فيهما، وعَمر للقراءِ مدرسةً سمَّاها: دار القرآن، وأقرأ الناس، وقدم القاهرة مرارًا، وكان حسن الشَّكلِ، ثريًّا فصيحًا بليغًا، وكان باشر عند قطلبك استادار ايتمش، فاتفق أنه نقم عليه شيئًا فتهدده، ففرَّ منه، فنزل البحر إلى بلاد الرُّوم في سنة ثمان وتسعين، فاتصل ببايزيد بن مراد الأول العثماني فعظَّمه وأخذ أهل البلاد عنه عِلمَ القراءات، وأكثروا عنه، ثم كان فيمن حضر الوقعة مع بايزيد وتيمورلنك، فلما أُسِرَ بايزيد اتصل ابن الجزري بتيمورلنك، فعظَّمه وفوَّض له قضاء شيراز فباشره مدة طويلة، وكان كثير الإحسان لأهل الحجاز، وأخذ عنه أهل تلك البلاد القراءات والحديث، ثم اتفق أنه حجَّ سنة اثنتين وعشرين فنُهِب، ففاته الحجُّ، وأقام بينبع، ثم بالمدينة المنورة، ثم بمكَّة إلى أن حجَّ ورجع إلى العراق، ثم عاد سنة ست وعشرين وحجَّ، ودخل القاهرة سنة سبع، فعظَّمه الملك الأشرف برسباي وأكرمه، وأقام بها قليلًا، ثم دخل اليمن تاجرًا فأسمع الحديث عند صاحبها ووصله، ورجع ببضاعة كثيرة، فدخل القاهرة، وأقام بها مدة إلى أن سافر على طريق الشام، ثم على طريق البصرة، إلى أن رحل إلى شيراز وفيها توفي عن 82 عامًا. قال ابن حجر: \"وقد انتهت إليه رئاسة علم القراءات في الممالك، وكان قديمًا صنَّف الحصن الحصين في الأدعية، ولهج به أهل اليمن، واستكثروا منه، وسمعوه عليَّ قبل أن يدخل هو إليهم، ثم دخل إليهم فأسمعهم، وحدَّث بالقاهرة بمُسنَد أحمد ومسند الشافعي وغير ذلك\" له مصنفات، أشهرها: النشر في القراءات العشر، والتمهيد في علم التجويد، وله منجد المقرئين، وله ملخص تاريخ الإسلام، وله الدرة المضيئة في القراءات، وله أسنى المطالب في مناقب علي بن أبي طالب، وغيرها من المصنَّفات."},{"id":3356,"title":"انتصارات مراد الثاني في استعادة المناطق التي فقدتها الدولة العثمانية .","date":["العام الهجري :833","العام الميلادي :1429"],"text":"أراد السلطان مراد الثاني بن محمد جلبي أن يعيد الإمارات في الأناضول إلى سيادة الدولة العثمانية بعد عدوان تيمورلنك على تلك المنطقة؛ ولذلك عقد هدنة مع ملك المجر لمدة خمس سنوات، كما صالح أمير القرامان، وبدأ يتجه لأوروبا مستأنفًا حركة الجهاد ومؤدبًا للأوربيين الذين أساؤوا للعثمانيين أيام المحنة التي حلَّت بهم أيام السلطان بايزيد. وفتح المجر وأخذ الجزية من أمير الصرب مع تقديم فرقة من جنود الصرب لمساعدة السلطان في حروبه، واستعاد مدينة سلانيك (سالونيك) والأفلاق وألبانيا، وعندما تجهز لحصار القسطنطينية نقض أمراءُ أوربا العهد معه، فاتجه إليهم مرة أخرى، فأدَّب ملك المجر وأمير الأفلاق وأمير الصرب، واستعاد مدينة سلانيك عام 833 من البندقية، وكان إمبراطور القسطنطينية قد تنازل عنها لهم، وقد حاصرها السلطان خمسة عشر يومًا، واعترف أمير الأفلاق بسيادة العثمانيين على بلاده عام 836."},{"id":3357,"title":"خلع الملك محمد الثامن الصغير وعودة محمد التاسع الأيسر .","date":["العام الهجري :833","العام الميلادي :1429"],"text":"قام الملك محمد الثامن الملقب بأبي عبد الله الصغير بطرد الوزير يوسف سراج الدين الذي لجأ إلى ملك قشتالة ودبَّر معه رد المُلْكِ إلى محمد التاسع الملقب بالأيسر الذي خُلِعَ سنة 831، فقام الوزير المذكور باستدعاء محمد التاسع الأيسر من تونس حيث كان لاجئًا عند ملك فاس فلبى الدعوة وعاد إلى الأندلس، فزوده ملك قشتالة بالفرسان والهدايا، فورد الخبر إلى الملك محمد الثامن أبي عبد الله الصغير الذي أرسل قواتِه لقتال الأيسر، لكن أكثر الجند مالوا وانضموا للأيسر؛ مما أتاح للأيسر الزحف على غرناطة، فاعتصم ملكها أبو عبد الله الصغير بقلعة الحمراء، ولكنَّ دخول محمد الأيسر إلى غرناطة وحفاوة كثير من الناس به ومبالغته بالحصار أتاح له القبضَ على الملك محمد الثامن أبي عبد الله الصغير، وقَتَلَه وأعاد الوزير سراج الدين للوزارة، ثم إن ملك قشتالة طلب من الملك العائد الأيسر أن يؤدي له مقابل ما قدَّمه له في سبيل عودته للملك، وفرض عليه جزيةً سنوية مقابل ذلك وأن يبقى تحت طاعته، فرفض ذلك محمد الأيسر."},{"id":3358,"title":"ملك الحفصيين يرسل جيشًا يغزو صقيلية .","date":["العام الهجري :833","الشهر القمري : محرم","العام الميلادي :1429"],"text":"في ثامن عشر محرم بعث صاحب تونس وإفريقية وتلمسان أبو فارس عبد العزيز ملك الحفصيين أسطولًا فيه مائتا فرس، وخمسة عشر ألف مقاتل من العسكرية والمطوعة؛ لأخذ جزيرة صقلية، فنازلوا مدينة مارز حتى أخذوها عنوة، ومضوا إلى مدينة مالطة، وحصروها حتى لم يبق إلا أخذها، فانهزم من جملتِهم أحد الأمراء من العلوج، فانهزم المسلمون لهزيمته، فركب الفرنج أقفيتهم، فاستُشهِد منهم في الهزيمة خمسون رجلًا من الأعيان، ثم إنهم ثبتوا وقبضوا على العلج الذي كادهم بهزيمتِه، وبعثوا به إلى أبي فارس، فأمدَّهم بجيوش كثيرة."},{"id":3359,"title":"انتشار الطاعون في مصر والشام وبلاد الروم .","date":["العام الهجري :833","الشهر القمري : ربيع الآخر","العام الميلادي :1430"],"text":"فشا الطاعون في الوجه البحري، سيما في التحريرية ودمنهور، فمات خلق كثير جدًّا بحيث أحصي من مات من أهل المحلة زيادة على خمسة آلاف إنسان، ومن ناحية بورصا زيادة على ستمائة إنسان، وكان قد وقع بغزة والقدس وصفد ودمشق في شعبان في السنة الماضية طاعون، واستمر إلى هذا الشهر، وعُدَّ هذا من النوادر؛ فإن الوقت شتاء، وما عهد فيما أدركناه وقوع الطاعون إلا في فصل الربيع! ويعلل الأطباء ذلك بسيلان الأخلاط في الربيع، وجمودها في الشتاء، ولكنَّ الله يفعل ما يريد، وقدم الخبر بشناعة الطاعون بمدينة بورصا من بلاد الروم، وأنه زاد عدد من يموت بها في كل يوم على ألفين وخمسمائة إنسان، وأما القاهرة فإنه جرى على ألسنة غالب الناس منذ أول العام أنه يقع في الناس الطاعون، حتى سُمعت الأطفال تتحدث بهذا في الطرقات، فلما أهلَّ شهر ربيع الآخر كانت عدة من ورد الديوان فيه من الأموات اثني عشر إنسانًا، وأخذ يتزايد في كل يوم حتى بلغت عدة من ورد الديوان بالقاهرة في يوم الأربعاء آخره ثمانية وأربعين إنسانًا، وجملة من أحصاه ديوان القاهرة في الشهر كله أربعمائة وسبعة وسبعون إنسانًا، وبلغ ديوان المواريث بمدينة مصر دون ذلك، هذا سوى من مات بالمارستان، ومن جُهِّز من ديوان الطرحاء على الطرقات من الفقراء، وهم كثير، قال تقي الدين المقريزي: \"وفي هذا الشهر بلغت عدة من ورد الديوان بالقاهرة مائة على أنهم لا يرفعون في أوراقهم إلى الوزير وغيره إلا بعض من يَرِدُ لا كلهم، وفيه نودي في الناس بصيام ثلاثة أيام، وأن يتوبوا إلى الله تعالى من معاصيهم، ويخرجوا من المظالم، ثم يخرجوا في يوم الأحد رابعه إلى الصحراء. هذا والحكام والولاة على ما هم عليه من المعاصي!! لا تنهَ عن خلقٍ وتأتيَ مِثلَه  عارٌ عليك إذا فعلتَ عظيمُ!  وفي يوم الأحد رابعَه خرج قاضي القضاة علم الدين صالح في جمع موفور إلى الصحراء خارج باب النصر، وجلس بجانب تربة الظاهر برقوق، فوعظ الناسَ على عادته في عمل الميعاد، فكثر ضجيج الرجال والنساء وكثُر بكاؤهم في دعائهم وتضرعهم، ثم انفضُّوا قبيل الظهر فتزايدت عدة الأموات عما كانت عليه\", وفي شهر جمادى الأولى شنع الموتان السريع بالطاعون، والنزلات التي تنحدر من الدماغ إلى الصدر، فيموت الإنسان في أقل من ساعة، بغير تقدُّم مرض، وكان أكثر في الأطفال والشباب، ثم في العبيد والإماء، وأقله في النساء والرجال، وتجاوز في مدينة مصر الفسطاط المائتين في كل يوم، سوى من لم يرد الديوان، وتجاوز في القاهرة الثلاثمائة سوى من لم يرد الديوان، وضُبِط من صُلِّيَ عليه في مصليات الجنائز فبلغت عدتهم زيادة على ما أوردوه في ديوان المواريث زيادة كثيرة، وبلغت عدة من مات بالتحريرية خاصة إلى هذا الوقت تسعة آلاف، سوى من لم يُعرف، وهم كثُرٌ جدًّا، وبلغت عدة الأموات بالإسكندرية في كل يوم نحو المائة، وشمل الوباء عامة البحيرة الغربية والقليوبية، ثم بدأ يتناقص من شهر رجب، ومات في هذا الوباء على أقل ما قيل مائة ألف إنسان، والمجازِفُ يقول المائة ألف من القاهرة فقط، سوى من مات بالوجه القبلي والوجه البحري، وهم مِثلُ ذلك! وكان هذا الطاعون أعظم من هذه الطواعين كلها وأفظعها، ولم يقع بالقاهرة ومصر بعد الطاعون العام الذي كان سنة 749 نظير هذا الطاعون، وخالف هذا الطاعون الطواعين الماضية في أمور كثيرة، منها أنه وقع في الشتاء وارتفع في فصل الربيع، وكانت الطواعين تقع في فصل الربيع وترتفع في أوائل الصيف."},{"id":3360,"title":"جفاف وخراب بالعراق .","date":["العام الهجري :833","الشهر القمري : ذي الحجة","العام الميلادي :1430"],"text":"وقع بعراقي العرب والعجم نهوب وغارات وقتال، بحيث إن شاه محمد بن قرا يوسف متملك بغداد مِن عَجزِه لا يتجاسر على أن يتجاوز سورَ بغداد، وخلا أحد جانبي بغداد من السكان، وزال عن بغداد اسم التمدُّن، ورحل عنها حتى الحيات، وجفَّ أكثر النخل من أعمالها!!"},{"id":3361,"title":"ملك قشتالة يهاجم بني نصر في غرناطة .","date":["العام الهجري :834","الشهر القمري : رمضان","العام الميلادي :1431"],"text":"جمَعَ مَلِكُ قشتالة الفونسو عساكِرَه من الفرنج، وركب البحرَ إلى قرطبة يريد أخذ غرناطة من المسلمين، فاشتدَّ البلاء عليهم؛ لقلة المال بغرناطة، وفناء عسكرها في الفتنة التي حصلت في استعادة الملك، وموت من هلك في الزلزلة أكثر من ستة آلاف إنسان، ونزل الفرنج عليهم، فلقُوهم في يوم الجمعة عاشر رمضان من هذه السنة، وقاتلوهم يومهم ومن الغد، قُتِلَ من المسلمين نحو الخمسة عشر ألفًا، وألجأهم العدو إلى دخول المدينة، وعسكر بإزائها على بريد منها، وهم نحو خمسمائة وثمانين ألفًا، وقد اشتد الطمع في أخذها، فبات المسلمون ليلة الأحد في بكاء وتضرع إلى الله، ففتح عليهم الله تعالى، وألهمهم رُشدَهم، وذلك أن الشيخ أبا زكريا يحيى بن عمر بن يحيى بن عمر بن عثمان بن عبد الحق شيخ الغزاة خرج من مدينة غرناطة في جمع ألفين من الأجناد، وعشرين ألفًا من المطوعة، وسار نصف الليل على جبل الفخار، حتى أبعد عن معسكر الفرنج إلى جهة بلادهم، ورفع أمارة في الجبال يُعلِمُ بها السلطان بغرناطة، فلما رأى تلك العلامات من الغد خرج يوم الأحد، بجميع من بقي عنده إلى الفرنج، فثاروا لحربهم، فولى السلطان بمن معه من المسلمين، كأنهم قد انهزموا، والفرنجُ تتبَعُهم، حتى قاربوا المدينة، ثم رفعوا الأعلام الإسلامية، فلما رآها الشيخ أبو زكريا نزل بمن معه إلى معسكر الفرنج، وألقى فيه النار، ووضع السيفَ فيمن هنالك، فقَتَل وأسَرَ وسبى، فلم يدع الفرنج إلا والصريخ قد جاءهم، والنار ترتفع من معسكرهم، فتركوا أهل غرناطة ورجعوا إلى معسكرهم، فركب السلطانُ بمن معه أقفيَتَهم، يقتلون ويأسرون، فبلغت عدة من قتل من الفرنج ستة وثلاثين ألفًا، ولحق باقيهم ببلادهم، بعدما كادوا أن يملكوا غرناطة، وبلغت عدةُ مَن أَسَر المسلمون من الفرنج نحو اثني عشر ألفًا، ويقول المكثِر: إنه قُتِل ومات وأُسِر من الفرنج في هذه الكائنة زيادة على ستين ألفًا."},{"id":3362,"title":"معاهدة ذل للمسلمين مع القشتاليين في الأندلس .","date":["العام الهجري :835","الشهر القمري : محرم","العام الميلادي :1431"],"text":"بعد مؤامرة خلع أبي عبد الله محمد الملقب بالأيسر حاكم غرناطة -في فترة حكمه الثانية- والتي قام بها خصومه، وتولِّي أبي الحجاج يوسف بن المول الحكم، والذي كان مائلًا إلى ملك قشتالة ليساعده على انتزاع حكم غرناطة في مقابل تعهُّده بأن يحكم غرناطة باسم ملك قشتالة وتحت طاعته، تم بعد ذلك توقيعُ معاهدة بين يوسف بن المول وخوان الثاني ملك قشتالة؛ لتحقيق هذا الهدف في 7 محرم سنة 835 (16 سبتمبر 1431م) متضمنة بنودًا مهينة للطرف المسلم، نصت على إقرار من يوسف بأنه من أتباع ملك قشتالة وخُدَّامه، وتعهَّد منه بدفع جزية سنوية قدرها عشرون ألف دينار ذهبي، وإطلاق سراح الأسرى النصارى، وأن يقدِّمَ يوسف ألفًا وخمسمائة فارس إلى ملك قشتالة لمحاربة أعدائه، سواء أكانوا من النصارى أو المسلمين. وفي مقابل هذه التنازلات يتعهد الطرف القشتالي بأن يكون الصلحُ مستمرًّا طوال حكم يوسف ومَن يخلُفُه من أبنائه، وأن يُعينَه على محاربة أعدائه من المسلمين والنصارى، وطبقًا لهذه المعاهدة وتنفيذًا لبنودها تحركت القوات القشتالية لمعاونة يوسف في حربة مع السلطان الأيسر، ونشبت بينهما معركة شديدة، انتهت بهزيمة الأيسر، ودخول يوسف غرناطة بمؤازرة النصارى القشتاليين، وجلس على عرش السلطنة في جمادى الأولى من هذه السنة، وكان أول ما فعله يوسف أن جدَّد المعاهدة مع ملك قشتالة باعتباره سلطان غرناطة، وبهذه المعاهدة قَطَعت قشتالة خطوة كبيرة في سبيل تحقيق أمنيتها، وإزالة الوجود الإسلامي من إسبانيا، وهذا ما حدث بعد سنوات قليلة!!‏"},{"id":3363,"title":"الفرنج يهاجمون جزيرة جربة ويأخذونها من الحفصيين .","date":["العام الهجري :835","الشهر القمري : ذي الحجة","العام الميلادي :1432"],"text":"نزل الطاغية النشو بن دون فرنادو بن أندريك بن جوان بن فدريك بن أندريك ملك الفرنج الكيتلان، وصاحب برشلونة، على جزيرة صقلية في شهر رمضان، وسار ومعه صاحب صقلية في نحو مائتي قطعة بحرية حتى أرسى على جربة في سابع عشر ذي الحجة وملكها، وكان ملك المغرب أبو فارس عبد العزيز غائبًا عن تونس في جهات تلمسان، فلما بلغه تَرَك معظم عسكره وسار على الصحراء حتى دنا من جربة، وكانت بينه وبين الفرنج وقعةٌ كاد يُؤخَذُ فيها، وقُتِلَ من الفريقين جماعاتٌ كثيرة."},{"id":3364,"title":"الفرنج يتخطفون سفن المسلمين التجارية في الشام ومصر .","date":["العام الهجري :836","الشهر القمري : محرم","العام الميلادي :1432"],"text":"طَرَقَ الفرنجُ ميناء طرابلس الشام في يوم السبت عاشِرَه، وأخذوا مركبًا فيه عدد كثير من المسلمين، وبضائع لها قيمة جليلة، وبينما هم في ذلك إذ قَدِمت مركب من دمياط فأخذوها أيضًا بما فيها وساروا، فلما ورد الخبر بذلك كتب بإيقاع الحوطة على أموال الفرنج الجنوية والكيتلان دون البنادقة، فأحيط بأموالهم التي بالشام والإسكندرية."},{"id":3365,"title":"السلطان الأشرف برسباي يجبر قرا يلك صاحب آمد على الصلح .","date":["العام الهجري :836","الشهر القمري : ذي القعدة","العام الميلادي :1433"],"text":"كان السلطان الأشرف برسباي قد تجهز للسفر إلى جهة آمد من هذه السنة، وسبب ذلك أن قرا يلك مَلِك آمد أظهر أولًا أنه يريد الطاعة لَمَّا كان ابنه هابيل في قبضة السلطان من أيام تملُّك الرها، ثم لما مات هابيل بالطاعون لم يعُدْ قرا يلك يُلقي بالًا للسلطان، بل عدا على ملطية وغيرها من البلاد، وأحرق وأفسد، وكان السلطان في السنوات الماضية يُشيعُ أنه يريد السفر لقتاله؛ لعل قرا يلك يُرعَب منه فيطلب الصلح، ولكنه لم يفعَلْ، فعزم في هذه السنة على السفر فسافر إلى آمد، ثم وصل كتاب السلطان من الرها، مؤرخًا بالثامن عشر ذي القعدة، يتضمَّنُ أنه رحل عن آمد بعدما أقام على حصارها خمسة وثلاثين يومًا، حتى طلب قرا يلك الصلح، فصُولحَ، ورحل العسكر في الثالث عشر ذي القعدة، وكان من خبرهم أن سار السلطان بعساكره من الرها وعليهم الأسلحة وآلة الحرب، إلى أن نزل إلى آمد في يوم الخميس ثامن شوال، وقبل نزول السلطان عليها صَفَّ عساكره عدة صفوف، ووراءهم الثقل والخدم، حتى ملؤوا الفضاء طولًا وعرضًا، وقد هال أهل آمد ما رأوه من كثرة العساكر وتلك الهيئة المزعجة؛ لكثرة ما اجتمع على السلطان من العساكر المصرية والنواب بالبلاد الشامية وأمراء التركمان والعربان، وكان قرا يلك قبل أن يخرج من مدينة آمد أمر أن يُطلَق الماءُ على أراضي آمد من خارج البلد من دجلة، ففعلوا ذلك فارتطمت خيول كثير من العسكر بالماء والطين، فلم يكترث أحد بذلك، ومشى العسكر صفًّا واحدًا، ولم يكن لآمد قلعة بل سور المدينة لا غير، إلا أنه في غاية الحسن من إحكام بنيانه؛ فلهذا يصعب حصارها ويبعد أخذها عَنوةً، فوقف العسكر حول آمد ساعة، ثم مال السلطان بفرسه إلى جهة بالقرب من مدينة آمد، ونزل به في مخيمه، وأمر الناس بالنزول في منازلهم، وأمرهم بعدم قتال أهل آمد، ونزل الجميعُ بالقرب من آمد، كالحلقة عليها، غير أنهم على بعد منها، بحيث إنه لا يلحقهم الرمي من السور، ونزل السلطان بمخيمه وقد ثبت عنده رحيل قرا يلك من آمد، وأنه ترك أحد أولاده بها، فأقام بمخيَّمه إلى صبيحة يوم السبت عاشر شوال، فركب وزحف بعساكره على مدينة آمد بعد أن كلَّمهم السلطان في تسليمها قبل ذلك، وتردَّدت الرسل بينه وبينهم، فأبى من بها من الإذعان لطاعة السلطان وتسليم المدينة إلا بإذن قرا يلك، ولما زحف السلطان على المدينة اقتحمت عساكر السلطان خندق آمد، وقاتلوا من بها قتالًا شديدًا، حتى أشرف القوم على الظفر وأخْذ المدينة، ورُدِم غالب خندق مدينة آمد بالحجارة والأخشاب، وبينما الناس في أشدِّ ما هم فيه من القتال، أخذ السلطانُ في مقت المماليك وتوبيخهم، وصار كلما جُرِحَ واحد من عساكره وأُتي له به يزدريه ويهزأُ به، وينسب القوم للتراخي في القتال، ثم لبس هو سلاحه بالكامل، وأراد أن يقتحم المدينة بنفسه حتى أعاقه عن ذلك أعيان أمرائه، وهو يتكلم بكلام معناه أن عساكره تتهاون في قتال أهل آمد، فلا زالت الأمراء به، حتى خلع عن رأسه خوذته ولبس تخفيفة على العادة، واستمرَّ القرقل عليه، إلى أن ترضَّاه الأمراء، وخلع قرقله، وسَئِمَت الناس من القتال، هذا مع ما بلغهم من غضب السلطان، بعد أن لم يُبقوا ممكِنًا في القتال، وقد أثخنت جراحات الأمراء والمماليك من عِظَم القتال، كل ذلك والسلطان ساخِطٌ عليهم بغير حق، فعند ذلك فتر عزم القوم عن القتال من يومئذ، ولما انقضى القتال وتوجه كل واحد إلى مخيمه، وهو غير راض في الباطن، وجد أهل آمد راحة كبيرة بعودة القوم عنهم، وأخذوا في تقوية أبراج المدينة وسورها، بعد أن كان أمرهم قد تلاشى؛ مما دهمهم من شدة قتال مَن لا قِبَلَ لهم بقتاله، ونزل السلطان بمخيمه، وندب الأمراء والعساكر للزحف، على هيئة ركوبهم يوم السبت، في يوم الثلاثاء، وهو أيضًا في حال غضبه، وقد اجتهد مماليك السلطان وأمراؤه في القتال، وجُرِح الغالب منهم، فكان آخر كلام السلطان للأمراء: إن العساكر تركب صحبة الأمراء في يوم الثلاثاء، وتزحف على المدينة، ويكون الذي يركب مع الأمراء للزحف المماليك القرانيص، وأنا ومماليكي الأجلاب نكون خلفهم، وقامت قيامةُ القوم، وتنكَّرت القلوب على السلطان في الباطن، وتطاولت أعناقُ أمرائه إلى الوثوب عليه، وبلغ السلطان عن الأمراء والمماليك نوع من الممالأة على الفتك به، فاضطرب أمره وصار يحاور المدينة، وهو في الحقيقة محصور من احتراسه من أمرائه ومماليكه، وأخذ في الندم على سفره، وفتر عزمه عن أخذ المدينة في الباطن، وضَعُف عن تدبير القتال، هذا والقتال مستمر في كل يوم، بل في كل ساعة، بين العسكر السلطاني وبين أهل آمد، وقُتِلَ خلائق من الطائفتين كثيرة، وصار السلطان يضايق أهل آمد بكل ما وصلت قدرتُه إليه، هذا وقد قَوِيَ أمرهم واشتد بأسهم لما بلغهم من اختلاف عساكر السلطان، وبينما السلطان فيما هو فيه قَدِمَ عليه الأمير دولات شاه الكردي صاحب أكل من ديار بكر، فأكرمه السلطان وخلع عليه، ثم لما بلغ الأشرف أحمد ابن الملك العادل سليمان صاحب حصن كيفا قدوم السلطان الملك الأشرف إلى آمد، خرج من الحصن في قليل من عسكره في أوائل ذي القعدة يريد القدوم على السلطان، فاعترضه في مسيره جماعة من أعوان قرا يلك على حين غفلة، وقاتلوه إلى أن قُتِلَ الملك الأشرف من سهم أصابه، وانهزم بقيةُ من كان معه وانتهبوا، فقدم جماعةٌ منهم على السلطان الأشرف، وعَرَّفوه بقتل الملك الأشرف صاحب الحصن، فعَظُم عليه ذلك إلى الغاية، ومن هذا اليوم أخذ السلطان في أسباب الرحيل عن آمد، غيرَ أنه صار يترقب حركة يرحل بها؛ لتكونَ لرحيله مندوحةٌ، ثم ندب السلطان جماعة كبيرة من التركمان والعربان من عسكره لتتبع قتلة الملك الأشرف صاحب الحصن، ولما ندب السلطان الجماعة المذكورة لتتبُّع قتلة الملك الأشرف وغيره، خرجوا إلى جهة من الجهات فوافوا جماعة كبيرة من أمراء قرا يلك وقاتلوهم حتى هزموهم، وأسَروا منهم جماعة كبيرة من أمراء قرا يلك وفرسانه، وأتوا بهم إلى السلطان، وهم نيِّف على عشرين نفسًا، فأمر السلطان بقيدهم فقُيِّدوا، ثم توجهوا ثانيًا فوافقوا جماعة أخرى فقاتلوهم أيضًا وأسروا منهم نحو الثلاثين، ومن جملتهم قرا محمد أحد أعيان أمراء قرا يلك، فأحضر السلطان قرا محمد وهدده بالتوسيط إن لم يُسَلِّم له آمد، فأخذوا قرا محمد ومرُّوا إلى تحت سور المدينة، فكلَّمهم قرا محمد في تسليم المدينة، فلم يلتفتوا إليه، فأخذوه وعادوا، وأصبح السلطان فوسَطَ منهم تحت سور آمد عشرين رجلًا، من جملتهم قرا محمد، ثم بلغ السلطان أن قرا يلك نزل من قلعة أرقنين بجماعة من عساكره يريد أن يكبس على السلطان في الليل، أو يتوجه بهم إلى حلب، فندب السلطانُ جماعة من الأمراء والمماليك في عمل اليزك بالنوبة، في كل ليلة لحفظ العساكر، ثم رسم السلطان للأمير جارقطلو نائب الشام بالتوجُّه لقرا يلك بقلعة أرقنين، وندب معه جماعة من النواب والأمراء والعساكر المصرية، فخرجوا من الوطاق السلطاني في الليل بجموع كثيرة، وجدُّوا في السير حتى وافوا قرا يلك وهو بمخيمه تحت قلعة أرقنين بين الظهر والعصر، وكان غالب العسكر قد تخلَّف، فتقدم بعض العسكر السلطاني من التركمان والعربان، واقتتلوا مع القرا يلكية قتالًا جيدًا إلى أن كانت الكسرة في العسكر السلطاني، وقُتِل جماعة كثيرة من التركمان والعربان وأمراء دمشق وغيرهم، كل ذلك وسنجق السلطان إلى الآن لم يَصِل، وأما جارقطلو فإنه لما قَوِيَ الحر عليه نزل على نهر بالقرب من أرقنين ليروي خيوله منه، وصار الرائد يرد عليه بأن القوم قد التقوا مع عساكر قرا يلك، وهم في قلة وقد عزموا على القتال، فلم يلتفت إلى ذلك وسار على هيئته، فتركه بعض عساكره وساروا حتى لحقوا بمن تقدَّمهم وقاتلوا القرا يلكية، ثم تراجع القومُ وكرُّوا على القرا يلكية وهزموهم أقبح هزيمة، وتعلَّق قرا يلك بقلعة أرقنين وتحصَّن بها، ونُهِبت عساكره وتمزقوا كل ممزق، هذا والسلطان مجتهد في عماره قلعة من الخشب تجاه أبراج، ومكاحل النفط ترمي في كل يوم بالمدافع، والمجانيق منصوبة يُرمى بها، وأيضًا على الأبراج، وأهل آمد في أسوأ ما يكون من الحال، هذا مع عدم التفات السلطان لحصار آمد الالتفات الكلي؛ لشغل خاطره من جهة اختلاف عساكره، وهو بتلك البلاد بين يدي عدوِّه، وقد تورط في الإقامة على حصار آمد، والشروع ملزم، وطالت إقامته على آمد بعساكره نحو خمسة وثلاثين يومًا، وقد ضاق الحالُ أيضًا على أهل آمد، فعند ذلك ترددت الرسل بين السلطان وبين قرا يلك في الصلح، وكان قرا يلك هو البادئ في ذلك، حتى تم وانتظم الصلح بينهما على أن قرا يلك يُقَبِّل الأرض للسلطان، ويَخطُب باسمه في بلاده ويَضرِبَ السكةَ على الدينار والدرهم باسمه، فأجاب إلى ذلك، فأرسل إليه السلطان القاضيَ شرف الدين الأشقر نائب كاتب السر، فتوجَّه إليه القاضي شرف الدين بالخِلَع والفرس الذي جهزه السلطان إليه بقُماش ذهب، ونحو ثلاثين قطعة من القماش السكندري، ولما بلغ قرا يلك مجيءُ القاضي شرف الدين نزل من قلعة أرقنين بمخيمه، ولقي القاضي شرف الدين وسَلَّم عليه، ثمَّ قام وقَبَّل الأرض، فألبسه القاضي شرف الدين الخِلعة، ثم قُدِّمَ له الفرس صحبة الأوجاقي، فقام إليه، فأمره القاضي شرف الدين بتقبيل حافرِ الفرس، فامتنع من ذلك قليلًا، ثم أجاب بعد أن قال: واللهِ، إن هذه عادة تعيسة، أو معنى ذلك, ثم أخذ في الكلام مع القاضي شرف الدين، فأخذ القاضي شرف الدين يعظه ويحذره مخالفة السلطان وسوء عاقبة ذلك، وعاد القاضي شرف الدين إلى السلطان، وفي الحال أخَذَ السلطان في أسباب الرحيل، ورحل في ليلة الخميس ثالث عشر ذي القعدة في النصف الثاني من الليل من غير ترتيب ولا تطليب، ولا تعبية، ورحلت العساكر من آمد كالمنهزمين، لا يلوي أحد على أحد، بل صار كل واحد يسير على رأيه، وعند رحيل القوم أطلق الغلمان النيران في الزروع المحصودة برسم عليق خيول الأجناد، فإنه كان كل جندي من الأجناد صار أمام خيمته جرن كبير مما يحصُدُه غلامه، ويأتيه به من زروع آمد، فلما انطلق النار في هذه الأجران، انطبق الوطاق بالدخان إلى الجو، حتى صار الرجل لا ينظر إلى الرجل الذي بجانبه، ورحل الناس على هذه الهيئة مسرعين، مخافة أن يسير السلطان ويتركهم غنيمةً لأهل آمد!"},{"id":3366,"title":"أصبهان بن قرا متملك بغداد يخلي بغداد والموصل من السكان .","date":["العام الهجري :837","العام الميلادي :1433"],"text":"لَمَّا أخذ أصبهان بن قرا يوسف بغدادَ من أخيه شاه محمد بن قرا يوسف أساء السيرةَ؛ بحيث إنه أخرج جميع من ببغداد من الناس بعيالهم، وأخذ كل مالهم من جليل وحقير، فتشتَّتوا بنسائهم وأولادهم في نواحي الدنيا، وصارت بغداد وليس بها سوى ألف رجل من جند أصبهان بن قرا يوسف، لا غير، وليس بها إلا ثلاثة أفران تخبز الخبز فقط، ولم يبقَ بها سكان ولا أسواق، وأنه أخرب الموصل حتى صارت يبابًا، فإنه سلب نعِمَ أهلها، وأمر بهم فأُخرجوا وتمزقوا في البلاد، واستولت عليها العربان، فصارت الموصل منازل العرب بعد التمدُّن الذي بلغ الغاية في الترف، وأنه أخذ أموال أهل المشهد، وأزال نِعَمَهم، فتشتتوا بعيالهم، وصار من أهل هذه البلاد إلى الشام ومصر خلائق لا تُعد ولا تُحصى، وكان غرض أصبهان بذلك أن يخرب بغداد، حتى لا يبقى لأخيه إسكندر ولا غيره طمعٌ فيها، فمد يده في ذلك، حتى صارت بغداد خرابًا يبابًا لا يأويها إلا البومُ!!"},{"id":3367,"title":"سيل عظيم بمكة يغرق أرض المسجد الحرام بالطين ويهدم الدور .","date":["العام الهجري :837","الشهر القمري : جمادى الأولى","العام الميلادي :1434"],"text":"في ليلة الجمعة السادس والعشرين جمادى الأولى وقع بمكة المشرفة مطر غزير، سالت منه الأودية، وحصل منه أمر مهول على مكة؛ بحيث صار الماء في المسجد الحرام مرتفعًا أربعة أذرع، فلما أصبح الناس يوم الجمعة ورأوا المسجد الحرام بحر ماء، أزالوا عتبة باب إبراهيم، حتى خرج الماء من المسفلة، وبقي بالمسجد طين في سائر أرضه قَدْر نصف ذراع في ارتفاعه، فانتدب عدة من التجار لإزالته، وتهدم في الليلة المذكورة دور كثيرة، يقول المكثِر: زيادة على ألف دار، ومات تحت الردم اثنا عشر إنسانًا، وغرق ثمانية أنفس، ودلف سقف الكعبة، فابتلَّت الكسوة التي بداخلها، وامتلأت القناديل التي بها ماء، حدث ذلك السيل بمكة وأوديتها، وبطرق اليمن."},{"id":3368,"title":"وفاة السلطان عبد العزيز ملك الحفصيين وتولي حفيده المنتصر محمد .","date":["العام الهجري :837","الشهر القمري : ذي الحجة","العام الميلادي :1434"],"text":"هو السلطانُ أبو فارس عبد العزيز بن أبي العباس أحمد بن محمد بن أبي بكر بن يحيى بن إبراهيم بن يحيى بن عبد الواحد بن عمر بن ونودين الهنتاتي الحفصي ملك المغرب. وَلِيَ الأمر بعد والده أبي العباس سنة 796, فوزع الوظائِفَ من الإمارة والوزارة وولاية الأعمال على إخوته، فاعتضد بهم، وكان من جملتهم أخوه أبو بكر بن أبي العباس بقسنطينة، فنازعه بها ابن عمه الأمير أبو عبد الله محمد بن أبي زكريا الحفصي صاحب بونة، وألح عليه في الحصار، فصمد إليه السلطان أبو فارس الحفصي، وأوقع به على سيبوس وقعة شنعاء انتهت به هزيمته إلى فاس. مات أبو فارس في رابع عشر ذي الحجة عن ست وسبعين سنة، ومدة ملكه إحدى وأربعين سنة وأربعة أشهر وأيام، بعدما خطب له بتلمسان وفاس, وقام من بعده حفيده المنتصر أبو عبد الله محمد بن الأمير أبي عبد الله محمد بن السلطان أبي فارس. والسلطان أبو فارس هذا ملك المغرب يختلف عن السلطان أبي فارس عبد العزيز بن أبي العباس أحمد المريني ملك تونس، الذي توفي سنة 798 مع تشابُهٍ في  أسمائِهما."},{"id":3369,"title":"وفاة السلطان أبو المغازي ملك كلبرجة بالهند وتولى ابنه أحمد .","date":["العام الهجري :838","العام الميلادي :1434"],"text":"هو السلطان شهاب الدين أبو المغازي أحمد شاه بن أحمد بن حسين شاه بن مهمن شاه ملك كلبرجة من بلاد الهند، وكان من خير ملوك تلك البلاد عدلًا وفضلًا وسياسة، له مآثر بمكة معروفة، أقام في الملك أربع عشر سنة، ثم قام بعده ابنه أحمد الملقَّب ظفر شاه."},{"id":3370,"title":"قتال بين الأعراب وبين الحفصيين .","date":["العام الهجري :838","الشهر القمري : محرم","العام الميلادي :1434"],"text":"قَوِيَ عرب إفريقية وحصروا مدينة تونس؛ وذلك أن المنتصر أبا عبد الله محمد بن الأمير أبي عبد الله محمد بن السلطان أبي فارس عبد العزيز، لما قام في سلطنة أفريقية بعد موت جده أبي فارس عبد العزيز بن أبي العباس أحمد، عندما كان المنتصر في سفره بنواحي تلمسان، قدم إلى مدينة تونس دار ملكه في يوم عاشوراء، وأقام بها أيامًا، ثم خرج إلى عمرة، ونزل بالدار التي بناها جده أبو فارس، وضيق على العرب ومنعهم من الدخول إلى بلاد إفريقية، وكان مريضًا، فاشتد به المرض، وفرَّ من عنده الأمير زكريا بن محمد بن السلطان أبي العباس، وأمه ابنة السلطان أبي فارس عبد العزيز بن أبي العباس، ونزل عند العرب المخالفين على المنتصر، فسار عند ذلك المنتصر من عمرة عائدًا إلى تونس، وقد تزايد مرضه، فتبعه زكريا ومعه العرب حتى نزلوا على مدينة تونس، وحصروها عدة أيام، فخرج عثمان أخو المنتصر من قسنطينة، وقدم تونس فسُرَّ به المنتصر، والفقيه أبو القاسم البرزلي مفتي البلد وخطيبها يجول في الناس بالمدينة، ويحرِّضُهم على قتال العرب، ويخرجهم فيقاتلون العرب، ويرجعون مدة أيام، إلى أن حمل العرب عليهم حملة منكرة، هزموهم، وقُتِل من الفريقين عدد كبير، كلُّ ذلك والمنتصر مُلقًى على فراشه لا يقدر أن ينهض للحرب؛ مِن شدةِ المرضِ."},{"id":3371,"title":"وقوع وباء عظيم ببلاد كرمان .","date":["العام الهجري :838","الشهر القمري : ربيع الأول","العام الميلادي :1434"],"text":"وقع وباء عظيم ببلاد كرمان، وكان ابتداؤه في مدينة هراة من بلاد خراسان في شهر ربيع الأول، وشنع واشتد، فمات فيه عالمٌ عظيم، يقول المكثر: ثمانمائة ألف!"},{"id":3372,"title":"وفاة الأمير سيف الدين طراباي نائب طرابلس .","date":["العام الهجري :838","الشهر القمري : رجب","العام الميلادي :1435"],"text":"هو الأمير سيف الدين طراباي نائب طرابلس, وهو أحد المماليك الظاهرية برقوق، وممن نبغ بعد موت برقوق واشتهر ذكره، ثم خرج عن طاعة الناصر فرج فيمن خرج وتنقَّل في أطوار من المحن إلى أن صار من أعظم الأمراء بديار مصر، ثم سُجِنَ عدة سنين بالإسكندرية في الأيام الأشرفية، ثم أُفرِجَ عنه وعمل في نيابة طرابلس، وكان عفيفًا عن القاذورات متدينًا. توفي بكرة نهار السبت رابع شهر رجب من غير وعكٍ ولا تقدُّم مرض، بل صلى الجمعة وصلى الصبحَ فمات في مُصلَّاه فجأةً."},{"id":3373,"title":"فتح عدة مدن من بلاد الحطي ملك الحبشة .","date":["العام الهجري :838","الشهر القمري : رجب","العام الميلادي :1435"],"text":"بعث الملك شهاب الدين أحمد بدلاي بن سعد الدين سلطان المسلمين بالحبشة أَخاه خير الدين لقتال أهل أمحرة الكَفَرة بالحبشة، ففتح عدة بلاد من بلاد الحطي ملك الحبشة، وقتل أميرين من أمرائه، وغنم مالًا عظيمًا، وأكثر من القتل في أمحرة النصارى، وأخرب لهم ستَّ كنائس، وكان الوباء العظيم قد شنع بعامَّة بلاد الحبشة، ومات فيه من المسلمين والكفّار عالم لا يُحصى حتى كادت أن تخلو البلاد، بل خلا الكثير منها. وكان هلك في هذا الوباء ملك الحبشة الكافر صاحب أمحرة الذي يقال له الحطي، ووقع الخلاف بعده، ثم اتفقوا على إقامة صغير، فاغتنم فخر الدين الفرصة وغزى هذه الغزوة وعاد مؤيَّدًا منصورًا ومعه من الأموال والسبايا ما لا يُحصى، ثم عاد غازيًا في شوال أيضًا."},{"id":3374,"title":"خروج عثمان قرا يلك على السلطان بمصر .","date":["العام الهجري :839","الشهر القمري : صفر","العام الميلادي :1435"],"text":"ورد الخبر باتصال جانبك الصوفي بابن قرا يلك، وأنه بمدينة كماخ، وأنَّ قرا يلك سُرَّ به وجهَّز إليه بالخيل والمال، وأمدَّه بأشياء كثيرة، فزاد انزعاج السلطان وأهل الدولة بهذا الخبر, فأرسل السلطان إسكندر بن قرا يوسف لقتال عثمان قرا يلك, فجمع عثمان عسكره ولقي إسكندر فاقتتلا، فخرج كمين لإسكندر على عثمان، فانهزم وقصد أرزن الروم والخيل في طلبه. فلما خاف عثمان أن يُؤخَذ باليد رمى نفسه في خندق المدينة فغرق، ثم أخرجه أولاده ودُفِن في مسجد هناك، وكان شاه رخ بن تيمورلنك قد بعث بولده أحمد جوكي والأمير بابا حاجي على عسكر في إثر إسكندر نجدةً لقرا يلك، فقدما بعد هزيمة عثمان وغَرَقِه, فلقي إسكندر مُقدَّمة هذا العسكر على ميافارقين، وقاتلهم وقتل منهم، ثم انهزم جوكي إلى جهة بلاد الروم, ثم قدم إسكندر يسأل عن عثمان قرا يلك فدَلَّه بعضهم على قبره، فأخرجه بعد ثلاثة أيام من دفنه وقطع رأسه وحمله إلى السلطان الأشرف برسباي بمصر، ومعه خمسة رؤوس منها رؤوس بعض أولاده!!"},{"id":3375,"title":"وفاة السلطان المنتصر محمد ملك الحفصيين وقيام أخيه عثمان .","date":["العام الهجري :839","الشهر القمري : صفر","العام الميلادي :1435"],"text":"هو السلطانُ المنتصر أبو عبد الله محمد بن أبي عبد الله محمد بن أبي فارس ملك تونس وبلاد إفريقية من الغرب، تولى الملكَ بعد وفاة جَدِّه أبي فارس عبد العزيز بن أحمد سنة 837, وقام بمملكة تونس من بعده أخوه أبو عمرو عثمان، فقَتَل عدة من أقاربه وغيرهم، وكان من خبر المنتصر مع أخيه أبي عمر: أنه لما ثقل في مرضه حتى أقعد، وصار إذا سار يركب في عمَّاريَّة نوع من المحامل تُحمَل على بغل- وتردد كثيرًا إلى قصر بخارج تونس للتنزه به، إلى أن خرج يومًا ومعه أخوه أبو عمرو عثمان صاحب قسنطينة، وقد قدم عليه وولَّاه الحكم بين الناس، ومعه أيضًا القائد محمد الهلالي، وقد رفع منه حتى صار هو وأبو عمرو عثمان مرجِعَ أمور الدولة إليهما، وحَجَباه عن كل أحد، فلما صارا معه إلى القصر المذكور تركاه به، وقد أغلقا عليه، يوهمان أنه نائم، ودخلا المدينة، وعبرا إلى القصبة، واستولى أبو عمرو على تخت الملك، ودعا الناس إلى بيعته، والهلالي قائم بين يديه، فلما ثبتت دولته قبض على الهلالي وسجَنَه، وغيَّبَه عن كل أحد، ثم التفت إلى أقاربه، فقَتَل عمَّ أبيه الأمير الفقيه الحسين بن السلطان أبي العباس، وقتل معه ابنيه وقد فرَّ بهما إلى العرب، فنزل عندهم، فاشتراه منهم بمالٍ جَمٍّ، وقتل ابني عم أبيه الأمير زكريا بن العناب ابن أبي العباس، وقتل ابني الأمير أبي العباس أحمد صاحب بجاية، فنفرت عنه قلوب الناس، وخرج عليه الأمير أبو الحسن بن السلطان بن أبي فارس عبد العزيز، متولي بجاية، وحاربه، ووقع له معه أمور كثيرة، إلى أن مات أبو عمرو، وأما المنتصر فإنه قُتِلَ بعد خلعه بمدة، وقيل: مات من شدة القهر يوم الخميس الحادي والعشرين صفر بتونس، ولم يتهنَّ في ملكه؛ لطول مرضه وكثرة الفتن."},{"id":3376,"title":"العسكر المصري يقاتل دلغار نائب أبلستين الخارج عن الطاعة  .","date":["العام الهجري :839","الشهر القمري : رمضان","العام الميلادي :1436"],"text":"توجَّه العسكر المجرَّد من مصر إلى حلب، وسار منها نائبها تغري برمش البهسني بعساكر حلب، وصحبته الأمير قاني باي الحمزاوي نائب حماة بعساكر حماة، ونزل على عينتاب؛ لقتال دلغادر نائب أبلستين, وقد نزل جانبك الصوفي مرغش، فتوجهوا إليه من الدربند, ونزلوا على بزرجق يعني سويقة باللغة العربية- ثم عدَّوا الجسر، وقصدوا ناصر الدين بك دلغادر نائب أبلستين من طريق دربند كينوك، فلم يقدروا على سلوكه؛ لكثرة الثلوج، فمضوا إلى دربند آخر من عمل بهسنا، وساروا منه بعد مشقة يريدون أبلستين وساروا حتى طرقها تغري برمش بمن معه في يوم الثلاثاء تاسع شهر رمضان، فلم يدرك ناصر الدين بن دلغادر بها، فأمر تغري برمش بنهب أبلستين وإحراقها، فنُهِبَت وأُحرقت بأجمعها، وأخذوا منها شيئًا كثيرًا، ثم عاد تغري برمش نائب حلب بمن معه والأغنام تساق بين يديه بعد أن امتلأت أيدي العساكر من النهب، وترك أبلستين خرابًا قاعًا صفصفًا، وعاد إلى حلب بعد غيبته عنها خمسين يومًا، كل ذلك وأمراء مصر بحلب."},{"id":3377,"title":"العسكر المصري يقاتل أولاد دلغار نائب أبلستين الخارج عن الطاعة .","date":["العام الهجري :839","الشهر القمري : ذي الحجة","العام الميلادي :1436"],"text":"بلغ تغري برمش البهسني نائب حلب بعد قدومه من أبلستين إلى حلب أن ناصر الدين بن دلغادر نزل بالقرب من كينوك، فجهَّز إليه أخاه حسنًا حاجب حجَّاب حلب، وحسن هو الأسنُّ، ومعه مائة وخمسون فارسًا إلى عينتاب؛ تقويةً للأمير خجا سودون، وقد نزل بها بعد أن انفرد عن العسكر المصري من يوم خرج من الديار المصرية، فتوجَّه حسن بمن معه إلى خجا سودون وأقام عنده، فلما كان يوم الرابع والعشرين ذي الحجة من سنة تسع وثلاثين وصل إليهم الأمير جانبك الصوفي، ومعه الأمير قرمش الأعور، والأمير كمشبغا المعروف بأمير عشرة أحد أمراء حلب، وكان توجَّه من حلب وانضمَّ على جانبك الصوفي قبل تاريخه بمدة طويلة، ومعه أيضًا أولاد ناصر الدين بك ابن دلغادر جميعهم ما عدا سليمان، فنزلوا على مرج دلوك، ثم ركبوا وساروا منه إلى قتال خجا سودون بعينتاب، فركب خجا سودون أيضًا بمماليكه وبمن معه من التركمان والعربان، وقاتلهم آخر النهار، وباتوا ليلتهم، وأصبحوا يوم الثلاثاء خامس عشرين ذي الحجة تقدَّم حسن حاجب الحُجَّاب بمن معه من التركمان والعربان أمام خجا سودون، فتقدم إليهم جانبك الصوفي بمن معه، وهم نحو الألفي فارس، فقاتلته العساكر المذكورة المصرية، وقد تفرقوا فرقتين: فرقة عليها خجا سودون وحسن حاجب الحجاب، وفرقة عليها الأمير تمرباي اليوسفي المؤيدي دوادار السلطان بحلب، وتركمان الطاعة في كل فرقة منهما، وتصادم الفريقان فكانت بينهم وقعة هائلة انكسر فيها جانبك الصوفي، وأمسك الأمير قرمش الأعور، والأمير كمشبغا أمير عشرة، وهما كانا جناحي مملكته، وثمانية عشر فارسًا من أصحاب جانبك الصوفي، وانهزم جانبك في أناس وتبعهم العساكر فلم يقدروا عليهم فعادوا، فأخذ خجا سودون قرمش وكمشبغا بمن معهما، وقيَّد الجميع وسيَّرهم إلى حلب، وكتب بذلك إلى السلطان، فقدم الخبر على السلطان في صفر من سنة 840، ومع المخبر رأس الأمير قرمش الأعور، ورأس الأمير كمشبغا أمير عشرة، وأنه قُتِل من قُبِض معهما بحلب، فشُهِر الرأسان بالقاهرة، ثم ألقيا في سرداب الأقذار بأمر السلطان ولم يُدفَنا."},{"id":3378,"title":"الفرنج يحاولون سرقة مراكب المسلمين في الإسكندرية .","date":["العام الهجري :840","الشهر القمري : محرم","العام الميلادي :1436"],"text":"في الحادى والعشرين محرم طرق ميناءَ بوقير خارجَ مدينة الإسكندرية ثلاثةُ أغربة -نوع من المراكب- من الفرنج الكيتلان، وأخذوا مركبين للمسلمين، فخرج إليهم أقباي اليشبكي الدوادار نائب الثغر، ورماهم حتى أخذ منهم أحد المركبين، وأحرق الفرنج المركبَ الآخر وساروا، وفي الثاني والعشرين منه بعد هذه الوقعة طرق ميناءَ الإسكندرية مركبٌ آخر للكيتلان، وكان بها مركب للجنوية، فتَحاربا، وأعان المسلمون الجنوية حتى انهزم الكيتلان."},{"id":3379,"title":"أبو الحسن عم ملك الحفصيين يحاصر قسنطينة ويحاربه الملك عثمان .","date":["العام الهجري :840","الشهر القمري : محرم","العام الميلادي :1436"],"text":"في محرم خرج من مدينة بجاية بإفريقية أبو الحسن علي ابن السلطان أبى فارس عبد العزيز ملك الحفصيين، حتى نزل على قسنطينة، وحصرها، ثم في شهر صفر سار أبو عمرو عثمان بن أبي عبد الله محمد ابن السلطان أبى فارس عبد العزيز من مدينة تونس يريد قسنطينة؛ لقتال عمه أبي الحسن علي."},{"id":3380,"title":"وفاة إمام الزيدية المنصور نجاح الدين علي صاحب صنعاء .","date":["العام الهجري :840","الشهر القمري : صفر","العام الميلادي :1436"],"text":"هو الإمامُ المنصور نجاح الدين أبو الحسن علي بن صلاح بن علي بن محمد بن علي بن أحمد بن منصور بن حجَّاج بن يوسف الحسني، الرسي المدعو بأمير المؤمنين، إمامُ الزيدية ورأسُهم. صاحبُ صنعاء باليمن، أقام في الإمامة بعد أبيه ستًّا وأربعين سنة وثلاثة أشهر، وأضاف إلى صنعاء وصعدة عدة من حصون الإسماعيلية، أخذها منهم بعد حروب وحصار. مات في سابع صفر،  فقام بعده ابنه الإمام الناصر صلاح الدين محمد بعهده إليه وبيعة الجماعة له، فمات بعد ثمانية وعشرين يومًا في الخامس والعشرين شهر ربيع الأول، فأجمع الزيدية بعده على رجل منهم يقال له صلاح بن علي بن محمد بن أبي القاسم وبايعوه، ولقَّبوه بالمهدي، وهو من بني عم الإمام المنصور، وقام بأمره قاسم ابن سنقر على أن يكون الحُكمُ له، فعارضه الإمام وصار يحكُمُ بما يؤدي إليه اجتهاده، ولا يلتفت إلى ابن سنقر، فثار عليه بعد ستة أشهر رجل يقال له محمد بن إبراهيم الساودي، وأعانه ابن سنقر، وقبضا عليه وسجناه في قصر صنعاء، ووكل به محمد بن أسد الأسدي، وقام قاسم بالأمر، فدبرت زوجةُ الإمام المهدي في خلاصِه، ودفعت إلى الأسدي الموكل به ثلاثة آلاف أوقية، فأفرج عنه، وخرج به من القصر، وسار إلى معقل يسمى ظفار، وفيه زوجة المهدي، ومضى الأسدي إلى معقل يسمى دمر، وهو من أعظم معاقل الإسماعيلية التي انتزعها الإمام المنصور علي بن صلاح، وأقام المهدي مع زوجته بظفار، ثم جمع الناس وسار إلى صنعاء، فوقع بينه وبين ابن سنقر وقعة، انكسر فيها الإمامُ وتحصَّن بقلعة يقال لها تلى، فلما بلغ ذلك زوجته ملكت صعدة، وأطاعها من بها من الناس، فاضطرب أمر ابن سنقر، وكان الناس مخالفين عليه، فأقام ولدًا صغيرًا وهو ابن بنت الإمام المنصور علي وأبوه من الأشراف الرسية، فازداد الناس نفورًا عنه وإنكارًا عليه، واستدعَوا الإمام المهدي إلى صعدة، فقدمها وبايعه الأشراف بيعة ثانية، حتى تم أمره، وبعث إلى أهل الحصون يدعوهم إلى طاعته، فأجابوه، وانفرد ابن سنقر بصنعاء وحدها على كرهٍ من أهلها، وبُغضٍ له."},{"id":3381,"title":"طاعون حاد في الشام .","date":["العام الهجري :841","الشهر القمري : محرم","العام الميلادي :1437"],"text":"كثُرَ الوباء بالطاعون بحلب وأعمالها، حتى تجاوزت عدة الأموات بمدينة حلب في اليوم مائة، وفي شهر ربيع الآخر شنع الوباء بحماة، حتى تجاوزت عدة الأموات عندهم في كل يوم ثلاثمائة إنسان، ولم يعهدوا مثل ذلك في هذه الأزمنة، وفي شهر جمادى الأولى فشا الموت في الناس بمدينة حماة وأعمالها، حتى تجاوز عدة من يموت في كل يوم مائة وخمسين إنسانًا، وفي شهر جمادى الآخرة وقع الوباء بدمشق، وفشا الموت بالطاعون الوحى، ثم كثر بدمشق، وشنع بحلب وأعمالها، فأظهر أهلها التوبة، وأغلقوا حانات الخمارين، ومنعوا البغايا الواقفات للبغاء، والشباب المُرصدين لعمل الفاحشة، بضرائِبَ تُحمَل لنائب حلب وغيره من أرباب الدولة، فتناقص الموت وخفَّ الوباء، حتى كاد يرتفع، ففرح أهل حلب بذلك، وجعلوا شكرَ هذه النعمة أن فتحوا الخمَّارات، وأوقفوا البغايا والأحداث للفساد بالضرائب المقرَّرة عليهم، ولا حول ولا قوة إلا بالله!! فأصبحوا وقد مات من الناس ثمانمائة إنسان، واستمر الوباء الشنيع، والموت الذريع فيهم، رجب، وشعبان، وما بعده! ثم شنع الوباء بدمشق في شعبان، ومات من الغرباء -الذين قَدِموا من بغداد وتبريز والحلة والمشهد وتلك الديار فرارًا من الجور والظلم الذى هنالك وسكنوا حلب وحماة ودمشق- عالمٌ عظيم لا يحصُرُهم العادُّ؛ لكثرتِهم!"},{"id":3382,"title":"وقعة بين النصارى البرتغال وبين المسلمين في مدينة سبتة .","date":["العام الهجري :841","الشهر القمري : ربيع الأول","العام الميلادي :1437"],"text":"قدم الخبرُ بأن ملك البرتغال صاحب مدينة شلب من الأندلس سار يريد مدينة طنجة، فنزل على سبتة في المحرم، ومضى منها وهى بيده في البر والبحر، ومعه فيما يقال ثمانية عشر ألف رامٍ، وستة آلاف فارس، حتى نزل على طنجة فحصرها مدة شهر إلى أن أتته جموع المسلمين من فاس ومكناسة وأصيلا في شهر ربيع الآخر، فكانت بينهم وبين البرتغال من النصارى حروب عظيمة، نصر الله فيها المسلمين، وقُتِل نحو الثلثين من النصارى، والتجأ باقيهم إلى محلتهم، فضايقهم المسلمون حتى طلبوا الأمان على أن يسلِّموا للمسلمين مدينة سبتة، ويُفرجوا عن سبعمائة أسير من المسلمين، ويدفعوا ما بأيديهم من آلات الحرب للمسلمين، فأمَّنوهم، وبعثوا برهائنهم على ذلك، فصار المسلمون يأخذون النصارى ويوصلونهم إلى أسطولهم بالبحر، فحسد أحمد اللحيانى القائم بتدبير مكناسة الأزرق، وهو أبو زكريا حي بن زيان بن عمر الوطاسي القائم بتدبير مدينة فاس، وقَتَل عدة من النصارى، ورحل، فحنق النصارى من ذلك، وحطموا على المسلمين حطمةً قُتِلَ فيها جماعة، وخلصوا إلى أسطولهم، وبقي ابن ملكهم في يد المسلمين، فلما وصلوا إلى بلادهم، لم يرضَ أكابرهم بتسليم سبتة للمسلمين، وبعثوا في فداء ابن الملك بمال، فلم يقع بينهم وبين الرسول اتفاق، وسجنوه مع ابن الملك المرتهن عند صالح بن صالح بن حمو، بطنجة، فيقول المكثر: إن الذى قُتِلَ من النصارى في هذه الواقعة خمسة وعشرون ألفًا، وغَنِمَ المسلمون منهم أموالًا كثيرة."},{"id":3383,"title":"فتنة بين العبيد وبين مماليك السلطان في مصر .","date":["العام الهجري :841","الشهر القمري : رجب","العام الميلادي :1438"],"text":"جرت في ليلة الاثنين ويوم الاثنين خامس رجب شنائع؛ وذلك أن مماليك السلطان سكان الطباق بالقلعة نشؤوا على مقت السلطان لرعيَّته، مع ما عندهم من بغض الناس، فنزل كثير منهم في أول الليل، وأخذوا في نهب الناس، وخَطْف النساء والصبيان للفساد، واجتمع عدد كثير من العبيد السود، وقاتلوا المماليك، فقُتِلَ من العبيد خمسة نفر، وجُرِح عدة من المماليك، وخُطِف من العمائم وأخذ من الأمتعة شيء كثير، فكان ذلك من أقبح ما سُمِع به، ثم أخذ المماليك في تتبع العبيد، فقتلوا منهم جماعة، ففر كثيرٌ منهم من القاهرة، واختفى كثيرٌ منهم، فلما نودي بذلك سكن ذلك الشر، وأمِنَ الناس على عبيدهم بعد خوف شديد، ثم نودي بألا يحمِلَ أحد من العبيد السلاح، ولا سيفًا ولا عَصًا، ولا يمشي بعد المغرب، وأن المماليك لا تتعرض لأحد من العبيد، ثم رُسِمَ بمنع المماليك من النزول من طباقهم بالقلعة إلى القاهرة، وذلك أنهم صاروا ينزلون طوائف طوائف إلى المواضع التي يجتمع بها العامة للنزهة، ويتفنَّنوا في العبث والفساد، من أخذ عمائم الرجال واغتصاب النساء والصبيان، وتناوُل معايش الباعة، وغير ذلك، فلم يتم منعُهم، ونزلوا على عادتهم السيئة!!"},{"id":3384,"title":"طاعون حاد في مصر .","date":["العام الهجري :841","الشهر القمري : رجب","العام الميلادي :1438"],"text":"في هذا الشهر وقع الوباء بالطاعون ببلاد الصعيد من أرض مصر، وفي شهر رمضان كانت عدة الأموات التي رُفِعت بها أوراق مُباشِري ديوان المواريث بالقاهرة ثمانية عشر إنسانًا، وتزايدت عدتُهم في كل يوم حتى فشا في الناس الموتُ بالطاعون في القاهرة ومصر، لا سيما في الأطفال والإماء والعبيد؛ فإنهم أكثر من يموت موتًا سريعًا، ثم شنعت الأخبار بكثرة من يموت، وسرعة موتهم، وشناعة الموتان أيضًا ببلاد الواحات من أرض مصر، ووقوعه قليلًا بصعيد مصر، وقد شنع الموت بالدُّور السلطانية في أولاد السلطان الذكور والإناث، وفي حظاياه وجواريه، وجواري نسائه، وفي الخدَّام الطواشية، وشنع الموت في مماليك السلطان سكان الطباق، حتى لقد مات منهم في هذا الوباء نحو آلاف، ومات من الخُدَّام الخصيان مائة وستون طواشي، ومات من الجواري بدار السلطان زيادة على مائة وستين جارية، سوى سبع عشرة حظية وسبعة عشر ولدًا، ذكورا وإناثًا، وشنع الموت أيضًا في الناس بالقاهرة ومصر وما بينهما، وفي سكان قلعة الجبل، وفي بلاد الواحات والفيوم، وبعض بلاد الصعيد، وبعض الحوف بالشرقية، ووقع الطاعون في الغنم والدواب، ووُجِد في النيل سمك كثير طافٍ قد مات من الطاعون، وأما الطاعون فإنه ابتدأ بالقاهرة من أول شهر رمضان، وكثر في شوال حتى تجاوز عدة من يُصلَّى عليه في مصلى باب النصر كل يوم أربعمائة ميت، سوى بقية المصلَّيات وعدتها بضع عشرة مُصلًّى، ومع ذلك فلم تبلغ عدة من يُرفَع في أوراق ديوان المواريث قط أربعمائة، وسببه أن الناس أعدوا توابيتَ للسبيل، ومعظم من يموت إنما هم الأطفال والإماء والعبيد، فلا يحتاج أهلُهم إلى إطلاقهم من الديوان، وفي شهر ذي الحجة والذى قبله فشا الموت بالطاعون في الإسكندرية، ودمياط، وفوه، ودمنهور، وما حول تلك الأعمال؛ فمات بها عالم كبير، وتجاوزت عدة من يموت بالإسكندرية في كل يوم مائة إنسان."},{"id":3385,"title":"هدم دير المغطس للنصارى في مصر .","date":["العام الهجري :841","الشهر القمري : شعبان","العام الميلادي :1438"],"text":"في هذا الشهر شعبان هُدِمَ للنصارى دير المغطس عند الملاحات، قريبًا من بحيرة البرلس، وكانت نصارى الإقليم قبليًّا وبحريًّا تحج إلى هذا الدير كما يحجون إلى كنيسة القيامة بالقدس، وذلك في عيده من شهر بشنس، ويسمونه عيد الظهور."},{"id":3386,"title":"وفاة السلطان الأشرف برسباي وقيام ابنه العزيز يوسف .","date":["العام الهجري :841","الشهر القمري : ذي الحجة","العام الميلادي :1438"],"text":"هو السلطانُ الملك الأشرف سيف الدين أبي النصر برسباي الدقماقي الظاهري، سلطان الديار المصرية، جركسي الأصل، اشتراه الأمير دقماق المحمدي الظاهري نائب ملطية، وأقام عنده مدة، ثم قدَّمه إلى الملك الظاهر برقوق, وهو السلطان الثاني والثلاثون من ملوك دولة الترك المماليك، والثامن من الجراكسة بالديار المصرية، وقد تولى السلطنة بمصر سنة 825 وفتح مدينة قبرص وأنشأ بمصر مدرسة وجامعًا بسرياقوس, كان سلطانًا جليلًا سياسيًّا مدبِّرًا، عاقلًا شهمًا متجمِّلًا في مماليكه وخيوله، وكانت صفتُه أشقر طوالًا نحيفًا رشيقًا منوَّر الشيبة بهيَّ الشكل، غير سبَّاب ولا فحَّاش في لفظه، حَسنَ الخُلقِ، ليِّنَ الجانب، حريصًا على إقامة ناموس الملك، يميل إلى الخير، يحب سماع تلاوة القرآن العزيز، حتى إنه رتب عدة أجواق تُقرأُ عنده في ليالي المواكب بالقصر السلطاني دوامًا. وكان يكرم أرباب الصلاح ويُجِلُّ مقامهم، وكان يكثر من الصوم صيفًا وشتاء؛ فإنه كان يصوم في الغالب يوم الثالث عشر والرابع عشر والخامس عشر من الشهر، يديم على ذلك. وكان يصوم أيضًا أول يوم في الشهر وآخر يوم فيه، مع المواظبة على صيام يومي الاثنين والخميس في الجمعة، حتى إنه كان يتوجه في أيام صومه إلى الصيد ويجلس على السماط وهو صائم، ويُطعِمُ الأمراء والخاصكية بيده، ثم يَغسِلُ يديه بعد رفع السِّماط كأنه واكل القوم. وكان عبدًا صالحًا ديِّنًا خيِّرًا لا يتعاطى المُسكِرات، ولا يحب من يفعل ذلك من مماليكه وحواشيه. وكان يحب الاستكثار من المماليك، حتى إنه زادت عدة مماليكه المشتروات على ألفي مملوك، لولا ما أفناهم طاعون سنة ثلاث وثلاثين، ثم طاعون سنة إحدى وأربعين هذا، فمات فيهما من مماليكه خلائق. وكان يميل إلى جنس الجراكسة على غيرهم في الباطن، يَظهَرُ ذلك منه في بعض الأحيان، وكان لا يحبُّ أن يشهر عنه ذلك؛ لئلا تنفر الخواطر منه؛ فإن ذلك مما يُعاب به على الملوك، وكانت مماليكه أشبه الناس بمماليك الملك الظاهر برقوق في كثرتهم، وأيضًا في تحصيل فنون الفروسية، ولو لم يكن من مماليكه إلا الأمير إينال الأبوبكري. لَمَّا تولى الأشرف برسباي نيابةَ حلب لم يقطع يدَ أحد بحلب، ولا قَتَل أحدًا، وحماها وبلادها بالحال, وفي يوم الثلاثاء رابعه عَهِدَ السلطان الأشرف برسباي إلى ولده المقام الجمالي يوسف، ثم جلس الخليفة أمير المؤمنين المعتضد بالله أبو الفتح داود، وقضاة القضاة الأربعة على مراتبهم، والأمير الكبير جقمق العلائي أتابك العساكر، ومن تأخَّر من أمراء الألوف، والمباشرون، ما عدا كاتب السر فإنه شديد المرض، ثم قام القاضي زين الدين عبد الباسط وفتح باب الكلام في عهد السلطان من بعد وفاته لابنه المقام الجمالي بالسلطنة، وقد حضر أيضًا مع أبيه، فاستحسن الخليفة ذلك وأشار به، فتقدَّم القاضي شرف الدين الأشقر بالعهد إلى بين يدي السلطان، فأشهد السلطان على نفسه بأنه عهد إلى ولده الملك العزيز جمال الدين أبي المحاسن يوسف من بعد وفاته بالسلطة، فأمضى الخليفة العهد، وشهد بذلك القضاة، ثم ظل المرض يتزايد بالسلطان إلى أن خارت قواه وأصبح يهذي أحيانًا حتى لما كان شهر ذي الحجة مات عصر يوم السبت ثالث عشر، وفي الحال حضر الخليفة والقضاة الأربعة والأمير الكبير جقمق العلائي وسائر أمراء الدولة، وسلطَنوا المقام الجمالي يوسف، ولقبوه بالملك العزيز يوسف جمال الدين أبي المحاسن وعمره يومئذ أربع عشرة سنة وسبعة أشهر، ثم أخذ الأمراء في تجهيز السلطان، فجُهِّز وغُسِّل وكُفِّن بحضرة الأمير إينال الأحمدي الفقيه الظاهري برقوق أحد أمراء العشرات بوصية السلطان له، وهو الذي أخرج عليه كلفة تجهيزه وخرجته من مال، كان الأشرف دفعه إليه في حياته، وأوصاه أن يحضر غسله وتكفينه ودفنه، ولما انتهى أمْرُ تجهيز الملك الأشرف حُمِل من الدور السلطانية إلى أن صُلِّي عليه بباب القلعة من قلعة الجبل، وتقدم للصلاة عليه قاضي القضاة شهاب الدين أحمد بن حجر، ثم حُمِل من المصلى على أعناق الخاصكية والأمراء الأصاغر، إلى أن دفن بتربته التي أنشأها بالصحراء خارج القاهرة، وكانت جنازته مشهودة بخلاف جنائز الملوك، ولم يقع في يوم موته اضطراب ولا حركة ولا فتنة، ونزل إلى قبره قُبَيل المغرب، وكانت مدة سلطنته بمصر سبع عشرة سنة تَنقُص أربعة وتسعين يومًا."},{"id":3387,"title":"حصار آقشهر وأرزكان وعودهما إلى الطاعة .","date":["العام الهجري :841","الشهر القمري : ذي الحجة","العام الميلادي :1438"],"text":"قَدِمَ الخبر بأن إسكندر بن قرا يوسف نزل قريبًا من مدينة تبريز، فبرز إليه أخوه جهان شاه، المقيم بها من قِبَل القان معين الدين شاه رخ بن تيمورلنك المغولي ملك المشرق، فكانت بينهما وقعة انهزم فيها إسكندر إلى قلعة يلنجا من عمل تبريز، فنازله جهان شاه وحصره بها، وأن الأمير حمزة بن قرا يلك متملك ماردين وأرزنكان أخرج أخاه ناصر الدين علي باك من مدينة آمد، وملكها منه، فقلق السلطان من ذلك، وعزم على أن يسافر بنفسه إلى بلاد الشام، وكتب بتجهيز الإقامات بالشام، ثم أبطل ذلك، ثم رسم بخروج تجريدة إلى بلاد الشام، وعيَّن من الأمراء المقدمين ثمانية، وكتب لنائب الشام الأمير أينال الجكمى أن يتوجه بمن معه صحبة الأمراء إلى حلب، ويستدعوا حمزة باك بن قرا يلك صاحب ماردين وأرزنكان، فإن قدم إليهم خلع عليه بنيابة السلطة فيما يليه، وإلا مشوا بأجمعهم عليه وقاتلوه وأخذوه، ثم رحل الأمراء المجرَّدون من أبلستين، ومعهم نواب الشام وعساكرها من غزة إلى الفرات، وجميع تركمان الطاعة، وتوجهوا في جمع كبير يريدون مدينة آقشهر، حتى نزلوا عليها وحصروها، وكان من خبرهم أن العسكر المجرد لما قصد مدينة آقشهر تلقَّاهم سلطان أحمد بن قليج أرسلان صاحب تلى صار وقد رغب في الطاعة السلطانية، وسار معهم حتى نازلوا مدينة أقشهر في أول ذي الحجة، فهرب متملكها حسن الأيتاقى في ليلة الثلاثاء ثانيه إلى قلعة برداش، فملك العسكر المدينة وقلعتها، وقبضوا على عدة من أعيانها، وبعثوا بسلطان أحمد بن قليج أرسلان على عسكر، فملك قلعتي فارس وتمشلي، فأقروه على نيابة السلطة بهما، وساروا لمحاصرة حسن بقلعة برداش ففر منها إلى قلعة بزطلش، فنزل من العسكر عليها حتى أخذها في الثامن عشر الأمير قرقماس أمير سلاح، بعد أن قاتل أهلها بضعة عشر يومًا، ثم هدمها حتى سوَّى بها الأرض، وقد فرَّ منها حسن أيتاقي، ثم سار الأمير قرقماس بمن معه مع بقية العساكر يريدون أرزنكان، فقدم عليهم الأمير مرزا بن الأمير يعقوب ابن الأمير قرا يلك رسولًا من أبيه يعقوب صاحب أرزنكان وكماخ، وقد خرج عن أرزنكان ونزل كماخ، وقدم مع مرزا زوجة أبيه وعدة من القضاة والأعيان بأرزنكان، يسألون العفو عن الأمير يعقوب وإعفاءه من قدومه إليهم، وأن يُجهَّز لنيابة السلطنة بأرزنكان الأمير جهان كير ابن الأمير ناصر الدين علي باك بن قرا يلك، فأُجيبوا إلى ذلك كله، وخُلِع على الأمير مرزا، ودُفِع إليه خِلعة لأبيه الأمير يعقوب، وأُعيد وصحبته الأمير جهان كير، وقد خُلِع عليه بنيابة أرزنكان، وساروا وقد جهز إلى أرزنكان بالأمير سودون النوروزى دوادار نائب حلب، ومعه نائب دوركى ونائب بهنسنى، فتسلموا أرزنكان بلا مانع، وأقاموا بها، ثم توجه القاضي معين الدين عبد اللطيف ابن القاضي شمس الدين الأشقر كاتب السر بحلب، حتى حلف أهل أرزنكان بالإقامة على طاعة السلطان، ثم سارت العساكر من أقشهر في الثاني والعشرين حتى نزلت على أرزنكان، وعسكروا هناك، فخرج إليهم أهلها، وباعوا عليهم ما أرادوا منهم، وفُتِحت أبواب المدينة، والعساكر يدخل منها المدينة من أراد ذلك، من غير ضرر ولا نهب، واستمروا على ذلك إلى آخر الشهر."},{"id":3388,"title":"خلع السلطان العزيز يوسف وتسلطن الأمير جقمق .","date":["العام الهجري :842","الشهر القمري : ربيع الأول","العام الميلادي :1438"],"text":"بعد أن أصبح السلطان العزيز يوسف بن برسباي سلطانًا أصبح الأمير الكبير جقمق هو نظام الملك؛ فله الأمر والنهي، وبيده كل شيء، وليس للسلطان سوى الاسم، وكان في هذه السنة حصلت فتن بين المماليك الأشرفية التابعين للسلطان، وبين الأمير جقمق ومن معه من الأمراء والمماليك الظاهرية والمؤيدية، فعزز الأمير جقمق مركزه وعلا شأنُه، حتى لما كان يوم الأربعاء التاسع عشر ربيع الأول قام الأمير الكبير جقمق بخلع السلطان العزيز يوسف بعد أن دام في السلطنة مدة أربعة وتسعين يومًا، وذلك باتفاق الأمراء وأعيان المملكة على سلطنته، ولما تم أمره استُدعي الخليفة المعتضد بالله داود والقضاة الأربعة والأمير قرقماس أمير سلاح وسائر الأمراء وجميع أعيان الدولة إلى الحراقة -نوع من السفن فيها مرامي نيران يرمى بها العدو- بباب السلسلة من الإسطبل السلطاني، وجلس كل واحد في مجلسه، فافتتح الأمير قرقماس الكلام مع الخليفة والقضاة بأن قال: السلطان صغير، والأحوال ضائعة؛ لعدم اجتماع الكلمة في واحد بعينه، ولا بد من سلطان ينظر في مصالح المسلمين وينفرد بالكلمة، ولم يكن يصلح لهذا الأمر سوى الأمير الكبير جقمق هذا, فقال جقمق: هذا لا يتم إلا برضا الأمراء والجماعة، فصاح الجميع: نحن راضون بالأمير الكبير؛ فعند ذلك مد الخليفة يده وبايعه بالسلطنة، ثم بايعه القضاة والأمراء على العادة، ثم قام مِن فَورِه إلى مبيت الحراقة، ولبس الخلعة الخليفتية السوداء، وتقلد بالسيف، وخرج راكبًا فرسًا أُعِدَّ له بأبهة السلطنة وشعار الملك، فأصبح السلطان الجديد هو السلطان الملك الظاهر سيف الدين أبو سعيد جقمق العلائي الظاهري الشركسي."},{"id":3389,"title":"فتنة الأمير الكبير قرقماس ومحاولة خلع السلطان الظاهر جقمق .","date":["العام الهجري :842","الشهر القمري : ربيع الآخر","العام الميلادي :1438"],"text":"بعد أن تسلطن الظاهر جقمق أصبح الأمير قرقماس هو أتابك العساكر وهو الأمير الكبير، ثم في ربيع الآخر ثارت عدة من المماليك القرانصة الذين قاموا مع السلطان العزيز يوسف بن برسباي قبل ذلك على الأشرفية، وطلبوا الآن من السلطان الزيادة في مرتباتهم، فنزل إليهم الأمير قرقماس ووعدهم بأن يكلم السلطان بذلك، ولكنهم أبوا إلَّا أن يقاتلوا السلطان واستطاعوا أن يقنعوا الأمير قرقماس بأن يكون معهم ضِدَّ السلطان، فلبسوا سلاحهم ولبس هو الآخر أيضًا، وأتاه كثير من الأشرفية، وساروا به حتى وقف بالرميلة تجاه باب السلسلة، وهم في اجتماعهم مختلفة آراؤهم، وعندما وقف تجاه باب السلسلة من القلعة سار بعض أتباعه ونادى في القاهرة على لسانه بمجيء المماليك إلى الأمير قرقماس، وأنه ينفق فيهم مائتي دينار لكل واحد، وبمجيء الزعر إليه وأنه يعطي كل واحد منهم عشرين دينارًا، فعَظُم جمعُه، بحيث توهَّم كثير من الناس أن الأمر له، وكان السلطان عند ذلك في نفر قليل، فبادر بنزوله من القصر إلى المقعد الذي بجانب باب السلسلة، ومعه المال، وبعث بجماعة للقتال، فوقعت الحربُ بين الفريقين مرارًا، والجراح فاشية فيهم، وقد قُتِل جماعة وتعَيَّن الغلب لقرقماس ومن معه، إلا أن عدة من الأمراء فرُّوا عنه، وصعدوا من باب السلسلة إلى السلطان، فسُرَّ بهم، ثم أقبل أيضًا من جهة الصليبة عدة أمراء، ووقفوا تجاه قرقماس في هيئة أنهم جاؤوا ليقاتلوا معه، ثم ساقوا خيولهم بمن معهم، ودخلوا باب السلسلة، وصاروا مع السلطان، فازداد بهم قوة، هذا وقد دُقَّت الكوسات -قطعتان من نحاس يدق بإحداهما على الأخرى بإيقاع مخصوص- السلطانية حربيًّا بالطبلخاناه من القلعة، وقامت ثلاثة مشاعلية على سور القلعة تنادي من كان في طاعة السلطان فليحضُرْ وله من النفقة كذا وكذا، ونثر مع ذلك السلطان من المقعد على العامة ذهبًا كثيرًا، وصار يَقِفُ على قدميه ويحَرِّض أصحابه على القتال، فأقبلت الفرسان نحوه شيئًا بعد شيء داخلة في طاعته، وتركت قرقماس، والحرب مع هذا كله قائمة بين الفريقين ضربًا بالسيوف، وطعنًا بالرماح، إلا أن الرمي من القلعة على قرقماس ومن معه بالنشاب كثيرٌ جدًّا، مع رمى العامة لهم بالحجارة في المقاليع؛ لبغضها في قرقماس وفي الأشرفية، فتناقص جمعهم، وتزايد جمع السلطان إلى قبيل العصر، فتوجه بعض الأشرفية وأخذوا في إحراق باب مدرسة السلطان حسن؛ ليتمكنوا من الرمي على القلعة من أعلاها، فلم يثبت قرقماس، وفَرَّ وقد جُرِح، فثبتت الأشرفية وقاتلت ساعة، حتى غُلِبت بالكثرة عليها، فانهزمت بعدما قُتِل من الفرسان والرجالة جماعة، وجُرح الكثير، فممن جُرح من السلطانية الأمير تغري بردي المعروف بالمؤذي حاجب الحجاب من طعنة برمح في شدقه، والأمير أسنبغا الطيارى الحاجب في آخرين، فكانت هذه الوقعة من الحروب القوية بحسب الوقت، إلا أن قرقماس جرى فيها على عادته في العجلة والتهور، ففاته الحزم، وأخطأه التدبير من وجوه عدة؛ ليقضي الله أمرًا كان مفعولًا {وَإِذَا أَرَادَ اللَّهُ بِقَوْمٍ سُوءًا فَلَا مَرَدَّ لَهُ} وعندما انهزم القوم ندب السلطان الأمير أقبغا التمرازي أمير سلاح في جماعة؛ لطلب المنهزمين، فتوجه نحو سرياقوس خشية أن يمضوا إلى الشام، فكانوا أعجز من ذلك، ولم يجد أحدًا فعاد، ثم قُبِض على الأمير قرقماس، ثم سُجِن بالإسكندرية، ثم قُتِل بعد عدة أشهر."},{"id":3390,"title":"وفاة محدث الشام شمس الدين ابن ناصر الدين الدمشقي .","date":["العام الهجري :842","الشهر القمري : ربيع الآخر","العام الميلادي :1438"],"text":"هو الشيخ الإمام الحافظ محدث الشام شمس الدين أبو عبد الله محمد بن أبى بكر بن عبد الله بن محمد بن أحمد بن مجاهد بن يوسف بن محمد بن أحمد بن علي، المعروف بابن ناصر الدين القيسي الحموي الدمشقي الشافعي. ولد بدمشق سنة 777, طلب الحديث، فصار حافظ بلاد الشام من غير منازع، ووليَ مشيخة دار الحديث بالأشرفية, وصنَّف عدة مصنَّفات؛ منها: تحفة الإخباري بترجمة صحيح البخاري، وعقود الدرر في علوم الأثر، والرد الوافر في الدفاع عن ابن تيمية، وله التنقيح في حديث التسبيح، وله برد الأكباد عند فقد الأولاد، وله فضل عشر ذي الحجة ويوم عرفة، وغيرها من المصنفات الدالة على غزير علمه في الحديث والفقه. كان متأثرًا بشيخ الإسلام ابن تيمية. توفي في الثامن والعشرين ربيع الآخر بدمشق، وقيل: إنه قُتِل شهيدًا في إحدى قرى دمشق."},{"id":3391,"title":"وفاة الظاهر عبد الله بن الأشرف ملك اليمن وتولي ابنه الأشرف .","date":["العام الهجري :842","الشهر القمري : رجب","العام الميلادي :1439"],"text":"هو المَلِكُ الظاهر هزبر الدين عبد الله بن الأشرف إسماعيل بن علي بن داود بن يوسف بن عمر بن علي بن رسول ملك اليمن. ضعفت مملكة اليمن في أيامه؛ لقلة مجابي أموالها، واستيلاء العربان على أعمالها. مات يوم الخميس آخر شهر رجب، وله في الملك نحو اثنتي عشرة سنة، وأقيم بعده ابنه الأشرف إسماعيل، وله من العمر نحو العشرين سنة، فأكثر من سفك الدماء، وأخْذ الأموال، وغير ذلك من أنواع الفساد!"},{"id":3392,"title":"خروج الأمير تغري برمش والأمير إينال الجكمي عن الطاعة وقتلهما .","date":["العام الهجري :842","الشهر القمري : رمضان","العام الميلادي :1439"],"text":"أول من بدأ بالعصيان على السلطان هو تغري برمش الذي استطاع أن يستحوذ على حلب وأعلن عصيانه، فقام السلطان بإنابة غيره على حلب، وبعث بعض الأمراء لتولية الأمراء النواب الجدد، وكانت الأخبار تَرِدُ أن نائب دمشق الأمير إينال الجكمي أيضًا يريد الخروج عن الطاعة، لكن أمره لم يتحقق إلى أن كان يوم الاثنين تاسع رمضان، كان جميع أمراء دمشق وسائر المباشرين بين يدي الأمير إينال، وقد اطمأنَّ كل أحد بأن ملك الأمراء مستمِرٌّ على الطاعة، فما هو إلا أن استقر في مجلسه أشار بالقبض على أعيان أمراء دمشق، فأغلق الباب وقبض على جميع الأمراء والمباشرين، فلما سمع السلطان هذا الخبر اضطرب وتشوش غاية التشويش، وجمع الأمراء واستشارهم في أمر إينال وتغري برمش، فأشار الجميع بسفره، وانفضَّ الموكبُ على أن السلطان يسافر لقتالهما، ثم في يوم الأربعاء ورد الخبر على السلطان أن الأمير قطج أتابك حلب وصل أيضًا إلى حماة، وأن تغري برمش أخذ مدينة عينتاب وقلعتها، وأن عدة من قَبَض عليه الأمير إينال الجكمي من أمراء دمشق تسعة عشر أميرًا، ثم ورد على السلطان كتابُ الأمير فارس نائب قلعة دمشق بأن الأمير إينال الجكمي أمر فنُوديَ بدمشق بالأمان والاطمئنان والدعاء للسلطان الملك العزيز يوسف، ثم في يوم الأربعاء الخامس والعشرين عيَّن السلطان للسفر من أمراء الألوف اثنين، ومن أمراء العشرات عشرة، ثم ورد الخبر على السلطان من الأمير طوغان العثماني نائب القدس بأن إينال الجكمي أطلق الأمراء الذين قبض عليهم قبل تاريخه، وحَلَّفهم للملك العزيز يوسف، ولكن نفرت القلوب بذلك عن إينال الجكمي، وأول من نفر عنه تغري برمش نائب حلب، وقال في نفسه عن إينال: هذا في الحقيقة ليس بخارج عن الطاعة، وإنما قصد بالإشاعة عنه أنه عاصٍ حتى أقدم عليه ويقبض عليَّ تقربًا لخاطر السلطان جقمق، ومن يومئذ أخذ أمر إينال الجكمي في الاضمحلال قليلًا، واستخَفَّ كُلُّ أحد عَقْلَه وتعجَّب من سوء تدبيره، وكاد أخوه سودون العجمي أن يموت قهرًا لَمَّا بلغه عن أخيه إينال ذلك، وهو يوم ذاك من جملة أمراء العشرات بالديار المصرية، ثم ورد الخبر بانكسار تغري برمش وهروبه من حلب إلى الرملة، ثم ورد الخبر على السلطان بأن إينال الجكمي برز بمخيَّمِه من مدينة دمشق إلى ظاهرها، فلما كان يوم الخميس ثالث شوال، عزم هو على الخروج من المدينة بنفسه إلى مخيمه؛ ليسير بمن معه إلى نحو الديار المصرية، فبينما هو في ذلك ركب عليه الأمير قاني باي الأبوبكري الناصري البهلوان أتابك دمشق، وكان ممن وافق الجكمي على العصيان وحسَّن له ذلك ثم تركه ومال إلى جهة السلطان، وركب معه الأمير برسباي الناصري حاجب الحجاب بدمشق، وجميع أمراء دمشق وعساكرها، ولم يبقَ مع إينال من أعيان أمراء دمشق إلا جماعة يسيرة، فلما بلغ إينال الجكمي ركوب هؤلاء عليه، مال عليهم وقاتلهم، فلم يثبتوا له وانهزموا أقبح هزيمة، ثم تراجعوا فحمل عليهم فانكسروا وتمزقوا شذر مذر، ثم إن العسكر المصري وصل إلى الشام وتصادم مع العسكر الشامي بقيادة إينال، وحصلت بينهم وقائع كانت بدايتها بانهزام العسكر المصري ثم تخلى عن إينال أصحابه ومدوا أيديهم إلى النهب في أطلاب النواب لما انهزموا أمام العسكر الشامي، وبقي إينال في أناس قليلة، فحطَّ بهم على العسكر المصري، فثبتوا له وقاتلوه ساعة، وقد تفرقت عنه أصحابه بسبب النهب، فلم يجد مساعدًا، فانهزم بعد أن قتِل من الفريقين جماعة كبيرة جدًّا، فلما أصبح العسكر يوم الخميس ثاني ذي القعدة ورد الخبر عليهم من دمشق بالقبض على إينال الجكمي من قرية حرستا من عمل دمشق ثم في يوم الأحد ثاني عشر ذي القعدة كُتِبَ بقتل إينال الجكمي بسَجنِه بقلعة دمشق، بعد تقريره على أمواله وذخائره، وبقتل جماعة من أصحابه ممن قُبِضَ عليه في الوقعة، وكان قتله بقلعة دمشق في ليلة الاثنين عشرين ذي القعدة، ثم قَدِمَ الخبر على السلطان بأن العساكر توجهت من دمشق في الحادي عشر ذي القعدة إلى حلب؛ لقتال تغري برمش، هذا وأهل حلب يد واحدة على قتاله، ثم إن العسكر المصري بمن معه من العسكر الشامي لما ساروا من دمشق إلى جهة حلب وافاهم الأمير قاني باي محمزاوي وغيره وصاروا جمعًا واحدًا، فلقيهم تغري برمش بجموعه التي كانت معه قريبًا من حماة، في يوم الجمعة السابع عشر ذي القعدة، وقد صفَّ عساكره من التركمان وغيرهم، حتى ملؤوا الفضاء، فلما وقع بصر عسكره على العساكر السلطانية أخذوا في الانهزام من غير مصافَّة، بل حدث بعض التناوش من صغار الطائفتين، فولوا الأدبارَ ومدت العساكر السلطانية أيديها إلى عساكر تغري برمش، فغنموا منهم غنائم لا تُحصى كثرة، ونُهِبَ جميع وطاق تغري برمش وماله، وانهزم هو في جماعة يسيرة من خواصه إلى جهة التركمان الصوجية، ثم قبضوا عليه بعد ذلك، وكُتِبَ بقتل تغري برمش بعد عقوبته ليقِرَّ على أمواله، فعوقِبَ، فأقر على شيء من ماله، نحو الخمسين ألف دينار؛ ثم أُنزِلَ ونودي عليه تحت قلعة حلب، ثم ضُرِبَت عنُقُه."},{"id":3393,"title":"القتال بين ملك الحفصيين أبي عمرو عثمان وبين عمه أبي الحسن .","date":["العام الهجري :843","العام الميلادي :1439"],"text":"جرت حروب بأفريقية من بلاد المغرب، وذلك أنه لما مات أبو فارس عبد العزيز، وقام من بعده حفيده المنتصر أبو عبد الله محمد بن أبى عبد الله، ولى عمه أبا الحسن على بن أبي فارس بجاية وأعمالها، فلما مات المنتصر، وقام من بعده أخوه أبو عمرو عثمان بن أبي عبد الله، امتنع عمه أبو الحسن من مبايعته، ورأى أنه أحق منه، ووافقه فقيه بجاية منصور بن علي بن عثمان وله عصبة وقوة، فاستبد بأمر بجاية وأعمالها، فسار أبو عمرو من تونس في جمع كبير لقتاله، فالتقيا قريبًا من تبسة وتحاربا، فانهزم أبو الحسن إلى بجاية، ورجع أبو عمرو إلى تونس، ثم خرج أبو الحسن من بجاية، وضم إليه عبد الله بن صخر من شيوخ إفريقية، ونزل بقسنطينة وحصرها وقاتل أهلها مدة، فسار إليه أبو عمرو من تونس في جمع كبير، فلما قرب منه سار أبو الحسن عائدًا إلى جهة بجاية، فتبعه أبو عمرو حتى لقيه وقاتله، فانهزم أبو عمرو بعدما قتل أبو الحسن عدةً من أصحابه، وعاد كل منهما إلى بلده، فلما كان في هذه السنة أعمل أبو عمرو الحيلةَ في قتل عبد الله بن صخر حتى قتله، وحُمِل رأسه إليه بتونس، ففَتَّ ذلك في عضد أبي الحسن، ثم جهز أبو عمرو العساكر من تونس في إثر ذلك، فنازلت العساكر بجاية عدة أيام، حتى خرج الفقيه منصور بن علي إلى قائد العسكر، وعقد معه الصلح ودخل به إلى بجاية، وعبر الجامع وقد اجتمع به الأعيان، وجاء أبو الحسن ووافق على الصلح، وأن تكون الخطبة لأبي عمرو، ويكون هو ببجاية في طاعته، وترجع العساكر عن بجاية إلى تونس، فلما تم عقد الصلح أقيمت الخطة باسم أبي عمرو، وعادت العساكر تريد تونس، فبلغهم أن أبا عمرو خرج من تونس نحوهم لقتال أبي الحسن، فأقاموا حتى وافاهم، ووقف على ما كان من أمر الصلح، فرضي به، وأخذ في العود إلى جهة تونس، فورد عليه الخبر بأن أبا الحسن خاف على نفسه من أهل بجاية، فخرج ليلًا حتى نزل جبل عجيسة، فأقر عساكرَه حيث ورد عليه الخبر، وسار جريدة في ثقاته، ودخل مدينة بجاية، فسُرَّ أهلها بقدومه، وزينوا البلد، فرتب أحوالها واستخلف بها أصحابه، وعاد إلى معسكره، واستدعي شيوخ عجيسة، فأتاه طائفة منهم فأرادهم على تسليم أبى الحسن إليه، وبذل لهم المال، فأبوا أن يسلموه، فتركهم وعاد إلى تونس، فكثُرَ جمع أبي الحسن بالجبل، وأقام به مدة، ثم خاف من عجيسة أن تغدر به، ولم يأمنهم على نفسه، فسار ونزل جبل عياض قريبًا من الصحراء."},{"id":3394,"title":"وقوع الصلح بين ملك إشبيلية وبين ملك المسلمين بغرناطة .","date":["العام الهجري :843","الشهر القمري : محرم","العام الميلادي :1439"],"text":"وقع الصلح بين الفنش ملك إشبيلية وقرطبة وغيرهما من ممالك الفرنج، وبين محمد بن الأحمر ملك المسلمين بغرناطة من بلاد الأندلس، بعدما امتدت الفتنة بين الفريقين عدة سنين."},{"id":3395,"title":"هدم قلعة الكهف الإسماعيلية في طرابلس .","date":["العام الهجري :843","الشهر القمري : ذي الحجة","العام الميلادي :1440"],"text":"قدم عسكر من مدينة طرابلس فنازلوا قلعة الكهف ومدينتها وبها إسماعيل بن العجمي أمير الإسماعيلية مدة أيام، حتى أخذوها، وهدموا القلعة حتى سووا بها الأرض، وأنعم على إسماعيل بإمرة في طرابلس، فزالت قلعة الكهف، وكانت إحدى الحصون الإسماعلية المنيعة، وذلك بسعاية ناصر الدين محمد، وحجي، وفرج: أولاد عز الدين الداعي."},{"id":3396,"title":"غزو المسلمين رودس .","date":["العام الهجري :844","الشهر القمري : جمادى الأولى","العام الميلادي :1440"],"text":"في يوم الثلاثاء الحادي والعشرين جمادى الأولى قدم غزاة المسلمين في البحر، وكان من خبرهم أنهم انحدروا في النيل من ساحل بولاق إلى دمياط، ثم ركبوا بحر الملح من دمياط وساروا في جزيرة قبرص، فقام لهم متملكها بزوادتهم، ومروا إلى العلايا فأمدهم صاحبها بطائفة في غرابين -نوع من المراكب-  ومضوا إلى رودس، وقد استعد أهلها لقتالهم، فكانت بينهم محاربة طول يومهم، لم يكن فيها حسم، وقُتِلَ من المسلمين اثنا عشر من المماليك، وجُرح كثير، وقُتِل وجُرح من الفرنج كثير، فلما خلص المسلمون بعد جهد مروا بقرية من قرى رودس، فقتلوا وأسروا ونهبوا ما فيها، وقدموا دمياط، ثم ركبوا النيل إلى القاهرة، وأسفر وجه الأمراء أنهم لم يكن لهم طاقة بأهل رودس."},{"id":3397,"title":"استغاثة إمارة غرناطة بالسلطان المملوكي جقمق .","date":["العام الهجري :844","الشهر القمري : رجب","العام الميلادي :1440"],"text":"أرسلت إمارة غرناطة آخر إمارات الإسلام في الأندلس بسفارة استغاثة ونجدة بعثتها إلى السلطان المملوكي الظاهر جقمق بالديار المصرية؛ وذلك طلبًا للعون والمساعدة، وكان المسلمون في غرناطة يعانون من ضراوة الهجوم الذي يشنه النصارى الأسبان على دولتهم، لكن هذه الاستغاثة لم تَجِدِ استجابةً كافية من السلطان المملوكي!!"},{"id":3398,"title":"اشتداد البرد بالقاهرة حتى جمدت المياه .","date":["العام الهجري :844","الشهر القمري : شعبان","العام الميلادي :1441"],"text":"اشتدَّ البرد بالقاهرة حتى جمدت المياه بعدة مواضع، وبِيعَ الجليد بالأسواق في يوم الخميس الحادي عشر من شعبان، وجمدت بركة من مستنقع ماء النيل في بعض الضواحي بحيث صارت قطعة واحدة، ومشى فوقها الأوزُّ، وأصبحت زروعٌ كثيرة من الفول وقد اسودَّت وجفَّت، فحُملت وأُوقدت في الأفران، واسودَّ ورقٌ كثير من شجر الجميز وغيره!"},{"id":3399,"title":"وفاة الخليفة العباسي المعتضد داود وتولية أخيه المستكفي سليمان .","date":["العام الهجري :845","الشهر القمري : ربيع الأول","العام الميلادي :1441"],"text":"هو الخليفة العباسي المعتضد بالله داود بن المتوكل على الله أبي عبد الله محمد، في يوم الأحد رابع ربيع الأول كانت وفاته بعد مرض تمادى به أيامًا، وحضر السلطان الملك الظاهر جقمق الصلاة عليه بمصلاة المؤمني، ودُفن بالمشهد النفيسي، وكانت خلافته تسعة وعشرين سنة وأيامًا، ثم في يوم الخميس ثامن ربيع الأول كانت مبايعة الخليفة أمير المؤمنين سليمان ابن الخليفة المتوكل على الله أبي عبد الله محمد بالخلافة، بعد وفاة أخيه المعتضد داود، بعهدٍ منه إليه، ولُقِّب بالمستكفي بالله أبي الربيع سليمان."},{"id":3400,"title":"خلع أمير مكة بركات بن حسن وتولية أخيه علي بعده .","date":["العام الهجري :845","الشهر القمري : جمادى الأولى","العام الميلادي :1441"],"text":"في يوم الاثنين السادس عشر جمادى الأولى خَلَع السلطانُ الظاهر جقمق على الشريف علي بن حسن بن عجلان باستقراره في إمرة مكة، عِوَضًا عن أخيه الشريف بركات بن حسن بحكم عزله؛ لعدم حضوره إلى الديار المصرية، وعيَّن السلطان مع الشريف علي خمسين مملوكًا من المماليك السلطانية، وعليهم الأمير يشبك الصوفي المؤيدي أحد أمراء العشرات ورأس نوبة، لمساعدة الشريف علي على قتال أخيه الشريف بركات، وسافر الشريف علي من القاهرة في يوم الخميس الرابع والعشرين جمادى الآخرة، ثم في يوم الأحد الثاني عشر ربيع الآخر سنة 846 قدم الأمير سودون المحمدي من مكة إلى القاهرة، وهو مجروح في مواضع من بدنه، من قتال كان بين الشريف علي صاحب مكة وبين أخيه الشريف بركات، انتصر فيه الشريف علي، وانهزم بركات إلى البر، ثم في يوم الاثنين ثالث شوال من سنة 846 خلع السلطان على الشريف أبي القاسم بن حسن بن عجلان باستقراره أمير مكة، عوضًا عن أخيه علي، بحكم القبض عليه وعلى أخيه إبراهيم بمكة."},{"id":3401,"title":"وفاة المؤرخ المقريزي .","date":["العام الهجري :845","الشهر القمري : رمضان","العام الميلادي :1442"],"text":"هو الشيخ الإمام العالم المحدِّث المفنن، عمدة المؤرخين، ورأس المحدثين: تقي الدين أحمد بن علي بن عبد القادر بن محمد بن إبراهيم بن محمد بن تميم بن عبد الصمد البعلبكي الأصل, المصري المولد والوفاة، المقريزي الحنفي ثم الشافعي، ولد في القاهرة 764 نشأ بالقاهرة، وتفقه على مذهب الحنفية، وهو مذهب جده العلامة شمس الدين محمد بن الصائغ، ثم تحول شافعيًّا بعد مدة طويلة. تفقه وبرع، وصنف التصانيف المفيدة النافعة الجامعة لكل علم، وكان ضابطًا مؤرخًا، مفننًا، محدِّثًا، معظَّمًا في الدول. وَلِيَ حسبة القاهرة غيرَ مرة، أوَّلُ ولاياته مِن قِبَل السلطان برقوق في الحادي والعشرين رجب سنة 801 عوضًا عن شمس الدين محمد النجانسي، وولي عدة وظائف دينية، مثل القضاء والحِسبة، وعُرِضَ عليه قضاء دمشق في أوائل الدولة الناصرية، فرَدَّ وأبى أن يَقبَل ذلك، وكان إمامًا مفننًا، كتب الكثير بخطه، وانتقى أشياء، وحصَّل الفوائد، واشتهر ذكره في حياته وبعد موته في التاريخ وغيره، حتى صار به يُضرَبُ المَثَل، وكان له محاسن شتى، ومحاضرة جيدة إلى الغاية لا سيما في ذكر السلف من العلماء والملوك وغير ذلك، وكان منقطعًا في داره، ملازمًا للعبادة والخلوة، قلَّ أن يتردد إلى أحد إلا لضرورة، قال ابن تغري بردي الحنفي: \"قرأت عليه كثيرًا من مصنَّفاته، وكان يرجِعُ إلى قولي فيما أذكره له من الصواب، ويغيِّرُ ما كتبه أولًا في مصنفاته، وأجاز لي جميع ما يجوز له وعنه روايته من إجازة وتصنيف وغير ذلك، وسمعت عليه كتاب فضل الخيل للحافظ شرف الدين الدمياطي بكماله في عدة مجالس\". وقال عنه ابن تغري في كتابه النجوم الزاهرة: \"أملى علي نسبَ المقريزي الناصري محمد ابن أخيه بعد وفاته، إلى أن رفعه إلى علي بن أبي طالب من طريق الخلفاء الفاطميين\". وهذا يفسِّرُ سِرَّ الدفاع الشديد من المقريزي عن نسب الفاطميين ويصحِّحُ نَسَبَهم, قال ابن حجر العسقلاني: \"والعجب أن صاحبنا المقريزي كان يُفرِطُ في تعظيم ابن خلدون؛ لكونه كان يجزم بصحة نسب بني عُبيد -الذين كانوا خلفاء بمصر، وشُهِروا بالفاطميين- إلى عليٍّ، ويخالف غيرَه في ذلك، ويدفع ما نقل عن الأئمة في الطعن في نَسَبِهم، ويقول: إنما كتبوا ذلك المحضرَ مراعاة للخليفة العباسي. وكان المقريزي ينتمي إلى الفاطميين فأحبَّ ابن خلدون؛ لكونه أثبت نِسبَتَهم، وغفل عن مراد ابن خلدون؛ فإنه كان لانحرافه عن آل علي يُثبِتُ نسبة الفاطميين إليهم، لما اشتهر من سوء معتقد الفاطميين، وكون بعضهم نُسِب إلى الزندقة، وادعى الألوهية كالحاكم، وبعضُهم في الغاية من التعصب لمذهب الرفض، حتى قُتِلَ في زمانهم جمعٌ من أهل السنة, وكانوا يصرِّحون بسب الصحابة في جوامعهم ومجامعهم، فإذا كانوا بهذه المثابة وصحَّ أنهم من آل علي حقيقة، التصق بآل عليٍّ العيبُ، وكان ذلك من أسباب النفرة عنهم، والله المستعان\". له عدة مصنفات في التاريخ، أشهرها: السلوك في معرفة دول الملوك, وله كتاب الخطط المشهور، واسمه المواعظ والاعتبار في ذكر الخطط والآثار، يَذكُرُ فيه ما بمصر من الآثار، وله كتاب اتعاظ الحنفاء في تاريخ الفاطميين الخلفاء، وله الدرر المضيئة في التاريخ، وله إمتاع الأسماع بما للرسول من الأبناء والأحوال والحفدة والمتاع، وغيرها من الكتب. كانت وفاته في يوم الخميس السادس عشر رمضان، ودفن من الغد بمقابر الصوفية خارج باب النصر."},{"id":3402,"title":"الملك شاه رخ ابن الطاغية تيمورلنك يكسو الكعبة .","date":["العام الهجري :846","العام الميلادي :1442"],"text":"لما ملك شاه رخ ابن الطاغية تيمورلنك، واستقلَّ بممالك العجَم وعراقة، وعظُمَ أمرُه وهابَتْه الملوك، وحُمِدَت سيرته، وشُكِرت أفعالُه، وقَدِمَت رسله إلى البلاد المصرية مرارًا عديدة, وراسلته ملوكُ مصر، إلى أن تسلطن الملك الأشرف برسباي، طلب شاه رخ أن يكسو البيت الشريف، فأبى الأشرفُ برسباي وخشَّن له الجواب. وترددت الرسلُ بينهما مرارًا، واحتجَّ شاه رخ أنَّه نذر أن يكسو البيت الشريف، فلم يلتفت الأشرف برسباي إلى كلامه، ورد قُصَّاده إليه بالخيبة. ثم أرسل بعد ذلك شاه رخ بجماعة أُخرى وزعم أنهم أشراف، وعلى يدِهم خلعة للملك الأشرف برسباي، فجلس الأشرف مجلسًا عامًّا للحكم بالإصطبل السلطاني على عادة الملوك، ثم طلب القصَّاد رسل شاه رخ، فحضروا ومعهم الخِلعة، فأمر بها الأشرف فمُزِّقت الخلعة شذَرَ مذَرَ، ثم أمر بضرب حامِلِها عظيم القصَّاد، فضُرِبَ بين يديه ضربًا مُبَرِّحًا أشرف منه على الهلاك، ثم ضَرَب الباقين، ثم أمر بهم فأُلقوا في فسقية ماء بالإصطبل السلطاني منكوسين، رؤوسُهم إلى أسفل وأرجلهم إلى فوق، والأوجاقية تمسِكُهم بأرجلهم، واستمرُّوا يغمسِونَهم في الماء حتى أشرفوا على الهلاكِ، ولا يستجرئُ أحد من الأمراء يشفَعُ فيهم ولا يتكلَّم؛ لشدة غضب السلطان في أمرِهم بكلمةٍ واحدة، والسلطان يسبُّ شاه رخ جهارًا، ويحطُّ من قَدْره، على أنه كان قليلَ الفحش والسبِّ لآحاد الناس، وصار لونُه يتغير لعِظَمِ حَنَقِه، ثم طلب القصَّادَ بين يديه، وحدَّثَهم بكلام طويل، محصولُه أنه قال لهم: قولوا لشاه رخ: الكلامُ الكثيرُ ما يصلحُ إلا من النساء، وأما الرجالُ فإن كلامهم فعلٌ، لا سيما الملوك، فإن كان له مادة وقوَّة فيتقَدَّم ويسير نحوي، وأنا ألقاه حيث شاء، وإن كان بعد ذلك ما ينتجُ منه أمرٌ فكلامُه كله فشارٌ، وهو أفشَرُ من كلامه، وكتب له بأشياءَ من هذا المعنى، وانفَضَّ الموكب، فتحققَّ كل واحد بمجيء شاه رخ إلى البلاد الشاميَّةِ، وقاسوا على أنَّه ما أرسل هذه الخِلعةَ إلا وهو قد تهيأ للقتال، وقد أفحش الأشرفُ أيضًا وأمعن في الجوابِ. فلما بلغ القان شاه رخ ما فعل الأشرف بقصَّاده، ما زاده ذلك إلا رعبًا، وسكت عن كسوةِ الكعبة، ولم يذكُرْها بعد ذلك إلى أن مات الملِكُ الأشرف، وآل المُلكُ إلى الملك الظاهر جقمق، فبعث شاه رخ رسُلَه إلى الملك الظاهر بهدايا وتُحَف، وأظهر السرورَ الزائد بسلطنته، وأنَّه لما بلغه سلطنة الملك الظاهر جقمق دُقَّت البشائر بهراة، وزُيِّنت له أيامًا، فأكرم الملك الظاهر جقمق قصَّاده وأنعم عليهم، ثم بعث السلطان إليه في الرسلية الأمير ششك بغا دوادار السلطان بدمشق، فتوجَّه إليه وعاد إلى السلطان الملك الظاهر جقمق بأجوبة مرضية. ثم بعد ذلك في سنة 846، أرسل شاه رخ يستأذِنُ في إرسال ما نذر قديمًا أنه يكسو الكعبة، فأذِنَ له السلطان الملك الظاهر جقمق في ذلك، فأرسل شاه رخ بعد ذلك كسوةً للكعبة. فصعب ذلك على الأمراء وعلى أعيان الديار المصريةِ، فلم يلتفِت السلطانُ لكلامهم، وأمر أن يأخُذَها ناظِرُ الكسوة بالقاهرة، ويبعَثَها كي تلبسَ من داخل البيت، وتكون كسوةُ السلطان من خارج البيت على العادةِ، قال ابن تغري بردي: \"رأيتُ أنا الكسوةَ المذكورة، وما أظنُّها تساوي ألف دينار\"."},{"id":3403,"title":"القتال بين سلطان العثمانيين مراد الثاني وبين المجر .","date":["العام الهجري :846","العام الميلادي :1442"],"text":"قام أميرُ الصرب جورج برنكوفتش بمهاجمة السلطان مراد الثاني العثماني، واستطاع أن يفتح جزءًا من بلاد الصرب، وحاصر مدينة بلغراد ستة أشهر، وغادرها أميرها نائب السلطان العثماني متوجهًا إلى بلاد المجر، ثم غادرها أيضًا, وأرسل جيشه للهجوم على ترانسلفانيا من أملاك المجر -تقع في الجزء الغربي من رومانيا- غير أن جيشه هُزم، وقُتل قائِدُه مع عشرين ألفًا من جند المسلمين، وانسحب العثمانيون إلى ما بعد نهر الدانوب، فأرسل السلطان مراد الثاني جيشًا آخر قوامه ثمانون ألفًا غير أنه هُزِمَ، وأُسر قائده سنة 845، وسار الجيش المجري بعد ذلك إلى بلاد الصرب، فالتقى في هذا العام بالسلطان مراد الثاني نفسه، فنشبت بين الفريقين ثلاثة معارك هُزم فيها السلطان كلها، واضطر إلى توقيع معاهدة تنازل فيها السلطان عن الأفلاق للمجر، ورَدَّ الصرب بعض المواقع، وكانت مدة هذه الهدنة عشر سنين، ويُذكر أنه اشترك مع الجيش المجري أعداد من الصليبيين من بولندا وفرنسا وألمانيا والبندقية وجونيه وأفلاق وصرب وغيرهم، ولكن البابا لما بلغه خبر هذه المعاهدة أرسل مندوبًا مِن قِبَلِه، وهو سيزاريني- إلى ملك المجر، وأمره أن يرفضَ هذه المعاهدة وينقُضَها."},{"id":3404,"title":"خروج العسكر المصري لغزو رودس وعودته دون الوصول لرودس .","date":["العام الهجري :846","الشهر القمري : محرم","العام الميلادي :1442"],"text":"كان السلطان الظاهر جقمق مهتمًّا بغزو رودس؛ فعَيَّن عدة كبيرة من المماليك السلطانية والأمراء، ومُقدَّم الجميع اثنان من مقدَّمي الألوف: الأمير إينال العلائي الناصري، المعزول عن نيابة صفد، والأمير تمرباي رأس نوبة النوب، وسافر الجميع من ساحل بولاق في محرم سنة ست وأربعين، ومعهم عدة كبيرة من المطوعة، بأبهج زي من العدد والسلاح، وكان لسفرهم بساحل بولاق يوم مشهود، إلا أنهم عادوا في أثناء السفر، ولم ينالوا من رودس غرضًا، بعد أن أخربوا قشتيل."},{"id":3405,"title":"فتنة المماليك السلطانية الأجلاب على السلطان الظاهر جقمق .","date":["العام الهجري :846","الشهر القمري : صفر","العام الميلادي :1442"],"text":"لما كان يوم الاثنين السادس عشر صفر وثب جماعة كبيرة من مماليك السلطان الأجلاب-هكذا يُعرَفون- من مشترواته الذين بالأطباق من القلعة، وطلعوا إلى أسطحة أطباقهم، ومنعوا الأمراء وغيرهم من الأعيان من طلوع الخدمة، وأفحشوا في ذلك إلى أن خرجوا عن الحد، ونزلوا إلى الرحبة عند باب النحاس، وكسروا باب الزردخاناه السلطانية، وضربوا جماعةً من أهل الزردخاناه -خزانة السلاح- وأخذوا منها سلاحًا كثيرًا، ووقع منهم أمور قبيحة في حقِّ أستاذهم الملك الظاهر جقمق، ولهجوا بخلعِه من الملك، وهمَّ السلطان بقتالهم، ثم فتَرَ عزمُه عن ذلك؛ شفقة عليهم لا خوفًا منهم، ثم سكنت الفتنة بعد أمورٍ وقعت بينهم وبين السلطانِ."},{"id":3406,"title":"وفاة الأمير سودون بن عبد الله النوروزي .","date":["العام الهجري :847","العام الميلادي :1443"],"text":"الأمير سيف الدين سودون بن عبد الله النوروزي حاجب حُجَّاب دمشق, ويعرف بسودون العجمي أحد العشرات ورؤوس النوب، ممن تأمَّر في أيام الظاهر جقمق. من مماليك الأمير نوروز الحافظي، وتنقَّلت به الأحوال بعد موت أستاذه إلى أن صار في الدولة الأشرفية برسباي دوادار السلطان بحلب، وأمير مائة ومقدم ألف بها، ودام على ذلك مدة طويلة بحلب، إلى أن نقله الملك الظاهر جقمق إلى حجوبية الحجَّاب بدمشق، بعد الأمير برسباي من حمزة الناصري بحكم انتقالِه إلى نيابة طرابلس، بعد قاني باي الحمزاوي المنتَقِل إلى نيابة حلب بعد انتقالِ نائبها الأمير جلبان إلى نيابة دمشق بعد موت آقبغا التمرازي في سنة 843. واستمر سودون في حجوبية دمشق مدة طويلة، وقدِمَ القاهرة على الملك الظاهر جقمق بتقاديم هائلة، ثم عاد مستمرًّا على حجوبيته، ونالته السعادة، واستمرَّ إلى أن توفي بدمشق في سنة 847, وكان متوسطَ السيرة لا بأس به، وتولى الحجوبية من بعده الأمير جانبك نائب قلعة دمشق، الذي كان دوادار الأمير برسباي حاجب حجَّاب دمشق الذي هو الآن نائب طرابلس, وسودون هذا غير الأمير سودون بن عبد الله المحمدي الشهير بتلي المتوفي سنة 818."},{"id":3407,"title":"البابا أوغانيوس يعلن قيام حرب صليبية جديدة ضد المسلمين .","date":["العام الهجري :847","العام الميلادي :1443"],"text":"قام البابا أوغانيوس الرابع بالدعوة لحرب صليبية ضد العثمانيين، وخاصةً أن مراد الثاني هُزم أكثر من مرة وخاصةً أمام المجريين، ولاقت هذه الدعوة ترحيبًا كبيرًا في بولندا والمجر والنمسا وألمانيا وفرنسا، وتعاقدوا على جيش يقودُه ملك المجر جان هونياد."},{"id":3408,"title":"تنازل السلطان العثماني مراد بن محمد عن السلطة لولده محمد .","date":["العام الهجري :848","العام الميلادي :1444"],"text":"لما مرَّ على مرادِ الثاني ما مرَّ من حروب وهُزِمَ أكثَرَ من مرة أمام المجر، وتوفِّيَ ولده الأكبر علاء الدين، شعَرَ السلطان بالتعب، فرأى أن يخلُدَ إلى الراحة، فتنازل عن الحكم لابنه الثاني محمد، الذي لم يكن يبلغ من العمر سوى أربعة عشر عامًا، وسافر هو إلى غربي الأناضول في ولاية آيدين، وهذا ممَّا قوى عزيمةَ الصليبيين للقيام بحملة صليبية على العثمانيين."},{"id":3409,"title":"العسكر المصري والشامي يغزو رودس ويعود دون فتحها .","date":["العام الهجري :848","الشهر القمري : ربيع الأول","العام الميلادي :1444"],"text":"في يومِ السبت سادس عشر شهر ربيع الأول خرج الغُزاة من القاهرة، فنزلوا في المراكبِ من ساحل بولاق؛ وقصدوا الإسكندرية ودمياط؛ ليركبوا من هناك البحرَ المالح، والجميعُ قصْدُهم غزو رودس، وكانوا جمعًا موفورًا، ما بين أمراء وخاصكية ومماليك سلطانية ومطوعة، وكان مقَدَّمَ الجميع في هذه الغزوة الأميرُ إينال العلائي الدوادار الكبير، وكانت المماليك السلطانية في هذه الغزوة تزيد عدتهم على ألف مملوك، هذا خارجٌ عمَّن سافر من المطوِّعة، وأضاف إليهم السلطان جماعةً كبيرة من أمراء البلاد الشامية، ورسمَ لهم أن يتوجَّهَ الجميع إلى طرابلس، ليضافَ إليهم العسكر الشامي، ويسير الجميع عسكرًا واحدًا، ففعلوا ذلك، وفي يوم الخميس حادي عشر شهر ربيع الآخر سار الجميع من ثغر الإسكندرية ودمياط إلى طرابلس، ثم من طرابلس إلى رودس، حتى نزلوا على برِّها بالقرب من مدينتها في الخيم، وقد استعدَّ أهلها للقتال، فأخذوا في حصار المدينة، ونصبوا عليها المجانيق والمكاحل، ورمَوا على أبراجها بالمكاحل والمدافع، واستمرُّوا على قتال أهل رودس في كل يوم، هذا ومنهم فرقةٌ كبيرة قد تفرَّقت في قرى رودس وبساتينها ينهَبون ويسبون، واستمَرُّوا على ذلك أيامًا، ومدينة رودس لا تزداد إلَّا قوة؛ لشدة مقاتليها ولعِظَم عمارتِها، وقد تأهَّبوا للقتال وحصَّنوا رودس بالآلات والسلاح والمقاتلة، وصار القتالُ مستمرًّا بينهم في كل يوم، وقُتل من الطائفتين خلائقُ كثيرة، هجم عليهم الفرنج في عدة كبيرة من المراكب، فبرز إليهم يلخجا ومن معه، وقاتلوهم قتالًا عظيمًا، حتى نصر اللهُ المسلمين، وانهزم الفرنجُ وغنم المسلمون منهم، كل ذلك وقتال رودس مستمرٌّ في كل يوم، والعساكرُ في غاية ما يكون من الاجتهاد في قتال رودس، غير أن رودس لا يزداد أمرُها إلا قوة؛ لعِظَمِ استعداد أهلها للقتال، ولما كان في بعض الأيام وقع للمسلمين محنة عظيمة، قُتِلَ فيها جماعة كبيرة من أعيان الغزاة من الخاصكية وغيرهم؛ حيث كانوا بائتين في كنيسةٍ فطرقهم الفرنج وقتلوهم، ودام القتالُ بعد ذلك في كلِّ يوم بين عساكر الإسلام وبين فرنج رودس أيامًا كثيرة، فعند ذلك أجمع المسلمون على العود، وركبوا مراكبَهم، وعادوا إلى أن وصلوا إلى ثغر الإسكندرية ودمياط، ثم قَدِموا إلى القاهرة."},{"id":3410,"title":"الحرب بين العثمانيين وبين الصليبيين وموقعة فارنا .","date":["العام الهجري :848","الشهر القمري : رجب","العام الميلادي :1444"],"text":"بعد أن أصبح سلطان العثمانيين محمدُ بن مراد الثاني وهو ما يزال صغيرًا غِرًّا على القتال، جمع الصليبيون جموعَهم وهاجموا بلاد البلغار، ساعدهم على ذلك صِغَرُ سن السلطان وبُعدِ السلطان مراد عن البلاد، ولكِنَّ السلطان مراد لما سمع بهذا الهجوم على البلغار غادر مكانه واتَّجه إلى أوربا فقاد الجيش وسار نحو الأعداءِ فوجدهم يحاصرون مدينة فارنا البلغارية الواقعة على ساحل البحر الأسود، فنازلهم وقتَلَ ملِكَ المجر في ساحة المعركة، فاختَلَّ ترابط الجند، فهاجم السلطانُ معسكر الأعداء واحتَلَّه وقتل الكاردينال سيزاريني مندوب البابا، وتم النصرُ للمسلمين في الثامن والعشرين من شهر رجب من هذا العام، ثم رجع مرة أخرى إلى مغنيسيا في آيدين."},{"id":3411,"title":"عودة السلطان مراد الثاني للسلطة لجهاد الصليبيين .","date":["العام الهجري :849","العام الميلادي :1445"],"text":"عاد السلطانُ مراد الثاني للسلطة بعد أن ترك اعتزالَه لقتال الصليبيين في فارنا وهزمهم ثم عاد مرةً أخرى إلى مكان إقامتِه تاركًا الأمر لابنه محمد، لكن إقامتَه لم تطل أكثر من ثلاثة أشهر فاضطر للعودةِ إلى أدرنة قاعدةِ الملك، حيث استصغر قادةُ الجيش العثماني من الانكشارية السلطانَ محمد بن مراد، فعَصَوا أمره ونهَبوا المدينة، فوصل السلطانُ مراد فأدَّب القادة وأشغَلَهم بالقتالِ في بلاد اليونان، وذلك أنَّ إمبراطور القسطنطينية قسَمَ أملاكَه بين أولاده؛ إذ أعطى ابنه حنا مدينة القسطنطينية، وابنه قسطنطين بلاد المورة، أي جنوب اليونان، فسار السلطان لحرب اليونان مستعملًا المِدفَع لأول مرة، ولكنَّه لم يتمكن من فتحها بسبب تمرُّد إسكندر بك أحد أبناء أمير ألبانيا الذين عاشوا رهينةً عند السلطان عندما سلَّم أبوه البلاد للسلطان، فأظهر إسكندر الإسلامَ فلما وجد الفرصةَ مواتية بانشغال السلطان بحربه فرَّ إلى ألبانيا وطرد العثمانيين منها."},{"id":3412,"title":"خلع محمد الأيسر ملك بني نصر في غرناطة وتولي محمد العاشر مكانه .","date":["العام الهجري :849","العام الميلادي :1445"],"text":"كان محمد التاسع الملقب بالأيسر هذا منفيًّا في المغرب، ثم عاد بتقوية ملك قشتالة له فأزاح محمد الثامن الملقب بالصغير وحَلَّ محلَّه، لكِنَّ الفتنَ لم تنتهِ، وكان له عدةُ خصوم، فاستطاع الأميرُ محمد العاشر بن عثمان بن يوسف المعروف بالأحنف أن يتزعَّمَ خصوم محمد الأيسر ويستولي على قصر الحمراء والحصون المجاورة له، ويقبِضَ على الأيسر هذا وينُهيَ ملكَه ويزجَّه وآلَه في السجن، ويخلُفَه في ملك بني نصر."},{"id":3413,"title":"وفاة الشيخ الحافظ عبد الله العبدوسي المالكي مفتي فاس .","date":["العام الهجري :849","الشهر القمري : ذي القعدة","العام الميلادي :1446"],"text":"هو شيخُ الإسلام الحافظ العلامة أبو محمد عبد الله بن محمد بن موسى بن معطي العبدوسي المالكي، مفتي فاس وعالِمُها ومحَدِّثُها. قال فيه السيوطي: \"كان عالِمًا بارعًا صالحًا مشهورًا\" وقال الشيخ أحمد زروق الفاسي: \"كان أبو محمد العبدوسي عالِمًا صالحًا مفتيًا، حُملتُ إليه وأنا رضيع ولم أزل أتردَّدُ إليه في ذلك السن؛ لكون جدتي تقرأُ عليه مع أختيه فاطمة وأم هانئ، وكانتا فقيهتين صالحتين، وكان قطبًا في السخاءِ، إمامًا في نصح الأمة، أمات كثيرًا من البِدَع بالمغرب، وأقام الحدود والحقوق وتولَّى آخِرَ أمره خطابةَ جامع القرويين، ثم توفى سنة تسع وأربعين، وكان أكثر علمه فقهَ الحديث، سمعت شيخنا القوري يقول: إنهم حسبوا الخارج من يده والداخل فيها فوجدوا الخارج أكثر، وحدَّثنا أنه حَفِظَ مختصر مسلم للقرطبي في كل خميس خمسة أحاديث، وشهرةُ أخلاقه وسخائه أبينُ من أن تُذكَر، كان لا يدَّخِر شيئًا حتى لم يوجَدْ يوم مات إلا بدنان وإحرامان ودراعتان إحداهما للأمير يحيى بن زيان، فقال: هكذا يكون الفقيهُ وإلا فلا. وكان يشترط العزلَ في النكاحِ، فرارًا من الولدِ؛ لفساد الزمانِ، قالوا: وكان لا تفارِقُ كُمَّه الشمائلُ عاملًا بها، وحَدَّثَت زوجته أنه كان يعمل الخوصَ خُفيةً ويعطيه لمن لا يعرفُ أنَّها له يبيعُها، ثم يتقَوَّتُ بها في رمضان، ومناقبُه كثيرة جمع فيها بعض أصحابنا تأليفًا ذكر فيه كثيرًا, وكان العبدوسي أقوى من جَدِّه موسى في العمل، وإنَّ جَدَّه أقوى منه في العلم, وكان شيخ الجماعة الفقهاء والصوفية، وتخرَّج به جماعةٌ، كالفقيه المحقق ابن آملال، والفقيه القوري، وأبي محمد الورياجلي، وغيرهم\" قال شمس الدين السخاوي: كان أبو محمد هذا واسِعَ الباع في الحفظ، وليَ الفُتيا بالمغرب الأقصى، وإمامة جامع القرويين بفاس، ومات فجأة وهو في صلاةٍ\""},{"id":3414,"title":"خلع محمد العاشر الأحنف ملك بني نصر بغرناطة .","date":["العام الهجري :850","العام الميلادي :1446"],"text":"لم تدُمْ أيام الأحنف محمد العاشر الملك بغرناطة كثيرًا؛ فقد ثار عليه الأمير سعد بن علي بن أبي الحجاج يوسف الثاني، فانتزع منه الملك وتلقب بالمستعين وعُرِفَ بابن الأحمر، لكنَّه لم يلبث كثيرًا حتى عاد محمد العاشر الأحنف بعد أن لجأ إلى ملك قشتالة فزوَّدَه بقوة استرد بها المُلكَ بالقوة وخلع المستعينَ."},{"id":3415,"title":"وفاة الأمير سودون بن عبد الله المحمدي نائب قلعة دمشق .","date":["العام الهجري :850","العام الميلادي :1446"],"text":"هو الأمير سيف الدين سودون بن عبد الله المحمدي، نائب قلعة دمشق، هو مملوك سودون بن عبد الله المحمدي المتوفي سنة 818، وعتيقه، وإليه يُنسَب بالمحمدي. واستمرَّ بخدمته إلى أن قتله المؤيد شيخ، واستمرَّ من جملة المماليك السلطانية إلى أن صار في الدولة الأشرفية برسباي خاصكيًّا، ورأَسَ نوبةَ الجمدارية مدةً طويلة. ثم أراد الأشرفُ أن يؤمِّرَه فامتنع وترك وظيفته أيضًا، وصار من جملة المماليك السلطانية على إقطاعه، ودام على ذلك إلى أن وثب الأتابك جقمق على الملك العزيز يوسف، فانضَمَّ سودون المحمدي إلى الملك العزيز، ولم يوافِق الأتابك جقمق، فعدَّها عليه جقمق إلى أن تسلطن فنفاه، ثم شُفِعَ فيه بعد أشهر، وكَتَبَ بعوده إلى القاهرة، وأنعم عليه بإمرةِ عشرة بسفارة خوند مغول بنت القاضي ناصر الدين البارزي زوجة الملك الظاهر جقمق، فإن سودون هذا هو زوج أختها لأبيها, فاستمرَّ سودون مدة ثم توجَّه إلى مكة المشرفة ناظرًا بها وشاد العمائر، كما كان توجَّه في الدولة الأشرفية برسباي. واستمر بمكة نحو السنتين أو أكثر، وعاد إلى القاهرة وأقام بها مدة يسيرة، واستقرَّ في نيابة قلعة دمشق في سنة 848، فتوجَّه إليها ودام بها إلى أن مات في صفر. قال ابن تغري بردي: \"كان ديِّنًا خَيِّرًا، عفيفًا عن المنكرات والفروج، عاقلًا ساكنًا، إلا أنه كان قليل المعرفة كثيرَ الظن برأي نفسِه. من ذلك أنه لما توجه إلى مكة ليصلِحَ ما تشعَّثَ من حيطان الحرم، فلما وصل إلى مكَّةَ هدم سقْفَ البيت الشريف، ورفع الأخشابَ التي كانت بأعلى البيت وغيرَها، فمنعه أكابِرُ مكة من ذلك، فأبى، فقالوا له: هذا عليه كتابةٌ تمنع الطيرَ أن يقعُدَ بأعلى البيت، فلم يلتفِتْ إلى كلامهم، وهدم السقفَ واعتذر بأنه يدلِفُ المطرَ إلى داخل البيت، فرحل جماعةٌ من أهل مكة خوفًا من أن ينزل عليهم بلاء من الله، وصار البيت مكشوفًا أيامًا بغير كسوة إلى أن جَدَّد له سقفًا، فتَلِفَ ما صنعه أكثَرَ من السقف القديم، وتكرر منه هذا الفعل، فلم يُحمَدْ على ما فعل، وساءت سيرتُه بمكة لأجل ذلك، ونَقَم عليه كل أحد، وصار سقفُ البيت مأوًى للطيور، وأتعب الخدامَ ذلك؛ فإنهم صاروا كل قليل ينزلون من أعلى البيت بقُفَف من زبلِ الحمام وغيره، فما شاء الله كان، ونَدِمَ هو أيضًا على فعلته، فلم يُفِدْه الندم، وهو غير الأمير سودون بن عبد الله النوروزي المتوفى سنة 847."},{"id":3416,"title":"وفاة الأمير أزبك جُحا .","date":["العام الهجري :850","العام الميلادي :1446"],"text":"هو الأمير سيف الدين أزبك بن عبد الله السيفي قاني باي، أحد أمراء العشرات ورأس نوبة، المعروف بجُحا، أصله من مماليك نوروز الحافظي، وبقى عنده كتابيًّا، فأخذه بعد موته الأمير قاني باي المحمدي نائب دمشق وأعتقه، ثم اتصل بعد موت قاني باي بخدمة السلطان الملك المؤيد شيخ، وصار في دولته خاصكيًّا، ثم صار رأس نوبة الجمدارية- حَمَلة ملابس السلطان- في دولة السلطان الأشرف برسباي، ثم أمَّرَه الأشرفُ عشرةً وجعله من جملة رؤوس النوب، ودام على ذلك إلى أن توفِّيَ الملك الأشرف برسباي، فسافر أزبك إلى البلاد الشامية بسلطنة الملك العزيز يوسف، فلمَّا أن عاد أزبك إلى القاهرة كان كافأ الملك الظاهر جقمق على ما فعله معه من الخيرِ بأنَّه لما أن عصى الأتابك قرقماس الشعباني وافقه أزبك، وقاتل الملك الظاهِر جقمق وانهزم قرقماس واختفى، ثم ظفِرَ به، فعندما ظفر بقرقماس وقبَض على أزبك أيضًا، وحبسه بثغر الإسكندرية ثم نقله إلى حبس صفد، فاستمر محبوسًا إلى أن توفي في حدود الخمسين وثمانمائة تقريبًا بالقلعة بصفد، وهو في الكهولية, وكان عنده مروءة وكرم، مع خِفة روح ومُجون ودعابة، ولهذا سمِّيَ جحا، مع إسراف على نفسِه."},{"id":3417,"title":"نشأة إمارة الدرعية في نجد .","date":["العام الهجري :850","العام الميلادي :1446"],"text":"كان الأمير مانع المريدي الجدُّ الأعلى لأسرة آل سعود يقطُنُ ببلدة الدروع من أعمال القَطيف بشرق الجزيرة العربية، وكان يربطُه بابن درع رئيسِ حجر اليمامة صلةُ نسب، فدعا ابنُ درع مانعًا وأقطعه من أملاكه مرتَفعًا في وادي حنيفة يشتمل على قريتي المليبيد وغصيبة- تبعد 12 ميلًا عن الرياض- فاستقر مانع مع صحبِه وأهله في هذه المنطقة، وبنوا مساكنَهم وسَمَّوها الدرعية، على اسم بلدتهم الأولى في القطيف. كان ذلك في سنة 850هـ ثم توالى أبناءُ مانع وأحفادُه على إمارة الدرعية والقرى التي حولها, ولم يتجاوزوها إلى مناطقَ أخرى إلى أن آلت الإمارةُ إلى محمد بن سعود بن محمد بن مقرن بن مرخان سنة 1139هـ /1727م. وبعد أن تمَّت المعاهدة التاريخية بينه وبين الإمام محمد بن عبد الوهَّاب سنة 1157، وبدأت بذلك الدولةُ السعودية الأولى."},{"id":3418,"title":"وفاة شهاب الدين ابن المجدي .","date":["العام الهجري :850","الشهر القمري : ذي القعدة","العام الميلادي :1447"],"text":"هو الشيخ الإمام العالم العلامة شهاب الدين المجدي أحمد بن رجب بن طيبغا، الشهير بابن المجدي الشافعي. مولدُه بالقاهرة في سنة 767، ونشأ بها، وتفقَّه على مذهب الشافعي، رضي الله عنه، ولازم علماء عصره، واجتهد في طلب العلم إلى أن برع في الفقه، والفرائض، والحساب، والعربية، وتصدر للإقراء والتدريس مدةً طويلة، وانتفع به الطلبة، وتفقَّه به جماعة من أعيان الطلبة، وكان له مشاركةٌ في علوم كثيرة لا سيما في الفرائض، والحساب، والهندسة، والميقات؛ فإنه فاق في هذه العلوم أهلَ عصره، وانفرد بها، وما برح مستمرًّا على الاشتغال والأشغال والتصنيف، ومصنفاته كثيرة مشهورة. توفى ليلة السبت حادي عشر ذي القعدة."},{"id":3419,"title":"العثمانيون يقاتلون إسكندر بك المتحكم في ألبانيا .","date":["العام الهجري :851","العام الميلادي :1447"],"text":"كان إسكندر بك سببًا في فشل القوات العثمانية في الحرب مع اليونان؛ وذلك لهربه من الجيش العثماني وهروبه إلى ألبانيا واحتمى بها؛ ممَّا اضطر الجيشَ العثماني إلى المسير إليه بقوة كبيرة وحصل بينهم عدَّةُ حروب في هذه السنة كانت نهايتُها هزيمة إسكندر بك وأخْذِ بعض المواقع منه، لكِنَّ السلطان العثماني اضطُرَّ إلى تركه والتوجُّه إلى الجيش المجري الذي بدأ بالثوران للثأر من هزيمة وقعةِ فارنا."},{"id":3420,"title":"وفاة السلطان شاه رخ بن تيمورلنك سلطان هراة، وسمرقند .","date":["العام الهجري :851","العام الميلادي :1447"],"text":"هو السلطان القان معين الدين شاه رخ ابن الطاغية تيمورلنك كوركان بن أيتمش قنلغ بن زنكي بن سنيا بن طارم بن طغريل بن قليج بن سنقور بن كنجك بن طغر سبوقا بن التاخان، المغولي الأصل، من طائفة جغتاي، سلطان هراة، وسمرقند، وشيراز، وما والاها من بلاد العجم وغيرها. مَلَك البلاد بعد ابن أخيه خليل بن أميران شاه بن تيمورلنك، فإنَّه لما مات والده الطاغية تيمورلنك بأهنكران شرقي سمرقند، وثب خليلٌ على الأمر وتسلطن، وبلغ شاه رخ هذا الخبر في هراة، فجمع ومشى إليه، ووقعت بينهما حروب وخطوب إلى أن ملك شاه رخ، واستقَلَّ بممالك العجم وعراقة، وعظُمَ أمره وهابته الملوك، وحُمِدَت سيرتُه، وشُكِرت أفعاله، وقَدِمَت رسله إلى البلاد المصرية مرارًا عديدة, وراسلته ملوكُ مصر، إلى أن تسلطَنَ الملك الأشرف برسباي، وقع بينهما وحشة بسبب طلب شاه رخ أن يكسوَ البيت الشريف، فأبى الأشرفُ برسباي وخشَّن له الجواب. وترددت الرسلُ بينهما مرارًا، واحتجَّ شاه رخ أنه نذر أن يكسو البيت الشريف، فلم يلتفت الأشرفُ إلى كلامه، ورد قصَّاده إليه بالخيبة. ولَمَّا آل المُلك إلى المَلِك الظاهر جقمق، أذن له بكسوتها, واستمرَّت الصحبةُ بين الملك الظاهر جقمق وبين شاه رخ إلى أن مات شاه رخ في سنة 851. تولى الملك بعده حفيدُه علاء الدولة بن باي سنقر، نصبته جدتُه لأبيه كهرشاه خاتون، أرادت بولاية علاء الدولة، وعدم ولايتها ولَدَها ألوغ بك صاحب سمرقند، أن يكون الأمرُ إليها. فلما سمع ألوغ بك ذلك عزَّ عليه، وحشد ومشى إلى والدته كهرشاه وإلى ابن أخيه علاء الدولة بن باي سنقر، ووقع له معهما أمور وحوادث، ثم قُتِلَ ألوغ بك, واستمرت الفتنة بين بني تيمور. ولم يعُدْ بيت تيمور صالحًا للحكم بعد موت شاه رخ وقتْلِ ولده ألوغ بك صاحب سمرقند. كان شاه رخ ملكًا عادلًا ديِّنًا خَيِّرًا، فقيهًا متواضعًا، محبَّبًا لرعيته، غير محجوب عنهم، لم يسلك طريقة والده الطاغية تيمورلنك- لعنه الله وقبَّحه- كان يحب أهل العلم والصلاح، ويكرِمُهم ويقضي حوائجَهم. وكان متضعفًا في بدنه، يعتريه مرضُ الفالج فلا يزال يتداوى منه. وكان يحبُ السَّماع الطيب، وله حظٌّ منه، بل كان يَعرِفُ يضرب بالعود، وكان ينادمه الأستاذ عبد القادر بن الحاج غيبى ويختصُّ به، وكان له حظ من العبادة وله أوراد هائلة، لم يزل غالبَ أوقاته على طهارة كاملة، مستقبِلَ القبلة والمصحفُ بين يديه، وكان مَسيكًا لا يصرف المالَ إلا لحقه."},{"id":3421,"title":"إعادة الشريف بركات بن حسن أميرًا على مكة .","date":["العام الهجري :851","الشهر القمري : شعبان","العام الميلادي :1447"],"text":"في يوم الخميس أول شعبان قدم الشريف بركات بن حسن بن عجلان مصرَ، ونزل الملك الظاهر جقمق إلى لقائِه خارج القاهرة، وبالغ السلطانُ في إكرام بركات، وقام إليه ومشى له خطوات، وأجلسه بجانبه، ثم خلع عليه، وقيَّد له فرسًا بسرج ذهبٍ وكنبوش زركش، وركب مع السلطان، وسار إلى قريبِ قلعة الجبل، فرسم له السلطانُ بالعود إلى محلٍّ أنزله به، وهو مكان أخلاه له المقرُّ الجمالي ناظر الخواص، ورتَّب له الرواتب الهائلة، وقام الجمالي بجميع ما يحتاج إليه بركات، من الكلَفِ والخدم السلطانية وغيرها، وكان أيضًا هو القائم بأمره، إلى أن أعاده إلى إمرة مكة، والسفيرُ بينهما الخواجا شرف الدين موسى التتائي الأنصاري التاجر."},{"id":3422,"title":"وفاة الشيخ ابن قاضي شهبة الدمشقي الشافعي .","date":["العام الهجري :851","الشهر القمري : ذي القعدة","العام الميلادي :1448"],"text":"هو العلامة الشيخ تقي الدين أبو بكر بن أحمد بن محمد بن عمر الدمشقي الشافعي، المعروف بابن قاضي شهبة نسبةً إلى جده عمر الذي كان قاضيًا بشهبة من قرى حوران. ولد أبو بكر سنة 779، انتهت إليه الرئاسة في فقه مذهبه وفروعه، وكان وليَ قضاء دمشق وخطب في واقعة الجكمي للملك العزيز يوسف، فحقَدَ عليه الملك الظاهر جقمق ذلك، وعزله، إلى أن مات، بعد أن تصدى للإفتاء والتدريس سنين كثيرة، وانتفع به غالبُ طلبة العلم بدمشق، وصنَّف التصانيف المفيدة، من أشهَرِها تاريخه المشهور باسم الإعلام بتاريخ أهل الإسلام، وله طبقات الشافعية، وبه مناقب الشافعي، وله الكواكب الدرية وهو في سيرة نور الدين الشهيد الزنكي، وله طبقات الحنفية، وله طبقات النحاة واللغويين، وله ذيل على تاريخ ابن كثير. توفي في ذي القعدة بدمشق فجأة."},{"id":3423,"title":"العثمانيون ينتصرون على المجريين في موقعة (كوسوفا) .","date":["العام الهجري :852","الشهر القمري : شعبان","العام الميلادي :1448"],"text":"بعد انتصار العثمانيين على الصليبين في فارنا كانت رغبة الثأر تأكل قلبَ هونياد قائد الجيش الصليبي المجري، وكان يريد الانتقامَ ومحو آثار هزيمتِه وهروبه من ساحة القتالِ، لَمَّا رأى هونياد أنَّ السلطان العثماني مراد الثاني قد خلَدَ إلى الراحة تاركًا أعباء السلطنة لابنه محمد الذي كان ما يزال فتيًّا سولت لهم أنفسُهم نقضَ العهود التي كانوا قد أبرَموها مع السلطانِ مراد بزعم أنَّ هذه العهود لم تكن بإذن البابا الذي هو وكيلُ المسيح في الأرض، فنقض النصارى عهودَهم، وحشدوا الجيوشَ لمحاربة المسلمين، فقام بتجهيز الحملة الصليبية السادسة ضد العثمانيين، اشترك فيها مائةُ ألف جندي من المجر وألمانيا وبولونيا وصقلية ونابولي، وتألف الجيش من 38 كتيبة، معظمها لا تعرف لغة الأخرى. وحاصروا مدينة فارنا البلغارية الواقعة على ساحل البحر الأسود، والتي كانت قد تحرَّرت على أيدي المسلمين. لَمَّا سمع المسلمون في أدرنة بحركة الصليبيين وزحْفِهم انتابَهم الفزع والرعبَ، وبعث رجال الدولة إلى السلطان مراد يستعجلون قدومَه لمواجهة هذا الخطر، وخرج السلطان المجاهد من خلوته ليقود جيوش العثمانيين ضدَّ التحالف الصليبي، واستطاع مراد أن يتفق مع الأسطول الجنوي لينقُلَ أربعين ألفًا من الجيش العثماني من آسيا إلى أوربا تحت سمع الأسطول الصليبي وبصرِه في مقابل دينار لكلِّ جندي، وتقدَّم جيشُ الصليبين الجرار حتى صحراء كوسوفا والتقى بالجيش العثماني الذي يقوده مراد الثاني، واستمَرَّ اللقاء ثلاثة أيام، بدءا من 18 شعبان 852 (17 من أكتوبر 1448م) وفي اليوم الثالث نجح السلطان مراد في محاصرة العدو الذي أنهكَه التعبُ وضرباتُ القوات العثمانية المتتالية، وأغلق أمامه طريق العودة. عجز هونياد قائد الجيش الصليبي المجري عن المقاومة، حتى إذا حلَّ الظلام تمكن من الهرب، تاركًا خلفه 17 ألف قتيل وعشرات الآلاف من الأسرى، وأعاد هذا النصر ذكرى انتصارِ السلطان مراد الأول على لازار ملك الصربِ في هذا المكان سنة 791 (1389م) أي قبل 59 عامًا من النصر الثاني، كما قضى على آمال الأوربيين في إخراج العثمانيين من بلاد البلقان لعصورٍ طويلة."},{"id":3424,"title":"وفاة الحافظ أحمد ابن حجر العسقلاني .","date":["العام الهجري :852","الشهر القمري : ذي الحجة","العام الميلادي :1449"],"text":"هو أمير المؤمنين في الحديث قاضي القضاة، شيخُ الإسلام، حافظ العصر، رحلة الطالبين، مفتي الفِرَق، شهاب الدين أبو الفضل أحمد ابن الشيخ نور الدين علي بن محمد بن علي بن أحمد بن حجر، المصريُّ المولدِ والمنشأِ والدار والوفاة، العسقلانيُّ الأصلِ، الشافعيُّ، قاضي قضاة الديار المصرية وعالِمُها وحافظها وشاعرها، ولد في 23 شعبان بالقاهرة سنة 773. مات والده وهو حَدَث السن، فكفَلَه بعض أوصياء والده إلى أن كبرَ وحفظ القرآن الكريم، واشتغل بالمتجر، وتولَّع بالنظم، وقال الشعر الكثير المليح إلى الغاية, ثم حَبَّب الله إليه طلبَ الحديث فأقبل عليه وسَمِعَ الكثير بمصر وغيرها، ورحل وانتقى، وحصَّل وسَمِع بالقاهرة من شيخ الإسلام سراج الدين عمر البلقيني، والحافظين ابن الملقِّن والعراقي، وأخذ عنهم الفقه، ورحل إلى اليمن بعد أن جاور بمكة، وأقبل على الاشتغال والتصنيف، وبرع في الفقه والعربية، وصار حافظَ الإسلام، علَّامة في معرفة الرجال واستحضارهم، والعالي والنازل مع معرفةٍ تامة بعلل الأحاديث وغيرِها. وصار هو المعوَّلَ عليه في هذا الشأن في سائر أقطار الأرض، وقدوةَ الأمة، علَّامة العلماء، حجَّة الأعلام، مُحيي السنة، انتفع به الطلبة وحضر دروسَه جماعة من علماء عصره وقضاة قضاتِه، وقرأ عليه غالبُ فقهاء مصر، وأملى بخانقاه بيبرس نحوًا من عشرين سنة, ولَمَّا عُزِل عن منصب القضاة بالشيخ شمس الدين محمد القاياتي انتقل إلى دار الحديث الكاملية ببين القصرين، واستمَرَّ على ذلك، وناب في الحكم في ابتداء أمرِه عن قاضي القضاة جلال الدين عبد الرحمن البلقيني مدة طويلة، ثم عن الشيخ ولي الدين العراقي، ثم تنزَّه عن ذلك وتولى مشيخة خانقاه بيبرس الجاشنكير في دولة الملك المؤيد شيخ، وصار إذ ذاك من أعيان العلماء، وتصدر للإقراء والتدريس إلى أن ولَّاه الملك الأشرف برسباي قضاءَ القضاة الشافعية بالديار المصرية عوضًا عن قاضي القضاة علم الدين صالح البلقيني بعد عزلِه، وذلك في السابع والعشرين محرم سنة 827، فاستمَرَّ في المنصب ثم عُزِلَ عن القضاء وأعيد إليه، ثم عُزِلَ وأعيد أكثر من مرة. إلى أن طلب وأعيد عوضًا عن الشيخ ولي الدين محمد السفطي، وذلك في يوم الاثنين ثامن ربيع الآخرة سنة 852, وكان لولايته في هذه المرة يوم مشهود، فدام في المنصب إلى أن عزل نفسه في الخامس والعشرين جمادى الآخرة من هذه السنة، وولي من الغد عوضَه قاضي القضاة علم الدين صالح البلقيني، وهذه آخِرُ ولايته للقضاء, وانقطع شيخ الإسلام ابن حجر في بيته ملازمًا للاشغال والتصنيف إلى أن توفي بعد أن مرض أكثر من شهر. قال ابن تغري بردي: \"كان رحمه الله حافِظَ المشرق والمغرب، أميرَ المؤمنين في الحديث، انتهت إليه رئاسةُ علم الحديث من أيام شبيبتِه بلا مُدافَعةٍ، بل قيل: إنه لم يَرَ مِثلَ نفسه، قلتُ: وهذا هو الأصح. وكان ذا شيبةٍ نيرة ووقار وأبَّهة، ومهابة، هذا مع ما احتوى عليه من العقل والحكمة والسكون والسياسة، والدربة بالأحكام ومداراة الناس قبل أن يخاطب الشخصَ بما يكره، بل كان يحسِنُ لمن يسيء إليه ويتجاوز عمن قَدَر عليه, وكانت صفته ذا لحيةٍ بيضاء ووجه صبيحٍ، للقِصَرِ أقرب، وفي الهامةِ نحيف، جيدِّ الذكاء، عظيم الحذق لمن ناظره أو حاضره، راويةً للشعر وأيامِ من تقدمه وعاصره، فصيح اللسان، شجيَّ الصوت، هذا مع كثرة الصوم ولزوم العبادة، واقتفائِه طرق من تقَدَّمه من الصلحاء السادة، وأوقاته للطلبة مقسمة تقسيمًا لمن ورد عليه آفاقيًّا كان أو مقيمًا، مع كثرة المطالعة والتأليف والتصدي للإفتاء والتصنيف. وأما مصنفاته فإن أسماءها تستوعب مجلدًا كاملًا صغير الحجم\" مات رحمه الله ولم يخلِّفْ بعده مثله شرقًا ولا غربًا، ويكفيه شهرة أنه مؤلِّفُ كتاب: \"فتح الباري في شرح صحيح البخاري\" الذي لا يكاد يستغني عنه أحد، وله \"تغليق التعليق\" وكتاب \"الإصابة في تمييز الصحابة\" وكتاب \"تقريب التهذيب\" و \"تهذيب التهذيب\" و \"لسان الميزان\" و \"بلوغ المرام في أدلة الأحكام\"، وفي التاريخ: \"رفع الإصر عن قضاة مصر\" وكتاب \"الإعلام فيمن ولي مصر في الإسلام\" وغيرها من الكتب, وكلها تدل على سعة علمه في الحديث والرجال والعلل والفقه والخِلاف؛ مما أكسبه اسم الحافظ بحقٍّ. توفي في ليلة السبت الثامن والعشرين ذي الحجة، وصلِّيَ عليه بمصلاة المؤمني، وحضر السلطان الظاهر جقمق الصلاةَ عليه، ودفِنَ بالقرافة، ومشى أعيان الدولة في جنازته من داره بالقاهرة من باب القنطرة إلى الرملة، وكانت جنازته مشهودة إلى الغاية، حتى قال بعض الأذكياء: إنه حزر من مشى في جنازته نحو الخمسين ألف إنسان، وكان لموته يومٌ عظيم على المسلمين، وحتى على أهل الذمَّةِ."},{"id":3425,"title":"وفاة الأمير ألوغ بك بن القان صاحب مدينة هراة .","date":["العام الهجري :853","العام الميلادي :1449"],"text":"هو الأمير ألوغ بك بن القان معين الدين شاه رخ، ابن الطاغية تيمورلنك كوركان بن أيتمش قنلغ بن زنكي بن سنيا بن طارم بن طغريل بن قليج بن سنقور بن كنجك بن طغر سبوقا بن التاخان، المغولي الأصل، من طائفة جغتاي، وقيل: اسمه تيمور على اسم جدِّه، وقيل: محمد. صاحب سمرقند، فريد دهره ووحيد عصره في العلوم العقلية، والهيئة، والهندسة، طوسي زمانه، وهو حنفيُّ المذهب. ولد في حدود 790، ونشأ في أيام جدِّه، وتزوج في أيامه, ولما مات جدُّه تيمور وآل الأمر إلى أبيه شاه رخ ولَّاه سمرقند وأعمالها فحكمها نيِّفًا وثلاثين سنة، وعمل بها رصدًا عظيمًا انتهى به إلى سنة وفاته، وقد جمع لهذا الرَّصد علماء هذا الفنِّ من سائر الأقطار، وأغدق عليهم الأموالَ، وأجرى لهم الرواتبَ الكثيرة، حتى رحل إليه علماء الهيئة والهندسة من البلاد البعيدة، وهُرِعَ إليه كل صاحب فضيلة، وهو مع هذا يتلفت إلى من يسمع به من العلماء في الأقطار، ويُرسِلُ يطلب من سمِعَ به. هذا مع علمه الغزير وفضله الجمِّ واطلاعه الكبير وباعه الواسعِ في هذه العلوم، مع مشاركةٍ جيدة إلى الغاية في فقه الحنفية، والأصلين، والمعاني، والبيان، والعربية، والتاريخ، وأيام الناس. قيل: إنه سأل بعض حواشيه: ما تقول الناس عنِّي؟ وألحَّ عليه، فقال: يقولون: إنك ما تحفظ القرآنَ الكريم، فدخل من وقته وحَفِظَه في أقل من ستة أشهر حفظًا مُتقَنًا. وكان أسنَّ أولاد أبيه، واستمَرَّ بسمرقند إلى أن خرج عن طاعتِه ولدُه عبد اللطيف، وسببه أنه لما ملك ألوغ بك هراة طَمِعَ ابنه عبد اللطيف أن يوليَه هراة فلم يفعل، وولَّاه بلخ، ولم يعطِه من مال جدِّه شاه رخ شيئًا. وكان ألوغ بك هذا مع فضله وغزير علمِه مسيكًا كوالده لا يصرف المال إلا بحقه، فسأمَتْه أمراؤه لذلك، وكاتبوا ولده عبد اللطيف في الخروج عن طاعتِه، وكان في نفسه ذلك، فانتهز الفرصة وخرج عن الطَّاعة، وبلغ أباه الخبر فتجرَّد لقتاله، والتقى معه، وفي ظنِّه أن ولده لا يثبُت لقتالِه، فلما التقى الفريقان وتقابلا هرب جماعة من أمراء ألوغ بك إلى ابنه، فانكسر ألوغ بك وهرب على وجهه، وملك ولدُه سمرقند، وجلس على كرسي والده أشهرًا ثم بدا لألوغ بك العود إلى سمرقند، ويكون المُلك لولدِه، ويكون هو كآحاد الناس، واستأذن ولدَه في ذلك فأذن له، ودخل سمرقند وأقام بها، إلى أن قبض عبد اللطيف على أخيه عبد العزيز وقتله صبرًا في حضرة والده ألوغ بك، فعظم ذلك عليه، فإنَّه كان في طاعته وخدمته حيث سار، ولم يمكِنْه الكلام فاستأذن ولده عبد اللطيف في الحجِّ فأذن له، فخرج قاصدًا للحجّ إلى أن كان عن سمرقند مسافة يوم أو يومين، وقد حذَّر بعض الأمراء ابنَه منه، وحسَّن له قتله، فأرسل إليه بعض أمرائه ليقتُلَه، فدخل عليه مخيَّمه واستحيا أن يقول: جئتُ لقَتْلِك، فسلَّم عليه ثم خرج، ثم دخل ثانيًا وخرج، ثم دخل ففطن ألوغ بك، وقال له: لقد علمتُ بما جئتَ به فافعل ما أمَرَك به، ثم طلب الوضوء وصلَّى، ثم قال: واللهِ لقد علمت أنَّ هلاكي على يد ولدي عبد اللطيف هذا من يومِ وُلِدَ، ولكن أنساني القدر ذلك، والله لا يعيشُ بعدي إلَّا خمسة أشهُرٍ ثم يقتل أشرَّ قِتلةٍ، ثم سلَّم نفسَه فقُتِل، وقُتِلَ ولدُه عبد اللطيف بعد خمسة أشهر!!"},{"id":3426,"title":"انتشار طاعون في مصر .","date":["العام الهجري :853","الشهر القمري : صفر","العام الميلادي :1449"],"text":"فشا أمر الطاعون بالقاهرة، وتزايد، ثم أهلَّ صفر من سنة ثلاث وخمسين يوم الأربعاء، وفيه عظم الطاعون، ومات في هذا الشهر جماعةٌ كبيرة من الأمراء، وأعيان الدولة، ثم في يوم الاثنين عشرين صفر، تناقص الطاعون، وفي أواخر شهر ربيع الأول قلَّ الطاعون بالقاهرة، بعد أن مات به خلائق كثيرة، فكان من جملة من مات للسلطان جقمق فقط أربعة أولاد من صلبه، حتى لم يبقَ له ولد ذكر غير المقام الفخري عثمان."},{"id":3427,"title":"إنهاء الطاهريين للدولة الرسولية، وقيام دولتهم على أنقاضها  .","date":["العام الهجري :855","العام الميلادي :1451"],"text":"كانَ الطاهريُّون مشايخَ مَحلِّيينَ مِن منطقةِ رَداعَ حيث كانت لهمُ الرياسةُ فيها، وتابِعينَ لِبَني رَسولٍ، وقد توَطَّدتِ العَلاقةُ بينَ بَني طاهرٍ ودولةِ بَني رَسولٍ في أواخِرِ الدولةِ الرَّسوليةِ بمُصاهرةٍ تمت عامَ 836هـ بينَ المَلكِ الظاهرِ الرَّسوليِّ وابنةِ كَبيرِ آلِ طاهرٍ، الشَّيخِ طاهرِ بنِ معوضةَ، ثم صارَ آلُ طاهرٍ وُلاةً لآلِ رَسولٍ في جِهاتِهم، بل وامتَدَّ حُكمُهم إلى عَدَنٍ في فَتراتٍ لاحِقةٍ. وعندَما أيقنَ آلُ طاهرٍ مِن أنَّ أمرَ الرَّسوليِّينَ إلى زَوالٍ لا مَحالةَ، أعَدَّ الشيخُ علِيُّ بنُ طاهِرِ بنِ معوضةَ، الملقَّبُ بالمُجاهدِ مع أخيه المُلقَّبِ بالظافرِ، حَملةً لِحَربِ المَلكِ الرَّسوليِّ المَسعودِ في عَدَنٍ، ولكِنَّه عادَ مِن حَملتِه خائِبًا ولم يَتمَكَّنْ مِنَ القَضاءِ على خَصمِه المَسعودِ، ثم أعَدَّ نَفسَه إعدادًا أفضَلَ، فكَرَّرَ حَملَتَه على عَدَنٍ في عامِ 858هـ وتمكَّنَ هذه المرَّةَ مِن طَردِ المَسعودِ، ثم في شَهرِ رَجَبٍ مِنَ العامِ نَفسِه تمكَّنوا مِن دُخولِ عَدَنٍ وأسْرِ المؤيَّدِ هناك، آخرِ مُلوكِ دولةِ بَني رَسولٍ، وابتدأتِ الدولةُ الطاهريةُ بحُكم الأخوَيْنِ المُجاهدِ والظافرِ مِن آلِ طاهرٍ سنةَ 855هـ يَحكمان معًا، فبَسَطا سيطرتَهما على مناطقِ اليَمنِ، وأصبحا في حالةِ صِراعٍ مع الأئمةِ الزَّيديِّينَ، وفي حَربِ السيطرةِ على صَنعاءَ قُتِلَ المَلكُ الظافرُ، فتراجَعَ أخوه عنِ احتلالِها وترَكَها تحتَ سَيطرةِ الزَّيديِّينَ، بعدَ المَلكِ المُجاهدِ تولَّى ابنُ أخيه عبدُ الوهَّابِ بنُ داودَ الطاهريُّ، ولُقِّب بالمَنصورِ، وفي عهدِه انتقلت عاصمةُ الطاهريِّينَ مِن جُبَنَ إلى عَدَنٍ ثم تَعِزَّ، تولَّى بعدَه ابنُه عامرُ بنُ عبدِ الوهَّابِ، ولُقِّب بالظافرِ، وواجَه تمَرُّداتٍ وأخمَدَها، واستولى على ذِمارَ ثم دَخَل صَنعاءَ، حاول الإمامُ شَرَفُ الدِّينِ مُواجهةَ تَوسُّعِ الطاهريِّينَ، واتَّصلَ بالمماليكِ الشركسيةِ لِيُعينوه، وكانَ القائدُ المملوكيُّ حُسينٌ الكُرديُّ قد طلب مِنَ الطاهريِّينَ أنْ يُمدُّوه بقوةٍ في مُحاربةِ البُرتُغاليِّينَ، ولكنهم رَفضوا، فنزلَ إلى السَّواحلِ اليَمنيةِ وحارَبَهم، وكانت آخِرَ المَعارِكِ بَينَهم قُربَ صَنعاءَ، ولَقيَ المَلكُ الظافرُ عامِرُ بنُ عبدِ الوهَّابِ حَتفَه، وذلك عامَ 923هـ، وانتَهتْ بمَوتِه الدولةُ الطاهريةُ بعدَ 65 عامًا مِن قيامِها، ولم يَبقَ منها إلا جَيبُ عَدَنَ الذي تمكَّنَ الأميرُ عامرُ بنُ داودَ الطاهريُّ مِنَ الاحتِفاظِ به حتى قَضى عليه الأتراكُ."},{"id":3428,"title":"خبر قتل محمد الفاتح أخيه الرضيع .","date":["العام الهجري :855","العام الميلادي :1451"],"text":"اتُّهِم السلطان محمد الفاتح بقتلِ أخيه الرضيع أحمد بعد تولِّيه السَّلْطَنة، وخبَرُ هذا القتل نُقِل بدون خطامٍ أو زمام، فلم تذكُره مراجع التاريخ العثماني، وإنما لفَّقه أعداء الدولة العثمانية وخصومُها خاصةً من النصارى أو من العرب المخدوعين بالفكر القومي, والثابتُ أنَّ أحمد هذا مات غريقًا في حوض الماء بعد أن غَفَلت عنه مربيته."},{"id":3429,"title":"وفاة الخليفة العباسي المستكفي بالله سليمان .","date":["العام الهجري :855","الشهر القمري : محرم","العام الميلادي :1451"],"text":"هو الخليفة العباسي المستكفي بالله أبو الربيع سليمان ابن الخليفة المتوكِّل على الله أبي عبد الله محمد، توفي بالقاهرة يوم الجمعة الثاني محرم، ونزل السلطانُ الملك الظاهر جقمق للصلاة عليه بمصلاة المؤمني، ومشى في جنازته إلى أن شَهِد دفنَه، وربما أراد حملَ نعشِه في طريقه، ومات المستكفي وهو في عشر الستين، بعد أن أقام في الخلافة تسعَ سنين ونحو عشرة أشهر، وتولى الخلافةَ بعده أخوه أبو البقاء حمزة بغير عهدٍ منه، ولقِّبَ بالقائم بأمر الله."},{"id":3430,"title":"وفاة السلطان مراد الثاني بن محمد جلبي وتولي ابنه محمد (الفاتح) .","date":["العام الهجري :855","الشهر القمري : محرم","العام الميلادي :1451"],"text":"هو السلطان الغازي مراد الثاني بن محمد جلبي بن بايزيد بن مراد الأول بن أورخان بن عثمان بن أرطغرل, وهو سادس سلاطين العثمانيين. ولد مراد الثاني سنة 806 (1403م) وتولى سنة 824 (1421م) بعد موت أبيه وعمره ثماني عشرة سنة. كانت أيام حكمه مليئة بالجهاد والحروب, وقد افتتح أعماله بإبرام الصلح مع أمير القرمان والاتفاق مع ملك المجر على هدنة خمسِ سنوات حتى يتفرَّغ لإرجاع ما شقَّ عصا الطاعة من ولايات آسيا لكنْ حدَثَ ما شغله عن هذا العمل، وذلك أن إيمانويل إمبراطور القسطنطينية أطلق سراح عمه مصطفى بن بايزيد ليشغَلَه عن غزوه، فبدأ مراد بالقضاء على تمرد عمه مصطفى ابن بايزيد، فلما انتهى من القضاء على عمه توجه بقواته لحصار القسطنطينية سنة 825 (1421م) دون أن يتمكن من فتحها, ثم اتجه إلى ملوك أوربا فألزم أمير الصرب بدفع جزية سنوية وأن يزوِّجَه ابنته ويتنازل له عن بعض أراضي بلاده ويقطع علاقته بملك المجر, وأعاد مراد فتح مدينة سلانيك في ألبانيا, واعترف أمير الفلاخ بسيادة العثمانيين على بلاده, ثم تمرد أميرا الفلاخ والصرب بتحريض من ملك المجر فأخضعهما مراد الثاني بالقوة وأسر عشرات الآلاف من جنودهما، وفتَحَ مدينة سمندرية الواقعة في بلاد الصرب, ولما توفي أكبر أولاد السلطان واسمه علاء الدين حزن عليه حزنًا شديدًا وسئم الحياة فتنازل عن الملك لابنه محمد البالغ من العمر أربع عشرة سنة، وسافر هو إلى ولاية آيدين للإقامة بعيدًا عن هموم الدنيا وغمومها، لكنه لم يمكث في خلوته بضعة أشهر حتى أتاه خبر غدر ملك المجر فقام بجيشه لمحاربته فوجدهم محاصرين لمدينة وارنة الواقعة على البحر الأسود، فاشتبك القتال بين الجيشين وقُتِلَ ملك المجر, وبعد أن تم للمسلمين النصر واستخلاص مدينة وارنة رجع السلطان مراد إلى عزلته لكنه لم يلبث فيها هذه المرة أيضًا لأن عساكر الإنكشارية ازدروا بملكهم الفتى محمد الثاني وعصوه ونهبوا مدينة أدرنة عاصمة الدولة فرجع إليهم السلطان مراد الثاني في أوائل سنة 1445 م وأخمد فتنتهم ثم تنازل مراد الثاني عن السلطة لولده محمد، لكنه كان يضطر للعودة إلى الساحة السياسية وساحة القتال أكثر من مرة إلى أن توفي سنة 855 في الخامس من محرم، عن عمر يناهز الخمسين بعد أن قضى أيامًا كثيرة مجاهدًا كأنه سياج الإسلام، وبوفاته أصبح ابنه محمد متوليًا للسلطة تمامًا بكل زمامها، وكان عمره يومها يقارب الاثنين وعشرين سنة، ومحمد هذا هو المعروف بالفاتح؛ لأنه هو الذي فتح القسطنطينية."},{"id":3431,"title":"وفاة العلامة بدر الدين العيني .","date":["العام الهجري :855","الشهر القمري : ذي الحجة","العام الميلادي :1452"],"text":"هو العلامة قاضي القضاة بدر الدين أبو الثناء- وقيل أبو محمد- محمود ابن القاضي شهاب الدين أحمد بن موسى بن أحمد بن حسين بن يوسف بن محمود العينتابي الحنفي، قاضي قضاة الديار المصرية، وعالِمُها ومؤرِّخُها، وُلِدَ بعينتاب في رمضان سنة 762، ونشأ بها، وتفقه بوالده بعد حفظه القرآن الكريم، ثم رحل إلى حلب ثم القاهرة، إلى أن تولى فيها النظر في الأحباس- الأوقاف- ثم القضاء، كان مقربًا جدًّا من السلطان الأشرف برسباي، كان فقيهًا أصوليًّا نحويًّا، لغويًّا، وأفتى ودرَّس سنين، وصنف التصانيف المفيدة النافعة، وكتب التاريخ، ومن أشهر مصنفاته \"عمدة القاري في شرح صحيح البخاري\"، أما في التاريخ فاشتهر بكتابه الكبير \"عقد الجُمان في تاريخ أهل الزمان\"، وله \"مصطلح الحديث ورجاله\"، وله \"شرح الهداية في الفقه الحنفي\" وله \"شرح الكنز في الفقه الحنفي\" أيضًا وله \"شرح سنن أبي داود\" وله أكثر من كتاب في سير بعض السلاطين المماليك الشراكسة الذين عاصرهم. وله منظومة في سيرة الملك المؤيد شيخ, وكان نظمه منحطًّا إلى الغاية، وربما يأتي به بلا وزن، وقد جرد شيخُ الإسلام ابن حجر العسقلاني منها الأبياتَ الركيكة، والتي بلا وزن، فبلغت نحو أربعمائة بيت في كتاب، وسماه: \"قذى العين من نظم غرابِ البين\"، وكان بينهما منافسة. توفي في ليلة الثلاثاء رابع ذي الحجة، ودفن من الغد بمدرسته التي أنشأها تجاه داره بالقرب من جامع الأزهر."},{"id":3432,"title":"السلطان العثماني محمد الفاتح يستعد لحصار القسطنطينية .","date":["العام الهجري :856","العام الميلادي :1452"],"text":"منذ أن تولى محمد الفاتح السلطنة مشى على ما كان عليه أبوه من الجهاد والغزو؛ فأول ما بدأ به أن أرجع زوجة أبيه الأميرة الصربية النصرانية مارا إلى أبيها، ثمَّ بنى قلعة على مضيق البوسفور على الشاطئ الأوربي مقابِلَ القلعة التي بناها السلطان بايزيد على الشاطئ الآسيوي، كل ذلك ليُحكِمَ قبضته على المضيق ويمنعَ من وصول الإمدادات إلى القسطنطينية من مملكة طرابزون الواقعة على ساحل البحر الأسود شمال شرق الأناضول، ورأى قسطنطين أن محمد الفاتح عازم على دخول مدينته، فعرض دفع الجزية فرفض السلطان محمد ذلك، فاستنجد الإمبراطور قسطنطين بالدول النصرانية، فأرسل له البابا ثلاثين سفينة حربية لكنها هربت من القرن الذهبي، ثم طلب من الروس المساعدة لكنهم لم يكونوا وقتها أصحاب قوة، ثم إن الجنويين الذين كانوا في غلطة الواقعة في نقطة التقاء مضيق البوسفور مع القرن الذهبي، تظاهروا أنهم حياديون، ولكنهم أرسلوا دعمًا بقيادة جوستينان؛ قوة بحرية كبيرة اصطدمت مع السفن البحرية العثمانية، وتمكنت من هزمها والدخول إلى القرن الذهبي، ورفعت السلاسل في وجه السفن العثمانية، كل هذه الأمور كانت إرهاصات لفتح القسطنطينية."},{"id":3433,"title":"وفاة الملك الكامل خليل ابن الأشرف ملك حصن كيفا بديار بكر .","date":["العام الهجري :856","الشهر القمري : ربيع الأول","العام الميلادي :1452"],"text":"توفي الملك الكامل خليل ابن الملك الأشرف أحمد ابن الملك العادل سليمان، صاحب حصن كيفا من ديار بكر، تولى ملك الحصن بعد قتل أبيه الملك الأشرف سنة 836 على يد أعوان قرايلك, وتوفِّي هو قتيلًا بيد ولده في شهر ربيع الأول. وتولى ولده الملك من بعده، ولقِّبَ بالملك الناصر، ودام في مملكة الحصن إلى شهر رمضان من نفس السنة, فوثب عليه ابن عمه الملك حسن وقتله، وسلطن أخاه أحمد، ولقَّبه بلقب أبيه المقتول، الملك الكامل."},{"id":3434,"title":"وفاة السلطان الظاهر جقمق وتسلطن ابنه المنصور عثمان  .","date":["العام الهجري :857","الشهر القمري : محرم","العام الميلادي :1453"],"text":"هو السلطان الملك الظاهر سيف الدين أبو سعيد جقمق العلائي الظاهري الشركسي، السلطان الرابع والثلاثون من ملوك الترك، والعاشر من الجراكسة، ويذكر في أصله أنه أخذ من بلاده صغيرًا فاشتراه خواجا كزلك وجلبه إلى الديار المصرية، فابتاعه منه الأتابك إينال اليوسفي، وقيل: ولده أمير علي بن إينال وهو الأصح، وربَّاه عنده، فطلبه الملك الظاهر منه في سرحة سرياقوس، وأخذه وأعطاه لأخيه جاركس، وقد اختلفت الأقوال في أمر عتقه؛ فمن الناس من قال: إن أمير علي كان أعتقه قبل أن يطلُبَه الملك الظاهر منه، فلما طلبه الملك الظاهر سكت أمير علي عن عتقه لتنال جقمق السعادة بأن يكون من جملة مشتريات الملك الظاهر. تسلطن يوم خُلِعَ الملك العزيز يوسف، وهو يوم الأربعاء التاسع عشر من ربيع الأول سنة 842. كان قد خرج عن طاعة الظاهر جقمق الأمير قرقماس، فواقعه الملك الظاهر، فانهزم قرقماس واختفى، ثم ظُفِرَ به وضُرِبَ عنقه. ثم خرج عن طاعته تغرى برمش نائب حلب، ثم أينال الجكمي نائب الشام؛ فجهز إليهما العساكر، فقاتلوهما واحدًا بعد الآخر، فظَفِرَ بهما وقتلهما. وبعد قتل هؤلاء صفا الوقت للملك الظاهر، وأخذ وأعطى، وقرب أقوامًا وأبعد آخرين. ولم يزل في ملكه والأقدارُ تساعدُه، إلى أن بدأ المرض به في آخر السنة الماضية وما زال يزداد به حتى قويَ عليه جدًّا في أواخر شهر محرم من هذه السنة، ثم لما كان يوم الأربعاء العشرون من المحرم، تكلم السلطان مع بعض خواصِّه في خلع نفسه من السلطنة، وسلطنة ولده المقام الفخري عثمان في حياته، فروجِعَ في ذلك فلم يقبَلْ، ورسم بإحضار الخليفة والقضاة والأمراء من الغد بالدهيشة، فلما كان الغد، وهو يوم الخميس الحادي والعشرين محرم حضر الخليفة والقضاة وجميع الأمراء، وفي ظنِّ الناس أنه يعهد لولده عثمان بالملك من بعده كما هي عادة الملوك، فلما حضر الخليفة والقضاة عنده بعد صلاة الصبح، خلع نفسَه من السلطنة، وقال للخليفة والقضاة: الأمر لكم، انظروا فيمن تُسلطِنوه، أو معنى ذلك؛ لعِلمِه أنهم لا يعدلون عن ولده عثمان؛ فإنَّه كان أهلا للسلطنة بلا مدافعة، فلما سمع الخليفةُ كلام السلطان، لم يعدِلْ عن المقام الفخري عثمان، لِما كان اشتمل عليه عثمان من العلم والفضل، وإدراكِه سِنَّ الشبيبة، وبايعه بالسَّلطنة، وتسلطن في يوم الخميس ولقِّبَ بالملك المنصور، وعمره يومئذ نحو الثماني عشرة سنة تخمينًا، واستمرَّ الملك الظاهر مريضًا ملازمًا للفراش، وابنه الملك المنصور يأخذ ويعطي في مملكتِه، ويعزِلُ ويولي، والملك الظاهر في شُغلٍ بمرضه، وما به من الألم في زيادة، إلى أن مات في قاعة الدهيشة الجوانية بين المغرب والعشاء من ليلة الثلاثاء ثالث صفر وقرئ حوله القرآن العزيز، إلى أن أصبح وجُهِّزَ وغُسِّلَ وكُفِّن من غير عجلة ولا اضطراب، حتى انتهى أمرُه وحُمِل على نعشه، وأُخرِج به، وأمام نعشه ولده السلطان الملك المنصور عثمان ماشيًا وجميع أعيان المملكة إلى أن صلِّيَ عليه بمصلاة باب القلعة من قلعة الجبل، وصلى عليه الخليفة القائم بأمر الله أبو البقاء حمزة، وخلفه السلطان المنصور عثمان والقضاة وجميع الأمراء والعساكر، ثم حمل بعد انقضاء الصلاة عليه وأُنزِلَ من القلعة، حتى دفِنَ بتربة أخيه الأمير جاركس القاسمي المصارع، ولم يشهد ولده الملك المنصور دفنَه، وكانت مدة سلطنته أربع عشرة سنة وعشرة شهور ويومين."},{"id":3435,"title":"خلع السلطان المنصور عثمان بن جقمق وتسلطن الأشرف إينال .","date":["العام الهجري :857","الشهر القمري : ربيع الأول","العام الميلادي :1453"],"text":"لما تسلطن المنصور عثمان بن جقمق أساء تدبيرَ أمور الدولة فأخذ يعزِلُ ويولي ويعطي ويمنع دون رشدٍ ولا تدبيرٍ ولا توقيرٍ لكبير أو قديم، حتى أوغر صدورَ الأشرفية والمؤيدية عليه، وانتظم الصلح بين الطائفتين سرًّا فتحالفوا واتَّفقوا على الركوب في يوم بعينه، كل ذلك والمنصور ومماليك أبيه وحواشيه في غفلةٍ عن ذلك، وأكبَرُ همهم في تفرقة الإقطاعات والوظائف، وفي ظنِّهم أن دولتهم تدوم، وأنَّ الملك قد صار بيَدِهم، هذا مع عدم التفاتِهم لتقريبِ العُقلاء، ومشاورةِ ذوي التدبير وأرباب التجارب ممَّن مارس تغييرَ الدول والحروب والوقائع، وقد صار الناسُ عند الأمير الكبير إينال، ولَبِسوا السلاح، وأجمعوا على قتالهم، وأهلَّ شهر ربيع الأول يوم الاثنين، وفيه كان ابتداءُ الوقعة بين السلطان الملك المنصور عثمان وبين الأتابك إينال العلائي، وذلك أنَّه قدم الأمراء جميعًا إلى الرميلة يريدون طلوعَ القلعة، فتكاثرت المماليكُ عليهم واحتاطوا بهم، وأخذوهم غصبًا بأجمَعِهم، وعادوا بهم إلى بيت الأميرِ الكبير إينال العلائي، ولما اجتمع القومُ في بيت الأمير الكبير، وعَظُم جمعُهم، أتاهم الأمراءُ والخاصكية والأعيانُ من كل فجٍّ، حتى بقُوا في جمع موفور، فأعلنوا عند ذلك بالخروج عن طاعة الملك المنصور، والدخولِ في طاعة الأمير الكبير إينال، والأمير الكبير يمتنع من ذلك بلسانه، فلم يلتفتوا لتمنُّعِه، وأخفوا في لبس السلاح، فلَبِسوا في الحالِ عن آخِرِهم، وطلبوا الخليفةَ القائم بأمرِ الله حمزة، فحضر قبل تمامِ لُبسِهم السلاح، ولما حضر الخليفةُ أظهر الميل الكليَّ للأتابك إينال، وأظهر كوامِنَ كانت عنده من الملك المنصور وحواشيه وقام مع الأمراءِ في خلع المنصورِ أتمَّ قيام، ولما تكامل لبس المماليك والأمراء السلاح طلبوا من الأمير الكبير الركوبَ معهم والتوجُّهَ إلى بيت قوصون تجاهَ باب السلسلة، فامتنع تمنعًا ليس بذاك، ثم أجابهم في الحال، وركب هو والأمراءُ وحولهم العساكرُ مُحدِقة بهم إلى أن أوصلوهم إلى بيتِ قوصون، وأمَّا الملك المنصور لَمَّا بلغه ما وقع من القومِ في بيت الأمير الكبير تحقَّق مَن عنده من الأمراء والأعيان ركوبَ الأمير الكبير وخروجه عن الطاعة، فأمروا في الحال يشبك القرمي والي القاهرة أن يناديَ بطلوع المماليك السلطانية لأخذ النفقة، وأنَّ النفقة لكُلِّ واحد مائة دينار، فنزل يشبك من القلعة والمنادي بين يديه ينادي بذلك، إلى أن وصل إلى الرميلة تجاه باب السلسلة، فأخذته الدبابيسُ من المماليك، فتمَزَّقوا، وذهب القرمي إلى حال سبيلِه، ثم أمر الملك المنصور لأمرائِه وحواشيه بلُبس السلاح، فلبسوا بأجمعِهم، ولبس هو أيضًا، كل ذلك وآراؤهم مفكوكة، وكلمتهم غيرُ منضبطة، وابتدأ القومُ في القتال من يوم الاثنين هلال ربيع الأول، واشتدَّت الحرب، وجُرح من الطائفتين جماعة، وصار أمر الأميرِ الكبير في نموٍّ بمن يأتيه من المماليك السلطانية، ومضى نهارُ الاثنين بعد قتال كبيرٍ وقع فيه، وبات الفريقان في ليلة الثلاثاء على أُهبة القتال، وأصبحا يوم الثلاثاء على ما هم عليه من القتال والرميِ بالمدافع والنفوطِ والسهام من الجهتين، والجراحاتُ فاشية في الفريقين، ولم يكن وقت الزوال حتى كثُرَ عسكر الأمير الكبير إينال، واستفحل أمرُه، ثم في هذا اليوم لهج الخليفةُ أمير المؤمنين القائم بأمر الله حمزة بخلعِ الملك المنصور عثمان من الملك غيرَ مرة في الملأ، فقَوِيَ بذلك قلبُ أصحاب الأمير الكبير وجدُّوا في القتال، وتفرقَّوا على جهات القلعة، وجدُّوا في حصارها، وأصبحوا يومَ الأربعاءِ ثالث شهر ربيع الأول والقتال مستمِرٌّ، وأصحاب الملك المنصور تنسَلُّ منه إلى الأمير الكبير واحدًا بعد واحدٍ، ثم رسم الأمير الكبير بطلب القاضي محبِّ الدين بن الأشقر كاتب السر والقضاة الأربعة، فحضروا في الحال، وقد نزل الخليفةُ من القصر، وجلس عند الأمير الكبير هو والقضاة تكلَّموا مع الخليفة في خلع الملك المنصور عثمان بكلام طويل، ثم طلبوا بدر الدين ابن المصري الموقِّع فأملاه قاضي القضاة علم الدين صالح البلقيني الشافعي ألفاظًا كتبها تتضَمَّن القدحَ في الملك المنصور وخلْعَه من السلطنة، وكان ذلك في أوائل نهار الجمعة، وخُلِعَ الملك المنصور من المُلك وحَكَم القضاة بذلك، وكانت مدةُ سلطنة الملك المنصور شهرًا واحدًا وثلاثة عشر يومًا، ثم سأل قاضي القضاة من حضر المجلس عن سلطنة الأمير الكبير إينال عليهم، فصاحوا بأجمَعِهم: نحن راضون بالأمير الكبير، وكرَّر القاضي عليهم القولَ غيرَ مرة وهم يردون الجوابَ كمقالتهم أولًا، وفرحوا بذلك، وسُرُّوا غاية السرور، وانفَضَّ المجلس على خلع الملك المنصور وسلطنةِ الأتابك إينال، هذا والقتال مستمر أشد ما يكون بين الطائفتين، وأصبح الناسُ في يوم الأحد سابع شهر ربيع الأول والقتالُ مستمِرٌّ بين الفريقين، ثم استطاع الأمير إينال أن يملكَ القلعة ثم أخذ المنصور عثمان ورسم بتسفيرِه إلى الإسكندرية وسُجِنَ بها، ثم حضر الخليفةُ والقضاة الأربعة وسائر أمراء الدولة، وبويع الأميرُ الكبير إينال بالسلطنة، ولقِّبَ بالملك الأشرف، ولَبِس خِلعةَ السلطنة."},{"id":3436,"title":"فتح القسنطينية على يد السلطان العثماني محمد (الفاتح) .","date":["العام الهجري :857","الشهر القمري : جمادى الأولى","العام الميلادي :1453"],"text":"عرَضَ السلطان محمد بن مراد الثاني على إمبراطور القسطنطينية أن يسلِّمَها كي لا تصابَ بأذًى ولا يحِلَّ بالأهالي النكبات، وتعهَّد السلطان بحمايةِ العقائد وإقامةِ الشعائر، فرفض الإمبراطورُ ذلك، فقام السلطانُ بمحاصرة المدينة من الجانب الغربي من البَرِّ بجنود يزيد عددهم على مائتين وخمسين ألف مقاتل، ومن جهة البحر بمائة وثمانين سفينة بحرية، وأقام المدافِعَ حول الموقع، وكان من أهمِّها وأشهرها المدفعُ العظيم الذي صمَّمه له المجري أوربان خِصِّيصَى للسلطان، وهذا المدفَعُ كان يحتاج إلى سبعمائة شخص لجَرِّه، ويرمي كرة حجرية وزنها اثنا عشر رطلًا لمسافة ألف وستمائة متر، كما قام السلطان بنقل سبعين سفينة حربية إلى القرن الذهبي على ألواحٍ خشبية مسافة تقرُبُ من عشرة كيلومترات، وبهذا أحكم الحصارَ على القسطنطينية التي كان موقعُها يعطيها القوةَ؛ فهي محاطة بالمياه البحرية في ثلاث جبهات: مضيق البسفور، وبحر مرمرة، والقرن الذهبي الذي كان محميًّا بسلسلة ضخمة جدًّا تتحكم في دخول السفن إليه، بالإضافةِ إلى ذلك فإن خطينِ من الأسوار كانت تحيطُ بها من الناحية البرية من شاطئ بحر مرمرة إلى القرن الذهبي، يتخلَّلها نهر ليكوس، وكان بين السورين فضاءٌ يبلغ عرضه 60 قدمًا ويرتفِعُ السور الداخلي منها 40 قدمًا وعليه أبراجٌ يصل ارتفاعها إلى 60 قدمًا، وأمَّا السور الخارجيُّ فيبلغ ارتفاعُه قرابة خمس وعشرين قدمًا، وعليه أبراج موزَّعة مليئة بالجند، وبدأ الحصارُ يوم الجمعة السادس والعشرين ربيع الأول، ولكن كل المحاولات البحرية كانت تبوء بالفشل بسبب تلك السلاسل، أمَّا في البَرِّ فتمكنت المدافِعُ العثمانية من فتحِ ثغرة في الأسوار البيزنطية عند وادي ليكوس في الجزء الغربي من الأسوار، فاندفع إليها الجنودُ العثمانيون بكلِّ بسالة محاولينَ اقتحام المدينة من الثغرة، كما حاولوا اقتحامَ الأسوار الأخرى بالسلالم التي ألقَوها عليها، ولكِنَّ المدافعين عن المدينة بقيادة جستنيان استماتوا في الدفاعِ عن الثغرة والأسوار، واشتَدَّ القتال بين الطرفين، وكانت الثغرةُ ضيقة وكثرةُ السهام والنبال والمقذوفات على الجنود المسلمين، ومع ضيقِ المكان وشدة مقاومة الأعداء وحلول الظلام أصدر الفاتِحُ أوامره للمهاجمين بالانسحاب بعد أن أثاروا الرعب في قلوب أعدائهم متحيِّنين فرصة أخرى للهجوم، ثم لما رأى السلطان الفاتح أن المحاولات البحرية لا تجدي، أمر بنقل السفن الحربية برًّا إلى القرن الذهبي على الألواح الخشبية المدهونة بالزيت والدهون، وهذا العمل كان من معجزات ذلك الزمان في سرعته وكيفيته؛ حيث تم نقل سبعين سفينة في ليلة واحدة مسافة ثلاثة أميال برًّا خلف هِضاب غلطة وصولًا إلى القرن الذهبي، وبهذا تمكَّنوا من الالتفاف على السلسلة, واستمر العثمانيون في دكِّ نقاط دفاع المدينة وأسوارها بالمدافع، وحاولوا تسلُّق أسوارها، وفي الوقت نفسِه انشغل المدافِعونَ عن المدينة في بناء وترميم ما يتهدَّمُ من أسوار مدينتهم وردِّ المحاولات المكثفة لتسلُّق الأسوار مع استمرار الحصار عليهم، كما وضع العثمانيون مدافِعَ خاصة على الهضاب المجاورة للبسفور والقرن الذهبي، مهمتها تدمير السفن البيزنطية والمتعاوِنة معها في القرن الذهبي والبسفور والمياه المجاورة؛ مِمَّا عرقل حركةَ سُفُن الأعداء وأصابها بالشَّللِ تمامًا وحاول العثمانيون بكلِّ طريقة الدخول فحاولوا حفرَ الأنفاق تحت الأسوار لكنَّها كانت تبوء بالفشلِ، وحاولوا صنع أبراج خشبية أعلى من أسوار المدينة دون كلل ولا تعب، وكانت المدفعية العثمانية لا تنفكُّ عن عملها في دكِّ الأسوار والتحصينات، وتهدمت أجزاءٌ كثيرة من السور والأبراج وامتلأت الخنادق بالأنقاض، وبقي الهجومُ مكثفًا وخصوصًا القصف المدفعي على المدينة، حتى إن المدفع السلطاني الضخم انفجر من كثرة الاستخدامِ, وعند الساعة الواحدة صباحًا من يوم الثلاثاء 20 جمادى الأولى سنة 857 (29 مايو 1435م) بدأ الهجوم العام على المدينة بعد أن شجَّع السلطانُ المجاهدين ووعدهم بالأعطيات، وانطلق المهاجمون وتسلَّقوا الأسوار وقاتلوا من عارضَهم، وقد واصل العثمانيون هجومهم في ناحية أخرى من المدينة حتى تمكنوا من اقتحام الأسوار والاستيلاء على بعض الأبراج والقضاء على المدافعينَ في باب أدرنة، ورفعت الأعلامُ العثمانية عليها، وتدفَّق الجنود العثمانيون نحوَ المدينة من تلك المنطقة، ولما رأى قسطنطين الأعلامَ العثمانية ترفرف على الأبراج الشمالية للمدينة، أيقن بعدم جدوى الدفاعِ وخلع ملابِسَه حتى لا يُعرَفَ، ونزل عن حصانِه وقاتل حتى قُتِلَ في ساحة المعركةِ، ثم دخل السلطانُ كنيسة آيا صوفيا، ومنع أعمالَ السلب والنهب التي كانت قائمةً، ووصل إلى الكنيسة فأمر المؤذِّنَ أن يؤذِّنَ للصلاةِ وحوَّلها إلى مسجدٍ، وهو المسجِدُ المشهور في إسطنبول، وسمح السلطان للنصارى بتأدية شعائرهم وأعطاهم نصف كنائِسِهم محولًا النصف الآخر لمساجد، وأطلق على القسطنطينية اسمَ إسلامبول، وهي تعني: تخت الإسلام، أو مدينة الإسلام."},{"id":3437,"title":"فتح بلاد البلقان كلها عدا بلدتي بلغراد وغوسة .","date":["العام الهجري :857","الشهر القمري : رجب","العام الميلادي :1453"],"text":"بعد أن أتم السلطانُ محمد الفاتح فتحَ القسطنطينية، أراد التوجُّهَ إلى بلاد المورة فأرسل مَلِكُها وفدًا يعرضُ على السلطانِ دفع جزيةٍ سنوية مقدارُها اثنا عشر ألف دوك ذهبي، كما صالح أمير الصربِ مقابل جزية سنوية قدرها ثمانون ألف دوك ذهبي، ثم دخل السلطان إلى بلاد الصرب وحاصر بلغراد، ودافع عنها المجريون، ولم يتمكن العثمانيون من فتحها."},{"id":3438,"title":"خلع محمد العاشر ملك بني نصر وعودة المستعين سعد .","date":["العام الهجري :858","العام الميلادي :1454"],"text":"قام المستعين بالله سعد بن علي بن يوسف الثاني بخلع الأحنف محمد العاشر بن عثمان ملك بني نصر وتولي بدلًا عنه حُكمَ غرناطة، وقد تكرر الخلعُ بينهما أكثَرَ من مرة؛ فقد ثار الأمير سعد على الأحنف سنة 850 فخلعه، ثم لم يلبَث الأحنفُ أن عاد للحُكم وخلَعَ الأمير سعد بن علي بدعم من ملك قشتالة."},{"id":3439,"title":"زوال دولة بني رسول في زبيد وعدن .","date":["العام الهجري :858","العام الميلادي :1454"],"text":"وفي هذه السنة زالت دولةُ بنى رسول ملوك اليمن في زبيد وعدن بعد ما حكموا ممالكَ اليمن نحوًا من مائتين وثلاثين سنة, وكان أولُ ملوكهم الملكَ المنصور أبا الفتح عمر بن على بن رسول إلى آخر من ملَكَ منهم، وهو الملِكُ المسعود أبو القاسم بن إسماعيل الثاني، وقد استولى على جميع ممالك اليمن بعد بني رسول أمراءُ بني طاهر بزعامة الملك الطاهر صلاح الدين عامر الأول بن طاهر، ويُذكَرُ أن دولة بني رسول تأسَّست سنة 626."},{"id":3440,"title":"ضعف شأن الوزارة في عهد المماليك  .","date":["العام الهجري :859","الشهر القمري : صفر","العام الميلادي :1455"],"text":"في يوم الاثنين التاسع والعشرين صفر من هذه السنة استقرَّ شمس الدين نصر الله بن النجار ناظر الدولة وزيرًا عِوَضًا عن سعد الدين فرج بن النحال بحكم عزلِه، وكان قد طرأ على أمر الوزارة من الضعفِ ما جعل ابن تغري بردي يقول عنها: \"لم تَرَ عيني فيما رأيتُ ممن لبس خِلَعَ الوزارة أقبح زيًّا من ابن النجار، حتى إنَّه أذهب رونقَ الخِلعة مع حسن زيِّ خِلعةِ الوزارة وأبَّهة صفتها، ولو منَّ الله سبحانه وتعالى بأن يُبطِلَ اسمَ الوزير من الديار المصرية في هذا الزمانِ كما أبطلَ أشياء كثيرة منها، لكان ذلك أجودَ وأجمل بالدولة، ويصير الذي يلى هذه الوظيفة يسمَّى ناظر الدولة؛ لأنَّ اسم الوزارة عظيمٌ، وقد سمِّيَ به جماعةٌ كبيرة من أعيان الدنيا قديمًا وحديثًا في سائر الممالك والأقطار، مثل الصاحب إسماعيل بن عبَّاد، وهلَّم جرًّا، إلى القاضي الفاضل عبد الرحيم، ثم بني حنَّاء وغيرهم من العلماء والأعيان، إلى أن تنازلت ملوكُ مصر في أواخر القرن الثامن حتى ولِيَها في أيامهم أوباش النَّاسِ وأسافِلُ الكَتَبة الأقباط، وتغيَّرَ رسومها، وذهب بهم أبَّهة هذه الوظيفة الجليلة التي لم يكن في الإسلامِ بعد الخلافة أجَلُّ منها ولا أعظم، وصارت بهؤلاء الأصاغرِ في الوجود كلا شيء، وليت مع ذلك كان يلي هذه الوظيفةَ من هؤلاء الأسافلِ من يقوم بما هو بصَدَدِه، بل يباشر ذلك بعَجزٍ وضَعفٍ وظُلمٍ وعَسْفٍ، مع ما يمدُّه السلطانُ بالأموال من الخزانة الشريفة، فليت شعري لم لا كان ذلك مع من هو أهلٌ للوزارة وغيرِها، فلا قوة إلَّا بالله, وباشر ابن النجَّار الوزارة أشرَّ مباشرة، وأقبح طريقة، ولم تطُلْ أيَّامه، وعجز وبلغ السلطانَ عَجزُه، فلما كان يوم الخميس أول شهر ربيع الآخر طلب السلطان الوزراء الثلاثة ليختار منهم من يوليه، وهم: ابن النجَّار الذي عجز عن القيام بالكُلَف السلطانية، والصاحب أمين الدين بن الهيصم، وسعد الدين فرج بن النحَّال، فوقع في واقعة طريفةٍ، وهي أن السلطان لما أصبح وجلس على الدكَّة من الحوش استدعى أوَّلًا ابن النجَّار، فقيل له: هرب واختفى، فطلب أمينَ الدين بن الهيصم، فقيل له: مات في هذه الليلةِ، وإلى الآن لم يُدفَن، فطلب فرج بن النحَّال، فحضر، وهو الذي فَضَل من الثلاثة، فكلَّمه السلطان أن يستقرَّ وزيرًا على عادته، فامتنع واعتذر بقلَّة متحصَّل الدولة، وفي ظنِّه أن السلطان قد احتاج إليه بموتِ ابن الهيصم وتسحَّب ابن النجَّار، وشرع يكرِّرُ قوله بأنَّ لحم المماليكِ السلطانية المرتَّب لهم في كل يوم ثمانية عشر ألف رطل، خلا تفرقة الصُّرَر التي تعطى لبعض المماليك السلطانية وغيرهم، عوضًا عن مرتَّب اللحم، فلما زاد تمنُّعُه أمر به السلطان فحُطَّ إلى الأرض وتناولته رؤوسُ النوب بالضرب المبَرِّح إلى أن كاد يهلك، ثم أقيم ورُسِمَ عليه بالقلعة عند الطواشي فيروز الزمام والخازندار إلى أن عُمِلَت معه مصالحة وأعيد للوزارةِ\""},{"id":3441,"title":"فتنة المماليك الظاهرية ومحاولتهم خلع السلطان الأشرف إينال .","date":["العام الهجري :859","الشهر القمري : جمادى الآخرة","العام الميلادي :1455"],"text":"في يوم الاثنين آخر جمادى الآخرة كانت وقعةُ المماليك الظاهرية الجقمقية مع الملك الأشرف إينال، وسببُ هذه الفتنة ثورةُ المماليك الأجلاب أولًا، وأفعالُهم القبيحة بالناس، ثم عقب ذلك أنَّ السلطان كان عيَّنَ تجريدة إلى البحيرة، نحوًا من خمسمائة مملوك، وعليهم من أمراء الألوف الأمير خشقدم المؤيدي أمير سلاح، والأمير قرقماس رأسُ نوبة النوب، وعِدَّةٌ من أمراء الطبلخانات والعشرات، ورسم لهم السلطانُ بالسفر، ولم يفرِّقْ على المماليك المكتوبة للسفر الجمالَ على العادة، فعَظُم ذلك عليهم، وامتنَعوا إلى أن يأخذوا الجِمالَ، فسافر الأمير خشقدم في صبيحة يوم الاثنين المذكور، وتبعه الأمير قرقماس في عصر نهاره، وأقاما ببر منبابة تجاه بولاق، فلم يتبَعْهم أحد من المماليك المعيَّنة معهم، بل وقف غالبُهم بسوق الخيل تحت القلعة ينتظِرونَ تفرقةَ الجِمال عليهم، إلى أن انفَضَّ الموكب السلطاني ونزلت الأمراءُ إلى جهة بيوتهم، فلما صار الأميرُ يونس الدوادار بوسط الرميلة احتاطت به المماليك الأجلاب، وتحقق الغدرَ، فأمر مماليكه بإشهار سيوفِهم ففعلت ذلك، ودافعت عنه، وجرَحَ من المماليك الأجلاب جماعةً، وقطع أصابِعَ بعضِهم، وشقَّ بطنَ آخر على ما قيل، فعند ذلك انفرجت ليونس فرجةٌ خرج منها فارًّا إلى جهة داره، ونزل بها، ورمى عنه قماش الموكِبِ، ولَبِسَ قماشَ الركوبِ، وطلع من وقتِه إلى القلعةِ من أعلى الكبش، ولم يشق الرميلة، وأعلم السلطانَ بخبَرِه، فقامت لذلك قيامةُ المماليك الأجلاب، وقالوا: نحن ضربناهم بالدبابيس فضربونا بالسيوفِ، وثاروا على أستاذِهم ثورةً واحدةً، وساعدهم جماعةٌ من المماليك القرانيص وغيرِهم لِما في نفوسهم من السلطانِ لعدم تفرقةِ الجِمالِ وغيرها، ووقفوا بسوق الخيل وأفحشوا في الكلامِ في حقِّ السلطان، وهددوه إن لم يسلِّم لهم الأميرَ يونس، ثم ساقوا غارةً إلى بيت يونس الدوادار، فمنعهم مماليكُه من الدخول إلى داره، فجاؤوا بنار ليحرقوا الباب، فمنعوهم من ذلك أيضًا، فعادوا إلى سوق الخيل، فوافَوا المنادي ينادي من قبل السلطانِ بالأمان، فمالوا على المنادي بالدبابيس، فسكت من وقته، وهرب إلى حالِ سبيله، وقد طلعت جميعُ أمراء الألوف إلى السلطانِ، وهو على حالة السكوتِ غير أنه طلب بعضَ مماليكه الأجلاب الأعيان، وكلَّمه بأنَّه يعطي من جُرِحَ من الأجلاب ما يكفيه، وأنه يعطي للذي قُطِعَت أصابعه إقطاعًا ومائة دينار، فلم يقع الصلحُ، وانفضَّ الأمر على غير طائلٍ؛ لشدة حر النهار، ولما تفرقت المماليك نزلت الأمراءُ إلى دورهم ما خلا الأمير يونس الدوادار؛ فإنه بات في القلعة، فلما تضحى النهارُ أرسل إليهم السلطان بأربعة أمراء، وهم: الأمير يونس العلائي أحد مقدَّمي الألوف، وسودون الإينالي المؤيدي قراقاش رأس نوبة ثان، ويلباي الإينالي المؤيدي أحد أمراء الطبلخانات ورأس نوبة، وبردبك البجمقدار أحد الطبلخانات أيضًا ورأس نوبة، فنزلوا إليهم من القلعة؛ فما كان إلَّا أن وقع بصر المماليك الأجلاب على هؤلاء الأمراء احتاطوا بهم، وأخذوهم بعد كلامٍ كثير، ودخلوا بهم إلى بيتِ الأمير خشقدم أمير سلاح تجاه باب السلسلة، ورسموا عليهم بعضَهم، كلُّ ذلك والمماليك الظاهرية الجقمقية وقوفٌ على بُعدٍ، لا يختلفون بهم، لينظروا ما يصيرُ من أمرهم، فلما وقع ما ذُكِرَ تحققوا خروجَهم على أستاذهم، وثار ما عندهم من الكمائنِ التي كانت كامنةً في صدورهم من الملك الأشرف إينال لِما فَعَل بابن أستاذِهم الملك المنصور عثمان، وحَبْسِ خشداشيَّتِهم- زملائهم- وتقريب أعدائهم الأشرفية مماليك الأشرف برسباي، فانتهزوا الفرصة، وانضافوا إلى المماليك الأجلاب، وعرَّفوهم أن الأمر لا يتم إلا بحضرة الخليفةِ ولبس السلاح، فساق قاني باي المشطوب أحد المماليك الظاهريَّة من وقته إلى بيت الخليفة القائم بأمر الله حمزة، وكان في الخليفةِ خِفَّةٌ وطَيشٌ، فمال إليهم ظنًّا أنه يكون مع هؤلاء وينتَصِرُ أحدُهم ويتسلطنُ، فيستفحلُ أمره ثانيًا أعظَمَ من الأول، ولما حضر الخليفة عندهم، تكامل لُبسُهم السلاح، وانضافت إليهم خلائقُ من المماليك السيفية، وأوباش الأشرفية، وغيرُهم من الجياع الحرافيش، فلما رأت الأجلابُ أمر الظاهرية حسبوا العواقب، وخافوا زوالَ ملك أستاذهم، فتخلَّوا عن الظاهرية قليلًا بقليلٍ، وتوجه كل واحد إلى حالِ سبيله، فقامت الظاهريةُ بالأمر وحدهم، وما عسى يكونُ قيامهم من غير مساعدة، وقد تخلَّى عنهم جماعة من أعيانهم وخافوا عاقبةَ هذه الفتنة، وقد تعبَّأ السلطان لحربهم، ونزل من القلعة إلى باب السلسلة من الإسطبل السلطاني، وتناوش القومُ بالسهام، وأرادوا المصاففة، فتكاثر عليهم السلطانيةُ، وصدموهم صدمةً واحدة بدَّدوا شملهم، بل كانوا تشتَّتوا قبل الصدمة أيضًا، وهجم السلطانيةُ في الحال إلى بيت الأمير خشقدم أمير سلاح، وأخذوا الأمراءَ المرسَّم عليهم، وأخذوا فيمن أخذوا الخليفةَ معهم، وطلعوا بهم إلى السلطانِ، فلما رأى السلطان الخليفةَ وبَّخه بالكلام الخَشِن، وتفرقت من يوم ذاك أجلابُ السلطان فرقتين: فرقةٌ وهم الذين اشتراهم من كتابية الظاهر جقمق وابنه، وفرقةٌ اشتراهم هو في أيام سلطنته، وقويت الفرقةُ الذين اشتراهم على الفرقةِ الظاهرية، ومنعوهم من الطلوعِ إلى القلعة، والسكنى بالأطباق، ولما انتهت الوقعة أمسك جماعةً من المماليك الظاهرية وحبسهم بالبرج من قلعة الجبل، ونفى بعضَهم واختفى بعضُهم."},{"id":3442,"title":"خلع الخليفة العباسي القائم بأمر الله حمزة وتولية أخيه المستنجد بالله .","date":["العام الهجري :859","الشهر القمري : رجب","العام الميلادي :1455"],"text":"لما وقف الخليفةُ القائم بأمر الله في صفِّ المماليك الظاهرية في فتنتِهم ضِدَّ السلطان الأشرف إينال ظنًّا منه أنه يُخلَعُ فيزداد بذلك مرتبةً فوق التي هو فيها بوقوفِه مع هؤلاء المماليك، ولكن لما انكسر أمرُهم ومَسَك السلطانُ الأشرف إينال الخليفةَ ووبَّخه على وقفته هذه، أمر بحبسه بالبحرةِ من قلعة الجبل، وخلعه من الخلافة بأخيه يوسف في يوم الخميس ثالث شهر رجب، ثم أرسل الخليفةَ القائمَ بأمر الله في يوم الاثنين سابع رجب إلى سجن الإسكندرية، فسجن بها مدة سنين، ثم أُطلِقَ من السجن، وسكنَ بالإسكندرية إلى أن مات بها في أواخر سنة 862، فأصبح الخليفةُ هو أبو المحاسن يوسف بن المتوكل ولقِّب بالمستنجد بالله."},{"id":3443,"title":"وفاة العلامة العز عبد السلام القيلوي البغدادي .","date":["العام الهجري :859","الشهر القمري : رمضان","العام الميلادي :1455"],"text":"هو العلَّامةُ العِزُّ مجد الدين عبد السلام بن أحمد بن عبد المنعم بن أحمد بن محمد بن كيدوم بن عمر بن أبي الخير سعيد الحسيني القيلوي البغدادي ثم القاهري الحنبلي ثم الحنفي. ولدَ تقريبًا بعد سنة 770 والقيلوي نسبة لقرية بالجانب الشرقي من بغداد يقال لها قيلويه نشأ بها العز. قرأ القرآنَ لعاصم وحَفِظَ كتبًا جمة في فنون كثيرة، وبحث في غالب العلوم على مشايخ بغداد والعجم والروم، حتى إنه بحث في مذهبي الشافعي وأحمد وبرع فيهما وصار يقرأ كتبَهما ولازم الرحلةَ في العلم إلى أن صار أحدَ أركانه، وأدمن الاشتغال والأشغال بحيث بقي أوحدَ زمانه، ومن شيوخه في فقه الحنفية الضياء محمد الهروي أخذ عنه المجمع بعد أن حفظه، وسمع غالب الهداية على عبد الرحمن التشلاقي أو القشلاغي، وسمع عليه أصولَ الحنفية، وفي فقه الحنابلة محمد بن الحادي، وسمع عليه البخاري، وتزايد اشتغاله بالمذهب الحنبلي لكون والده كان حنبليًّا، وفي فقه الشافعية ناصر الدين محمد المعروف بأيادي الأبهري ولازمه مدة طويلة أخذ عنه فيها النحو والصرف، ولم يتسير له البحث في فقه المالكية، وقصد ذلك فما قدر، وأخذ أصول الدين وآداب البحث عن السراج الزنجاني، وأصول الفقه عن أحمد الدواليبي، وحضر بحث المختصر الأصلي لابن الحاجب والعضد وكثيرًا من شروح التلخيص في المعاني، وكثيرًا من الكشَّاف على ميرك الصيرامي أحد تلامذة التفتازاني، وبحث بعض الكشاف أيضًا والمعاني والبيان على عبد الرحمن ابن أخت أحمد الجندي، وجميع الشاطبية بعد حفظها على الشريف محمد القمني، والنحو عن أحمد بن المقداد وعبد القادر الواسطي، وبحث عليه الأشنهية في الفرائض بخلوة الغزالي من المدرسة النظامية ببغداد، وانتفع به في غير ذلك, وعُنِيَ بالطب والمعاني والبيان بعد حفظه للتلخيص عن المجد محمد المشيرقي السلطاني الشافعي, والمنطق بعد حفظه الشمسية عن القاضي غياث الدين محمد الخراساني الشافعي، كذا بحث عليه علم الجدل والطب عن موفق الدين الهمذاني، وسمع على موسى باش الرومي علم الموسيقى بحثًا، وارتحل إلى تبريز فأخذ بها عن الضياء التبريزي النحو وأصول الفقه، وعن الجلال محمد القلندشي فقه الشافعية وأصولهم، وحضر المعاني والبيان وبعض الكشاف عند حيدر، ثم ارتحل إلى أرزنجان من بلاد الروم فأخذ علم التصوف عن يارغلي السيواسي، ثم عاد من بلاد الروم بعد أن جال الآفاق وقاسى شدة مع تيمورلنك بحيث كانوا يقطعون الرؤوس ويحمِّلونه إياها إلى البلاد الشامية في سنة 810, ولقي بحلب مَن شاء الله من العلماء، وناظر في الشام الجمالَ الطيماني واجتمع في القدس بالشهاب بن الهائم فعظَّمه كثيرًا وارتحل إلى القاهرة بعد هذا كله, فأشير إليه في الصرف والنحو والمعاني والبيان والمنطق والجدل وآداب البحث والأصلين، والطب والعروض، والفقه والتفسير والقراءات، والتصوف وغيرها، فنزل بالجمالية وقرر في صوفيتها وأقبل الناس عليه فأخذوا عنه، وزوَّجه الشيخ مصطفى المقصاتي ابنته وتدرب به في عمل المقصات، وتكسب بها وقتًا مع اشتهاره بالفضيلة التامة حتى إنه لما تمت عمارة الجامع المؤيدي وحضر السلطان عند مدرسيه ومنهم البدر الأقصرائي الحنفي كان من جملة الحاضرين فلم يتكلم معه غيره، بحيث عظُمَ في عين السلطان، وأشار لما تم الدرس ورام المدرس الدعاء بنفسه مبالغة في تعظيم السلطان القيلوي أن يفعل ففعل، وأعلمه البدر بن مزهر وذلك قبل أن يلي كتابة السر بأنه رجل عالم يتكسب بعمل المقصات، فوعد ببناء مدرسة من أجله يكون هو شيخًا فما تيسر، وربما أقرأه ولده إبراهيم بل رام المؤيد الاجتماع به في محل خلوة للقراءة عليه، فما وافق العز خوفًا من إلصاق كثير مما يصدر عن السلطان به، وعُدَّ ذلك من وفور عقله، واستمر العز ملازمًا للإشغال غير مفتقر للاستفادة من أحد إلا في علم الحديث دراية ورواية؛ فإنه أخذ علوم الحديث جميعًا لابن الصلاح عن الولي العراقي بعد قراءته وسائره سماعًا، وسمع المنظومة في غريب القرآن، ومن أول السيرة الألفية إلى ذكر أزواجه والكثير من النكت على ابن الصلاح، وقرأ منها جميع الألفية الحديثية رواية، والمورد الهني، ومن غيرها الكثير من الأصول الكبار وغيرها، قال شمس الدين السخاوي: \" قرأ العز عبد السلام على شيخنا الكمال الشمني صحيح البخاري والنخبة له، واختص به كثيرًا، وكان أحد الطلبة العشرة عنده بالجمالية، وحضر دروسه وأماليه، ورأيت بخط شيخنا بتصنيفه النخبة كتبها برسمه قال في آخرها ما صورته: علقها مختصرها تذكرةً للعلامة مجد الدين عبد السلام نفع الله به آمين، وتمت في صبيحة الأربعاء ثاني عشر شوال سنة أربع عشرة، وقال في أولها ما نصه: رواية صاحبها العلامة الأوحد المفنن مجد الدين عبد السلام البغدادي، وكتب له عليها أنه قرأها قراءة بحث وإتقان وتقرير وبيان، فأفاد أضعاف ما استفاد، وحقق ودقق ما أراد، وبنى بيت المجد لفكره الصحيح وأشاد، ثم قال: وأذن له أن يُقرئها لمن يرى ويرويها لمن درى، والله يسلمه حضرًا وسفرًا، ويجمع له الخيرات زُمَرًا\" وأما الرواية فإنه سمع وقرأ على غير واحد وطلبها بنفسه فأكثر وكتب الطباق، وضبط الناس ورافق المتميزين، صار غالب فضلاء الديار المصرية من تلامذة العز عبد السلام، كل ذلك مع الخير والديانة والأمانة والزهد والعفة، وحب الخمول والتقشف في مسكنه وملبسه ومأكله، والانعزال عن بني الدنيا والشهامة عليهم وعدم مداهنتهم، والتواضع مع الفقراء والفتوة والإطعام وكرم النفس والرياضة الزائدة، والصبر على الاشتغال واحتمال جفاء الطلبة والتصدي لهم طول النهار، والتقنع بزراعات يزرعها في الأرياف ومقاساة أمر المزارعين، والإكثار من تأمل معاني كتاب الله عز وجل وتدبره، مع كونه لم يستظهر جميعه ويعتذر عن ذلك بكونه لا يحب قراءته بدون تأمل وتدبر، والمحاسن الجمة بحيث سمعت عن بعض علماء العصر أنه قال: لم نعلم من قَدِمَ مصر في هذه الأزمان مثل العز عبد السلام البغدادي, ولقد تجملت هي وأهلها به, وكان ربما جاءه الصغير لتصحيح لوحه ونحوه من الفقراء المبتدئين لقراءة درسه وعنده من يقرأ من الرؤساء، فيأمرهم بقطع قراءتهم حتى ينتهي تصحيح ذاك الصغير أو قراءة ذاك الفقير لدرسه، ويقول: أرجو بذلك القربة وترغيبهم وأن أندرج في الربانيين ولا يعكس، ولم يحصل له إنصاف من رؤساء الزمان في أمر الدنيا ولا أُعطي وظيفة مناسبة لمقامه، وكان فصيح اللسان مفوهًا طلْقَ العبارة قوي الحافظة سريع النظم جدًّا. مات في ليلة الاثنين الخامس العشر رمضان سنة تسع وخمسين، وصلى عليه من الغد بمصلى باب النصر، ودُفن بتربة الأمير بورى خارج باب الوزير تحت التنكزية، ولم يخلَّف بعده في مجموعِه مثله."},{"id":3444,"title":"فتنة المماليك الأجلاب بمصر .","date":["العام الهجري :860","الشهر القمري : جمادى الآخرة","العام الميلادي :1456"],"text":"في يوم الخميس الخامس عشر جمادى الآخرة من هذه السنة أمسك السلطان الأشرف إينال الأمير زين الدين الأستادار، واستقرَّ عِوَضَه في الأستادارية سعد الدين فرج بن النحال الوزير، فلمَّا سمعت المماليك الأجلاب بهذا العزل والولاية نزلوا من وقتهم غارةً إلى بيت الأستادار لينهبوه، فمنعهم مماليك زين الدين، وقاتلوهم وأغلقوا الدروبَ، فلما عجزوا عن نهب بيت زين الدين نهبوا بيوت الناسِ من عند بيت زين الدين فأخذوا ما لا يدخُلُ تحت حصر كثرةً، واستمرُّوا في النهب من نهار الغد إلى قريب العصر، وفعلوا بالمسلمين أفعالًا لا تفعلها الكفَرةُ ولا الخوارجُ، فكانت هذه الحادثةُ من أقبح الحوادث الشنيعة، ومن ثمَّ دخل في قلوب الناس من المماليك الأجلاب من الرجيف والرعب أمرٌ لا مزيد عليه؛ لعلمهم أنه مهما فعلوا جاز لهم، وأنَّ السلطان لا يقوم بنصرِ من قُهِرَ منهم، وفي يوم الأربعاء الثالث والعشرين رمضان نودي بالقاهرة من قبل السلطان بعدم تعرُّض المماليك الأجلاب إلى الناس والباعة والتجار، فكانت هذه المناداة كضرب رباب أو كطنين ذباب، واستمرُّوا على ما هم عليه من أخذِ أموال الناس والظلمِ والعنف حتى غلت الأسعارُ في سائر الأشياء من المأكول والملبوس والغلال والعلوفات، وصاروا يخرجون إلى ظواهر القاهرة، ويأخذون ما يريدون بأبخس الأثمان، إن أعطوا ثمنًا، وإن شاؤوا أخذوه بلا ثمنٍ، ثم شرعوا في نهب حواصل البطيخ الصيفي وغيره، ثم تزايد أمرُهم، فغلت جميع الأسعار مع كثرتِها عند أربابها، فضرَّ ذلك بحال الناس قاطبة؛ رئيسِها وخسيسِها."},{"id":3445,"title":"محمد الفاتح يضم بلاد الصرب ويحاصر مدينة بلغراد .","date":["العام الهجري :861","العام الميلادي :1456"],"text":"التقى السلطان العثماني محمد الفاتح مع هونياد زعيم الصرب في معركة انتهت بقتل هونياد واستيلاء العثمانيين نهائيًّا على بلاد الصرب وجعْلها ولاية عثمانية، ولكن بقيت بلغراد التي حاصرها السلطانُ ومعه مائة وخمسون ألف مقاتل ومعه مائتا سفينة حربية، ولكنه فَشِلَ مع كثرة الغارات؛ وذلك بسبب الجرح الذي أصاب السلطان محمد الفاتح؛ مما اضطره للعودة عن الحصار، ولكنَّه فتح في عوده دوقية أثينا التي كانت بيد عائلة من فلورنسة."},{"id":3446,"title":"فتنة المماليك الأجلاب على السلطان بمصر .","date":["العام الهجري :861","الشهر القمري : صفر","العام الميلادي :1457"],"text":"في يوم الخميس ثالث صفر ثارت المماليك الأجلاب على السلطان، وأفحشوا في أمرِه إلى الغاية، فبينما هو جالسٌ بقاعة قلعة الدهيشة، وكانت الخدمةُ بطالةً في هذا اليوم، وذلك قبل أن يصلِّيَ السلطان الصبح، وإذا بصياح المماليك، فأرسل السلطانُ يسأل عن الخبر، فقيل له إن المماليك أمسكوا نوكار الزردكاش وهددوه بالضرب، وطلبوا منه القرقلات-جمع قرقل وهو ثوب بغير كمين- التي وعدهم السلطان بها من الزردخاناه السلطانية، فحلف لهم أنه يدفع لهم ذلك في أول الشهر، فتركوه ومضَوا، فلقوا الشيخ عليًّا الخراساني الطويل محتسب القاهرة، وهو داخل إلى السلطان، فاستقبلوه بالضرب المبَرِّح المتلِف، وأخذوا عمامتَه من على رأسه، فرمى بنفسه إلى باب الحريم السلطاني حتى نجا، ثم إنَّ الصياح قوي ثانيًا فعُلم أن ذلك صياح الأجلاب، فأرسل إليهم الأميرُ يونس الدوادار، فسألهم يونس عن سبب هذه الحركة، فقالوا: نريد نقبض جوامكنا- المخصصات- كل واحد سبعة أشرفية ذهبًا في كل شهر، وكانت جامكية الواحد منهم ألفين قبل تاريخه يأخذها ذهبًا وفضة، بسعر الذهب تلك الأيام، فلما غلا سعر الذهب تحيَّلوا على زيادة جوامكهم بهذه المندوحة، ثم قالوا: ونريد أن تكون تفرقة الجامكية في ثلاثة أيام، أي على ثلاث نفقات كما كانت قديمًا، ونريد أيضًا أن يكون عليقنا السلطاني الذي نأخذه من الشونة مُغَرْبلًا، ويكون مرتبنا من اللحم سمينًا, فعاد الأمير يونس إلى السلطان بهذا الجواب، ولم يتفوَّه به إلى السلطان، وتربص عن ردِّ الجواب على السلطان حتى يفرغَ السلطان من أكل السماط، فأبطأ الخبر لذلك عن الأجلاب، فندبوا مرجانًا مقدَّم المماليك للدخول بتلك المقالة إلى السلطان، فدخل مرجان أيضًا ولم يخبِر السلطان بشيء حتى فرغ من أكل السماطِ، فعند ذلك عرفه الأمير يونس بما طلبوه، فقال السلطان: لا سبيل إلى ذلك، وأرسل إليهم مرجانًا المقدَّم يعرفهم مقالة السلطان، فعاد مرجان ثانيًا إلى السلطان بالكلام الأول، وصار يتردُّد مرجان بين السلطان والمماليك الأجلاب نحو سبعة مرار، وهم مصمِّمون على مقالتهم، والسلطان ممتنع من ذلك، وامتنع الناس من الدخول والخروج إلى السلطان خوفًا من المماليك؛ لما فعلوه مع العجمي المحتسِب، فلما طال الأمر على السلطان خرج هو إليهم بنفسه، ومعه جماعةٌ من الأمراء والمباشرين، فلما علموا بمجيء السلطان أخذوا في الرجم، فلما رأى شدةَ الرجم، قصد العودَ إلى الدهيشة، ورسم لمن معه من الأمراء أن ينزلوا إلى دورهم، فامتنعوا إلَّا أن يوصلوه إلى باب الحريم، فعاد عليهم الأمر فنزلوا من وقتهم، وبقي السلطان في خواصِّه وجماعة المباشرين وولده الكبير المقام الشهابي أحمد، فلما سار السلطان إلى نحو باب الستارة، ووصل إلى باب الجامع أخذه الرجمُ المفرط من كل جهة، فأسرع في مشيته والرجم يأتيه من كل جانب، وسقط الخاصكي الذي كان حامِلَ ترس السلطان من الرجم، فأخذ الترسَ خاصكيٌّ آخر فضُرِبَ الآخر فوقع وقام، وشج دوادار ابن السلطان في وجهه وجماعة كثيرة، وسقطت فردةُ نعل السلطان من رجله فلم يلتفت إليها لأنَّه محمول من تحت إبطيه مع سرعة مشيهم إلى أن وصل إلى باب الستارة، وجلس على الباب قليلًا، فقصدوه أيضًا بالرجم، فقام ودخل من باب الحريم وتوجه إلى الدهيشة، واستمر وقوف المماليك على ما هم عليه إلى أذان المغرب، وبات القوم وهم على وجل، والمماليك يكثرون من الوعيد في يوم السبت؛ فإنهم زعموا أن لا يتحركوا بحركةٍ في يوم الجمعة مراعاةً لصلاة الجمعة، وأصبح السلطان وصلَّى الجمعة مع الأمراء على العادة، فتكلم بعض الأمراء مع السلطان في أمرهم بما معناه أنه لا بد لهم من شيء يطيب خواطرهم به، ووقع الاتفاق بينهم وبين السلطان على زيادة كسوتهم التي يأخذونها في السنة مرة واحدة، وكانت قبل ذلك ألفين، فجعلوها يوم ذاك ثلاثة آلاف درهم، وزادوهم أيضًا في الأضحية، فجعلوا لكل واحد ثلاثة من الغنم الضأن، فزيدوا رأسًا واحدًا على ما كانوا يأخذونه قبل ذلك، ثم رُسِمَ لهم أن تكون تفرقة الجامكية على ثلاث نفقات في ثلاثة أيام من أيام المواكب، فرَضُوا بذلك وخَمَدت الفتنة."},{"id":3447,"title":"العسكر المصري والشامي يسير لقتال ابن قرمان .","date":["العام الهجري :861","الشهر القمري : جمادى الآخرة","العام الميلادي :1457"],"text":"في يوم السبت أول شهر ربيع الآخر نودي في المماليك السلطانية المعينين إلى تجريدة البلاد الشامية لقتال ابن قرمان، ثمَّ في يوم الخميس خامس جمادى الأولى برز الأمراء والعساكر من القاهرة إلى الريدانية خارج القاهرة، وأقاموا بالريدانية إلى ليلة الاثنين تاسِعَه، فاستقلوا فيه بالمسير من الريدانية إلى جهة البلاد الشامية، ثم سافر الأمير نوكار الزردكاش، ومعه عدة من الرماة والنفطية وآلات الحصار وهو مريض، ورسم له أن يأخذ من قلعة دمشق ما يحتاج إليه من أنواع الآلات وغيرها للحصار، ويلحق العساكر المتوجِّهة لقتال ابن قرمان، وفي يوم الثلاثاء الرابع عشر جمادى الأولى ورد الخبر على السلطان بوصول العساكر المتوجهة لقتال ابن قرمان إلى حلب، وأنه اجتمع رأي الجميع على السير من حلب إلى جهة ابن قرمان في يوم السبت السادس والعشرين جمادى الآخرة، ثمَّ في يوم الاثنين رابع شعبان وصل الخبر من الأمير خشقدم أمير سلاح ومن رفقته النواب بالبلاد الشامية بأنهم وصلوا إلى بلاد ابن قرمان، وملكوا قلعة دوالي، ونهبوها وأخربوها، وأنهم جهَّزوا الأمير بردبك البجمقدار رأس نوبة ومعه عدَّةٌ من المماليك السلطانية والأمراء بالبلاد الشاميَّة إلى جهةٍ من جهات بلاد ابن قرمان، فصدفوا في مسيرهم عسكرًا من أصحاب ابن قرمان فواقعوهم وهزموهم، وأنَّه قُتل من المماليك السلطانية أربعة في غير المصاف، بل من الذين صدفوهم في أثناء الطريق، ثم ورد الخبرُ بأن العساكر المتوجهة إلى بلاد ابن قرمان قصدت العودَ إلى جهة حلب بعد أن أخذوا أربع قلاع من بلاد ابن قرمان، وأخربوا غالب قرى ممالكه، وأحرقوا بلاطه وسَبَوا ونهبوا وأمعنوا في ذلك، حتى إنهم أحرقوا عدة مدارس وجوامع، وذلك من أفعال أوباش العسكر، وأنهم لم يتعرَّضوا إلى مدينة قونية ولا مدينة قيصرية لنفودِ زادهم، ولضجَر العسكر من طول مدَّتِهم بتلك البلاد، مع غلوِّ الأسعار في المأكل وغيره من سائر الأشياء، ولولا هذا لاستولوا على غالب بلاد ابن قرمان، وأنَّ ابن قرمان لم يقاتل العسكر السلطاني، بل إنه انحاز إلى جهة منيعة من جهاته وتحصَّن بها هو وأعيان دولته، وترك ما سوى ذلك من المتاع والمواشي وغيرها مأكلةً لمن يأكله، فحصل له بما أخذ له وهَنٌ عظيم في مملكته."},{"id":3448,"title":"وفاة الكمال ابن الهمام الحنفي .","date":["العام الهجري :861","الشهر القمري : رمضان","العام الميلادي :1457"],"text":"هو الإمامُ العلامة كمال الدين محمد ابن الشيخ همام الدين عبد الواحد ابن القاضي حميد الدين عبد الحميد ابن القاضي سعد الدين مسعود الحنفي السيرامي الأصل المصري المولد والدار والوفاة، المشهور بابن الهمام، ولد سنة 790 بالإسكندرية ومات أبوه وكان قاضي الإسكندرية وهو ابن عشر أو نحوها، فنشأ في كفالة جدته لأمه، وكانت مغربية خيِّرة تحفظ كثيرًا من القرآن وقدم بصحبتها القاهرة فأكمل بها القرآن عند الشهاب الهيثمي وتلاه تجويدًا على الزراتيتي، وبالإسكندرية على الزين عبد الرحمن الفكيري، وكان شيخه يصفه بالذكاء المفرط والعقل التام والسكون، وحَفِظَ مختصر القدوري والمنار والمفصَّل للزمخشري وألفية النحو، ثم عاد بصحبتها أيضًا إلى الإسكندرية فأخذ بها النحو عن قاضيها الجمال يوسف الحميدي الحنفي، وقرأ في الهداية على الزين السكندري، وفي المنطق على العز عبد السلام البغدادي والبساطي، وعنه أخذ أصول الدين وقرأ عليه شرح هداية الحكمة لملا زادة, ولم يبرح عن الاشتغال بالمعقول والمنقول حتى فاق في زمن يسير أقرانه, وأشير إليه بالفضل التام والفطرة المستقيمة، بحيث قال البرهان الأبناسي أحد رفقائه حين رام بعضهم المشي في الاستيحاش بينهما: \"لو طلبت حجج الدين ما كان في بلدنا من يقوم بها غيره. ثم قال: وشيخنا البساطي وإن كان أعلم، فالكمال أحفظ منه وأطلق لسانًا، هذا مع وجود الأكابر إذ ذاك، بل أعلى من هذا أن البساطي لما رام المناظرة مع العلاء البخاري بسبب ابن الفارض ونحوه قيل له: من يحكم بينكما إذا تناظرتما، فقال: ابن الهمام لأنه يصلح أن يكون حَكَم العلماء\" وقال يحيى بن العطار: \"لم يزل يُضرَب به المثل في الجمال المفرد مع الصيانة وفي حسن النغمة مع الديانة، وفي الفصاحة واستقامة البحث مع الأدب\" واستمر يترقى في درج الكمال حتى صار عالِمًا مفننًا علَّامة متقنًا، درَّس وأفتى وأفاد، وعكف الناس عليه، واشتهر أمره وعظُم ذِكرُه، قال شمس الدين السخاوي: \"فقد كان إمامًا علامة عارفًا بأصول الديانات والتفسير والفقه وأصوله، والفرائض والحساب، والتصوف والنحو والصرف والمعاني والبيان، والبديع والمنطق والجدل والأدب والموسيقى، وجُل علم النقل والعقل، متفاوت المرتبة في ذلك, ومع قلة علمه في الحديث فهو عالم أهل الأرض ومحقِّق أولي العصر حُجة أعجوبة ذا حجج باهرة واختيارات كثيرة وترجيحات قوية, وقد تخرج به جماعة صاروا رؤساء في حياته، فمن الحنفية التقي الشمس والزين قاسم وسيف الدين، ومن الشافعية ابن خضر والمناوي. ومن المالكية عبادة وطاهر والقرافي, ومن الحنابلة الجمال بن هشام. وهو أنظَرُ من رأيناه من أهل الفنون ومن أجمعهم للعلوم وأحسنهم كلامًا في الأشياء الدقيقة وأجلدِهم على ذلك مع الغاية في الإتقان والرجوع إلى الحق في المباحث ولو على لسان آحاد الطلبة، كل ذلك مع ملاحة الترسل وحسن اللقاء والسمت والبِشر والبزَّة ونور الشيبة وكثرة الفكاهة والتودد والإنصاف وتعظيم العلماء، والإجلال لتقي الدين ابن تيمية وعدم الخوض فيما يخالف ذلك، وعلو الهمة وطيب الحديث ورقة الصوت وطراوة النغمة جدًّا, وسلامة الصدر وسرعة الانفعال والتغير والمحبة في الصالحين وكثرة الاعتقاد فيهم والتعهد لهم والانجماع عن التردد لبني الدنيا حتى الظاهر جقمق مع مزيد اختصاصه به، ولكنه كان يراسله هو ومن دونه فيما يسأل فيه\" وقد حجَّ غير مرة وجاور بالحرمين مدة، وشرب ماء زمزم- كما قاله في شرحه للهداية- للاستقامة والوفاة على حقيقة الإسلام معها. ونشر في الحرمين علمًا جمًّا, وعاد في رمضان سنة ستين وهو متوعِّك فسُرَّ المسلمون بقدومِه وعكف عليه من شاء الله من طلبته وغيرهم أيامًا من الأسبوع إلى أن مات في يوم الجمعة سابع رمضان، ودفِنَ من يومه، وصُلِّيَ عليه عصرًا بمصلى المؤمني، وكانت جنازته مشهودة، شهده السلطانُ فمَن دونه، قدِمَ للصلاة عليه قاضي مذهبه ابن الديري، ودُفِنَ بالقرافة في تربة ابن عطاء الله، ولم يخلف بعده في مجموعه مثله. وله مصنفات أشهرها فتح القدير في الفقه الحنفي، وله التحرير في أصول فقه الأحناف، وغيرها من المصنفات."},{"id":3449,"title":"حرائق هائلة في ساحل بولاق وفي القاهرة .","date":["العام الهجري :862","الشهر القمري : رجب","العام الميلادي :1458"],"text":"وقع حريق عظيم بساحل بولاق لم يُسمَعْ بمثله في سالف الأعصار إلا قليلًا، بحيث إنَّه أتى على غالب أملاك بولاق من ساحل النيل إلى خط البوصة التي هي محل دفن أموات أهل بولاق، وعجز الأمراء والحكام عن إخماده، وكان من أمر هذا الحريق أنه لما كان صبيحة يوم الجمعة سادس رجب هبت ريح عظيمة وعظمت حتى اقتلعت الأشجار وألقت بعض المباني، واستمرت في زيادة ونمو إلى وقت صلاة الجمعة، فلما كان وقت الزوال أو بعده بقليل احترق ربع الحاج عبيد البرددار بساحل البحر، وذهب الربع في الحريق عن آخره ومات فيه جماعة من الناس، كل ذلك في أقل من ساعة رمل، ثم انتقلت النار إلى ربع القاضي زين الدين أبي بكر بن مزهر وغيره، وهبت الرياح وانتشرت النيران على الأماكن يمينًا وشمالًا، وحاجب الحجَّاب وغيره من الأمراء والأعيان وكل أحد من الناس في غاية الاجتهاد في تخميد النار بالطفي والهدم، وهي لا تزداد إلا قوة وانتشارًا على الأماكن، إلى أن وصلت النار إلى ربع الصاحب جمال الدين ناظر الجيش والخاص، وإلى الحواصل التي تحته، وأحرقت أعلاه وأسفله، وذهب فيه من بضائع الناس المخزونة فيه ما لا ينحصر كثرة، وسارت النار إلى الدور والأماكن من كل جهة، هذا وقد حضر الحريق جميع أمراء الدولة بمماليكهم وحواشيهم، شيئًا بعد شيء، والأمر لا يزداد إلا شدة، إلى أن صار الذي حضر من الناس لأجل طفي النار كالمتفرِّج من عِظَم النار والعجز عن إخمادها، وصارت النار إذا وقعت بمكان لا تزال به حتى يذهب جميعه، ويضمحل عن آخره، فعند ذلك فطن كل أحد أن النار تسير من دار إلى دار إلى أن تصل إلى القاهرة؛ لعِظَم ما شاهدوا من هولها، والريح يتداول هبوبها من أول النهار إلى نصف الليل؛ ولشدة هبوب الريح صارت رياحًا؛ لأنها بقيت تهب من سائر الجهات، فيَئِس كل من كان له دار تحت الريح، وتحقق زوالها، وشرع في نقل متاعه وأثاثه، واستمر الأمراء والأعيان يشاهدون الحريق، ويطفئون ما قدروا عليه من أطراف المواضع المنفردة؛ وأما الحريق العظيم فلا يستجرئ أحد أن يقربه لعِظَمِه، بل يشاهدونه من بعيد، واستمروا على ذلك إلى بعد أذان عشاء الآخرة، ثم ذهب كل واحد إلى داره والنار عمالة إلى نصف الليل، فأخذ أمر الريح في انحطاط، فعند ذلك اجتهد كل أحد في إخمادها، وأقاموا على ذلك أيامًا كثيرة، والنار موجودة في الأماكن والجُدُر والحيطان، والناس تأتي لبولاق أفواجًا للفرجة على هذا الحريق العظيم، فكان عدة ما احترق فيه من الأرباع زيادة على ثلاثين رَبْعًا، كل رَبْع يشتمل على مائة سكن وأكثر، وما به من الحوانيت والمخازن ما خلا الدور والأماكن والأفران والحوانيت وغير ذلك، وقد اختُلِفَ في سبب هذا الحريق على أقوال كثيرة، منهم من قال: إنها صاعقة نزلت من السماء، ومنهم من قال: إن الأرض كأن النار تنبع منها، ثم بعد ذلك بأيام أشيع أن الذي كان يفعل ذلك ويلقي النار في الأماكن هم جماعة من القرمانية ممن أحرق العسكر المصري أمكنَتَهم لما توجهوا إلى تجريدة ابن قرمان، وشاع القولُ في أفواه الناس، ثم ظهر للناس بعد ذلك أن الذي صار يحرق من الأمكنة بالقاهرة وغيرها بعد حريق بولاق إنما هو مِن فِعلِ المماليك الجلبان، لينهبوا ما في بيوت الناس عندما تُحرق، فإنه تداول إحراق البيوت أشهرًا، ثم تداول الحريق بعد ذلك بخط بولاق والقاهرة، وقوي عند الناس أن الذي يفعل ذلك إنما هو من تركمان ابن قرمان، ثم وقع الحريق أيضًا في شعبان بأماكن كثيرة، وتداول الحريق بالقاهرة وظواهرها، وضرَّ ذلك كثيرًا بحال الناس، وقد قوي عندهم أن ذلك من فعل القرمانية والمماليك الأجلاب: يعنون بالقرمانية والأجلاب أن القرمانية إذا فعلوا ذلك مرةً ويقع الحريق، فتَنهَبُ المماليك الأقمشة وغيرها لِما يطلبون الدور المحروقة للطفي، فلما حسن ببال المماليك ذلك صاروا يفعلون ذلك."},{"id":3450,"title":"الجيش العثماني يفتح المورة وبلغراد وغيرها .","date":["العام الهجري :863","العام الميلادي :1458"],"text":"لم يستطع الجيش العثماني أن يفتح بلغراد سنة 861 بعد أن حاصرها ورجع الجيش بعد أن تعهد ملك الصرب بدفع جزية سنوية، ثم في هذه السنة استطاع الجيش العثماني بقيادة الصدر الأعظم محمود باشا بعد أن حاصر بلغراد وفتحها كما تمكَّن من فتح بلاد المورة من هذا العام، وفر مَلِكُها إلى إيطاليا، كما فتح الجزر التي في بحر إيجة قرب مضيق الدردنيل، كما عقد صلحًا مع إسكندر بك أمير ألبانيا، وكان قبل ذلك يرفض أن يعقد الصلح مع العثمانيين بعد أن هرب منهم، كما فتح ميناء أماستريس بعد أن توجه سرًّا إلى الأناضول، وهذا الميناء يتبع جنوة وأكثر سكانه من التجار، كما دخل ميناء سينوب واحتل مملكة طرابزون دون مقاومة وهي تابعة للقسطنطينية."},{"id":3451,"title":"تزايد فتنة المماليك الأجلاب بمصر .","date":["العام الهجري :863","الشهر القمري : رجب","العام الميلادي :1459"],"text":"تعرَّض جماعة من المماليك الأجلاب للأمير زين الدين الأستادار، فهرب منهم فضربوه، ولا يختلف اثنان في قوة شوكة الأجلاب في هذه الأيام، حتى تجاوزت الحدَّ، وبطل أمر حكام الديار المصرية قاطبةً، وصار من كان له حقٌّ أو شِبهُ حق لا يشتكي غريمَه إلا عند الأجلاب، ففي الحال يخلص حقه من غريمه، إما على وجه الحقِّ أو غيره، فخافهم كل أحد، لا سيما التجَّار والبَيَعة من كل صنف، وترك غالب الناس معايشَهم؛ خوفًا على رأس مالهم، فعزَّ بسبب ذلك وجود أشياء كثيرة، ووقع الغلاء في جميع الأشياء، ثم في يوم الأحد السابع عشر رجب تعرَّض بعض المماليك الأجلاب للقاضي محب الدين ابن الشحنة كاتب السر، وهو طالِعٌ إلى الخدمة السلطانية، وضربه من غير أمرٍ يوجِبُ ضربه أو الكلام معه، وفي يوم الأحد تاسع شعبان ضرب السلطان مملوكينِ من مماليكه الأجلاب وحبَسَهما؛ لأجل قتلهما نانق الظاهري، ولم يقتُلْهما به كما أمر الله تعالى, ثم في يوم الجمعة الثاني عشر رمضان نهبت العبيد والمماليك الأجلاب النسوةَ اللاتي حضرن صلاة الجمعة بجامع عمرو بن العاص بمصر القديمة، وأفحشوا في ذلك إلى الغاية، وفي يوم الأحد الحادي والعشرين منه أغلقت المماليك الأجلاب باب القلعةِ، ومنعوا الأمراء والمباشرين من النزول إلى دورِهم؛ بسبب تعويق عليقِ خيولهم، وفعلوا ذلك أيضًا من الغدِ إلى أن رُسِمَ لهم عوضًا عن كل عليقة مائتا درهم!"},{"id":3452,"title":"وفاة جلال الدين المحلي صاحب التفسير .","date":["العام الهجري :864","الشهر القمري : محرم","العام الميلادي :1459"],"text":"هو الإمام العلامة جلال الدين محمد بن أحمد بن إبراهيم بن أحمد بن هاشم بن الكمال الأنصاري المحلي الأصل نسبة للمحلة الكبرى من الغربية بالقاهرة، الشافعي المصري، ويعرف بالجلال المحلي. ولد في مستهل شوال سنة 791 ونشأ بها فقرأ القرآن وحفظ المتون واشتغل في فنون، فأخذ الفقه وأصوله والعربية وأفتى ودرَّس عدة سنين، وله عدة مصنفات، ولم يكمل بعضها، ورُشِّح لقضاء الديار المصرية غير مرة. قال شمس الدين السخاوي: \"مهَر المحلي وتقدم على غالب أقرانه وتفنَّن في العلوم العقلية والنقلية، وكان أولًا يتولى بيع البزِّ في بعض الحوانيت ثم أقام شخصًا عوضه فيه وتصدى هو للتصنيف والتدريس والإقراء، فشرح كلًّا من جمع الجوامع والورقات والمنهاج الفرعي والبردة، وأتقنها ما شاء مع الاختصار، وعمل منسكًا وتفسيرًا لم يكمل وغيرهما، ورَغِب الأئمة في تحصيل تصانيفه وقراءتها وإقرائِها وكان شيخنا ابن خضر يكثر من وصفه بالمتانة والتحقيق, وقرأ على جلال الدين من لا يحصى كثرة، وارتحل الفضلاء للأخذ عنه، وتخرج به جماعة درَّسوا في حياته، ولكنه صار بأخرة أيامه يستروح في إقرائه لغلبة الملل والسآمة عليه وكثرة المخبطين، ولا يصغي إلا لمن علم تحرزه خصوصًا، وهو حاد المزاج لا سيما في الحر، وإذا ظهر له الصواب على لسان من كان، رجع إليه مع شدة التحرز، وحدَّث باليسير وسمع منه الفضلاء، وقد ولِيَ تدريس الفقه بالبرقوقية، وبالمؤيَّدية وعرض عليه القضاء فأبى، وشافه الظاهرَ العجزَ عنه، بل كان يقول لأصحابه: إنه لا طاقة لي على النار، وكان إمامًا علامة محققًا نظَّارًا مفرط الذكاء صحيح الذهن؛ بحيث كان يقول بعض المعتبرين: إن ذهنه يثقب الماس، وكان هو يقول عن نفسه: إن فهمي لا يقبل الخطأ، حاد القريحة قوي المباحثة\" وأشهر مصنفاته هو التفسير الذي لم يكمله، وأكمله بعده جلال الدين السيوطي، والمعروف اليوم بتفسير الجلالين نسبة إليهما، وله كنز الراغبين في فقه الشافعية، وله البدر الطالع في شرح جمع الجوامع في أصول الفقه، وغيرها من المصنفات, وقد حج مرارًا. توفي بالقاهرة وسنه نحو ثلاث وسبعين بعد أن تعلل بالإسهال من نصف رمضان, وفي صبيحة يوم السبت مستهل محرم سنة أربع وستين، وصلِّيَ عليه بمصلى باب النصر في مشهد حافل جدًّا، ثم دفن مع آبائه بتربته التي أنشأها تجاه جوشن، وتأسف الناس عليه كثيرًا وأثنوا عليه جميلًا ولم يخلف بعده في مجموعة مثله، ورثاه بعض الطلبة بل مدحه في حياته جماعة من الأعيان."},{"id":3453,"title":"الأمير جاك يحضر إلى السلطان المملوكي ويطلب أن يوليه قبرص .","date":["العام الهجري :864","الشهر القمري : شعبان","العام الميلادي :1460"],"text":"حضر لمصر في هذه السنة جاك بن ملك قبرص بعد أن توفِّيَ والده ونصبوا على عرش قبرص أخته عوضًا عنه، قيل: لأنه ولَدُ زنا، وقيل غير ذلك، ثم بقي في مصرَ على أمل أن يوليه السلطان عرش قبرص, وحضر كذلك جماعة من قبرص نيابة عن أخته وهي تطلب كذلك أن تبقى هي الملكة, وفي يوم الثلاثاء سادس شعبان وقع في مصر أمرٌ شنيع بسبب هذا الأمر، وهو أن السلطان جمع أعيان الفرنج القبارصة في الملأ بالحوش السلطاني، وأراد بقاء الملكة صاحبة قبرص على عادتها، وخلَعَ على قصَّادها أعيان الفرنج، واستقَرَّ تغري بردي الطياري مُسفرها، وعلى يده تقليدُها وخِلعتُها، وكان الفرنجي جاك أخوها حاضر الموكب، وقد جلس تحت مقدمي الألوف، فعز عليه ولاية أخته وإبقاؤها على ملك الأفقسية من جزيرة قبرص مع وجوده، فقام على قدميه واستغاث وتكلَّم بكلام معناه أنه قد جاء إلى مصر، والتجأ إلى السلطان، ودخل تحت كنَفِه، وله عنده هذه المدة الطويلة، وأنه أحقُّ بالملك من أخته، وبكى، فلم يسمع السلطان له، وصمَّم على ولاية أخته، وأمره بالنزول إلى حيث هو سكَنُه، فما هو إلا أن قام جاك وخرج من باب الحوش الأوسط، ثم خرج بعده أخصامُه حواشي أخته، وعليهم الخِلَعُ السلطانية، فمَدَّت الأجلاب أيديها إلى أخصام جاك من الفرنج، وتناولوهم بالضربِ والإخراق، وتمزيق الخِلَع، واستغاثوا بكلمة واحدة: أنهم لا يريدون إلا تولية جاك هذا مكان والِدِه، وعظُمَت الغوغاء، فلم يسع السلطان إلا أن أذعن في الحال بعزلِ الملكة وتولية جاك، فتولى جاك على رغم السلطانِ، بعد أن أمعن المماليك الأجلاب في سبِّ الأمير بردبك الدوادار الثاني، وقالوا له: أنت إفرنجي وتحامي للفرنج، فاستغاث بردبك، ورمى وظيفة الدوادارية، وطلب الإقالة من المشي في الخدمة السلطانية، فلم يسمع له السلطان، وفي الحال خُلِعَ على جاك، ورسم بخروج تجريدة من الأمراء إلى غزو قبرص، تتوجَّهُ مع جاك إلى قبرص، ثم في يوم الثلاثاء السابع عشر شوال سافر المجاهدون في بحر النيل إلى ثغر دمياط ومعهم جاك هذا ليساعدوه على تولي الملك مكان أخته، ثم في يوم الجمعة الثالث والعشرين محرم من السنة التالية حضر البعض من هناك وأخبر أنهم ساروا على ظهر البحر الملح يريدون السواحل الإسلامية، فهبت ريح عظيمةٌ شتَّتَت شملهم، وتوجهوا إلى عدة جهات بغير إرادة، وترك بجزيرة جماعة من المماليك السلطانية ومماليك الأمراء قوة لجاك صاحب قبرص."},{"id":3454,"title":"صراع على السلطة بين الأمير جاك وأخته ملكة قبرص .","date":["العام الهجري :865","الشهر القمري : ربيع الآخر","العام الميلادي :1461"],"text":"وصل القاهرة كتابُ جانبك الأبلق الظاهري من قبرص أنَّه هو ومن معه من المماليك السلطانية وغيرهم من الفرنج واقعوا أهلَ شرينة في عاشر شهر ربيع الآخر، وحصروا قلعتَها، وقتلوا من الفرنج بشرينة ثمانية نفر، وأسروا مثلَهم، ثم ذكر أنه واقع ثانيًا أهل شرينة، وقتل صاحب الشرطة بقلعتها، وآخر من عظمائها رمى بنفسِه إلى البحر فغرق، وأنَّه قبض على خمسة منهم، وأن الملكة صاحبة شرينة أخت جاك صاحب قبرص قد توجَّهت من شرينة إلى رودس تستنجد بهم، ثم ذكر أنه ظَفِرَ بعدة مراكب ممَّن كان قَدِمَ من الفرنج نجدة للملكة، وأنه أسَرَ منهم خلائق تزيد عدَّتُهم على مائة نفر، وأنه أخذ بالحصار عدة أبراج من أبراج قلعة باف بعد أن قاسوا منه شدائد، وأنه يستحِثُّ السلطان في إرسال عسكر بسرعة قبل مجيء نجدةٍ لهم من الفرنج أهل الماغوصة الجنوية، وإلى أهل شرينة من غير الجنوية."},{"id":3455,"title":"وفاة السلطان الأشرف إينال وسلطنة ابنه الشهابي أحمد .","date":["العام الهجري :865","الشهر القمري : جمادى الأولى","العام الميلادي :1461"],"text":"هو السلطان الأشرف سيف الدين أبو النصر إينال بن عبد الله العلائي الظاهري ثم الناصري، أصله شركسي الجنس، أُخذَ من بلاده، فاشتراه خواجا علاء الدين علي، وقدم به إلى القاهرة، فاشتراه الملك الظاهر برقوق، ودام إينال كتابيًّا بطبقة الزمام، إلى أن مَلَكه الملك الناصر فرج بن برقوق وأعتقه. وهو السادس والثلاثون من ملوك الترك. تولى السلطنة بعد أن خلع المنصور عثمان بن السلطان جقمق سنة 857. تسلَّط في أيامه مماليك السلطان الأجلاب وتعدوا على العامة نهبًا وقتلًا دون أن يعمل السلطان لهم ما يردعهم, ولما أصيب السلطان بمرض الموتِ يوم السبت ثالث جمادى الأولى لزم الفراش، وفي يوم الأربعاء الرابع عشر طلب السلطان إينال الخليفةَ والقضاة الأربعة إلى القلعة، وطلعت الأمراء والأعيان، واجتمع الجميع بقاعة الدهيشة، وكان الطلب لسلطنة ولده المقام الشهابي أحمد قبل موته، فلما تكامل الجمعُ خلع السلطان نفسَه من السلطنة بالمعنى؛ لأنه ما كان إذ ذاك يستطيع الكلامَ، بل كلَّمَهم بما معناه أن الأمر يكون من بعده لولدِه، فعلموا من ذلك أنه يريد خلعَ نفسه وسلطنة ولده، ففعلوا ذلك، وتوفي السلطان من الغد، وكانت مدة تملكه ثماني سنين وشهرين وستة أيام، فجُهز من وقته، وغُسل وكُفن، وصُلي عليه بباب القلة من قلعة الجبل، ودُفن من يومه بتربته التي عمرها بالصحراء، وقد ناهز الثمانين من العمر، أما السلطان الجديد المؤيد أبو الفتح أحمد بن إينال فتسلطن في يوم الأربعاء رابع عشر جمادى الأولى وتلقَّب بالمؤيد أحمد وانتدب كاتب السر لتحليف الأمراء، فحلف من حضر من الأمراء الأيمان المؤكدة، فلما انقضى التحليف وتمت البيعة قام كل أحد من الأمراء والخاصكية والأعيان وبادر إلى لبس الكلفتاة والتتري الأبيض، كما هي العادة، وأُحضِرت خِلعة السلطنة الخليفتية السوداء، ولُفَّت له عمامة سوداء حرير، وقام المقام الشهابي أحمد بن إينال ولبس الخلعة والعمامة على الفور."},{"id":3456,"title":"خلع السلطان المؤيد أحمد بن إينال وتسلطن الظاهر خشقدم .","date":["العام الهجري :865","الشهر القمري : رمضان","العام الميلادي :1461"],"text":"كان الباعث لهذه الفتنة وخلع المؤيَّد أنه لما تسلطن لم يحرك ساكنًا ولم يتغير أحدٌ مما كان عليه، فشقَّ ذلك على الظاهريَّة، وقال كل منهم في نفسه: كأن الملك الأشرف إينال ما مات، فإن الغالبَ كلٌّ منهم كان أخذ ما بيده من الإقطاعات، وحبس ونفى في أوَّل سلطنة الأشرف إينال، كما هي عادة أوائل الدُّول، وبقى منهم جماعة كثيرة بلا رزق ولا إمرة ولم يجدوا عندهم قوةً ليخلعوا الملك المؤيد هذا ويسلطنوا غيره وحدهم، فكلَّموا الأشرفيَّة في هذا المعنى غير مرَّة، وترققوا لهم، فلم يقبلوا منهم ذلك؛ لنفرةٍ كانت بين الطائفتين قديمًا وحديثًا، وأيضا فلسان حال الأشرفية: نحن الآن في كفاية من الأرزاق والوظائف، فعلام نحرك ساكنًا، ونخاطر بأنفسنا؟ فعجز فيهم الظاهرية وقد ثقُل عليهم الملك المؤيَّد، وكثر خوفُهم منه، فإنه أوَّل ما تسلطن أبرق وأرعد، فانخزى كل أحد، قال ابن تغري بردي: \"كان دخول المؤيد السلطنة بحرمة وافرة؛ لأن سنَّه كان نحو الثلاثين سنة يوم تسلطن، وكان قد ولِّيَ الأتابكية في أيَّام أبيه، وأخذ وأعطى، وسافر أميرَ حاجِّ المحمل، وحجَّ قبل ذلك أيضًا وسافر البلاد، ومارس الأمورَ في حياة والده وهذا كلُّه بخلاف من تقدَّمه من سلاطين أولاد الملوك؛ فإن الغالب منهم حدث السِّنِّ يريد له من يدبِّرُه، فإنه ما يعرف ما يرادُ منه، فيصير في حكم غيرِه من الأمراء فتتعلَّق الآمالُ بذلك الأمير، وتتردَّد الناسُ إليه، إلى أن يدبِّر في سلطنة نفسه، بخلاف المؤيَّد هذ؛ فإنَّه ولِيَ السلطنة وهو يقول في نفسه: إنه يدبِّرُ مع مملكة مصر ممالكَ العجم زيادةً على تدبير مصرَ! قلت: وكان كما زعم؛ فإنه كان عارفًا عاقلًا مباشرًا، حسن التدبير، عظيمَ التنفيذ شهمًا، وكان هو المتصرفَ في الأمور أيَّام أبيه في غالب الولايات والعَزلِ وأمور المملكة، فلما تسلطن ظنَّ كل أحد أنْ لا سبيل في دخول المكيدة على مثل هذا؛ لمعرفة الناس بحذقه وفطنته, وكان مع هذه الأوصاف مليح الشكل، وعنده تؤدة في كلامه، وعقل وسكوت خارج عن الحد، يؤديه ذلك إلى التكبُّر، وهذا كان أعظم الأسباب لنفور خواطر الناس عنه؛ فإنه كان في أيام سلطنته لا يتكلَّمُ مع أحد حتى ولا أكابر الأمراء إلا نادرًا، ولأمر من الأمور الضروريات، وفعل ذلك مع الكبير والصغير، وما كفى هذا حتى صار يبلُغُ الأمراءَ أنَّه في خلوته يسامِرُ الأطرافَ الأوباشَ الذين يُستحيا من تسميتهم، فعظم ذلك على الناس، فلما وقع ذلك وجد من عنده حقدٌ فرصةً، وأشاع عنه هذا المعنى وأمثاله، وبشَّع في العبارة وشنَّع، وقال هذا وغيره: إنَّه لا يلتفت إلى المماليك ويزدريهم، وهو مستعزٌّ بمماليك أبيه الأجلاب وأصهاره وحواشيه وخشداشية أبيه- زملاء مهنته-وبالمال الذي خلَّفه أبوه، ومنهم من قال أيضًا: إنما هو مستعزٌّ بحسن تدبيره، فإنه قد عبَّأ لكل سؤال جوابًا، ولكل حرب ضربًا، وكان مع هذا قد قمع مباشري الدولة وأبادهم، وضيَّق عليهم، ودقَّق في حسابهم كما هو في الخاطر وزيادة، فما أحسن هذا لو كان دام واستمر, فنفرت قلوب المباشرين منه، وأخذ أمره في إدبار؛ لعدم مثابرته على سير طريقه الأوَّل من سلطنته، فلو جَسَر لكَسَر، لكنه هاب فخاب\" فلما كان آخرُ يوم الجمعة السابع عشر رمضان رسم السلطان الملك المؤيد أحمد لنقيب الجيش الأمير ناصر الدين محمد بن أبي الفرج أن يدور على الأمراء مقدَّمي الألوف، ويُعلمَهم أن السلطان رسم بطلوعهم من الغد في يوم السبت إلى الحوش السلطاني من قلعة الجبل بغير قماش الموكب، ولم يعلِمْهم لأيِّ معنى يكون طلوعهم واجتماعهم في هذا اليوم بالقلعة، وهو غيرُ العادة، وأخذ الأمراء من هذا الأمر أمرٌ مريج، وخلا كل واحد بمن يثق به، وعرفه الخبر، وهو لا يشكُّ أن السلطان يريد القبضَ عليه من الغد، ووجد لذلك من كان عنده كمينٌ من الملك المؤيد أو يريد إثارةَ فتنة فرصةً، وحرَّض بعضهم بعضًا، إلى أن ثارت المماليك الظاهرية في تلك الليلة، وداروا على رفقتهم وإخوانهم وعلى من له غرضٌ في القيام على الملك المؤيد، وداموا على ذلك ليلتَهم كلها، فلما كان صبح نهار السبت تفرَّقوا على أكابر الدولة والأمراء في بيت الأتابك خشقدم لعمل المصلحة، وقد اجتمعت طوائفُ المماليك والجميع في بيت الأمير الكبير، ولم يطلع إلى القلعة في هذا اليوم أحدٌ من الأمراء والأعيان إلا جماعة يسيرة جدًّا، فلما تكامل جمعهم في بيت الأمير الكبير وصاروا على كلمة واحدة؛ على خلع الملك المؤيَّد أحمد من السلطنة، وسلطنة غيره، وتكلموا فيمن يولونه السلطنة, فأجمع رأي الجميع على سلطنة أحد من أعيان الأمراء، ثم تكلموا فيمن يكون هذا السلطان، فقال جانبك: الرأي عندي سلطنةُ الأمير الكبير خشقدم المؤيدي؛ فإنه من غير الجنس يعني كونه روميَّ الجنس وأيضًا إنه رجل غريبٌ ليس له شوكة، ومتى أردتم خلعَه أمكنكم ذلك، وحصل لكم ما تقصدونه من غير تعب، فأعجب الجميعَ هذا الكلامُ، بخلاف المماليك الأشرفية، وإن كانوا هم أيضًا متفقين على خلع المؤيد؛ لتطَلُّعهم تسلطُنَ خشداشهم الأمير جانم نائب الشام، ولو أنَّ أمر المؤيد طرقهم بغتةً ما طاوعوا على الرُّكوبِ في مثل هذا اليوم قبل مجيء خشداشهم جانم، فبويع خشقدم ولقِّبَ بالملك الظاهر أبو سعيد سيف الدين خشقدم ونودي بالحال بسلطنته بشوارع القاهرة، ثم شرعوا بعد ذلك في قتالِ الملك المؤيد أحمد، كل ذلك والملك المؤيَّدُ في القلعة في أناس قليلة من مماليكه ومماليك أبيه الأجلاب، ثم التحم القتال بين الطائفتين مناوشةً لا مصاففةً، غير أن كلًّا من الطائفتين مُصِرٌّ على قتال الطائفة الأخرى، والملك المؤيَّد في قلة عظيمة من المقاتلة ممن يعرف مواقِعَ الحرب وليس معه إلا أجلاب، فلم ينقضِ النهار حتى آل أمرُ الملك المؤيد إلى زوال، وهو مع ذلك ينتظر من يجيء إليه لمساعدته، حتى من ليس له غرض عند أحد بعينه جاء إلى الأمير الكبير مخافة على رزقه ونفسه؛ لِما علم من قوة شوكة الأمير الكبير وما يؤول أمره إليه، هذا مع حضور الخليفة والقضاة الأربعة عند الأمير الكبير وجميع أعيان الدولة من المباشرين وأرباب الوظائف وغيرهم، والملك المؤيَّد في أناس قليلة جدًّا، وظهر ذلك للملك المؤيد عيانًا، فأراد أن يسَلِّمَ نفسه، ثم أمسك عن ذلك من وقته، فلما رأى الملك المؤيد أنَّ ذلك لا يفيده إلا شدةً وقسوةً أمر عساكره ومقاتلته بالكفِّ عن القتال، وقام من وقته وطلع القلعة بخواصِّه، وأمر أصحابه بالانصراف إلى حيث شاؤوا، ثم دخل هو إلى والدته خوند زينب بنت البدري حسن بن خاص بك، وترك باب السلسلة لمن يأخذه بالتسليم، وتمزَّقت عساكره في الحال كأنها لم تكن، وزال ملكه في أقل ما يكون، وخُمِدت الفتنة كأنَّها لم تكن، ثم أرسل الأتابك خشقدم في الحال جماعةً من أصحابه قبضوا على الملك المؤيد أحمد هذا من الدور السلطانية، فأُمسِكَ من غير ممانعة، وسلَّم نفسه، وأُخرِجَ من الدور إلى البحرة من الحوش السلطاني، وحُبِسَ هناك بعد أن اقتِيدَ واحتُفظ به، وكانت مدة حكمه أربعة أشهر وستة أيام، ثم رسم السلطان الملك الظاهر خشقدم بتوجُّهِه وتوجه أخيه محمد إلى سجن الإسكندرية."},{"id":3457,"title":"خروج الأمير جانم نائب دمشق عن الطاعة .","date":["العام الهجري :866","الشهر القمري : جمادى الأولى","العام الميلادي :1462"],"text":"حاول الأمير جانم نائب دمشق قبل هذا أن يتسلطنَ، ولكنه كان يخاف، وكان قد أرسل ولده يحيى في السنة الماضية إلى مصر أيام السلطان المؤيد أحمد وكلم بعض الأمراء بذلك وبعضهم وعده أن يقِفَ معه، حتى إنَّ أمر سلطنة خشقدم السلطان الحالي كان على أساس أنه يكون مؤقتًا؛ لأن كثيرًا من الأمراء كاتبوا الأمير جانم على أنهم يسلطنونه وأرسلوا له أن يحضُرَ إلى مصر لذلك؛ لذا فإن جانم هذا وفي هذا شهر جمادى الأولى من هذا العام أرسل يدعو تركمان الطاعة إلى موافقته، كما أنه دُعي لجانم على منابر ديار بكر، ثم ورد الخبر بأن جانم نائب الشام كان عدَّى الفرات في جمعٍ كثير من المماليك وتركمان حسن بك بن قرايلك، وسار بعساكره حتى وصل إلى تل باشر من أعمال حلب، وتجهَّز نائب حلب لقتاله، ففي الحال عين السلطان تجريدةً إلى حلب لقتال جانم ثمَّ رسم بإبطال التجريدة، وسَبَبُ ذلك ورود الخبر من نائب حلب بعود جانم على أقبحِ وجه، وأن جماعة كثيرة من مماليكه فارقوه، وقَدِموا إلى مدينة حلب، وأمرُ رجوع جانم أنَّه كان لما وصل إلى تل باشر وقع بينه وبين تركمان حسن بك- الذين كانوا معه- كلامٌ طويل، فتركوه وعادوا، فتلاشى أمر جانم لذلك وعاد، ثم في يوم الثلاثاء الثالث عشر ربيع الآخر من سنة 867 ورد الخبر من جانبك التاجي نائب حلب أن جانم نائب الشام قُتِل بمدينة الرها، وقد اختُلِف في قتله على أقاويل."},{"id":3458,"title":"نهاية الدولة الأيوبية الكردية على يد ابن قرايلك .","date":["العام الهجري :866","الشهر القمري : ذي القعدة","العام الميلادي :1462"],"text":"أخذ حسن بك بن علي بك بن قرايلك مدينة حصن كيفا، ثم أخذ قلعتَها في ذي القعدة بعد ما حاصرها سبعةَ أشهر، وانقطع من الحصنِ ملك الأكراد الأيوبية، بعدما ملكوها أكثَرَ من مائتي سنة، وذلك بعد قتلِ صاحبها الملك خلف بيد بعض أقاربه، فاختلف الأكراد فيما بينهم، فوجد حسن بك بذلك فرصةً في أخذها، فحاصرها حتى أخذها، وقوِيَ أمر حسن بأخذِها، فإنه أخذ بعد ذلك عدةَ قلاع من أعمالِ ديار بكر من تعلُّقات الحصنِ وغيرِه."},{"id":3459,"title":"استيلاء الإسبان الفرنج على جبل طارق .","date":["العام الهجري :867","العام الميلادي :1462"],"text":"استولى الإسبان الفرنج على جبل طارق الذي كان بيد بني الأحمر ملوك غرناطة، وكان هذا الاستيلاء سببًا لانقطاع غرناطة عن بقية العالم الإسلامي، وأصبحوا تحت تحكُّم الفرنج الذين قاموا بذلك لقطع إي إمدادات لبني الأحمر في حال الهجوم عليهم."},{"id":3460,"title":"ثورة عمرانية في القسطنطينية في عهد الفاتح بناء جامع الفاتح .","date":["العام الهجري :868","العام الميلادي :1463"],"text":"أمر السلطان محمد الفاتح بإنشاء جامِعِه في موقع كنيسة بيزنطة القديمة التي دمَّرها الصليبيون أثناء الحملة الصليبية الرابعة، وسمي الجامعُ باسم جامع الفاتح نسبةً إليه، وأمر كذلك أن يُبنى بجانب مسجده ثماني مدارس، على كل جانب من جوانب المسجد أربعة مساجد يتوسَّطُها صَحنٌ فسيح، وفيها يقضي الطالبُ المرحلة الأخيرة من دراسته، وأُلحقت بهذه المدارس مساكِنُ للطلبة ينامون فيها ويأكلون فيها طعامَهم، ووضعت لهم منحة مالية شهرية، وكان الموسمُ الدراسي على طول السنة في هذه المدارس، وأنشأ بجانبها مكتبة خاصة، وكان يشترط في الرجل الذي يتولى أمانة هذه المكتبة أن يكون من أهل العلم والتقوى، متبحرًا في أسماء الكتب والمؤلِّفين، وكان المشرف على المكتبة يعير الطلبة والمدرسين ما يطلبونَه من الكتب بطريقةٍ منظمة دقيقة ويسجل أسماء الكتب المستعارة في دفتر خاص، وهذا الأمين مسؤول عن الكتب التي في عهدته، ومسؤول عن سلامة أوراقها، وتخضع هذه المكتبة للتفتيش كل ثلاثة أشهر على الأقل، وكانت مناهج هذه المدارس تتضمن نظام التخصص، فكان للعلوم النقلية والنظرية قسم خاص، وللعلوم التطبيقية قسم خاص أيضًا، ثم صار الوزراء والعلماء من أصحاب الثروات يتنافسون في إنشاء المعاهد والمدارس والمساجد والأوقاف الخيرية، وكان الفاتح مهتمًّا باللغة العربية؛ لأنها لغة القرآن الكريم، كما أنها من اللغات العلمية المنتشرة في ذلك العهد، وليس أدلَّ على اهتمام الفاتح باللغة العربية من أنه طلب إلى المدرسين بالمدارس الثماني أن يجمعوا بين الكتب الستة في علم اللغة، كالصحاح، والتكملة، والقاموس، وأمثالها، ودعم الفاتح حركة الترجمة والتأليف لنشر المعارف بين رعاياه بالإكثار من نشر المكاتب العامة، وأنشأ له في قصره خزانة خاصة احتوت على غرائب الكتب والعلوم. كان السلطان محمد الفاتح مغرمًا ببناء المساجد والمعاهد والقصور والمستشفيات، والخانات والحمامات، والأسواق الكبيرة والحدائق العامة، وأدخل المياه إلى المدينة بواسطة قناطر خاصة، وشجع الوزراء وكبار رجال الدولة والأغنياء والأعيان على تشييد المباني وإنشاء الدكاكين والحمامات، وغيرها من المباني التي تعطي المدن بهاءً ورونقًا، واهتم بالعاصمة إسلامبول اهتمامًا خاصًّا، وكان حريصًا على أن يجعلها حاضرة العلوم والفنون، وكثر العمران في عهد الفاتح وانتشر، واهتم بدُور الشفاء ووضع لها نظامًا مثاليًّا في غاية الروعة والدقة والجمال؛ فقد كان يعهد بكل دار من هذه الدور إلى طبيب، ثم زيد إلى اثنين من حذاق الأطباء من أي جنس كان، يعاونهما كحَّال- طبيب عيون- وجراح وصيدلي، وجماعة من الخدم والبوابين، ويشترط في جميع المشتغلين بالمستشفى أن يكونوا من ذوي القناعة والشفقة والإنسانية، ويجب على الأطباء أن يعودوا المرضى مرتين في اليوم، وألا تصرف الأدوية للمرضى إلا بعد التدقيق من إعدادها، وكان يشترط في طباخ المستشفى أن يكون عارفًا بطهي الأطعمة والأصناف التي توافق المرضى منها، وكان العلاج والأدوية في هذه المستشفيات بالمجان، ويغشاها جميع الناس بدون تمييز بين أجناسهم وأديانهم!"},{"id":3461,"title":"البوسنة تصبح ولاية عثمانية .","date":["العام الهجري :868","العام الميلادي :1463"],"text":"امتنع أميرُ البوسنة من أداء الجزية المتعاهَد عليها للدولة العثمانية، فسار إليه السلطان محمد الفاتح بجيشه وانتصر عليه، فضمَّ بذلك بلاد البوسنة إلى الدولة العثمانية، وحاول ملك المجر مساعدةَ أهل البوسنة البوشناق ضد العثمانيين ولكنه انهزم هو الآخر، ويُذكر أن كثيرًا من البوشناق اعتنقوا الإسلام، وانتشر في تلك البلاد الدين الإسلامي على يد العثمانيين."},{"id":3462,"title":"خلع الملك سعد ملك بني نصر وتولي ابنه الغالب علي .","date":["العام الهجري :868","العام الميلادي :1463"],"text":"قام أبو الحسن علي بن سعد بن علي بن أبي الحجاج يوسف الثاني بالخروجِ على أبيه وانتزاع الملك منه، وتلقَّب بالغالب بالله."},{"id":3463,"title":"السلطان الظاهر خشقدم يمنع استعمال أهل الذمة في السلطة .","date":["العام الهجري :868","الشهر القمري : محرم","العام الميلادي :1463"],"text":"في يوم الأثنين الثاني عشر محرم نودي بشوارع القاهرة أن أحدًا من الأعيان لا يستخدم ذميًّا في ديوانه من الكَتَبة وغيرهم، فمنعت هذه المناداة أهل الذمة قاطبةً من التصرف والمباشرة بقلم الديوان بوجه من الوجوه في أعمال مصر، وكُتِب بذلك إلى سائر الأقطار، ثم عقد السلطان بالصالحية ببين القصرين مجلسَ بالقضاة الأربعة، وحضره الدوادار الكبير، وجماعة من الأعيان، وقُرئت العهود المكتوبة قديمًا على أهل الذمة، فوجدوا في بعضِها أن أحدًا من أهل الذمة لا يباشِرُ بقلم الديوان عند أحد من الأعيان، ولا في عمل من الأعمال، وأشياء من هذه المقولة، إلى أن قال فيها: ولا يلفُّ على رأسه أكثر من عشرة أذرع، وأن نساءَهم يتميزن من نساء المسلمين بالأزرق والأصفر على رؤوسهن في مشيهن بالأسواق، وكذلك بشيء في الحمامات، فحكم قاضي القضاة علم الدين صالح البلقيني الشافعي بإلزام أهل الذمة بذلك جميعه، ما عدا الصرفَ والطبَّ بشروطه، وصمَّم السلطان على هذا الأمر، وفرح المسلمون بذلك قاطبةً، فأسلم بسبب ذلك جماعةٌ من أهل الذمة من المباشرين، وعظُمَ ذلك على أقباط مصر، ودام ذلك نحو السنة، وعاد كل شيء على حالِه أولًا، وبلغ السلطان ذلك فلم يتكلَّم بكلمة واحدة!!"},{"id":3464,"title":"العسكر المصري يأخذ قلعة الماغوصة ويسيء السيرة فيها .","date":["العام الهجري :868","الشهر القمري : جمادى الآخرة","العام الميلادي :1464"],"text":"في يوم الجمعة الثالث والعشرين جمادى الآخرة وصل رسول صاحب قبرص جاك، وأخبر أنه أخذ مدينة الماغوصة وقلعتها من يد الفرنج، وأنَّه سلمها للأمير جانبك الأبلق المقيم بجزيرة قبرص بمن بقيَ معه من المماليك السلطانية، فأساء جانبك السيرةَ في أهل الماغوصة، ومدَّ يده لأخذ الصبيان الحِسان من آبائهم وهم أعيانُ أهل الماغوصة، فشق ذلك عليهم، وقالوا: نحن سلَّمناكم البلد بالأمان، وقد حلفتم لنا أنَّكم لا تفعلوا معنا بعد أخذكم المدينة إلا كل خير، وأنتم مسلمون، فما هذا الحال؟ فلم يلتفت جانبك الأبلق إلى كلامِهم، واستمرَّ على ما هو عليه، فأرسل أهل الماغوصة إلى جاك عرفوه الخبر، فأرسل جاك إلى جانبك ينهاه عن هذه الفعلة، فضرب جانبك القاصِدَ بعد أن أوسعه سبًّا، فأرسل إليه قاصدًا آخر، فضربه جانبك بالنشَّاب، فركب جاك إليه من الأفقسية مدينة قبرص، وجاء إليه وكلَّمه، فلم يلتفت إليه، وخشَّن عليه الكلام، فكلمه جاك ثانيًا، فضربه بشيءٍ كان في يده، فسقط جاك مغشيًّا عليه، فلما رأت الفرنج ذلك مدَّت أيديها إلى جانبك ومن معه من المسلمين بالسيوفِ، فقُتِلَ جانبك وقُتِل معه خمسة وعشرون مملوكًا من المماليك السلطانية، واستولى جاك على الماغوصة على أنَّه نائب بها عن السلطان، فعيَّن السلطان سودون المنصوري الساقي وتوجَّه لقبرص مع يعقوب قاصد جاك."},{"id":3465,"title":"العثمانيون يقاتلون البنادقة .","date":["العام الهجري :869","العام الميلادي :1464"],"text":"اصطدم السلطان العثماني محمد الفاتح مع البنادقة الذين يملِكونَ بعض المواقع في بلاد المورة، وجزرًا كثيرة في بحر إيجة، وقد هاجم البنادقة بعض المراكز العثمانية ودخلوها فسار إليهم السلطان ففرُّوا من مواقعهم ودخلها العثمانيون، وبعد هدنةِ سنة عاد البنادقة لغيِّهم ونقضوا العهد فأرادوا استعادةَ ما فقدوه، وبدؤوا يُغيرون على الدولة العثمانية، ولكنهم باؤوا بالفشل وفقَدوا بعض مواقعهم المهمَّة."},{"id":3466,"title":"نهاية دولة بني مرين وتولية أبي عبد الله الحفيد على المغرب .","date":["العام الهجري :869","الشهر القمري : رمضان","العام الميلادي :1465"],"text":"اضطربت أحوال الدولة المرينية بفاس وتسلَّط بها اليهود, بعد تعيين السلطان عبد الحق هارون اليهودي رئيسًا لدولته كما عين عددًا منهم في حكومته، وكانوا قد أظهروا الإسلام, فاجتمع رؤساءُ فاس عند خطيب القرويين الفقيه أبي فارس عبد العزيز بن موسى الورياكلي وكانت له صلابة في الحقِّ وجَلادة عليه بحيث يلقي نفسَه في العظائم ولا يبالي، وقالوا له: ألا ترى إلى ما نحن فيه من الذلَّة والصغار وتحكُّم اليهود في المسلمين والعبث بهم حتى بلغ حالهم إلى ما سمعت، فأثر كلامهم فيه, وللحينِ أغراهم بالفتك باليهودِ وخلع طاعة السلطانِ عبد الحق وبيعة الشريفِ أبي عبد الله الحفيد، فأجابوه إلى ذلك واستدعوا الشريف الحفيد فبايعوه والتفَّت عليه خاصَّتُهم وعامَّتهم وتولى كِبْرَ ذلك أهل حومة القلقليين منهم ثم تقدم الورياكلي بهم إلى فاس الجديد فصمدوا إلى حارة اليهود فقتلوهم واستلبوهم واصطلموا نعمَتَهم واقتسموا أموالهم، وكان السلطان عبد الحق يومئذ غائبًا في حركة له ببعض النواحي, وقيل إن السلطان عبد الحق خرج بجيشه إلى جهة القبائل الهبطية وترك اليهودي يقبض من أهل فاس المغارم فشَدَّ عليهم حتى قبض على امرأةٍ شريفة وأوجعها ضربًا وحكى ما تقدَّمَ فاتصل بعبد الحق خبَرُ خلعه فانفضَّ مُسرعًا إلى فاس واضطرب عليه أمر الجند ففسدت نيَّاتُهم وتنكَّرت وجوهُهم، وصار في كل منزلة تنفض عنه طائفة منهم فأيقن بالنكبةِ وعاين أسبابَ المنية، ولما قَرُب من فاس استشار هارون اليهوديَّ فيما نزل به فقال اليهودي له: لا تَقدَم على فاس لغَلَيان قِدرِ الفتنة بها، وإنما يكون قدومنا على مكناسة الزيتون؛ لأنها بلدنا وبها قوَّادنا وشيعتنا، وحينئذ يظهر لنا ما يكون، فما استتمَّ اليهودي كلامه حتى انتظمه بالرمحِ رجلٌ من بني مرين يقال له تيان، وعبد الحق ينظر، وقال: وما زلنا في تحكم اليهود واتِّباعِ رأيهم والعمل بإشارتِهم، ثم تعاورت اليهوديَّ الرماحُ من كل جانب وخرَّ صريعًا، ثم قالوا للسلطان عبد الحق: تقدم أمامَنا إلى فاس؛ فليس لك اليوم اختيار في نفسِك، فأسلم نفسه وانتُهِبت محلَّتَه وفيئَت أموالُه وحلَّت به الإهانة وجاؤوا به إلى أن بلغوا عين القوادس خارج فاس الجديد، فاتصل الخبر بأهل فاس وسلطانهم الحفيد، فخرج إلى عبد الحق وأركبه على بغل بالبردعة، وانتزع منه خاتم المُلك وأدخله البلد في يومٍ مشهود حضره جمعٌ كبير من أهل المغرب، وأجمعوا على ذمه، وشكروا الله على أخذِه، ثم جُنِّب إلى مصرعه، فضُربت عنقه صبيحة يوم الجمعة السابع والعشرين رمضان من هذه السنة, ودفن ببعض مساجد البلد الجديد ثم أُخرج بعد سنة ونُقِل إلى القلعة، فدفن بها وانقرضت بمَهلِكِه دولةُ بني عبد الحق من المغرب."},{"id":3467,"title":"العثمانيون يضمون ألبانيا إلى الدولة العثمانية .","date":["العام الهجري :870","العام الميلادي :1465"],"text":"بدأ البابا بالدعوة إلى حرب صليبية فشجَّع إسكندر بك ملك ألبانيا على نقض العهدِ الذي أبرَمَه مع العثمانيين سابقًا، داعيًا ملوك أوربا وأمراءها لمساندته، غير أن البابا هلك فجأةً ولم تقم تلك الحرب المزعومة، ولكنَّ إسكندر بك نقض عهده وحارب العثمانيين، فكانت الحرب بينهم سِجالًا إلى أن توفي إسكندر بك بعد حُمَّى شديدة أصابته في مدينة السيو، واستطاع العثمانيون أن يضمُّوا ألبانيا إليهم."},{"id":3468,"title":"خروج الأمير شاه سوار نائب أبلستين عن الطاعة وقتاله .","date":["العام الهجري :872","الشهر القمري : محرم","العام الميلادي :1467"],"text":"في يوم الخميس الثاني عشر محرم ورد الخبر من نائب حلب يشبك البجاسي أن شاه سوار نائب أبلستين خرج عن طاعةِ السلطان سيف الدين خشقدم، ويريد المشيَ على البلاد الحلبية، فرسم السلطانُ في الحال بخروج نائب طرابلس ونائب حماة إلى جهة البلاد الحلبية لمعاونة نائب حلب إن حصل أمر، ثم عيَّن السلطان تجريدة- خيل لا رَجَّالة فيها- من مصر إلى جهات البلاد الحلبية إن ألجأت الضرورة إلى سفرهم، ثم إنَّ الأمير بردبك نائب الشام خرج من دمشق بعساكرها في آخر المحرم إلى جهة حلب لمعاونة نائب حلب على قتال شاه سوار، كما أن جميع نواب البلاد الشامية قد خرجوا من أعمالهم إلى البلاد الحلبية، لقتال شاه سوار بن دلغادر، كان بردبك قد تهاون في قتال شاه سوار، وخذل العسكر الشامي لِما كان في قلبه من الملك الظاهر خشقدم، فكان ذلك سببًا لكسر العسكر الشامي والحلبي وغيرهم ونهْبِهم، وقتل في هذه الواقعة نائب طرابلس قاني باي الحسني المؤيدي، ونائب حماة تنم خوبي الحسيني الأشرفي، وأتابك دمشق قراجا الخازندار الظاهري، وأتابك حلب قانصوه المحمدي الأشرفي، وغيرهم من أمراء البلاد الشامية، وغيرهم، ثم ورد الخبر من البلاد الحلبية من أمر شاه سوار، وقتل أكابر أمراء البلاد الشامية، ونهبه للبلاد الحلبية، وأخذه قلاع أعمالها، وأنَّ نائب الشام بردبك في أسره، وأن يشبك البجاسي نائب حلب دخل إلى حلب على أقبح وجهٍ، وورد الخبَرُ بأن الأمير بردبك نائب الشام فارق شاه سوار، وقدم إلى مرعش طائعًا، ثم سار إلى منزلة قارا في يوم الخميس السابع عشر ربيع الآخر، ثم استطاع الجيش بعد ذلك من أسر شاه سوار وأخذ إلى القاهرة وقتل فيها وعُلِّقَ على باب زويلة."},{"id":3469,"title":"الأعراب يهجمون على حجاج مصر العائدين .","date":["العام الهجري :872","الشهر القمري : محرم","العام الميلادي :1467"],"text":"في يوم الخميس التاسع عشر محرم ورد الخبَرُ بأن إقامة الحاج التي جهزت من القاهرة أُخِذَت عن آخرها، أخذها مبارك شيخ بني عقبة بمن كان معه من العرب، وأنه قتل جماعة ممن كان مع الإقامة المذكورة، منهم جارقطلو السيفي دولات باي أحد أمراء آخورية السلطان، فعظم ذلك على السلطان، وزاد توعُّكُه، وعلى الناس قاطبة، وضَرَّ أخذُ إقامة الحاج غايةَ الضرر، وأشرف غالبهم على الموت، فلما كان يوم الجمعة العشرين من المحرم وصل الحاج الرجبي، وعظيم من كان فيه زين الدين بن مزهر كاتب السر وأمير حاج الركب الأول سيباي، إلى بركة الحاج معًا، بعد أن قاست الحجاج أهوالًا وشدائد من عدم الميرة والعلوفة وقلَّة الظهر، ودخل نانق أمير الحاج من الغد، فلما كان يوم الاثنين الثالث والعشرين محرم عين السلطان الأميرَ أزبك رأس نوبة النوب الظاهري، والأمير جانبك حاجب الحجاب الأشرفي المعروف بقلقسيز، وصحبتهما أربعة من أمراء العشرات، وعدة مماليك من المماليك السلطانية؛ لقتال مبارك شيخ عرب بني عقبة ومن معه من الأعراب، وكتب السلطان أيضًا لنائب الكرك الأمير بلاط، ونائب غزة الأمير إينال الأشقر، بالمسير إلى جهة الأمير أزبك بعقبة أيلة، ومساعدته على قتال مبارك، وخرج الأميرُ أزبك بمن عيِّن معه من القاهرة في يوم الاثنين سابع صفر، وخرج نائب صفد، ونائب غزة أيضًا إلى جهة العقبة لقتال مبارك شيخ عرب بني عقبة، ووصل الخبَرُ بقدوم الأمير أزبك رأس نوبة النوب من تجريدة العقبة، بعد أن أمسك مباركًا شيخ بني عقبة، الذي قطع الطريقَ على إقامة الحجَّاج، ورسم بتسمير مبارك شيخ بني عقبة ورفقته، وكانوا أزيد من أربعين نفرًا، فسَمَّروا الجميع، وطِيفَ بهم الشوارع، ثم وسِّطوا- قتلوا- في آخر النهارِ عن آخِرِهم."},{"id":3470,"title":"وفاة السلطان الظاهر خشقدم وسلطنة الظاهر يلباي الإينالي .","date":["العام الهجري :872","الشهر القمري : ربيع الأول","العام الميلادي :1467"],"text":"هو السلطان الملك الظاهر أبو سعيد سيف الدين خشقدم بن عبد الله الناصري المؤيدي، تسلطن في يوم الأحد التاسع عشر رمضان بعد أن أجمع أمراء المماليك على خلع السلطان المؤيد أحمد بن إينال واختاروا الأمير الكبير خشقدم؛ لأنه ليس من جنس المماليك؛ فهو رومي ورجل غريب ليس له شوكة، ومتى أردوا خلعه أمكنهم ذلك، فلما كان يومُ قرروا خلع المؤيد الجمعة السابع عشر رمضان وقت الزوال طُلِبَ الخليفة المستنجد بالله يوسف والقضاة والأعيان، وقد حضر جميع الأمراء في الإسطبل السلطاني بباب السلسلة بالحراقة، وبويع بالسلطنة، وكان قد بويع بها من بكرة يوم السبت ثامن عشر شهر رمضان قبل قتال الملك المؤيد أحمد، ولقب بالملك الظاهر، وكنِّي بأبي سعيد، ويذكر أن الذي جلبه إلى الديار المصرية خواجا ناصر الدين وسِنُّه يوم ذلك دون البلوغ، فاشتراه الملك المؤيَّد شيخ، وجعله كتابيًّا سنين كثيرة، ثم أعتقه وجعله من جملة المماليك السلطانية. بدأ المرض بالسلطان الظاهر خشقدم من يوم عاشوراء وتزايد يومًا بعد يوم إلى أن أصبح يوم السبت عاشر شهر ربيع الأول، فلم يكن بعد أذان الظهر إلا بنحو ساعة رمل لا غير ومات السلطان بقاعة البيسرية، بعد أذان الظهر بدرجات، وفي حال وفاته طلعت جميع الأمراء إلى القلعة، وأخذوا في تجهيز السلطان الملك الظاهر خشقدم، وغسَّلوه وكفَّنوه، وصلَّوا عليه بباب القلة من قلعة الجبل، كل ذلك قبل أن تبايع العساكِرُ يلباي الإينالي بالسلطنة، وذلك أن الأمراء الأكابر بمقعد الإسطبل السلطاني عند الأمير آخور الكبير، وجلس الأتابك يلباي وهو أتابك العساكر وخشداش- زميل- السلطان في صدر المجلس وبإزائه الأمير تمربغا أمير مجلس، وهو متكلِّم القوم، ولم يحضر قرقماس أمير سلاح لإقامته بساحل النيل، وحضر جماعة من أمراء الألوف، وكبير الظاهرية الخشقدمية يوم ذاك خيربك الدوادار الثاني، وأخذوا في الكلام إلى أن وقع الاتفاق بينهم على سلطنة الأتابك يلباي، ورضي به عظيم الأمراء الظاهرية الكبار الأمير تمربغا أمير مجلس، وكبير الظاهرية الصغار الخشقدمية خيربك الدوادار، وجميع من حضر، وكان رضا الظاهرية الكبار بسلطنة يلباي بخلاف الظن، وكذلك الظاهرية الصغار، ثم تكلم بعضهم بأن القوم يريدون من الأمير الكبير أن يحلف لهم بما يطمئن به قلوبهم وخواطرهم، فتناول المصحف الشريف بيده، وحلف لهم يمينًا بما أرادوه، ثم حلف الأمير تمربغا أمير مجلس، كل ذلك كان قبل وفاة السلطان، ولما صلِّيَ على السلطان الظاهر خشقدم بباب القلة، وحُمل نعشه، وعلى نعشِه مرقعة الفقراء، ساروا به إلى أن أوصلوه إلى تربته ومدرسته التي أنشأها بالصحراء بالقرب من قبة النصر، ودُفن بالقبة التي بالمدرسة، وكانت مدة سلطنته ست سنين وخمسة أشهر واثنين وعشرين يومًا، ثم لما عادوا من الصلاة على الملك الظاهر خشقدم جلسوا عند باب الستارة وقتًا هينًا، وإذا بالأمير خيربك خرج من باب الحريم ومعه جماعة من خشداشيته وأخذوا الأتابك يلباي وأدخلوه من باب الحريم، ومضوا به إلى القصر السلطاني، وخاطبوه بالسلطنة، فامتنع امتناعًا هينًا، فلم يلتفتوا إلى كلامِه، وأرسلوا إلى الأمراء أحضروهم إلى القصر من خارج، فدخل الأمراء قبل أن يحضر الخليفة والقضاة، وطال جلوسُهم عنده، وقبَّل الأمراء الأرض قبل المبايعة، وهم في هرج لإحضار الخليفة والقضاة إلى أن حضروا بعد مشقة كبيرة، وتكاملوا بعد أن فرغ النهار، وقد أخذوا في بيعته وسلطنته، ولبَّسوه خِلعة السلطنة بالقصر، وجلس على تخت الملك من غير أن يركب فرسًا بأبهة الملك على العادة، وقبَّل الأمراء الأرض بين يديه وتمَّ أمره، ونودي بسلطنته، وتلقب بالملك الظاهر أبي نصر يلباي الإينالي، ويُذكَر أن أصله شركسي الجنس، جلبه الأمير إينال ضضع من بلاد الشراكس إلى الديار المصرية في عدة مماليك، فاشتراه الملك المؤيد شيخ قبل سنة 820، وأعتقه وجعله من جملة المماليك السلطانية."},{"id":3471,"title":"خلع السلطان الظاهر يلباي الإينالي وتسلطن الظاهر تمربغا .","date":["العام الهجري :872","الشهر القمري : جمادى الأولى","العام الميلادي :1467"],"text":"إنَّ الملك الظاهر يلباي الإينالي لما تسلطن وتم أمره غطَّاه المنصب، وصار كالمذهول، ولزم السكوتَ وعدم الكلام، وضَعُف عن بتِّ الأمور، وردْع الأجلاب، بل صارت الأجلاب في أيامه كما كانت أولًا وأعظم، فلم يَحسُن ذلك ببال أحد، وصار الأمير خيربك الدوادار الثاني هو صاحب الحل والعقد في مملكته، وإليه جميعُ أمور المملكة، وشاع ذلك في الناس والأقطار، فبهذا وأشباهه اضطربت أحوالُ الديار المصرية، ولما كان عصر يوم الأربعاء رابع جمادى الأولى، وطلعت الأمراء الألوف إلى القلعة ليبيتوا بالقصرِ على العادة، امتنعت المؤيدية عن الطلوع بمن وافقهم ما خلا الأمير جانبك الإينالي الأشرفي المعروف بقلقسيز أمير مجلس، وهو كبير الأشرفية الكبار يومئذ، واستمالت الظاهرية أيضًا الأمير جانبك قلقسيز الأشرفي أمير مجلس، فمال إليهم، ووعدهم بممالأة خشداشيته- زملائه- الأشرفية إليهم، وخذلان يشبك الدوادار، فعند ذلك صار الملك الظاهر يلباي وحده أسيرًا في أيدي القلعيين، فلما أصبحوا يوم الخميس خامس جمادى الأولى أعلن الأمير يشبك الفقيه الوثوب على الخشقدمية، ولبسوا آلة الحرب، وركب بمن معه من المؤيدية والأشرفية الكبار والأشرفية الصغار، والسيفية، واجتمع عليهم خلائقُ من كل طائفة، ومالت زعر الديار المصرية إليهم، وبلغ مَن بالقلعة أمرهم، فخافوهم خوفًا شديدًا، ولَبِسوا هم أيضًا آلة الحرب، ونزلوا بالسلطان الملك الظاهر يلباي إلى مقعد الإسطبل السلطاني المطل على الرميلة، وشرعوا في قتال الأمير يشبك بمن معه في الأزقة والشوارع بالصليبية، وأصبح يوم الجمعة سادس جمادى الأولى والقتال قائم بين الفريقين بشارع الصليبية من أول النهار إلى آخره، فلما جاء الليل ليلة السبت أدخل يلباي إلى مبيت الحراقة، وبات به على هيئة عجيبة، إلى أن أصبح النهار وأخذوه وطلعوا به إلى القصر الأبلق، وحبسوه في المخبأة التي تحت الخرجة، بعد أن طلعوا به ماشيًا على هيئة الخَلعِ من السلطنة ثم سُجِنَ بعد ذلك بسجن الإسكندرية إلى أن توفي في العام التالي وقد جاوز السبعين من عمره، وأخذ الناس في سلطنة الملك الظاهر تمربغا، وزال ملك يلباي هذا كأنه لم يكن، وكانت مدة ملكه شهرين إلا أربعة أيام، ليس له فيها إلا مجرد الاسم فقط، أما السلطان الجديد الظاهر أبو سعيد تمربغا فجلس بصدر المقعد بالإسطبل السلطاني المعروف بالحراقة، وحضر الخليفة المستنجد بالله أبو المظفر يوسف، والقاضي الشافعي والقاضي الحنفي، وتخلف المالكي لتوعكه، والحنبلي لإبطائه، وحضر غالب أرباب الدولة والأعيان وبايعوه بالسلطنة، فقام من وقته ودخل مبيت الحراقة، ولبس خلعة السلطنة السواد الخليفتي."},{"id":3472,"title":"خلع السلطان الظاهر تمربغا وتسلطن الأشرف قايتباي المحمودي .","date":["العام الهجري :872","الشهر القمري : رجب","العام الميلادي :1468"],"text":"في الخامس من رجب حصل بين المماليك الأجلاب وبعض الأمراء مناوشات، وكان عند السلطان جماعة من خشداشيته الأمراء، والسلطان ومن عنده كالمأسورين في يد الأجلاب، ثم تفرق الأجلاب إلى الأطباق بقلعة الجبل، ولبسوا آلة الحرب وعادوا إلى القصر بقوة زائدة وأمر كبير، وتوجه بعضهم لإحضار الخليفة، وتوجه بعضهم لنهب الحريم السطاني بداخل الدور، ودخل على السلطان ثلاثة أنفار منهم وهم ملثَّمون، وأرادوا منه أن يقوم وينزل إلى المخبأة التي تحت الخرجة، فامتنع قليلًا، ثم قام معهم مخافةً من الإخراق، وأخذوه وأنزلوه إلى المخبأة من غير إخراق ولا بهدلة، وأنزلوا فرشًا ومقعدًا، ونزل معه بعض مماليكِه وبعض الأجلاب أيضًا، وأغلقوا عليه الطابقة، وأخذوا النمجة والدرقة والفوطة ودفعوهم إلى خير بك، بعد أن أطلقوا عليه اسم السلطان، وقبَّل له الأرض جماعةٌ من أعيان الأمراء، وقيل إنهم لقبوه بالملك العادل، كل ذلك بلا مبايعة ولا إجماع الكلمة على سلطنته، بل بفعل هؤلاء الأجلاب الأوباش، غير أن خير بك لما أخذ النمجة والدرقة حدثته نفسه بالسلطنة، وقام وأبعد في تدبير أمره وتحصينِ القلعة، وبينما هو في ذلك فرَّ عنه غالب أصحابه الكبار مثل خشكلدي ومغلباي وغيرهما، فعند ذلك لم يجد خير بك بدًّا من الإفراج عن الملك الظاهر تمربغا ومن معه من خشداشيته ومماليكه، فأخرجوهم ونزل خير بك على رجل الملك الظاهر تمربغا يقبِّلُها، ويبكي ويسأله العفو عنه، وقد أبدى من التضرع أنواعًا كثيرة، فقَبِل السلطان عذره، هذا وقد جلس السلطان الملك الظاهر تمربغا موضع جلوس السلطان على عادته، وأخذ النمجة والدرقة، وقد انهزم غالب الأجلاب، ونزلوا من القلعة لا يلوي أحد منهم على أحد، كل ذلك والأتابك قايتباي بمن معه من الأمراء بالرملة، فلما تم جلوس الملك الظاهر تمربغا بالقصر على عادته، أمر من كان عنده من أكابر الأمراء بالنزول إلى الأتابك قايتباي لمساعدته، ولما تم أمر الأتابك قايتباي من قتال الأجلاب وانتصر، طلع من باب السلسلة، وجلس بمقعد الإسطبل بتلك العظمة الزائدة فكلَّمه بعض الأمراء في السلطنة، وحسَّنوا له ذلك، فأخذ يمتنع امتناعًا ليس بذاك، إلى أن قام بعضهم وقبَّل الأرض له، وفعل غيره كذلك، فامتنع بعد ذلك أيضًا، فقالوا: ما بقي يفيد الامتناع، وقد قبَّلنا لك الأرض، فإمَّا تذعن وإما نسلطن غيرك، فأجاب عند ذلك، فلما تمَّ أمر الأتابك قايتباي في السلطنة، طلع الأمير يشبك بن مهدي الظاهري الكاشف بالوجه القبلي إلى الملك الظاهر تمربغا، وعرَّفه بسلطنة قايتباي، وأخذه ودخل به إلى خزانة الخرجة الصغيرة فكانت مدة سلطنته ثمانية وخمسين يومًا، وحضر الخليفة والقضاة، وبايعوا الأتابك قايتباي بالسلطنة، ولبس خلعة السلطنة السواد الخليفتي، ونودي في الحال بسلطنته بشوارع القاهرة، وتلقب بالملك الأشرف قايتباي المحمودي."},{"id":3473,"title":"تحالف الدول الأوربية لقتال الدولة العثمانية .","date":["العام الهجري :872","الشهر القمري : رجب","العام الميلادي :1468"],"text":"عقدت 25 دولة أوربية- من بينها البندقية وفرنسا وقبرص وبولونيا- معاهدة لقتال الدولة العثمانية التي وجهت فتوحاتها الإسلامية إلى أوربا، لكن هذه الجيوش لم تستطع مواجهة السلطانَ محمد الفاتح!"},{"id":3474,"title":"القتال بين العثمانيين وبين الأمير حسن الطويل التتري .","date":["العام الهجري :874","العام الميلادي :1469"],"text":"استطاع الأمير حسن الطويل التتري الذي تزعَّم قبيلتي الخِراف البيض والخراف السود بعد توحُّدهما أن ينتزع خراسان من الأمير أبي سعيد بن محمد بن ميران شاه بن تيمورلنك بعد معركة انتهت بقتل أبي سعيد، ثم أبرم الأمير حسن هذا معاهدة مع دولة البنادقة ضد الدولة العثمانية، فأصبح قادرًا على تهديد الدولة العثمانية من ناحية المشرق، فهاجم الدولة العثمانية واحتلَّ مدينة توقات، فأرسل إليه السلطان العثماني محمد الفاتح جيشًا في هذا العام فهزمه، ثم سار السلطان الفاتح بنفسه وقاتله حتى قضى على من بقي من جيوشِه."},{"id":3475,"title":"استيلاء البرتغال على مدينة أسفي بالمغرب\n  .","date":["العام الهجري :874","العام الميلادي :1469"],"text":"استولى الفرنج البرتغال على مدينة أسَفِي- بلدة على شاطئ البحر المحيط بأقصى المغرب- وهدموها، وبقيت كذلك مدة تزيد على أربعين سنة، ثم شرعوا في تحصينها والبناء بها، ولم يزالوا مقيمين بها إلى حدود سنة 1154هـ."},{"id":3476,"title":"وفاة المؤرخ ابن تغري بردي .","date":["العام الهجري :874","الشهر القمري : ذي الحجة","العام الميلادي :1470"],"text":"هو جمال الدين أبو المحاسن يوسف ابن الأمير سيف الدين تغري بردي بن عبد الله الظاهري الحنفي، ولد في القاهرة سنة 813، كان أبوه من مماليك الظاهر برقوق ومن أمراء جيوشه، بل صار نائب دمشق في آخر حياته وتوفي فيها، وتفقه ابنه جمال الدين وقرأ الحديث وبرع في التاريخ، وامتاز به واشتهر بتآليفه التاريخية التي منها: النجوم الزاهرة في ملوك مصر والقاهرة، ومنها حوادث الدهور في مدى الأيام والشهور، وله المنهل الصافي والمستوفي بعد الوافي، وهو معجم تراجم، وله نزهة الرأي في التاريخ، وله كتب أخرى في غير التاريخ، مثل: نزهة الألباب في اختلاف الأسماء والألقاب، والبحر الزاخر في علم الأوائل والأواخر، وغيرها من المصنفات. توفي بالقاهرة"},{"id":3477,"title":"قيام دولة بني وطاس بالمغرب خلفًا لدولة بني مرين .","date":["العام الهجري :875","العام الميلادي :1470"],"text":"كان بنو وطاس فرقة من بني مرين غير أنهم ليسوا من بني عبد الحق، ولما دخل بنو مرين المغرب واقتسموا أعماله كان لبني وطاس بلاد الريف، فكانت ضواحيها لنزولهم وأمصارها ورعاياها لجبايتهم، وكان بنو الوزير من بني وطاس يتطلعون إلى الرياسة ويسعون في الخروج على بني عبد الحق، وقد تكرر ذلك منهم، ثم أذعنوا إلى الطاعة وراضوا أنفسهم على الخدمة، فاستعملهم بنو عبد الحق في وجوه الولايات والأعمال واستظهروا بهم على أمور دولتهم، فحَسُن أثرهم لديها وتعدد الوزراء منهم فيها، ولم يزل السرور متربعًا بين أعينهم لذلك والرياسة شامخة بأنوفهم، ولما كانت دولة السلطان أبي عنان واستولى على بجاية عقد عليها لعمر بن علي الوطاسي من بني الوزير فثار عليه أهلها, ثم ولِيَ والد محمد الشيخ أبو زكريا يحيى بن زيان الوطاسي الوزارة للسلطان عبد الحق، وتولى بعده ابنه يحيى فقتله السلطان عبد الحق في جماعة من عشيرته لما رأى منافستهم له في الحكم, وفرَّ أخوه أبو عبد الله محمد الشيخ الوطاسي إلى الصحراء وبقي متنقلًا في البلاد حتى تمكن من جمع الأتباع حوله وهو في الصحراء ودخل بهم آصيلا، وتمكن من حكمها, ثم زحف على فاس وتمكن من دخولها وتمت البيعة له سنة 896."},{"id":3478,"title":"العثمانيون يستولون على قلعة وجزيرة آغريبوز في بحر إيجة .","date":["العام الهجري :875","الشهر القمري : صفر","العام الميلادي :1470"],"text":"كان البابا بيوس الثاني ترأس اجتماع التحالف الذي عُقد في مدينة ريجنس بورغ في نيسان سنة 858 (1454م) بعد فتح محمد الفاتح القسطنطينية، وعاهدته على حرب العثمانيين ثلاثون دولة في أوربا وآسيا، ففي آسيا تحالفت دولة كرجستان جورجيا، ودولة الخرفان البيض آق قويونلو التركمانية المخالِفة للعثمانيين، والمسيطرة على إيران بزعامة حسن الطويل التتري أوزون حسن، ولكن محمد الفاتح لم يهتز لذلك التحالف، بل صمم على المواجهة، وعدم الخضوع للابتزاز، فبدأت الحرب الكبرى في سنة 867 (3 أبريل 1463م)، فهجم الفرنجة من الغرب مع بقية الأوربيين والبابوية، فتصدى للهجوم الأوربي الصدر الأعظم محمود باشا، ومات البابا في طريقه إلى الحرب سنة 867 (1464م) وخاض السلطان معارك عديدة ضد البندقية، وقاد الفاتح غزوة في صيف سنة 874 (1470م) اجتاح فيها قلاع ومواقع البندقية في بحر إيجة، وفتح جزيرة آغريبوز في بحر إيجة، وحرر الصدر الأعظم كديك أحمد باشا سواحل البحر الأبيض المتوسط التي كانت البندقية تسيطر عليها لمدة ستين ومائتين عامًا، وذلك بعد حصار استمر سبعة عشرة يومًا، وولَّد سقوط هذه الجزيرة أحزانًا كبيرة في أوربا لا تقل عن سقوط القسطنطينية؛ نظرًا لأن سيطرة العثمانيين عليها أتاحت لهم سيطرة كبيرة على سواحل البحر المتوسط؛ لذلك أعدَّت البندقية 14 مؤامرة لاغتيال السلطان حتى تموز سنة 883 (1479م) لكنها لم تنجح."},{"id":3479,"title":"استيلاء البرتغال على مدينة آصيلا بالمغرب .","date":["العام الهجري :876","العام الميلادي :1471"],"text":"استولى الفرنج البرتغال على آصيلا بالمغرب وظفروا فيها ببيت مال الوطاسي، وأسروا ولده محمدًا المدعو بالبرتغالي وابنته وزوجتيه وجماعة من الأعيان، وكان الخَطْبُ عظيمًا، وتمكن أبو عبد الله محمد الشيخ الوطاسي من عقد هدنة افتك فيها أهل بيته عدا ولده بقي عند البرتغال سبع سنين ثم افتكَّه والده بعدُ وكان يوم أُسر صبيًّا صغيرًا"},{"id":3480,"title":"وفاة الأمير يحيى بن يشبك المؤيدي .","date":["العام الهجري :876","الشهر القمري : رمضان","العام الميلادي :1472"],"text":"هو الأمير يحيى ابن الأمير الخير الفقيه يشبك المؤيدي سبط السلطان المؤيد شيخ، ولد في ربيع الأول سنة 842, وأمه الخوند آسية بنت السلطان شيخ كانت خيِّرة ديِّنة، عارفة بطرائق الخوندات، ولها شهرة وذكر. مات أبوها السلطان المؤيد وقد زادت على أربع سنين. فتزوجها أبوه الأمير الخير الفقيه يشبك وهو من موالى أبيها بعد موته، وكان لالتها - مربيها- نشأ يحي في عز, فقرأ القرآن واشتغل يسيرًا وجوَّد الكتابة عند البرهان الفرنوي وغيره، وتقدم فيها بحيث كتب بخطه أشياء بديعة، وكان مع ذلك متقدمًا في الفروسية بسائر أنواعها، كالرمح والسيف والدبوس والنشاب وسَوق الخيل، بحيث إنه ساق المحمل عدة سنين، مع حسن المحاضرة والشكالة ولطف العشرة والظرف وجودة الفهم ومزيد الإسراف على نفسه، وتزوج ابنة المحب بن الشحنة واستولدها ابنة ماتت في حياتهما ثم فارقها, وعظُمَ ميل أبيه إليه ومحبته فيه حتى إنه كان المستبدَّ بكثير من الأمور أيام مباشرته الدوادارية الكبرى مع شدة مبالغته في طواعية والده ومزيد خدمته له، وقد رقاه الظاهر خشقدم وأمره بعد سنطباي وغيره وصار أمير أربعين، وسافر في أيامه إلى الحجاز أمير الركب الأول وإلى البلاد الشامية لتقليد بعض النواب ورجع بمال كثير وابتدأ به التوعك من ثمَّ، بحيث أشرف على الموت وتحدَّث به الناس حتى بمكة, ونزل السلطان للسلام عليه وعالجه الأطباء خصوصًا المظفر محمود الأمشاطي حتى نجع ثم انتقض عليه بعد بمدة وتنوعت به الأمراض كالسل ونحوه، بل يقال إنه عرض له داء الأسد وأقام مدة واختلف الأطباء عليه وأكثروا له من الحقن إلى أن انتحل، وتخلى مما عسى أن يكون كل هذا سببًا للتكفير عنه. ومات يحيى وأبوه في دمياط وأمه تقالبه يوم الجمعة السادس عشر رمضان سنة ست وسبعين وصُلي عليه من الغد في جمع حافل جدًّا فيه السلطان، ودفن بالمؤيدية مدرسة جده، قال السخاوي: \"بلغني عن المحب بن الشحنة أنه لم يخلف بعده في أبناء الترك مثله- سامحه الله وإيانا وعوضه وأبويه الجنة\""},{"id":3481,"title":"وفاة الصوفي برهان الدين إبراهيم المتبولي .","date":["العام الهجري :877","الشهر القمري : ربيع الأول","العام الميلادي :1472"],"text":"هو الصوفي إبراهيم بن علي بن عمر برهان الدين الأنصاري المتبولي ثم القاهري الأحمدي، قدم من بلده متبول من الغربية إلى طنطا، فأقام بضريحها مدة ثم تحول إلى القاهرة ونزل بظاهر الحسينية، فكان يدير بها مزرعة ويباشر بنفسه العمل فيها من عزق وتحويل وغير ذلك من مصالحها، وكان يجتمع إذ ذاك بالشيخ إبراهيم الغنام ونزل بزاوية هناك بدرب التتر، تعرف بالشيخ رستم ثم قطن زاوية غيرها بالقرب من درب السباع، وصار الفقراء يَرِدون عليه فيها ويقوم بكلفتِهم من زرعه وغيره، فاشتهر أمره وتزايد خبره وحج غير مرة وانتقل لبركة الحاج، وأنشأ هناك زاوية كبيرة للجمعة والجماعات وبستانًا متسعًا وسبيلًا على الطريق هائلًا عم الانتفاعُ به سيما في أيام الحج، وكذا أنشأ جامعًا كبيرًا بطنطا وبرجًا بدمياط وأماكن غير ذلك، وكثرت أتباعه بحيث صار يُخبَز لهم كل يوم زيادة على أردب، وربما بلغ ثلاثة أرادب سوى عليق البهائم التي بلغت ثمانية أرادب، وهرع الأكابر فضلًا عمن دونهم لزيارته والتبرك به، ونسب إليه جماعته من الكرامات الكثير واستفيض بينهم أنه لم يجب عليه غُسلٌ قط لا من جماع فإنه لم يتزوج، ولا احتلام، بل كان- فيما قيل- يذكر ذلك عن نفسه، ويقول إنه أخذ عن الشيخ يوسف البرلسي الأحمدي وانتفع بصحبته وإنه فتح عليه في سطح جامع الظاهر؛ لأنه أقام فيه مدة وتزاحم الناس عليه في الشفاعات وكان يرفدهم برسائله، بل ربما توجه هو بنفسه في المهم منها، كل ذلك مع أميته ومداومته على الإهداء لكثير من الأمراء ونحوهم من فاكهة بستانه ونحوها، والناس فيه فريقان. مات وقد توجه لزيارة القدس والخليل بعد توعكه مدة بمكان بين غزة والرملة يقال له سدود بالقرب من المقام المنسوب للسيد سليمان، في ليلة الاثنين الثامن عشر ربيع الأول سنة سبع وسبعين، ودفن هناك وسنُّه ظنًّا يزيد على الثمانين."},{"id":3482,"title":"معركة أوطلوق بلي بين العثمانيين وبين التحالف الآسيوي الأوربي .","date":["العام الهجري :878","العام الميلادي :1473"],"text":"تعاهدت ثلاثون دولة أوربية وأسيوية ضد العثمانيين سنة 872 في الثاني من شباط/ فبراير (1468م)، وحاولت قوات التحالف ضم مملكة المماليك المصرية السورية إليهم، ولكن دولة المماليك رفضت ذلك؛ لاشتراكهم مع العثمانيين بالدين والمذهب، وعبأت دول التحالف قواها العسكرية، وخاضت ضد العثمانيين معارك فاشلة، ثم تعاهدت على خوض المعركة العمومية الكبرى بحرًا وبرًّا، وبدأت المعارك البحرية ضد العثمانيين في سواحل البحر الأبيض المتوسط انطلاقًا من قبرص، وتحرك أوزون حسن الآق قوينلو التركماني زعيم دولة الخرفان في إيران بجيش يتجاوز عدده الثلاثمائة ألف خيَّال، وغادر خربوط قاصدًا أرزنجان. وترك السلطان محمد الفاتح قوةً كافية لحماية إسلامبول، وترك ابنه الأصغر جَمَّ سلطان نائبًا عنه أثناء غيابه، وتحرك السلطانُ الفاتح من إسلامبول سنة 877 (11/4/ 1473م) ومعه مائة وتسعون ألف مجاهد يتوزعون في خمسة فيالق. وكان الفاتح يقود فيلق المقدمة، ويقود فيلق الميمنة ابنه الأمير بايزيد الثاني، ويقود الفيلق الأيسر ابنه الأمير مصطفى، وترك في المؤخرة فيلقين للالتفاف على العدو، ووصل إلى سيواس، وقصد عدوه المتآمر، فوصل إلى الجنوب من غومش خانة التركية الشرقية في 11/8/ 1473م، وحصلت المعركة التصادمية في سُهُوب بلدة أوطلوق بلي \"Otlukbeli\" الواقعة شمال شرق مركز محافظة أرزنجان التركية. وتحركت في البلقان قوات الحلفاء التابعة لملك المجر متياس، وإمبراطور ألمانيا فريدرك الثالث، وملك البندقية وتوابعه، وقرر الحلفاء تكرار هزيمة القوات العثمانية مثلما حصل قبل ذلك بإحدى وسبعين سنة في موقعة أنقرة بين السلطان العثماني بايزيد الأول، والطاغية تيمورلنك. ودارت الحرب العالمية بين سلطان المسلمين محمد الفاتح وأعدائه الأوربيين وعملائهم المرتدين الأسيويين، فهجمت أساطيل البندقية وغيرها على المواقع البحرية العثمانية، ولكنها صُدَّت، ولم تحقق انتصارًا يُذكر، وفشلت القوات البرية في البلقان بقيادة الإمبراطور الألماني فريديرك، وملك المجر متياس، وتراجعت أمام هجمات فرسان الرومللي العثمانيين, وبدأت المعركة البرية الكبرى بين قوات السلطان محمد الفاتح، وقوات حسن الطويل التركماني، وانطلقت قذائف المدفعية العثمانية، وبدأ حصاد فرسان العدو، وأوعز الفاتح لفيلقي الاحتياط بالالتفاف على العدو، فشكَّلا فكَّي كمَّاشة، ومنعا عساكر العدو من الفرار، وقَتَلَ الأمير العثماني مصطفى بن الفاتح قائدَ الجناح المعادي زينل ميرزا بن حسن الطويل، وأسر ثلاثة أمراء تيموريين، وهجم الأمير العثماني بايزيد الثاني على سرادق حسن الطويل، فهرب حسن الطويل، من ميدان المعركة، وقال لحليفه القره ماني أحمد بك: \"يا قره مان أوغلو خرَّب الله بيت سلالتك، سَبَّبْتَ خزيي وعاري، مالي وبني عثمان؟\" وأمر الفاتح بعدم ملاحقة الفارين، ومكث في الميدان مدة ثلاثة أيام يتفقد الجرحى والشهداء، وينظِّم أمور الأسرى، وطلب حسن الطويل الصلح، فأجابه الفاتح، ووقَّعا معاهدة صلح تضمنت اعتراف حسن الطويل بامتلاك العثمانيين لمملكتي طرابزون وقره مان، وأصبح حليفًا للعثمانيين في آسيا هو وأولاده من بعده."},{"id":3483,"title":"انقسام دولة بني نصر في غرناطة .","date":["العام الهجري :879","العام الميلادي :1474"],"text":"قامت في مالقة ثورة ولم يُفلح ملك بني نصر الأمير أبو الحسن علي بن سعد من إخمادها، وانتهت هذه الثورة بتقسيم المملكة إلى شطرين؛ شطر يملكه أبو الحسن، وشطر يملكه أخوه الثائر عليه أبو عبد الله محمد بن سعد الملقب بالزغل، وكان ملك قشتالة يبارك هذه الحروب؛ مما أمكنه من الاستيلاء على بعض المواقع والحصون القريبة من غرناطة."},{"id":3484,"title":"محمد الفاتح يوالي انتصاراته فيطرد الجنويين من شبه جزيرة القرم .","date":["العام الهجري :880","العام الميلادي :1475"],"text":"عرض السلطان محمد الفاتح سنة 878 على أمير البغدان استيفان الرابع الجزيةَ؛ حتى لا يحاربه، فلم يقبل الأمير فأرسل إليه جيشًا وانتصر عليه بعد حروب عنيفة، ولكن لم يستطع فتح الإقليم، فعزم السلطانُ على دخول القرم للإفادة من فرسانها في قتال البغدان، وتمكَّن من احتلال أملاك الجنويين الممتدة على شواطئ شبه جزيرة القرم ويطردهم منها، ولم يقاوم التتار سكان القرم العثمانيين، بل دفعوا لهم مبلغًا من المال سنويًّا، وأقلعت السفن البحرية العثمانية من القرم إلى مصب نهر الدانوب، فدخلت وكان السلطان يدخل بلاد البغدان عن طريق البر، فانهزم استيفان الرابع فتبعه السلطان في طريق مجهولة، فانقض عليه استيفان الرابع وانهزم السلطان، فارتفع بذلك اسم استيفان الرابع، وكان هذا في سنة 881."},{"id":3485,"title":"توقيع حاكم شبه جزيرة القرم معاهدة مع السلطان محمد الفاتح .","date":["العام الهجري :880","الشهر القمري : صفر","العام الميلادي :1475"],"text":"وقَّع حاكم شبه جزيرة القرم معاهدة مع السلطان العثماني محمد الفاتح تنصُّ على خضوع شبه جزيرة القرم للعثمانيين، شريطة أن يقوم العثمانيون بتعيين الحاكم من سلالة جنكيز خان، وأن يدعو لخان القرم في الصلاة بعد الدعاء للخليفة العباسي والسلطان العثماني."},{"id":3486,"title":"هزيمة العثمانيين في معركة فاسلوي  .","date":["العام الهجري :881","العام الميلادي :1476"],"text":"أراد السلطان فتح بلاد البغدان، فأرسل إليها جيشًا بعد أن عرض دفع الجزية على أميرها المسمى استيفان الرابع ولم يقبل. فوقعت معركة عنيفة بين الطرفين عُرفت بمعركة فاسلوي، وصل عدد الجنود العثمانيين إلى 120 ألف جندي، بينما بلغ عدد الجنود البغدان 40 ألف جندي، بالإضافة إلى بعض القوات المتحالفة الأصغر حجمًا وبعض المرتزقة, وبعد قتال عنيف قُتِلَ فيه جنود كثر من الجيشين المتحاربين، انهزم الجيش العثماني وعاد دون فتح شيء من هذا الإقليم. وبهذه المعركة اشتهر استيفان الرابع أمير البغدان بمقاومة العثمانيين، فخلع عليه البابا سيكستوس الرابع لقب بطل المسيح."},{"id":3487,"title":"استقرار حكم بني نصر في غرناطة على يد الأمير علي بن سعد .","date":["العام الهجري :882","العام الميلادي :1477"],"text":"كان الأمير أبو الحسن علي بن سعد بعد وفاة والده محجورًا عليه، والأمر كان للقوَّاد ولم يكن له من الملك إلا اسمه، فأراد أن يقوم بنفسه ويزيل عنه الحَجر، فانفرد بنفسه عن قواده كما انفرد معه بعضهم، ووقعت بينهم حروب وأحداث؛ وذلك أنه لما اعتزل عن قواده أخذوا أخاه محمد بن سعد الملقب بالزغل, وكان أصغر منه سنًّا فبايعوه، واشتعلت نار الفتنة بينهم, فأظهر أبو الحسن التوبة للناس ووعدهم إن قاموا معه أن يصلح شأنهم وأن يظهر الأحكام وينظر في مصالح الوطن ويقيم الشريعة، فمالت إليه الرعية وأعانوه على ما نواه من مراده إلى أن ظَفِرَ بخصومه في مدينة مالقة فأخذهم وقتَلَهم كلَّهم, ولم يبقَ له معاند، فاستقام له الأمر ودانت له البلاد، وهو مع ذلك يغزو الفرنج المرة بعد المرة حتى غزا غزوات كثيرة وأظهر الأحكام ونظر في مصالح الحصون، ونما الجيش فهابته النصارى وصالحته برًّا وبحرًا، وكثر الخير وانبسطت الأرزاق ورخصت الأسعار، وانتشر الأمن في جميع بلاد الأندلس وشملتهم العافية في تلك المدة وضربت سكة جديدة طيبة."},{"id":3488,"title":"تأسيس محاكم التفتيش في إسبانيا .","date":["العام الهجري :883","العام الميلادي :1478"],"text":"ظهرت فكرة محاكم التفتيش في القرن الثالث عشر الميلادي مع تزايد غطرسة الكنيسة الكاثوليكية واجتهادها في مراقبة ضمائر الناس في الدول التي كانت تحت سيطرتها، فكان بابا روما يكلف بعض الأساقفة بتعقب من كانت أفكاره مخالفة لتعاليم الكنيسة وطبق هذا النظام في البداية في إيطاليا وفرنسا وألمانيا حيث كان يتجول مندوبو البابا في أنحاء البلاد لتقصي أخبار الناس واتهام كل مخالف بالكفر ثم القبض عليه ومعاقبته, وكانت تُعقَد لذلك مجالس كنسية مؤقتة كانت بمثابة محاكم التفتيش المبدئية. ثم تحل المحكمة بعد مطاردة المتهمين والقضاء عليهم. وهكذا عذبت الكنيسة الكاثوليكية أجيالًا كاملة من المفكرين والعلماء في أنحاء أوربا بكل قساوة وبطرق إجرامية لا تمتُّ للإنسانية بصلة. كان الملك فرديناند ملك أراغوان والملكة إيزابيلا ملكة قشتالة وقتذاك معنيين بالمتنصِّرين في الأندلس بصفة خاصة، آملين أن يأتي وقت يصبح فيه جميع سكان الأندلس من المسلمين مسيحيين مخلصين، وأجرت إيزابيلا مدرسة لأصول الدين لتعليمهم، ومع ذلك فقد احتفظ كثير منهم بعقيدته السالفة سرًّا ولقنوها أبناءهم. وسكنت كراهية الكاثوليك لليهود غير المعمَّدين إلى حين، بينما اشتد الحنق على \"المسيحيين الجدد\" ونشبت الفتن ضدهم في طليطلة (1467م) وبلد الوليد (1470م) وقرطبة (1472م) وسيجوفيا (1474م) وأصبحت المسألة الدينية عنصرية، ودبر الملك والملكة الوسائل التي تحول هذا المزيج المضطرب في الشعوب واللغات والمذاهب المتصارعة إلى وحدة منسجمة وسلام اجتماعي. ورأيَا أن خير وسيلة لبلوغ هذه الأهداف هي تأسيس محاكم التفتيش في إسبانيا. خاصة أن إيزابيلا التي عاشت في جو علماء الدين كانت تتبنى آراء دينية متشددة تجاه المخالفين للكاثوليكية من النصارى واليهود فضلًا عن المسلمين. ولعل فرديناند، الذي كان رجلًا صلبًا من رجال الدنيا قد ارتاب في بعض إجراءات هذه المحاكم، ولكن يبدو أنه اقتنع بأن توحيد العقيدة الدينية يجعل إسبانيا أيسر حكمًا، وأقدر في التغلب على أعدائها. ولقد أصدر البابا سكستوس الرابع، بناء على رغبة فردينان وإيزابيلا، قرارًا في هذه السنة 883 (أول نوفمبر 1478م) يفوض لهما أن يعينا ستة قسس، من ملة الإجازات العليا في علوم الدين والشريعة، ليؤلفوا هيئة محكمة التفتيش؛ ليحققوا تهم الهرطقة ويعاقبوا عليها. ووضعت الهيئة برُمَّتها بعد سنة 889 (1483م) تحت إمرة وكالة حكومية، ولم تمسَّ محاكم التفتيش في أول أمرها اليهود الذين لم يتنصروا، وإنما وجهت أهوالها إلى المتنصرين الذين يشكُّ أنهم ارتدوا إلى اليهودية أو إلى الإسلام، وإلى المسيحيين المتهمين بالهرطقة، وكان اليهودي غير المتنصر إلى سنة 900 (1492م) آمنًا على نفسه أكثر من المعمَّد، وطالب القس والرهبان والمتعبدون الإعفاء من التفتيش، ولكن مطالبهم رُفضت، وقاوم اليسوعيون تشريعَها نصف قرن، ولكنهم غُلبوا على أمرهم أيضًا, وكانت محاكم التفتيش تطالب بتعاون من جميع الموظفين المدنيين، وشرعت القوانين والإجراءات الخاصة بها. وكانت قبل أن تقيم قضاتها في مدينة من المدن تذيع في الشعب عن طريق منابر الكنائس منشورًا دينيًّا \"يطالب كل من له علم بهرطقة أن يكشف عنها لرجال التفتيش, وشجع كل امرئ على أن يكون شاهدًا، ليبلغ عن جيرانه وأصدقائه وأقاربه، وكان البابا ستيكوس الرابع أصدر الموافقة على طلب الملكة إيزابيلا ملكة مملكة قشتالة بإنشاء محاكم تفتيش لتزيد من سلطانها باسم الدين النصراني, كما أصدر الملك أنريكي الرابع، ملك قشتالة، سنة 863 (1459م) أمرًا ملكيًّا للأساقفة بالبحث والاستقصاء في دوائرهم عن المارقين المضمرين لأفكار مخالفة للكثلكة. وهكذا ابتدأ الاضطهاد الكنسي ضد اليهود المتنصرين فأحرق منهم الجمَّ الغفير قبل سقوط غرناطة. ولم تشمل هذه المحاكم آنذاك المسلمين أو المدجنين- المداهنين- بعدُ، بل أرسل سكتوس الرابع- بابا روما- مرسولًا كلفه بالتحقيق والقبض على الخارجين على الكنيسة ومعاقبتهم. فخاف الملكان فراندو وإيزابيلا أول الأمر على سلطتِهما ووقفا ضد هذه المحاولة البابوية، فأوقفا القساوسة من متابعة النصارى من أصل يهودي. لكن مقاومة الملكين الكاثوليكيين لم تدم طويلًا؛ إذ أرسلا سفيرهما إلى البابا سنة 1478 م في هذا الأمر. فأصدر البابا مرسومًا في شهر نوفمبر من سنة 1478 م بإنشاء محكمة التفتيش في قشتالة وتعيين المفتشين لمطاردة الكفر ومحاكمة المارقين, وندب مفتشين إلى إشبيلية، عاصمة قشتالة آنذاك. وهكذا ابتدأت محاكم التفتيش عملها الجهنمي ضد المسلمين في إسبانيا. فكانت إجراءات هذه المحاكم تتم باسم الديانة الكاثوليكية وتقضي على المناوئين لها ولسياستها ومصادرة ممتلكاتهم، والأمر بتعذيبهم وإحراقهم، ثم انتقلت هذه المحاكم إلى غرناطة بعد سقوطها بيد الإسبان سنة 897 (1489م)."},{"id":3489,"title":"حادثة سيل غرناطة العظيم \n  .","date":["العام الهجري :883","العام الميلادي :1478"],"text":"كان من قضاء الله عز وجل وما قدَّره في آخر أيام مهرجان كبير عند أهل غرناطة حيث يجتمع فيه جُل أهل غرناطة من رجال ونساء وصبيان وشيوخ وكهول وكثير من أهل القرى حول غرناطة للنزهة، فاجتمعوا في السبيكة من الحمراء وما حولها وامتلأت تلك المواضع بالخلق الكثير، وأقبلت الفرسان وصاروا يتألفون في السبيكة وذلك وقت الضحى، فبينما الناس كذلك في المهرجان إذا بسحابة عظيمة قد أنشأها الله تعالى في السماء فأرعدت وأبرقت وانتشرت من ساعتها بقدرة مكوِّن الأشياء على السبيكة وما قرب منها وعلى غرناطة وما حولها وعلى وادي هداره، وجاءت بمطر عظيم ولم يزل المطر يزداد ويعظم ويكثر حتى صار كالأنهار العظيمة وجاءت السيول من كل ناحية وعظُم أمرها وعاين الناس الهلاكَ مِن عِظَم ما رأوا من شدة المطر وكثرة السيول من كل ناحية، واحتمل السيل الطرق وما حولها وانقطع الناس وحال السيل بينهم وبينها، فكان لا يُسمع إلا بكاء الصبيان وضجيج النسوان وأصوات الرجال بالدعاء إلى الله تعالى والابتهال، إلى أن ارتفع المطر وجاء وادي هداره الذي يشق غرناطة بسيل عظيم احتمل ما على ضفتيه من الأشجار العظام من الجوز واللوز وغير ذلك من الأشجار العظام الثابتة في الأرض، ودخل البلد واحتمل ما على ضفتيه من الدور والحوانيت والمساجد والفنادق ودخل الأسواق، وهدم البناء المشيد ولم يبقَ من القناطير إلا الأقواس، وذهب بكل ما كان عليها من البنيان، ثم جاء السيل بتلك الأشجار العظام التي اقتلعت فتراكمت في البلد في آخر قنطرة منه، فسُدَّت مجاري الوادي فتراكم السيل والشجر في قلب البلد، وعاين الأهالي الهلاكَ ودخل السيل تياره والقيسارية حتى دخل بعض حوانيتها، ووصل إلى رحبة الجامع الأعظم وإلى القراقين والصاغة والحدادين وغير ذلك من الأسواق والدور، فلطف الله تعالى بعباده فنفض السيل بقوة تراكمه بالقنطرة والسور وخرج ذلك كله خارج البلد، وكان هذا اليوم من أعظم الأيام شاهد فيه كل من رآه قدرة القادر القهار الملك العلام سبحانه وتعالى، ولم يسمع المعمَّرون بمثل ذلك اليوم."},{"id":3490,"title":"السلطان محمد الفاتح يجبر إمارة البندقية على توقيع معاهدة إستانبول .","date":["العام الهجري :883","الشهر القمري : ذي القعدة","العام الميلادي :1479"],"text":"أجبر السلطان محمد الفاتح إمارة البندقية على توقيع معاهدة إستانبول، التي انسحبت- بناء على شروطها- من حرب العثمانيين، وفرضت عليها غرامات الحرب، وجزية سنوية. وكانت هذه المعاهدة أولَ خطوة خطَتْها الدولة العثمانية للتدخل في أوربا، وكانت البندقية أهمَّ دول أوربا من الناحية التجارية."},{"id":3491,"title":"استسلام مدينة أشكودرا للسلطان محمد الفاتح .","date":["العام الهجري :883","الشهر القمري : ذي القعدة","العام الميلادي :1479"],"text":"استسلمت مدينة أشكودرا الواقعة في شمال ألبانيا والتي كانت خاضعة لحكم البنادقة إلى السلطان العثماني محمد الفاتح؛ حيث استخدم الفاتح في حصارها أنواعًا جديدة من الأسلحة النارية والمدافع الضخمة، وكانت حملة أشكودرا هي آخر حملات السلطان محمد الفاتح التي بلغت 25 حملة سلطانية كبرى."},{"id":3492,"title":"وفاة الخليفة العباسي المستنجد بالله يوسف وتولي ابن أخيه المتوكل .","date":["العام الهجري :884","الشهر القمري : محرم","العام الميلادي :1479"],"text":"هو الخليفة العباسي المستنجد بالله أبو المحاسن يوسف بن المتوكل على الله محمد بن المعتضد توفي في الرابع عشر محرم بعد أن أصابه الفالج الذي بقي بسببه مريضًا مدة شهرين، فكانت مدة خلافته قرابة الخمس وعشرين سنة إلا خمسة أشهر، ثم تم تولية ابن أخيه عبد العزيز بن يعقوب بن محمد المتوكل الخلافة وتلقيبه بالمتوكل على الله."},{"id":3493,"title":"محمد الفاتح يستولي على الجزر بين اليونان وإيطاليا .","date":["العام الهجري :885","الشهر القمري : جمادى الأولى","العام الميلادي :1480"],"text":"صالَحَ السلطان محمد الفاتح البنادقة وانهزم أمام المجر عندما سار لفتح ترانسلفانيا، ولكنه في البحر فتح الجزر التي بين اليونان وإيطاليا كما فتح مدينة أوترانتو في جنوبي شبه جزيرة إيطاليا، وحاصر أيضًا جزيرة رودوس، لكن لم يتمكن من فتحها، وكل ذلك كان في هذا العام."},{"id":3494,"title":"وفاة العلامة برهان الدين البقاعي الشافعي .","date":["العام الهجري :885","الشهر القمري : رجب","العام الميلادي :1480"],"text":"هو الشيخ الإمام القدوة العلامة المحدِّث المفسِّر المؤرِّخ برهان الدين أبو الحسن إبراهيم بن عمر بن حسن الرباط بن علي الشافعي، البقاعي الأصل، نسبة إلى سهل البقاع في سوريا، ولد سنة 809, وهو من أعيان جماعة شيخ الإسلام ابن حجر، سكن دمشق، قال البقاعي: \"في ليلة الأحد تاسع شعبان سنة 821 أوقع ناسٌ من قريتنا خربة روحًا من البقاع يقال لهم: بنو مزاحم بأقاربي بني حسن من القرية، فقتلوا تسعة أنفس، منهم والدي عمر بن حسن الرباط وشقيقه محمد سويد، وعلي أخوهما لأبيهما، وضُربت أنا بالسيف ثلاث ضربات إحداها في رأسي فجرحتني، وكنت إذ ذاك ابن اثنتي عشرة سنة، فخرجنا من قريتنا، واستمرينا نتنقل في قرى وادي التيم، والعرقوب، وغيرهما، إلى أن أراد الله تعالى بإقبال السعادتين الدنيوية والأخروية، فنقلني جدِّي لأمي علي بن محمد السليمي إلى دمشق- فنزل ببيت العدوي قبالة الناصرية بالقرب من الجامع الأموي- فجوَّدت القرآن، وجدَّدت حِفظَه، وأفردت القراءات وجمعتها على بعض المشايخ، ثم على الشَّمس ابن الجزري لما قدم إلى دمشق سنة 827، واشتغلت بالنحو، والفقه، وغيرهما من العلوم، وكان ما أراد الله تعالى من التنقُّل في البلاد والفوز بالغزو والحج\" ثم رحل البقاعي إلى بيت المقدس والقاهرة، فبرع في عدة علوم، وله مصنفات أشهرها: تنبيه الغبي إلى تكفير ابن عربي؛ حيث ألفه للرد على ابن الفارض وابن عربي، وبين وجه تكفيرهما من أقوالهما وأحوالهما، وله عنوان الزمان في تراجم الشيوخ والأقران، وأخبار الجلاد في فتح البلاد، وغيرها من الكتب."},{"id":3495,"title":"وفاة السلطان العثماني محمد الفاتح وتولي ابنه بايزيد الثاني .","date":["العام الهجري :886","العام الميلادي :1481"],"text":"هو السلطان المجاهد الغازي أبو الفتوحات: محمد بن السلطان مراد الثاني ابن السلطان محمد ابن السلطان بايزيد ابن السلطان مراد الأول بن أورخان بن عثمان، تنازل له أبوه بالملك سنة 848 لكنه لم يستقر فيه إلا بعد وفاة أبيه سنة 855. اقتفى أثر أبيه في المثابرة على دفع الفرنج حتى فاق ملوك زمانه، مع وصفه بمزاحمة العلماء، ورغبته في لقائهم، وتعظيم من يَرِدُ عليه منهم، وله مآثر كثيرة من مدارس وزوايا وجوامع، كان مُلكُ محمد الفاتح عظيمًا خاصة بعد فتحه للقسطنطينية عاصمة البيزنطيين وجعْلِها كرسي مملكته، غادر السلطان الفاتح إستنبول إلى آسيا الصغرى؛ حيث كان قد أُعد في إسكدار جيش آخر كبير، وكان السلطان محمد الفاتح قبل خروجه من إستنبول قد أصابته وعكة صحية إلا أنه لم يهتمَّ بذلك لشدة حبه للجهاد وشوقه الدائم للغزو، وخرج بقيادة جيشه بنفسه، إلا أن المرض تضاعف عليه هذه المرة وثقلت وطأتُه بعد وصوله إلى اسكدار فطلب أطباءَه غيرَ أنَّ القضاء حمَّ به فلم ينفع فيه تطبيبٌ ولا دواء، ومات السلطان الفاتح وسط جيشِه العرمرم يوم الخميس الرابع من ربيع الأول 886 (3 مايو 1481م) وهو في الثانية والخمسين من عمره بعد أن حكم نيفًا وثلاثين عامًا، لم يكن أحدٌ يعلم شيئًا عن الجهة التي كان سيذهب إليها السلطان الفاتح بجيشه، وذهبت ظنونُ الناس في ذلك مذاهبَ شتى، فهل كان يقصد رودس ليفتح هذه الجزيرة التي امتنعت على قائده مسيح باشا؟ أم كان يتأهب للحاق بجيشه الظافر في جنوبي إيطاليا ويزحف بنفسِه بعد ذلك إلى روما وشمالي إيطاليا ففرنسا وإسبانيا؟ توفي أوائل هذه السنة أثناء توجهه إلى برصا، ودفن بالبرِّية هناك، ثم حول إلى إستنبول في ضريح بالقرب من أكبر الجوامع بها, وبعد وفاة السلطان محمد الفاتح تولى ابنُه بايزيد الثاني أكبر أولاده الذي كان حاكمًا لمقاطعة أماسيا."},{"id":3496,"title":"الخلاف بين الأخوين بايزيد بن محمد الفاتح وأخيه جم .","date":["العام الهجري :886","العام الميلادي :1481"],"text":"بعد أن توفِّي السلطان العثماني محمد الفاتح كان كلٌّ من ولديه بعيدًا عنه، فالأوَّلُ بايزيد وهو الأكبر كان حاكمًا لمقاطعة أماسيا، وكان الآخر جم حاكمًا لقرمان، وكانت رغبة الصدر الأعظم قرماني محمد باشا في تولية الأمير جم؛ لذا أرسل إليه من يخبره بوفاة أبيه كي يأتي بأسرع وقت لتسلم الأمر، غيرَ أن حاكم الأناضول سنان باشا علم بالأمر فقتل رسول الصدر الأعظم حيث كانت رغبة الانكشاريين مع بايزيد؛ ولذلك لما علموا بما فعله الصدر الأعظم ثاروا عليه وقتلوه ونهبوا المدينةَ وأقاموا كركود نائبًا عن أبيه، وعندما وصل الأمير بايزيد استقبله الانكشاريون وبايعوه بالسلطنة وتسلَّم الأمر، أما جم فلما علم بالخبر سار إلى بورصة واحتلَّها عنوةً ودعا أخاه بايزيد لتقسيم البلاد فيستحوذ جم على القسم الآسيوي، ويستحوذ بايزيد على القسم الأوربي، الأمر الذي أثار بايزيد فسار إلى بورصة ففر منه جم ملتجئًا إلى المماليك عند السلطان قيتباي في القاهرة، وبقي عنده سنة ثم عاد إلى حلب وبدأ بمراسلة القاسم حفيد أمراء قرمان ووعده أن يعيد له إمارة قرمان إن تمكن من السلطة، فسارا معا للهجوم على قونية لكنهما فشلا فشلًا ذريعًا، ثم حاول جم الصلح مع أخيه على أن يعطيه مقاطعة فرفض بايزيد؛ لأن هذا سيكون بداية انقسام الدولة العثمانية، ثم التجأ جم إلى رودس حيث يوجد بها فرسان القديس يوحنا، وعقد مع رئيس الفرسان اتفاقًا إلا أنه نقضه تحت ضغط بايزيد وأصبح جم سجينًا في جزيرة رودس، وكسب فرسان القديس يوحنا بهذه الرهينة الخطيرة امتيازات طورًا من بايزيد الثاني، ومرة أخرى من أنصار جم بالقاهرة، فلما تحصَّل على أموال ضخمة باع رهينته للبابا أنوست الثامن، فلما مات هذا البابا ترك جم لخلفه إسكندر السادس، ولكن الأخير لم يبقِ على جم كثيرًا؛ حيث قُتِل واتُّهِم في ذلك بايزيد الثاني الذي تخلص من خطر أخيه."},{"id":3497,"title":"قيام الدولة الروسية القيصرية وطرد المغول من أراضيها .","date":["العام الهجري :886","العام الميلادي :1481"],"text":"استطاع الدوق إيفان الثالث أن يرقى على عرش روسيا بعد أن ضم الأمراء الروس إليه وجمعهم حوله، ثم جهز حملة قوية قاتل بها المغول في معركة جرت حول نهر أوكا وتمكَّن فيها من تحطيم المغول وهم يتقدمون إلى موسكو مستغلًّا ما بين قبائلهم من خلاف، فتحرر الروس من المغول وتلقَّب إيفان بالقيصر."},{"id":3498,"title":"حدوث خسف في مدن وقرى ببلاد الروم .","date":["العام الهجري :886","الشهر القمري : محرم","العام الميلادي :1481"],"text":"حصل خسف في بلاد الروم (بلاد ابن عثمان) في ثلاث مدن وقرى، وقيل في خمسة."},{"id":3499,"title":"احتراق غالب الحرم النبوي .","date":["العام الهجري :886","الشهر القمري : رمضان","العام الميلادي :1481"],"text":"نزلت صاعقة على هلال المئذنة تجاه الحجرة النبوية، ثم على سطح المسجد، فاحترق بنارِها المسجِدُ الشريف النبوي؛ سَقفُه، وحواصلُه، وخزائِنُ كتُبِه، وربعاته، ولم يبقَ من قناطره وأساطينه إلَّا اليسيرُ، وكانت آيةً من آيات الله تعالى.، وصعدت الرأس إلى الريس- وكان من أهل العلم - بالمئذنة فاحترق، واحترق في الحرم عالمٌ آخر خرج من بيته لطلب ولدِه، وصل الخبرُ من المدينة المشرَّفة بمحضر يكتتب بالكائنة التي اتفقت بالمدينة من الحريق الأعظم، فحصل عند الناس بذلك باعثٌ شديدٌ. وأخذ السلطان في الاهتمام بشأن هذا الحادث والاجتهاد في القيام ببناء المسجد الشريف النبويِّ، ثم عَمِل بتقدير النفقة عليه، فكانت نحوًا من مائة ألف دينار. ثم بُني بعد ذلك وأُعيد أحسَنَ ما كان، وبُنِيت القبَّة المعظَّمة على القبر الشريف بعد إحكام بناء القبر أيضًا، وعُمِلت المقصورة الهائلة النادرة، وكانت هذه من أجلِّ المباني وأعظمِها."},{"id":3500,"title":"استيلاء الفرنج على مدينة الحامة في غرناطة .","date":["العام الهجري :887","العام الميلادي :1482"],"text":"بدأ ملك الأمير أبي الحسن علي بن سعد ملك غرناطة في التقهقر والانتكاس والانتقاض. من وقت السيل العظيم سنة 883 الذي أصاب غرناطة؛ وذلك أن الأمير اشتغل باللذات والانهماك في الشهوات واللهو بالنساء المطربات، وركن إلى الراحة والغفلات، وضيع الجند وأسقط كثيرًا من نجدة الفرسان وثقَّل المغارم وكثَّر الضرائب في البلدان ومكَّس الأسواق ونهب الأموال وشحَّ بالعطاء، إلى غير ذلك من الأمور التي لا يثبت معها المُلك, وكان للأمير أبي الحسن وزير يوافقُه على ذلك ويُظهِرُ للناس الصلاحَ والعفاف وهو بعكس ذلك، وانصرف عن تقوية عساكره، فأهمل كل من فيه نجدة وشجاعة من الفرسان ويقطع عنهم المعروف والإحسان حتى باع الجند ثيابهم وخيلهم وآلات حربهم وأكلوا أثمانها، وقَتَل كثيرًا من أهل الرأي والتدبير والرؤساء والشجعان من أهل مدن الأندلس وحصونها، ولم يزل الأمير مستمرًّا على حاله والجيش في نقص والملك في ضعف إلى أن انقضى الصلح الذي كان بينه وبين النصارى في محرم سنة 887 فلم يشعر بهم أحد حتى دخلوا مدينة الحامة؛ وذلك أنهم طرقوها ليلًا على حين غفلة من أهلها فدخلوا قصبَتَها وكانت خالية، فلم يكن بها إلا عيال قائدها فملكوا القصبة والناس نيام مطمئنون، فلم يشعر أحد إلا والنصارى قد هبطوا من القصبة على البلد بالسيف والقتل والسبي الشديد حتى قتل من نفد أجَلُه وفَرَّ من قَدَر على الفرار واستولى النصارى على البلد وجميع ما كان فيه من الرجال والنساء والصبيان والأموال، وكان ذلك في التاسع عشر محرم، فلما بلغ أهل غرناطة ما فعل النصارى بإخوانهم المسلمين هاجت الرعية وقالوا: لا صبر لنا على هذه المصيبة العظمى ولا خير لنا في عيش بعد هذه النكبة الكبرى، إما أن نفك إخواننا أو نموت دونهم، فاجتمعوا مع الأمير أبي الحسن ووزيره فجعل الأمير والوزير يعجِّزانهم عن المسير ويتربصان بهم ويقولان لهم اصبروا حتى نأخذ أُهبَتَنا ونعمل على حال الحرب، فلم تزل بهم العامة حتى أخرجوهما فتقدم صدر الجيش فوجدوا النصارى قد أخرجوا من البلد ما سَبَوا من الرجال والنساء والصبيان والأموال، وقد أوقروا الدواب بذلك وهم عازمون على المسير إلى بلادهم، فلما رأوا خيل المسلمين قد أقبلت عليهم حطوا الأحمال ودخلوا البلد وتحصَّنوا بالأسوار ثم أقبل المسلمون بحملتهم واقتربوا منهم فقاتلوهم قتالًا شديدًا بجِدٍّ وعزم وقلوب محترقة وحزم، حتى دخلوا بعض أبواب المدينة وكسروه وحرقوه وتعلقوا بأسوار البلد وطمعوا في الدخول إليه، فبينما هم كذلك إذ وصل لهم أمر من الأمير أبي الحسن والوزير يأمرانهم فيه بالرجوع عن القتال، فأبى الناس عن الرجوع فقالا لهم: إذا كان غدًا ندخل عليهم أول النهار؛ لأن الليل قد أقبل ودخل علينا فترك الناس القتال ورجعوا إلى محلاتهم، أما النصارى فباتوا يصلحون شأنهم ويمنعون أسوارهم ويغلقون نقابهم، فلما أصبح الصباح ونظر المسلمون إلى البلد فإذا هو على صفة أخرى من المنعة والتحصين والاستعداد، فصَعُب عند ذلك على المسلمين الدخول إليه بل والدنو منه، ومع ذلك عزم المسلمون على حصار البلد والإقامة عليه فأقبلت وفود المسلمين من كل أرض من بلاد الأندلس، واجتمع في ذلك المحل محلة عظيمة وفتحوا الأسواق للبيع والشراء وجلبوا لأسواقهم كل ما يحتاجون إليه من الأطعمة والعلف والزاد وغير ذلك، وحاصروا العدو حصارًا شديدًا ومنعوا عليه الماء والحطب والداخل والخارج، والعامة في ذلك بحزم وعزم وجِدٍّ واجتهاد ونية صادقة وقلوب محترقة، والوزير يعد الناس بالدخول والقتال وعدًا بعد وعد، ويقول عن قريب نأخذهم عطشًا وها نحن نُعمل الحيلة في الدخول عليهم، وكان التقصير والتفريط والغش يبدو منه شيئًا بعد شيء حتى تبين لعامة الناس وخاصتهم ولاح لهم كالشمس، وظنوا بالملك والوزير ظنونَ السوء وكثر الكلام القبيحُ بينهم، فعند ذلك هاج شيطان الفتنة بينهم وتحدث الناس بعضهم مع بعض في مسائل غشِّهما للمسلمين، فبينما الناس كذلك في إساءة ظنهم بأميرهم وبوزيرهم إذا بهما قد استعملا حيلةً وكتبا كتبًا مزورة كأنها أتتهما من بعض من نصحهم من ناحية المسلمين المجاهدين المجاورين لبلاد الكفرة يعلمونَهم بها أن الطاغية ملك النصارى جمع جمعًا عظيمًا وحشد حشودًا كثيرة وعزم على نصرة النصارى المحصورين في بلد الحامة وهو قادم عن قريب، ولا طاقة لكم بملاقاته فحين أعلمهم الوزير بما ذُكر وخوفهم بذلك سُقِط في أيدي الناس فأمرهم حينئذ بالرحيل والإقلاع عن دار الحرب فرحل الناس كرهًا باكين متأسفين بحسرة وفجعة يا لها من حسرة!! وانصرف الناس كل واحد إلى وطنه."},{"id":3501,"title":"تمرد ابني ملك غرناطة في أخطر مراحل وجود المسلمين في الأندلس  .","date":["العام الهجري :887","العام الميلادي :1482"],"text":"كان الأمير أبو الحسن علي بن سعد ملك غرناطة متزوجًا بعائشة الحرة ابنة عمه الأمير محمد الأيسر وله منها ولدان محمد ويوسف, وكان من جملة انهماك الأمير أبي الحسن في الملذات أنه اصطفى على زوجته رومية اسمُها ثريا وهجر ابنة عمه وأولادها منه، فأدرك ابنة عمه من الغيرة ما يدرك النساء على أزواجهن، ووقع بينهما نزاع كثير وقام الأولاد محمد ويوسف مع أمهما وغلظت العداوة بينهم، وكان الأمير أبو الحسن شديد الغضب والسطوة، فكانت الأم تخاف على ولديها منه، فبقيت الحال كذلك مدة والأمير مشتغل باللذات منهمك في الشهوات، ووزيره يضبط المغارم, وفي يوم انتصار المسلمين على النصارى في موقعة لوشة بلغ الخبر لمن كان فيها أن ابني الأمير أبي الحسن محمد ويوسف هربا من القصبة خوفًا من أبيهما؛ وذلك أن شياطين الإنس صاروا يوسوسون لأمهما عائشة ويخوفونها عليهما من سطوة أبيهما ويغوونها مع ما كان بينها وبين مملوكة أبيهما الرومية ثرية من الشحناء، فلم يزالوا يغوونها حتى سمحت لهم بهما فاحتالت عليهما بالليل وأخرجتهما إليهم وساروا بهما إلى وادي آش، فقام أهل وادي آش بدعوتهما ثم قامت غرناطة أيضًا بدعوتهما واشتعلت نار الفتنة ببلاد الأندلس، ووقعت بينهم حروب بينهم إلى أن قتل الوالد ولَدَه ولم تزل نار الفتنة مشتعلة وعلاماتها قائمة في بلاد الأندلس، والعدو مع ذلك كله مشتغل بحيلته في أخذ الأندلس, ويعمل على اتحاد كلمتهم حتى تزوج فرناندو ملك أراجون من إيزابيلا ملكة قشتالة، واتحدت الممالك الصليبية في إسبانيا لأول مرة في تاريخها ضد المسلمين."},{"id":3502,"title":"موقعة لوشة العظيمة وانتصار المسلمين فيها .","date":["العام الهجري :887","الشهر القمري : جمادى الأولى","العام الميلادي :1482"],"text":"لما رأى فرديناند الخامس ملك قشتالة أن المسلمين قد عجزوا عن أخذ الحامة ونصرة من فيها من الأسارى، وقع له الطمع في بلاد الأندلس، فأخذ في الاستعداد والخروج إليها. طلب فرديناند الخامس من أبي عبد الله محمد بن سعد الملقب بالزغل أمير مالقة إمضاء معاهدة يكون فيها أمير مالقة تابعًا لقشتالة، فرفض ذلك أمير مالقة، فقام ملك قشتالة بإعلان الحرب عليه, فلما كان جمادى الأولى من هذا العام خرج ملك قشتالة بحملة عظيمة، وقصد مدينة لوشة فنزل عليها بحملته، وكان قد اجتمع فيها جملة من نجدة رجال غرناطة حين سمعوا بخروجه إليها فلما قرب من البلد خرج إليه الرجال والفرسان فقاتلوه قتالًا شديدًا وردوه على أعقابه وقتلوا كثيرًا من النصارى وأخذوا لهم من تلك العدة التي قربوا بها من النفط وغيره من عدة الحرب، ثم إن الأمير أبا الحسن علي بن سعد أمدهم بقائد من غرناطة يقود جيشًا من الفرسان في تلك الليلة فاشتدت عند ذلك عصبة المسلمين وقويت قلوبهم فلما أصبح الصباح ورأى النصارى الزيادة في جيش المسلمين مع ما نالهم من أول الليل من الهزيمة والقتل وأخذ العدة، داخَلَهم الرعب واشتد خوفهم فأخذوا في الارتحال عنهم، فخرج إليهم المسلمون فقاتلوهم قتالًا شديدًا، فانهزم النصارى وتركوا كثيرًا من أخبيتهم وأمتعتهم وأطعمتهم وآلة حربهم، وتركوا من الدقيق شيئًا كثيرًا فاحتوى المسلمون على جميع ذلك كله وانصرف العدو مهزومًا مفلولًا إلى بلده، ففرح المسلمون بذلك فرحًا عظيمًا، وكان ذلك في السابع والعشرين من جمادى الأولى."},{"id":3503,"title":"تنازل الأمير أبو الحسن ملك غرناطة عن الملك لابنه أبي عبد الله .","date":["العام الهجري :888","العام الميلادي :1483"],"text":"لما فقد الأمير أبي الحسن علي بن سعد بصَرَه، تنازل عن المُلك لابنه أبي عبد الله محمد الثاني عشر الملقب بأبي عبد الله الصغير، الذي كان قد ثار على أبيه السنة الماضية, وبعد أن تولى الحكم قام بانتهاز فرصة هزيمة الإسبان أمام أمير مالقة عمه أبي عبد الله الزغل, فخرج بقواته واتجه إلى قرطبة، مجتاحًا في طريقه عدة حصون وهزم الإسبان في عدة معارك محلية، وحين عودته وبيده الغنائم الكثيرة أدركه الإسبان وقاتلوه مرة أخرى وهزموه وأسروه وقتلوا عددًا كبيرًا من أمرائه وفرسانه، فقام الملك أبو الحسن باستدعاء أخيه أبي عبد الله محمد بن سعد الملقب بالزغل؛ ليتولى ملك غرناطة عوضًا عن ابنه المأسور أبي عبد الله الصغير."},{"id":3504,"title":"ثلوج بالأحساء تسبب معوقات في أثناء عودة الحجيج .","date":["العام الهجري :888","الشهر القمري : محرم","العام الميلادي :1483"],"text":"حصل على الحجيج في وقت رجوعهم للأحساء مشقة عظيمة، لم يُعهَدْ مِثلُها؛ وذلك بسبب الثلج الذي نزل عليهم، وقُتِلَ به خلق كثير وجِمال، وذهب للناس أموال لا تعَدُّ ولا تحصى."},{"id":3505,"title":"الإفراج عن ملك غرناطة المأسور وعقد صلح بشروط مع القشتاليين .","date":["العام الهجري :889","العام الميلادي :1484"],"text":"كان الإسبان قد أسروا الملك أبا عبد الله محمد الصغير، وفي هذه السنة تم فك أسره بسعاية أمِّه الأميرة عائشة الحرة، بعد مفاوضات انتهت بعقد معاهدة مع ملك قشتالة تقتضي دفع غرامة مالية باهظة، والإفراج عن الأسرى الإسبان، وأن يكون الملك أبو عبد الله الصغير تحت حكم قشتالة وحكم ملكها فرديناند إلى غير ذلك من شروط مهينة، تحقِّقُ سياسة الاستيلاء على غرناطة."},{"id":3506,"title":"وفاة الشيخ المحب أبو الفضل محمد ابن الشِّحْنَة الصَّغير\n  .","date":["العام الهجري :890","العام الميلادي :1485"],"text":"هو الشيخ العلَّامة أبو الفضل المحبُّ محمد بن محمد أبو الوليد بن محمد بن محمود بن غازي بن أيوب بن محمود الثقفي، الحلبي، الحنفي ابن الشحنة الصغير، عالم الحنفية بحلب. ولد سنة 804, والشحنة هو جدُّه الأعلى محمود الأول كان شحنة حلب ووالده أبو الوليد المتوفى سنة 815 يعرف أيضًا بابن الشحنة. كان المحبُّ هذا عالِمًا فاضلا، عارفًا بالفنون له وجاهة ورياسة، وولي الوظائف الجليلة، ولِيَ قضاء العسكر بحلب ثم قاضي الأحناف بها ثم النظر في جيش حلب وقلعتها وخطابة الجامع الكبير فيها، وتوالت عليه المحن، فترك حلب وقدم مصر فتولى كتابة السر فيها, ثم توجه لبيت المقدس، ثم أذن له بالعودة فقدم القاهرة وأعيد إلى كتابة السر فيها, وله نظم ونثر وتصانيف."},{"id":3507,"title":"استيلاء الإسبان على مدينة رندة .","date":["العام الهجري :890","العام الميلادي :1485"],"text":"قام الفرنج الإسبان بالهجوم على مدينة رندة فحاصروها وقذفوها بالنفط وهدموا أسوارها، فاضطرت المدينة للاستسلام، وغادر أهلها منها فاستولى الإسبان على سائر الأماكن والحصون الواقعة في تلك المناطق، وعاثوا فيها نهبًا وقتلًا وسلبًا، وكان هذا الاستيلاء هو بمثابة تحطيم وسائل الدفاع في المنطقة الغربية من غرناطة."},{"id":3508,"title":"وفاة السلطان الغالب بالله علي بن سعد صاحب غرناطة .","date":["العام الهجري :890","العام الميلادي :1485"],"text":"هو السلطان الغالب بالله أبو الحسن علي بن سعد بن محمد بن الأحمر الأرجواني، الأندلسي، الغرناطي، الأنصاري، المصري ملك الأندلس وصاحب غرناطة. ومولده قبيل سنة840. خرج على والده سعد واستولى على ملك غرناطة سنة 868 ونفا والده إلى المرية ومات من سنته، ومنذ البداية، دخل أبو الحسن في حروب مع أخويه، أبو الحجاج يوسف وأبو عبد الله محمد الزغل، اللذين نازعاه الملك، كل على حدة. ولما توفي أبو الحجاج بقي أبو عبد الله الزغل منازعًا لأخيه حتى إنه خرج إلى ملك قشتالة يستنصره على أخيه، ثم ثار عليه ولده محمد أبو عبد الله الصغير، ومع هذا الصراعات قام أبو الحسن أول أمره بتحصين الحصون وتنظيم شؤون البلاد، وتولى وزارته وزير أبيه أبو القاسم بن رضوان. كان ملكًا جليلًا عارفًا مدبِّرًا. لكنه في آخر أيامه اشتغل باللذات والانهماك في الشهوات واللهو بالنساء المطربات وركن إلى الراحة والغفلات, ومن ذلك افتتانه بجارية رومية نصرانية اسمها ثريا قيل إنها أسلمت وإنها ابنة القائد القشتالي سانشو خمينس دي سوليس، وولدت منه ولدين: سعدًا ونصرًا, وقد فضل أبو الحسن ثريا وولديها ونفى ابنة عمه عائشة الحرة وولديها في برج قمارش بقصر الحمراء, فثار به ولده محمد أبو عبد الله الصغير ابن عائشة الحرة، وجرت بينهما خطوب، وكان الوزير أبو القاسم بن رضوان يوافق الأمير أبا الحسن على إظهار الصلاح والعفاف للناس, وانصرف الأمير أبو الحسن عن تقوية عساكره فأهمل كل من فيه نجدة وشجاعة من الفرسان ولم يزل الأمير مستمرًّا على حاله والجيش في نقص والملك في ضعف إلى أن فقد أبو الحسن بصره، وتنازل بالحكم لابنه أبي عبد الله الصغير، فلما أسره الفرنج استدعى الأمير أبو الحسن أخاه أبا عبد الله الملقب بالزغل، وسلمه حكم غرناطة."},{"id":3509,"title":"مسلمو إسبانيا يستنجدون بالمماليك والعثمانيين .","date":["العام الهجري :890","العام الميلادي :1485"],"text":"تطورت الأحداث في بلاد الأندلس، وأصبح اهتمام الإسبان هو توحيد أراضيهم، وانتزاع ما تبقى للمسلمين بها خصوصًا بعدما خضع الإسبان لسلطة واحدة بعد زواج إيزابيلا الكاثوليكية المتعصبة ملكة قشتالة من فرديناند ملك أراغوان، وبعد هلاك الدون جويان الثاني ملك أراغون، وتولَّى مكانه ابنه فرديناند الكاثوليكي، ضمَّ أراغون وبلنسية وصقلية وميورقة إلى قشتالة، وبينما كانت الممالك النصرانية تتَّحد في تلك الأقطار، كانت المملكة الإسلامية الوحيدة في الأندلس تزداد فتقًا على فتق؛ ليقضيَ الله أمرًا كان مفعولًا! اندفعت الممالك الإسبانية المتحدة قبيل سقوط غرناطة في تصفية الوجود الإسلامي في كل إسبانيا، حتى يفرغوا أنفسَهم ويركزوا اهتمامهم على المملكة الإسلامية الوحيدة في غرناطة، وفرضت إسبانيا أقسى الإجراءات التعسُّفية على المسلمين في محاولة لتنصيرهم وتضييق الخناق عليهم حتى يرحلوا عن بلاد الأندلس؛ نتيجة لذلك وقبل سقوط غرناطة لجأ المورسكيون-وهم الأقلية المسلمة التي بقيت في الأراضي الإسبانية بعد انتزاع حكمها من المسلمين- إلى القيام بثورات وانتفاضات في أغلب المدن الإسبانية، والتي يوجد بها أقلية مسلمة، وأُخمِدَت تلك الثورات بدون رحمة ولا شفقة من قبل السلطات الإسبانية التي اتخذت وسيلة لتعميق الكره والحقد للمسلمين، ومن جهة أخرى كان من الطبيعي أن يرنو المورسكيون بأنظارهم إلى ملوك المسلمين في المشرق والمغرب لإنقاذهم، وتكررت دعوات وفودهم ورسائلهم إليهم للعمل على إنقاذهم مما يعانوه من ظلم، وخاصة من قبل رجال الكنيسة ودواوين التحقيق (محاكم التفتيش) التي عاثت في الأرض فسادًا وأحلت لنفسها كل أنواع العقوبات وتسليطها عليهم، وكانت أخبار الأندلس قد وصلت إلى المشرق فارتج لها العالم الإسلامي، وبعث الملك الأشرف قايتباي بوفود إلى البابا وملوك النصرانية يذكِّرُهم بأن النصارى الذين هم تحت حمايته يتمتعون بالحرية، في حين أن أبناء دينه في المدن الإسبانية يعانون أشد أنواع الظلم، وقد هدد باتباع سياسة التنكيل والقصاص تجاه رعايا المسيحيين، إذا لم يكفَّ ملك قشتالة وأراغون عن هذا الاعتداء وترحيل المسلمين عن أراضيهم وعدم التعرض لهم، ورد ما أخذ من أراضيهم، ولم يستجيب البابا والملكان الكاثوليكيان لهذا التهديد من قبل الملك الأشرف قايتباي، ومارسوا خطتهم في تصفية الوجود الإسلامي في الأندلس، وجُدِّدت رسائل الاستنجاد لدى السلطان العثماني بايزيد الثاني بن محمد الفاتح، فوصلته رسالةٌ منهم يذكرون فيها آلامَهم ومعاناتهم ويسألونه الخلاص، ومما كتبه بعض أهل الجزيرة بعد استيلاء الكفر على المدن الأندلسية للسلطان بايزيد خان الثاني ما نصه بعد سطر الافتتاح: الحضرة العلمية، وصل الله سعادتها وأعلى كلمتها ومهد أقطارها وأعز أنصارها وأذل عداتها، حضرة مولانا وعمدة ديننا ودنيانا، السلطان الملك الناصر ناصر الدين والدنيا، سلطان الإسلام والمسلمين، قامع أعداء الله الكافرين، كهف الإسلام وناصر دين نبينا محمَّد صلى الله عليه وسلم، محيي العدل ومنصف المظلوم ممن ظلم ملك العرب والعجم والترك والديلم، ظِل الله في أرضه، القائم بسنته وفرضه، ملك البرين وسلطان البحرين حامي الذمار وقامع الكفار، مولانا وعمدتنا مولانا بايزيد، لا زال ملكه موفور الأنصار مخلد المآثر والآثار مشهور المعالي والفخار، مستأثرا من الحسنات بما يضاعف الله الأجر الجزيل في الدار الآخرة والثناء الجميل، والنصر في هذه الدار، ولا بَرِحت عزماته العلية مختصة بفضائل الجهاد مجردة من أعداء الدين من بأسها ما يروي صدور السمر والصفاح وألسنة السلاح باذلة نفائس الذخائر في المواطن التي تألف فيها الأخيار مفارقة الأرواح للأجساد، سالكة سبيل السابقين الفائزين برضا الله وطاعته يوم يقوم الأشهاد:سلام كريم دائم متجدد أخص به مولاي خير خليفةسلام على مولاي ذي المجد والعلا ومن ألبس الكفار ثوب المذلةسلام على من وسع الله ملكه وأيده بالنصر في كل وجهةسلام على مولاي من دار ملكه قسنطينة أكرم بها من مدينةسلام على من زين الله ملك بنجد وأترك من أهل الرعايةسلام عليكم شرف الله قدركم وزادكم ملكا على كل ملة....وكان السلطان بايزيد يعاني من العوائق التي تمنعه من إرسال المجاهدين، بالإضافة إلى مشكلة النزاع على العرش مع أخيه الأمير جم، وما أثار ذلك من مشاكل مع البابوية في روما وبعض الدول الأوربية، ومع ذلك قام السلطان بايزيد بتقديم المساعدة وتهادن مع السلطان قايتباي لتوحيد الجهود من أجل مساعدة غرناطة ووقَّعا اتفاقًا بموجبه يرسل السلطان بايزيد أسطولًا على سواحل صقلية باعتبارها تابعة لمملكة إسبانيا، وأن يجهز السلطان المملوكي قايتباي حملات أخرى من ناحية أفريقيا، وبالفعل أرسل السلطان بايزيد أسطولًا عثمانيًّا تحول إلى الشواطئ الإسبانية، وقد أعطى قيادته إلى كمال رايس الذي أدخل الفزع والخوف والرعب في الأساطيل النصرانية في أواخر القرن الخامس عشر الميلادي، كما شجع السلطان بايزيد المجاهدين في البحر بإبداء اهتمامِه وعطفه عليهم، وكان المجاهدون العثمانيون قد بدؤوا في التحرك لنجدة إخوانهم المسلمين، وفي نفس الوقت كانوا يغنمون الكثير من الغنائم السهلة الحصول من النصارى، كذلك وصل عددٌ كبير من هؤلاء المجاهدين المسلمين أثناء تشييد الأسطول العثماني، ودخلوا في خدمته بعد ذلك أخذ العثمانيون يستخدمون قوتهم البحرية الجديدة في غرب البحر المتوسط بتشجيع من هؤلاء المجاهدين، وهذا الذي كان في وُسع السلطان بايزيد الثاني فعلُه."},{"id":3510,"title":"أمراء بني نصر يتناوشون على عرش الملك .","date":["العام الهجري :890","العام الميلادي :1485"],"text":"قام الأمير يوسف أبو الحجاج بن أبي الحسن علي بن سعد أمير المرية بمنازعة عمه أبي عبد الله الزغل ملك غرناطة، فقام القتال بينهما وقتل أمير المرية، ثم نازعه ابن أخيه الآخر عبدالله الصغير محمد الثاني عشر العائد من الأسر يريد استعادة ملكه الذي كان فيه قبل أن يؤسر، فأعلن نفسه ملكًا على غرناطة وقام بنصرته أهل ربض البيازين وهو حي غرناطة الشعبي، وأهله عرفوا بالاضطراب الدائم، كما أمده ملك قشتالة بقوة، فتمكن من التغلب على عمه."},{"id":3511,"title":"الفتنة بين أمراء بني نصر في الأندلس .","date":["العام الهجري :891","العام الميلادي :1486"],"text":"بعد القتال الذي دار بين أمراء بني نصر على الملك، بقيت هذه الفتنة بينهم إلى أن تم الاتفاق على أن تنقسمَ المملكة إلى قسمين؛ القسم الأول: وهو غرناطة ومالقة، يكون تحت ملك أبي عبد الله محمد بن سعد المعروف بالزغل، والقسم الثاني: وهو القسم الشرقي يكون تحت ملك ابن أخيه محمد بن علي المعروف بأبي عبد الله الصغير، ولكن هذا الأخير لم يلبث أن نقض الاتفاق وظهر فجأة في ساحة البيازين بغرناطة، وأذاع عقده للصلح مع الإسبان، وأنهم أمدوه بالرجال والعتاد، وبينما كان الأمير محمد بن سعد الزغل في طريقه إلى غرناطة بلغه خبر أن غرناطة قد قامت بدعوة ابن أخيه محمد بن علي, وأنه دخل البلد بقيام البيازين معه وملكه لها، وقتل القواد الذين كانوا بالبلد يقاتلونه، فرجع الأمير محمد بن سعد عند ذلك على عَقِبه يريد البشرة، فسار إلى وادي آش ممتنعًا بقواته فيها، وبعد هذا الاستيلاء انقسم ما تبقى من غرناطة إلى قسمين؛ الأول: ويحوي غرناطة وأعمالها اختص به أبو عبد الله محمد الصغير، الثاني: يضم وادي آش وأعماله اختص به عمه أبو عبد الله محمد الزغل."},{"id":3512,"title":"أول هزيمة عثمانية أمام مماليك السلطان قايتباي  .","date":["العام الهجري :891","العام الميلادي :1486"],"text":"حدثت معارك بين العثمانيين والمماليك على الحدود الشامية، إلا أنها لم تحتدم إلى حد التهديد بحدوث حرب شاملة بينهما، حيث استطاع قائد الجيوش المملوكية الأمير أزبك أن يأسر القائد العثماني أحمد بك بن هرسك، فأسهمت هذه الحرب في الشعور بعدم الثقة بينهما، الأمر الذي أدى إلى تعثر مفاوضات الصلح سنة 896. حتى إن السلطان المملوكي \" قايتباي\" قد ساورته مخاوف من احتمال قيام حرب واسعة بينه وبين العثمانيين؛ سواء لإدراكه ما كان عليه العثمانيون من قوة، أو لانشغال جزء هام من قواته في مواجهة البرتغاليين، إلا أن السلطان العثماني بايزيد الثاني قد بدَّد له هذه المخاوف؛ حيث قام بإرسال رسول من قِبَله إلى السلطان المملوكي معه مفاتيح القلاع التي استولى عليها العثمانيون على الحدود، وقد لقي هذا الأمر ترحيبًا لدى السلطان المملوكي، فقام بإطلاق سراح الأسرى العثمانيين، وأسهمت سياسة بايزيد السلمية في عقد صلح بين العثمانيين والمماليك في نفس السنة، وظل هذا الصلح ساريًا حتى نهاية عهد السلطان بايزيد الثاني سنة 917 وأكد هذا الحدث على حرص السلطان بايزيد في سياسة السلام مع المسلمين."},{"id":3513,"title":"استيلاء النصارى على مدينة لوشة  .","date":["العام الهجري :891","الشهر القمري : جمادى الأولى","العام الميلادي :1486"],"text":"بينما المسلمون في الأندلس بين حرب وصلح فيما بينهم إذ بصاحب قشتالة قد أقبل بحملته على مدينة لوشة, فنزل فيها الأمير محمد بن علي أبو عبد الله الصغير ومعه جماعة من أهل نجدة البيازين حين سمعوا بقدوم النصارى عليها، فتحصنوا بها مع أميرهم محمد ابن علي فحاصرها العدو حصارًا شديدًا ونصب عليها أنفاطه وعدته واقترب إليها بجيشِه وآلة حربه، حتى دخلوا ربضَها وهدموا بعض أسوارِها بالأنفاط، وقتل كثير من نجدة الرجال واشتد عليهم الحصار، فلما رأى أهل لوشة ما لا طاقة لهم به من شدة الحصار وكثرة جموع النصارى وتأخير أهل غرناطة عن نصرتهم، طلبوا الأمان واتفقوا على أن يخرجوا مؤمَّنينَ على أموالهم وأولادهم وخيلهم وسلاحهم ودوابهم وجميع ما يقدرون على حمله، فأجابهم العدو لذلك ووفى لهم به، فأخذوا في إخلاء البلاد ووصلوا إلى غرناطة بما معهم, وكان استيلاء العدو على مدينة لوشة في السادس والعشرين من جمادى الأولى من هذا العام، ولم يسَرِّح صاحبُ قشتالة الأميرَ محمد بن علي أبا عبد الله الصغير، بل حبسه عنده ليستأصل به بقية الأندلس."},{"id":3514,"title":"ملك قشتالة يحتل مدينة بلش  .","date":["العام الهجري :892","الشهر القمري : ربيع الآخر","العام الميلادي :1487"],"text":"لما كان النصف من شهر ربيع الثاني من هذا العام خرج ملك قشتالة إلى أرض المسلمين قاصدًا مدينة بلش مالقة، فلما سمع ملك غرناطة محمد الزغل بنزوله على مدينة بلش ندب أهل غرناطة ومن أطاعه من أهل تلك الجهات وترك طائفةً تقاتل أهل البيازين، وخرج يريد نصرة أهل بلش، وذلك يوم السبت الرابع والعشرين لربيع الثاني من عام التاريخ، فلما سار قريبًا منها وجد العدو قد سبقه بالنزول عليها، ودار بها من كل الجهات فقصد الأمير حصن منتميس فنزله بحملته وأقام به بعض الأيام فطلبه الناس أن يسير بهم نحو العدو للقائه فتوجه بهم إليه فرتبهم، وكان ذلك عشية النهار فدخل عليهم الليل بالطريق فبينما هم سائرون إذ قامت كرَّة ودهشة فانهزموا في ظلام الليل من غير لقاء عدو ولا قتال، وكانت على ذمة أمير غرناطة فنزلها فرجعوا منهزمين مفلولين إلى محلتهم، فباتوا ليلتهم تلك وفي الغد أتاهم الخبر أن العدو استخلص مدينة بلش فسُقط في أيديهم وانهزموا من غير أن يلقوا عدوًّا، ورجع كل واحد منهم إلى وطنه, ولما استولى العدو على مدينة بلش دخلت في ذمته جميع القرى التي تلي بلش وقرى جبل منتميس وحصن قمارش، وخرج أهل بلش من بلدهم مؤمَّنين وحملوا ما قدروا عليه، وذلك بعد قتال شديد وحرب عظيمة، فمنهم من جوزه العدو إلى أرض العدوة، ومنهم من أقام في بعض تلك القرى، ومنهم من سار إلى أرض المسلمين التي بقيت بالأندلس."},{"id":3515,"title":"استيلاء الإسبان على مالقة وقتلهم النساء والأطفال .","date":["العام الهجري :892","الشهر القمري : شعبان","العام الميلادي :1487"],"text":"لما استخلص ملك قشتالة الملك فرديناند مدينة بلش سار بحملته نحو مدينة مالقة فنزل عليها وقاتلها قتالًا شديدًا وحاصرها حصارًا عظيمًا لم يُرَ مثلُه، وأحاط بها من كل جانب ومكان برًّا وبحرًا، فتحصن أهل مالقة ببلدهم وأظهروا ما كان عندهم ومعهم من السلاح والعدة والأنفاط، وكان فيهم جملة من نجدة الفرسان فقاتلوا الروم قتالًا شديدًا، وقتلوا منهم خلقًا كثيًرا، حتى إنه قُتل من الروم في يوم واحد اثنا عشر ألفًا وسبع مئة، ومع ذلك بقي العدو يفتح عليهم أبوابًا من الحرب والحيل، والمسلمون قائمون بحراسة بلدهم ويغلبون عدوهم ويقتلون من قَرُب إليهم منهم، وهم صابرون محتسبون مدة طويلة حتى ضيق عليهم العدو ودوَّر بالمدينة سورًا من تراب وسورًا من خشب وحفيرًا مانعًا، ومنع عليهم الداخل والخارج في البر، ومنع عليهم في البحر بالمراكب من الداخل والخارج، وشد عليهم في الحصار والقتال، وهم مع ذلك صابرون محتسبون يقاتلون أشد القتال ولا يظهرون جزعًا ولا هلعًا ولا يُطمعون العدوَّ في شيء مما يرومُه منهم، حتى نفد ما عندهم من الأطعمة والزاد وأكلوا ما كان عندهم من المواشي من خيل وبغال وحمير وكلاب وجلود وورق الشجر وغير ذلك من الأشياء التي يمكن أكلها، حتى فني ذلك كله، وأثَّر فيهم الجوع أثرًا عظيمًا ومات كثير من نجدة رجالهم الذين كانوا يوالون الحرب والقتال، فحينئذ أذعنوا وطلبوا الأمان فاحتال عليهم العدو حتى دخل البلد بمكرٍ ومكيدة وأسرهم كلَّهم وسبى نساءهم وأولادهم واحتوى على جميع أموالهم، وفرَّقهم على أهل دخلته وقواده، وكان مصابهم مصابًا عظيمًا تحزن له القلوب وتذهل له النفوس وتذوب، وتبكي مصابَهم العيون بالدماء, وكان استيلاء العدو على مدينة مالقة في أواخر شعبان من هذا العام, فحين خلصت للعدو مدينة مالقة وبلش وجميع الغربية ولم يبقَ في تلك النواحي للمسلمين موضع واحد، ارتحل الطاغية إلى بلده من قشتالة."},{"id":3516,"title":"غلاء أسعار القمح والشعير بدمشق .","date":["العام الهجري :892","الشهر القمري : ذي الحجة","العام الميلادي :1487"],"text":"غلا سعر القمح والشعير، وبرز مرسومُ الحوَّاط بالمناداة بدمشق، بأن لا يبيع حاضر لجلَّاب قمحًا ولا شعيرًا، فتخبَّطت دمشق، وزادت الأسعار وصَغُرت قطع الخبز، وطلبه الناس، وبيعت غرارة القمح بأربعمائة وعشرين درهم، والشعير بمائة وسبعين!!"},{"id":3517,"title":"زحف الإسبان على غرناطة وبدأ حصارها .","date":["العام الهجري :893","العام الميلادي :1487"],"text":"طلب الإسبان من أبي عبد الله محمد الصغير أن يضعوا قواتٍ لهم في الحمراء فرفض أبو عبد الله الصغير هذا الطلب ومنعهم من دخول غرناطة، فقام ملك قشتالة فرديناند بالزحف بقواته على أطراف غرناطة الشرقية واستولى في طريقه على بعض المدن، ومنها المنكب والبيرة وبلش وغيرها من القواعد الشمالية، مكملًا مسيرته إلى غرناطة التي بدأ يحاصرها، واستمر الحصار إلى سنة 895."},{"id":3518,"title":"نهاية دولة الحفصيين بالمغرب .","date":["العام الهجري :893","العام الميلادي :1487"],"text":"توفي الأمير أبو عمرو عثمان بن محمد الحفصي وقام خلفًا عنه حفيده أبو زكريا يحيى بن مسعود بن محمد، وكان عثمان هذا آخر الحفصيين الكبار والذي بوفاته تعتبر الدولة الحفصية قد انتهت؛ وذلك أن سكان جزيرة جربة رفضوا الاعترافَ بالأمير الجديد يحيى وبسيادة الحفصيين عليهم، فشكَّلوا جمهورية مستقلة فحذت مدينة طرابلس حذوَهم وقاموا هم أيضًا بالتخلص من الحفصيين."},{"id":3519,"title":"هزيمة العثمانيين الثانية أمام مماليك السلطان قايتباي .","date":["العام الهجري :893","العام الميلادي :1487"],"text":"كانت الحرب الأولى للعثمانيين مع المماليك في سنة 891 حيث أُسِرَ فيها القائد العثماني أحمد بك بن هرسك، فأراد السلطان العثماني بايزيد الثاني الثأرَ فجهَّز جيوشًا برية وبحرية وانضم للماليك زعيم الآق قوينلو، ثم أراد السلطان المملوكي قايتباي أن يصلحَ الأمر فأطلق سراح الأسارى العثمانيين، ومنهم أحمد هرسك، ولكن هذا لم يُجدِ نفعًا, فنجح قائد الجيوش المملوكية الأمير أزبك في الوصول إلى أذنة ومن معه من القوات الموالية، فحاصرها ثلاثة أشهر ثم دخلها عَنوةً، وأسر وغنم واحتفلت القاهرة بهذا النصر أسبوعًا."},{"id":3520,"title":"الأمير أبو عبد الله الزغل يبايع ملك قشتالة ونكايته بالمسلمين .","date":["العام الهجري :895","العام الميلادي :1489"],"text":"بعد سيطرة فرديناند على بسطة أهم مدن شرق غرناطة التي كانت تحت حكم الأمير أبي عبد الله محمد بن سعد الزغل خرج الأمير الزغل من مدينة وادي آش تابعًا لصاحب قشتالة، فلما لحقه بايعه ودخل في ذمتة وتحت طاعته على أن يعطيه مدينة وادي آش وكل مدينة وحصن وقرية كانت تحت طاعته وحكمه، فأجابه إلى مطلبه ورجع معه إلى وادي آش وهو فرح مسرور، فدخلها العدو وقبض قصَبَتها واستولى عليها في العشر الأُوَل من شهر صفر، ودخل في ذمته جميع فرسان الأمير الزغل وجميع قواده، وصاروا له عونًا على المسلمين وطوَّعوا له جميع البلاد والقرى والحصون التي كانت تحت طاعتِهم من مدينة المرية إلى مدينة المنكب، ومن مدينة المنكب إلى قرية البذول، فقبض صاحب قشتالة ذلك كله من غير قتال ولا حصار ولا تعب ولا نصب، فإنا لله وإنا إليه راجعون!وجعل في كل قصبة قائدًا نصرانيًّا مع جماعة من النصارى يحكم في ذلك الموضع، وفي هذا الشهر خلصت جميع بلاد الأندلس لصاحب قشتالة، ودخلت تحت طاعته وتدجن-داهن- جميع أهلها ولم يبقَ للمسلمين في الأندلس غير مدينة غرناطة وما حولها من القرى خاصة، وزعم كثير من الناس أن الأمير محمد بن سعد الزغل وقواده باعوا صاحب قشتالة هذه القرى والبلاد التي كانت تحت طاعتهم وقبضوا منه ثمنها، وذلك على وجه الانتقام من ولد أخيه الأمير أبي عبد الله الصغير وقواده؛ لأنهم كانوا في غرناطة ولم يكن تحت طاعتهم غيرها، فأراد بذلك قطع علائق غرناطة؛ لتهلك كما هلك غيرها, ولا حول ولا قوة إلا بالله!"},{"id":3521,"title":"حصار الفرنج مدينة بسطة أهم مدن الزغل ثم استسلامها لهم .","date":["العام الهجري :895","الشهر القمري : محرم","العام الميلادي :1489"],"text":"خرج فرديناند ملك قشتالة بحملته وعُدَّته، وقصد نحو حصن موجر فحاصره وقاتله قتالًا شديدًا، فاستولى عليه، ثم استولى على الحصون القريبة منه, ثم قصد مدينة بسطة أهم مدن الأمير أبي عبد الله الزغل في شرق غرناطة فنزل قريبًا منها فوجد بلدًا مقيمًا بالخيل والرجال والعدة والطعام، فكلما قرب من البلد وأراد قتال المسلمين رجع خاسرًا وقُتل منه خلق كثير ولم يقدر أن يمنع داخِلَها وخارجها كما فعل بغيرها من المدن، وكان يدخلها كل من جاءها من نجدة الفرسان والرجال فبقي محاذيًا لها شهر رجب وشعبان ورمضان والمسلمون قائمون ببلدهم غالبون لعدوهم، فكلما أراد الدنو من البلد قمعوه وردوه على عقبه خائبًا خاسرًا، ولم يقدر على نَصبِ نفط ولا عدة من آلة الحرب، فلما كان شهر شوال شدَّد عليهم الحصار وعمل على البلد سورًا من خشب وحفيرًا عظيما وجعل على ذلك الرجال والحرس؛ لئلا يدخل داخل من أنجاد الرجال إليهم الذين يأتون لنصرتِهم وإعانتهم على عدوهم، ولا من يجلب لهم الطعام، فلم يعبأ المسلمون بما صنع، بل كانوا يخرجون من النقب ويهبطون من على الأسوار ويقتلون العدو في حملتهم وفي كل مسلك يسلكونه، حتى قتلوا منهم خلقًا كثيرًا، وكان المسلمون الواردون عليهم لنصرتِهم يحملون معهم ما يحتاجون إليه من الطعام، فبقوا على هذه الحالة شهر شوال وذا القعدة وذا الحجة وفي آخر ذي الحجة تفقَّد أعيان البلد ما بقي في بلدهم من الطعام وذلك في خُفيةٍ من العامة فلم يجدوا إلَّا ما يقام به أيامًا قلائل فبعثوا لفرديناند وطلبوا منه الأمان على شروط اشترطوها فوجدوه راغبًا في ذلك فجعلوا بينهم هدنة والكلام يتردَّدُ بينهم في خفية من العامة فأجابهم بجميع ما طلبوه منه، فلما كان يوم الجمعة عاشر محرم سنة 895 أدخل قواد البلاد جمعًا من النصارى للقصبة على حين غفلة من العامة، فملكوا القصبة وقهروا من كان بالبلد من العامة وغيرهم، وسُقِطَ في أيديهم، ثم إنهم سرحوا من كان عندهم من أنجاد الرجال والفرسان الذين كانوا عندهم يعينونهم على نصرة عدوهم، فخرجوا مؤمَّنين بخيلهم وأسلحتهم وأمتعتهم كما شرط عليه قواد البلد، فساروا إلى مدينة وادي آش وأخلوا البلد للنصارى وخرجوا إلى الأرباض بما معهم من أموالهم وأمتعتهم مؤمَّنين، ولم يتركوا شيئًا إلا سقف المدينة خاصة، ثم إن فرديناند جعل في البلد قائدًا من قواده حاكمًا ورتَّبه وأشحنه بما يحتاج إليه من أطعمة وزاد وآلة حرب، وارتحل من مدينة بسطة يريد المرية، فلم يمر على حصن ولا على قرية إلا ودخل أهلها في ذمته وتحت طاعته من غير حصار ولا قتال, وكان الزغل قد عقد معاهدة سرية مع فرديناند نصَّ فيها على أن يستقر الزغل أميرًا في مدينة أندرش، وجنوده، ويكونون تابعين لملك قشتالة، وله أن يحضر أبناءه من غرناطة، وترجع له جميع أملاكه، لكنه لم يطق حياة الذل مدة طويلة، فتنازل عن جميع حقوقه، وجاز البحر إلى وهران، ثم إلى تلمسان حيث استقرَّ بها وعددٌ من قواده."},{"id":3522,"title":"حمد الشيخ الوطاسي يضم مدينة فاس لحكمه .","date":["العام الهجري :896","العام الميلادي :1490"],"text":"لما أحسَّ محمد الشيخ الوطاسي حاكم آصيلا من نفسه القدرة على الاستيلاء على كرسي فاس وتنحية الشريف أبي عبد الله الحفيد الإدريسي عنه- لا سيما مع ما كان الناس فيه من افتراق الكلمة- فجمع جندًا صالَحَها وزحف إلى فاس فبرز إليه الشريف والتقوا بأحواز مكناسة، فوقعت بينهما حرب عظيمة كانت الكرَّة فيها على الوطاسي، ثم جمع عسكرًا آخر وزحف به إلى فاس وحاصرها نحو سنتين والشريف فيها مع أرباب دولته، وفي أثناء الحصار ورد عليه الخبر باستيلاء البرتغال على آصيلا وعلى بيت ماله الذي كان بها وعلى حظاياه وأولاده، فأفرج عن فاس ورجع مبادرًا إلى آصيلا فحاصرها، ولما امتنعت عليه عقد مع البرتغال هدنة وعاد سريعًا إلى فاس فحاصرها وضيق على الشريف بها حتى خرج فارًّا بنفسه وأسلمها إليه."},{"id":3523,"title":"توقيع الصلح بين المماليك والعثمانيين .","date":["العام الهجري :896","العام الميلادي :1490"],"text":"بعد أن بقيت العلاقات بين الطرفين متوترة واستطاع المماليك أن يُلحقوا الهزيمة بالعثمانيين ثلاث مرات آخرُها سنة 895 حيث أرسل قايتباي حملة بقيادة الأمير أزبك الذي وصل إلى كولك، وكان قد أمره قايتباي أن يحاول الصلح والسلم، فدخل أوزبك الأراضي العثمانية عن طريق حلب، فأرسل ماماي الخاصكي إلى المعسكر العثماني من أجل الصلح، ولكنه لما استبطأه دخل إلى العمق وبدأ بالنهب والحرق واستولى على قلعة كوارة وعاد إلى القاهرة في مستهل سنة 896، ثم توسط باي تونس بين الطرفين حتى تم عقد اتفاقية بين الطرفين سنة 896 فأرسل بايزيد الثاني رسولًا من قِبَلِه إلى القاهرة بصحبة ماماي الخاصكي ومعه مفاتيح القلاع التي استولى عليها العثمانيون، فاستقبله قايتباي بحفاوة، وسرعان ما أصدر أوامره بإطلاق الأسرى العثمانيين، وتخلى العثمانيون عن مطالبهم في كبادوكيا وقيليقيا، وظل هذا الصلح ساريًا حتى نهاية عهد السلطان بايزيد الثاني سنة 917 وأكد هذا الحدث على حرص السلطان بايزيد في سياسة السلام مع المسلمين."},{"id":3524,"title":"وقوع ثلج كثير بدمشق وما حولها .","date":["العام الهجري :896","الشهر القمري : محرم","العام الميلادي :1490"],"text":"وقع بدمشق وما حولها ثلج كثير، واستمرَّ إلى نصف النهار، فارتفع في الأسطح نحو ذراع، وتكسَّر بذلك كثير من الأشجار، سيما أشجار الزيتون، وكان الحطب قد غلا سعرُه وبلغ قنطار اليابس منه إلى نحو الثلاثين درهمًا، فرخُص سعرُه من يومئذٍ، واستمر الثلجُ في بعض الطرق وغيرها نحو عشرين يومًا، وكان آخره من مدينة زرع إلى مدينة حماة."},{"id":3525,"title":"نقض الملك فرديناند شروط تسليم غرناطة .","date":["العام الهجري :897","العام الميلادي :1491"],"text":"كان الملك فرديناند قد أظهر للمسلمين في الأيام الأولى من تسليم غرناطة العناية والاحترام حتى كان النصارى يَغيرون منهم ويحسدونهم ويقولون لهم أنتم الآن عند ملكنا أعز وأكرم منا، ووضع عنهم المغارم وأظهر لهم العدل حيلة منه وكيدًا؛ ليغرَّهم بذلك وليثبطهم عن الجواز، فوقع الطمع لكثير من الناس، وظنوا أن ذلك يدوم لهم فاشتروا أموالًا رخيصة وأمتعة أنيقة وعزموا على الجلوس مع النصارى، ثم إن فرديناند أمر الأمير محمد بن علي أبا عبد الله الصغير بالانصراف من غرناطة إلى قرية أندرش من قرى البشرة، فارتحل الأمير محمد بعياله وحشمه وأمواله وأتباعه، فنزل قرية أندرش وأقام بها ينتظر ما يؤمر به، ثم إن الملك فرديناند ظهر له أن يصرف الأمير أبا عبد الله الصغير إلى العدوة فأمره بالجواز وبعث للمراكب أن تأتي إلى مرسى عذرة، واجتمع معه خلق كثير ممن أراد الجواز فركب الأمير محمد ومن معه في تلك المراكب في عزة واحترام وكرامة مع النصارى، وساروا في البحر حتى نزلوا مدينة مليلة من عدوة المغرب، ثم ارتحل إلى مدينة فاس, وكان من قضاء الله وقدره أنه لما جاز أبو عبد الله الصغير وسار إلى مدينة فاس أصاب الناس شدة عظيمة وغلاء مفرِط وجوع وطاعون، واشتد الأمر بفاس حتى فر كثير من الناس من شدة الأمر، ورجع بعض الناس من الذين جازوا إلى الأندلس فأُخبروا بتلك الشدة فقصر الناس عن الجواز, فعزموا على الإقامة والدجن-المداهنة- ولم يجوز النصارى أحدًا بعد ذلك إلا بالكراء والمغرم الثقيل وعُشر المال، فلما رأى فرديناند أن الناس قد تركوا الجواز وعزموا على الدجن والاستيطان والمقام في الأوطان أخذ في نقض الشروط التي شرطوا عليه، ولم يزل ينقضها شرطًا شرطًا ويحلها فصلًا فصلًا إلى أن نقض جميعها وزالت حرمة الإسلام عن المسلمين وأدركهم الهوان والذلة، واستطال النصارى عليهم، وفُرِضت عليهم الفروضات وثَقُلت عليهم المغارم، وأمرهم بالخروج من مدينة غرناطة إلى الأرباض والقرى، فخرجوا أذلة صاغرين! أما الأمير أبو عبد الله الصغير فبعد أن لجأ إلى مدينة فاس بالمغرب وسلطانها يومئذ محمد الشيخ الوطاسي المعروف بالبرتغالي، بقي فيها ذليلًا حقيرًا يستعطف الناس إلى أن توفي سنة 940 عن عمر 73سنة."},{"id":3526,"title":"قيام مملكة صنغاي الإسلامية غربي أفريقيا .","date":["العام الهجري :897","العام الميلادي :1491"],"text":"تدفقت بعض القبائل المغربية وخاصة قبائل لمطة إلى الضفة اليسرى لنهر النيجر عند مدينة دندي، وسيطرت هذه القبائل على الزرَّاع من أهل صنغي الذين رحَّبوا بهم ليحموهم من الصيادين الذين كانوا يعتدون عليهم، ونجح هؤلاء الوافدون الجدد في تكوين أسرة حاكمة استفادت من علاقاتها التجارية مع غانة وشمال أفريقيا، وكان لهذه العلاقة أثر بعيد في تحويل ملوك صنغي إلى الإسلام وانتشاره في غربي قارة أفريقيا. كانت صنغاي في بداية أمرها دويلة صغيرة تحت حكم مالي غرب نهر النيجر في المنطقة الواقعة شمال بنين وغربي نيجيريا، ثم انتقلت مع نهر النيجر إلى الشمال وانتقلت معها عاصمتها، فكانت في البداية في دندي ثم كوكيا ثم رأى ملوك الصنغاي أن ينقلوا حاضرة ملكهم إلى جاو لتكون على مقربة من طرق القوافل الرئيسية, ولما كانت الصنغاي تحت حكم مالي قد قدمت رهائن لضمان بقاء خضوعها، ولكن لم يلبث الرهائن وهما ولدا الملك صنغاي زايا سبيًا- وولداه هما علي كولن وسليمان نار- وكانا طفلين يوم أخذا كرهائن، ثم لما كَبِرا استطاعا الفرار من مالي ووصلا إلى جاو وأنقذا مدينتهما من الحامية المالية، وأسَّسا مملكة جديدة أخذت تتوسع على حساب مملكة مالي التي بدأ الضعف يدب فيها، وكان علي كولن أول ملوك الدولة الجديدة، لكنه مات فخلفه أخوه سليمان نار، ثم عادت مملكة صنغاي تتبع اسميًّا لمالي، ولكن ما زال أمر الصنغاي يقوى، وقام ملكهم محمد دوغو بحملة ضد مالي واستطاع أن يتخلص من سيطرة الماليين عليهم، ثم خلفه ابنه سني علي الذي يعد مؤسس مملكة صنغاي المنفصلة؛ حيث احتل مدينة تومبكتو وطرد الطوارق منها، كما أخضع منطقة النيجر كلها مستوليًا على مدينة جني باسطًا نفوذه على منطقة ياتنغا مقر قبائل الموش، فكان هذا العمل إعلان قيام مملكة صنغاي المنفصلة."},{"id":3527,"title":"سقوط غرناطة ونهاية حكم المسلمين في الأندلس .","date":["العام الهجري :897","الشهر القمري : محرم","العام الميلادي :1491"],"text":"زحف الملك فرديناند ملك قشتالة على غرناطة سنة 895 وحاصرها وشدد الحصار عليها, وامتدَّ الحصار إلى هذه السنة وقعت خلاله ملاحم كثيرة، والمسلمون كانوا يلحُّون على حمايتها, فلم يزالوا يدافعون عنها ويقاتلون من قصَدَها حتى قصر عنها العدو؛ لكثرة ما قُتل له عليها من خيل ورجال، ولم تزل الحرب متصلة وقد أصيب فيها كثير من أنجاد فرسان المسلمين بالجراحات، واستشهد آخرون، ومن النصارى أضعاف ذلك, والمسلمون فوق ذلك صابرون محتسبون واثقون بنصر الله تعالى، يقاتلون عدوهم بنية صادقة وقلوب صافية, وكان يُغيرُ منهم رجال في الليل على النصارى فيغنموا ما وجدوا عندهم من خيل وبغال وحمير وبقر وغنم ورجال، حتى صار اللحم بالبلد من كثرته الرطل بدرهم, والحرب متصلة بينهم والقتل والجراح فاشيان في الفريقين سبعة أشهر إلى أن فنيت خيل المسلمين بالقتل، ولم يبق منها إلا القليل، وفني أيضًا كثير من نجدة الرجال, وفي هذه المدة انجلى كثير من الناس إلى بلاد البشرة لما نالهم من الجوع والخوف وكانت الطريق للبشرة على جبل شلير، وكان يأتي للبلد من البشرة على ذلك الطريق خير كثير من القمح والشعير والذرة والزيت والزبيب والفواكه والسلع، وما زال حال البلد يضعف ويقل من الطعام والرجال إلى أن دخل محرم سنة 897 ودخل فصل الشتاء والثلج نازل بالجبل، وقُطع الطريق من البشرة، فقل الطعام في أسواق المسلمين بغرناطة واشتد الغلاء، وأدرك الجوع كثيرًا من الناس، وكثر السُّؤَّال والعدو ساكن ببلده ومحلته، ولقد منع المسلمين من الحرث والزراعة وانقطعت الحرب في هذه المدة بين الفريقين، فلما دخل صفر اشتد الحال على الناس بالجوع وقلة الطعام وأدرك الجوع كثيرًا من الناس الموسرين، فاجتمع أعيان الناس من الخاصة والعامة والفقهاء والأمناء والأشياخ والعرفاء ومن بقي من أنجاد الفرسان، ومن لهم النظر بغرناطة، وساروا إلى أميرهم أبي عبد الله الصغير، فأعلموه بحال الناس وما هم فيه من الضعف وشدة الجوع وقلة الطعام، وأن بلدهم بلد كبير لا يقوم به طعام مجلوب، فكيف ولم يُجلَب إليه شيء، وأن الطريق التي كانت يأتيهم عليها الطعام والفواكه من البشرة انقطعت بسبب الثلوج، وأن أنجاد الفرسان هلكوا وفنوا، ومن بقي منهم أُثخِن بالجراحات، وقد امتنع عنهم الطعام والزرع والحرث، وأن رجالهم هلكوا في تلك الملاحم، ثم قالوا له: إن إخواننا المسلمين من أهل عدوة المغرب بعثنا إليهم فلم يأتنا أحد منهم لنُصرتنا وإغاثتنا، وعدُوُّنا قد بنى علينا وسكَنَ معنا وهو يزداد قوةً ونحن نزداد ضعفًا والمَدَد يأتيه من بلاده ونحن لا مدد لنا، وهذا فصل الشتاء قد دخل وحملة عدونا تفرقت وضعفت، وقد قطع عنا الحرب، وإن تكلمنا مع الملك فرديناند الآن قَبِلَ منا وأعطانا كل ما نطلب منه، وإن بقينا حتى يدخل فصل الربيع تجتمع عليه جيوشُه مع ما يلحقنا نحن من الضعف والقلة، فلن يعود يقبلُ منا ما نطلبه منه، ولا نأمن نحن على أنفسنا منه؛ فقد هرب لحملته من بلدنا أناس كثيرون يدلونه على عوراتنا ويستعين بهم علينا، فقال لهم أبو عبد الله الصغير: انظروا ما يظهر لكم وما تتفقون عليه من الرأي الذي فيه صلاحكم، فاتفق رأي الجميع من الخاصة والعامة أن يبعثوا للملك فرديناند من يتكلم معه في أمرهم،وقد زعم كثير من الناس أن أمير غرناطة ووزيره وقواده كان قد تقدم بينهم وبين فرديناند الكلام في إعطائه البلد، إلا أنهم خافوا من العامة وكانوا يحتالون عليهم ويلاطفونهم، فحين أتوهم بما كانوا أضمروا عليه أسعفوهم من حينهم, فأرسل أبو عبد الله الصغير المندوبين لهذه المهمة، فوجدوا الملك فرديناند راغبًا في الصلح بالتسليم، فأنعم لهم بجميع ما طلبوا منه وما شرطوا عليه, فتمت المفاوضة بوضع معاهدة التسليم، ووقَّع الطرفان عليها وتضمنت ستة وخمسين بندًا تعهد فيها الأمير أبو عبد الله الصغير ووزراؤه والفقهاء والعلماء بتسليم المدينة في ظرف ستين يومًا ابتداء من تاريخ المعاهدة التي بدأت في الثاني من محرم 897 الموافق لتشرين الثاني 1491م ومن جملة الشروط التي شرط أهل غرناطة على فرديناند: أن يؤمِّنَهم على أنفسهم وبلادهم ونسائهم وصبيانهم ومواشيهم ورباعهم وجناتهم ومحارثهم، وجميع ما بأيديهم، ولا يغرمون إلا الزكاة والعُشر لمن أراد الإقامة ببلده غرناطة، ومن أراد الخروج منها يبيع أصله بما يرضاه من الثمن لمن يريده من المسلمين والنصارى من غير غَبن، ومن أراد الجواز لبلاد العدوة بالغرب يبيع أصله ويحمل أمتعته ويحمله في مراكبه إلى أي أرض أراد من بلاد المسلمين من غير كراء ولا شيء يلزمه لمدة ثلاث سنين، ومن أراد الإقامة بغرناطة من المسلمين فله الأمان على نحو ما ذُكر، وقد كتب لهم فرديناند ملك قشتالة بذلك كتابًا وأخذوا عليه عهودًا ومواثيق في دينه مغلَّظة على أنه يوفِّي لهم بجميع ما شرطوه عليه, فلما تمت هذه العقود والمواثيق قُرئت على أهل غرناطة, فلما سمعوا ما فيها اطمأنوا إليها وانقادوا لطاعته، وكتبوا بيعتهم وأرسلوها لصاحب قشتالة وسمحوا له في الدخول إلي مدينة الحمراء وإلى غرناطة, فعند ذلك أمر أمير غرناطة أبو عبد الله الصغير محمد بن علي بإخلاء مدينة الحمراء فأُخليت دُورها وقصورها ومنازلها، وأقاموا ينتظرون دخول النصارى لقبضها، فلما كان اليوم الثاني لربيع الأول سنة897 أقبل فرديناند بجيوشه فبعث جناحًا من جيشه فدخلوا مدينة الحمراء وبقي هو ببقية الجيش خارج البلد؛ لأنه كان يخاف من الغدر، وكان طلب من أهل البلد حين وقع بينهم الاتفاق رهونًا من أهل البلد ليطمئن بذلك، فأعطوه خمسمائة رجل منهم, فلما اطمأن من أهل البلد ولم ير منهم غدرًا سرَّح جنوده لدخول البلد والحمراء، فدخل منهم خلق كثير وبقي هو خارج البلد وأشحن الحمراء بكثير من الدقيق والطعام والعدة، وترك بها قائدًا من قواده وانصرف راجعًا إلى محلته، وأخذ يبعث بالدقيق والعلوفات وأنواع الطعام والعدة وما يحتاجون إليه, فلما سمع أهل البشرة أن أهل غرناطة دخلوا تحت ذمة النصارى أرسلوا بيعتهم إلى الملك فرديناند ودخلوا في ذمته، ولم يبق حينئذ للمسلمين موضع بالأندلس، فإنا لله وإنا إليه راجعون! ولما اطمأن الملك فرديناند من غدر أهل غرناطة سرَّح الذين كانوا عنده مرتهنين مؤمَّنين في أموالهم وأنفسهم مكرَّمين، ثم أقبل في جيوشه فدخل مدينة الحمراء في بعض خواصه، وبقي الجند خارج المدينة وبقي هو يتنزه في الحمراء في القصور والمنازل المشيدة إلى آخر النهار، ثم خرج بجنده وصار إلى محلته, ومن غدٍ أخذ في بناء الحمراء وتشييدها وتحصينها وإصلاح شأنها وفتح طرقها، وهو مع ذلك يتردد إليها بالنهار ويرجع بالليل لمحلته، فلم يزل كذلك حتى ازداد اطمئنانًا من غدر المسلمين، فسرَّح للمسلمين الجواز إلى أرض العدوة فأتاهم بالمراكب في الساحل, فصار كل من أراد الجواز يبيع ماله ورباعه ودوره، فكان الواحد منهم يبيع الدار الكبيرة الواسعة المعتبرة بالثمن القليل وكذلك يبيع جنانه وأرض حرثه وكرمه وفدانه بأقل من ثمن الغلة التي كانت فيه، فمنهم من اشتراه من المسلمين الذين عزموا على الدجن- المداهنة- ومنهم من اشتراه من النصارى وكذلك جميع الحوائج والأمتعة، وأمرهم بالمسير إلى الساحل بما معهم فيرفعهم النصارى في البحر محترمين مكرمين، ويجوزونهم إلى عدوة المغرب آمنين مطمئنين."},{"id":3528,"title":"رحلة فاسكو دي جاما إلى الهند بتكليف من ملك البرتغال .","date":["العام الهجري :898","العام الميلادي :1492"],"text":"كلف ملك البرتغال مانويل الأول فاسكو دي جاما القيامَ برحلة للبحث عن طريق آخر يوصل بالهند دون المرور على بلاد المسلمين، فقام فاسكو بالسير جنوبًا بمحاذاة السواحل الغربية ووصل إلى رأس الزوابع في جنوب أفريقيا وسماها رأس الرجاء الصالح، ثم استدار شمالًا إلى السواحل الشرقية فوصل إلى موزمبيق وماليندي، وكانوا قد التقوا بسفن عربية أدهشتهم صناعتها، وكذلك أدوات الملاحة التي مع بحاريها من بوصلة وخرائط والمزاول، فأراد الاستفادة منهم للوصول إلى الهند، وكان من أبرز نتائجِ هذا الاكتشاف إضعافُ المسلمين اقتصاديًّا بانقطاع مرور التجارة ببلادهم بين الشرق والغرب؛ مما أدى إلى تدهورِ اقتصاد الدولة المملوكية، وكان أحدَ أسباب سقوطِها. أما ما أُشيع من أن ابن ماجد أرشد قائد الأسطول البرتغالي فاسكو دي غاما إلى طريق الهند، فهو باطل؛ قال أحمد علاونة: \"هو قول باطل مدارُه على النهروالي في كتابه (البرق اليماني في الفتح العثماني)، وقد ذكر هذه الأسطورةَ بعد ثمانين سنة من حدوثها، ولم يذكر أيُّ مؤرخ بعد النهروالي هذه الأسطورةَ، ثم جاء المستشرق فران عام 1922 ونفخ فيها من روحه، وتابعه عليها كثيرون، منهم الزِّرِكْلي\". وقد أورد العلاونة بعضَ الأدلةِ على بطلان إرشاد ابن ماجد لدي غاما، منها: أ / أن ابن ماجد أرشد دي غاما وهو سكران، وهذا غير معقول أن يطمَئِنَّ قائدٌ عسكري لفاقد الوعي ليدُلَّه على طريق محفوف بالمخاطر. ب/ لم تكن لابن ماجد خبرة في الساحل الأفريقي. ج/ لم يَرِدْ ذكرُ هذه الحادثة في أيٍّ من أعمال ابن ماجد النثرية والشعرية. د/ كان ابن ماجد يَعرِفُ حقَّ المعرفة نوايا البرتغاليين وما يضمرونه من شر للمسلمين. هـ/ لا يوجد مؤرخ برتغالي ممن عاصروا دي غاما وعُنُوا بتاريخ رحلاته، أو ممن جاؤوا على أثارهم ذكروا أحمد بن ماجد. و/ عاصر وصول البرتغاليين إلى المحيط الهندي عددٌ من المؤرخين العرب، ومنهم من عاصر ابن ماجد، ولم يذكر أيٌّ منهم صلةَ ابن ماجد بالبرتغاليين.ا."},{"id":3529,"title":"وقوع ثلوج وغلاء في الأسعار بمصر .","date":["العام الهجري :899","الشهر القمري : ربيع الآخر","العام الميلادي :1494"],"text":"في هذه الأيام تضاعف وقوف حال الناس؛ بسبب كثرة وقوع الثلج والجليد من أول الأصم- رجب- إلى آخره، حتى وصل الثلج إلى مصر على ما قيل، وماتت دواب كثيرة، وغلا سعر اللحم حتى صار رطله بخمسة دراهم، وسعر القمح حتى صارت الغرارة بنحو الأربعمائة."},{"id":3530,"title":"نهب إبل بني مدلج من العرب في دمشق .","date":["العام الهجري :900","الشهر القمري : جمادى الآخرة","العام الميلادي :1495"],"text":"دخل دمشق نهبُ إبل بني مدلج من العرب، قريب ألف ناقة وحمل وفصلان صغار، تجأر بصوتها الأمهات على أولادها، وأولادها على أمهاتها، حتى حزن الناس عليهم، ثم وضعوا في خان الجورة، وفارقوا بين الفصلان وأمهاتهم بالأكل والبيع، فزادوا في الجأر إلى الله، حتى سمعت من مكان بعيد، ولا حول ولا قوة إلا بالله، ودخل معهم عدة رؤوس مقطعة من عرب بني مدلج."}]
